cat > src/llist.c <<'EOF'
#include <stdlib.h>
#include "llist.h"

void llist_init(llist_t *l)
{
	l->head = NULL;
	l->tail = NULL;
}

void llist_free(llist_t *l)
{
	llist_item_t *i, *t;
	for (i = l->head; i; i = t) {
		t = i->next;
		free(i);
	}
	l->head = l->tail = NULL;
}

void llist_free_inner(llist_t *l, llist_fn_free_t fn_free)
{
	llist_item_t *i;
	for (i = l->head; i; i = i->next) {
		if (i->data) {
			fn_free(i->data);
			i->data = NULL;
		}
	}
}

llist_item_t *llist_first(llist_t *l)
{
	return l->head;
}

llist_item_t *llist_nth(llist_t *l, int n)
{
	llist_item_t *i;
	if (n < 0)
		return NULL;
	for (i = l->head; i && n != 0; i = i->next)
		n--;
	return i;
}

llist_item_t *llist_next(llist_item_t *i)
{
	return i ? i->next : NULL;
}

llist_item_t *llist_find_first(llist_t *l, void *data, llist_fn_match_t fn_match)
{
	llist_item_t *i;
	for (i = l->head; i; i = i->next) {
		if (fn_match(i->data, data))
			return i;
	}
	return NULL;
}

llist_item_t *llist_find_next(llist_item_t *i, void *data, llist_fn_match_t fn_match)
{
	if (!i)
		return NULL;
	for (i = i->next; i; i = i->next) {
		if (fn_match(i->data, data))
			return i;
	}
	return NULL;
}

llist_item_t *llist_find_nth(llist_t *l, int n, void *data, llist_fn_match_t fn_match)
{
	llist_item_t *i;
	if (n < 0)
		return NULL;
	for (i = l->head; i; i = i->next) {
		if (fn_match(i->data, data) && n-- == 0)
			return i;
	}
	return NULL;
}

void *llist_get_data(llist_item_t *i)
{
	return i ? i->data : NULL;
}

void llist_add(llist_t *l, void *data)
{
	llist_item_t *o = malloc(sizeof(llist_item_t));
	o->data = data;
	o->next = NULL;
	if (l->tail)
		l->tail->next = o;
	else
		l->head = o;
	l->tail = o;
}

/* Insert after all items that compare <= to the new item (stable). */
void llist_add_sorted(llist_t *l, void *data, llist_fn_cmp_t fn_cmp)
{
	llist_item_t *o = malloc(sizeof(llist_item_t));
	llist_item_t *i;
	o->data = data;
	o->next = NULL;
	if (!l->head) {
		l->head = l->tail = o;
	} else if (fn_cmp(data, l->tail->data) >= 0) {
		l->tail->next = o;
		l->tail = o;
	} else if (fn_cmp(data, l->head->data) < 0) {
		o->next = l->head;
		l->head = o;
	} else {
		i = l->head;
		while (i->next && fn_cmp(data, i->next->data) >= 0)
			i = i->next;
		o->next = i->next;
		i->next = o;
	}
}

void llist_remove(llist_t *l, llist_item_t *i)
{
	llist_item_t *j = NULL;
	if (l->head && i == l->head) {
		l->head = i->next;
		if (i == l->tail)
			l->tail = NULL;
	} else {
		for (j = l->head; j && j->next != i; j = j->next) ;
		if (!j)
			return;
		j->next = i->next;
		if (i == l->tail)
			l->tail = j;
	}
	free(i);
}

int llist_count(llist_t *l)
{
	int n = 0;
	llist_item_t *i;
	for (i = l->head; i; i = i->next)
		n++;
	return n;
}
EOF
echo done"}

