	 ((unsigned char)ch >= 0xE0) ? 3 : \
	 ((unsigned char)ch >= 0xC0) ? 2 : 1)
#define UTF8_ISCONT(ch) ((unsigned char)ch >= 0x80 && (unsigned char)ch <= 0xBF)
