#define DATEFMT(datefmt) (datefmt == DATEFMT_MMDDYYYY ? "%m/%d/%Y" : \
		datefmt == DATEFMT_DDMMYYYY ? "%d/%m/%Y" : \
		datefmt == DATEFMT_YYYYMMDD ? "%Y/%m/%d" : "%Y-%m-%d")

#define DATEFMT_DESC(datefmt) (datefmt == DATEFMT_MMDDYYYY ? "mm/dd/yyyy" : \
