}

int fork_exec(int *pfdin, int *pfdout, int *pfderr, const char *path, const char *const *arg)
{
	int pin[2], pout[2], perr[2];
	int pid;

	if (pfdin && (pipe(pin) == -1))
		return 0;
	if (pfdout && (pipe(pout) == -1))
		return 0;
	if (pfderr && (pipe(perr) == -1))
		return 0;

	if ((pid = fork()) == 0) {
		if (pfderr) {
			if (dup2(perr[0], STDERR_FILENO) < 0)
				_exit(127);
			close(perr[0]);
			close(perr[1]);
		}
		if (pfdout) {
			if (dup2(pout[0], STDIN_FILENO) < 0)
				_exit(127);
			close(pout[0]);
			close(pout[1]);
		}
		if (pfdin) {
			if (dup2(pin[1], STDOUT_FILENO) < 0)
				_exit(127);
			close(pin[0]);
			close(pin[1]);
		}
		execvp(path, (char *const *)arg);
		_exit(127);
	} else {
		if (pfdin)
			close(pin[1]);
		if (pfdout)
			close(pout[0]);
		if (pfderr)
			close(perr[0]);
		if (pid > 0) {
			if (pfdin) {
				fcntl(pin[0], F_SETFD, FD_CLOEXEC);
				*pfdin = pin[0];
			}
			if (pfdout) {
				fcntl(pout[1], F_SETFD, FD_CLOEXEC);
				*pfdout = pout[1];
			}
			if (pfderr) {
				fcntl(perr[1], F_SETFD, FD_CLOEXEC);
				*pfderr = perr[1];
			}
		} else {
			if (pfdin)
				close(pin[0]);
			if (pfdout)
				close(pout[1]);
			if (pfderr)
				close(perr[1]);
			return 0;
		}
	}
	return pid;
}

int shell_exec(int *pfdin, int *pfdout, int *pfderr, const char *path, const char *const *arg)
{
	int argc, i;
	const char **narg;
	char *arg0 = NULL;
	int ret;

	for (argc = 0; arg[argc]; argc++) ;
	if (argc < 1)
		return -1;
	narg = mem_calloc(argc + 4, sizeof(const char *));
	narg[0] = "sh";
	narg[1] = "-c";
	if (argc > 1) {
		arg0 = mem_malloc(strlen(path) + 6);
		sprintf(arg0, "%s \"$@\"", path);
		narg[2] = arg0;
		for (i = 0; i < argc; i++)
			narg[i + 3] = arg[i];
		narg[argc + 3] = NULL;
	} else {
		narg[2] = path;
		narg[3] = NULL;
	}
	ret = fork_exec(pfdin, pfdout, pfderr, "/bin/sh", narg);
	if (arg0)
		mem_free(arg0);
	mem_free(narg);
	return ret;
}

int child_wait(int *pfdin, int *pfdout, int *pfderr, int pid)
{
	int stat;
	if (pfdin)
		close(*pfdin);
	if (pfdout)
		close(*pfdout);
	if (pfderr)
		close(*pfderr);
	if (waitpid(pid, &stat, 0) == pid)
