/* Format printing. */

/* Print the duration/remaining time with the special format. */
static void print_duration(const char *fmt, long dur)
{
	const char *p;
	long days = dur / DAYINSEC;
	long hours = (dur % DAYINSEC) / HOURINSEC;
	long mins = (dur % HOURINSEC) / MININSEC;
	long secs = dur % MININSEC;

	for (p = fmt; *p; p++) {
		if (*p == '%') {
			int pad = 1, extend = 0;
			p++;
			if (*p == '-') {
				pad = 0;
				p++;
			}
			if (*p == 'E') {
				extend = 1;
				p++;
			}
			switch (*p) {
			case 'd':
				printf(pad ? "%02ld" : "%ld", days);
				break;
			case 'H':
				printf(pad ? "%02ld" : "%ld", extend ? dur / HOURINSEC : hours);
				break;
			case 'M':
				printf(pad ? "%02ld" : "%ld", extend ? dur / MININSEC : mins);
				break;
			case 'S':
				printf(pad ? "%02ld" : "%ld", extend ? dur : secs);
				break;
			case '%':
				putchar('%');
				break;
			case '\0':
				return;
			default:
				putchar('?');
				break;
			}
		} else {
			putchar(*p);
		}
	}
}

static void print_time_fmt(const char *fmt, time_t t, time_t day, int is_end)
{
	char buf[BUFSIZ_LINE];
	struct tm tm;

	if (!fmt || !*fmt || !strcmp(fmt, "default")) {
		if (!is_end && t < day) {
			fputs("..:..", stdout);
		} else if (is_end && t > NEXTDAY(day)) {
			fputs("..:..", stdout);
		} else {
			localtime_r_safe(t, &tm);
			strftime(buf, sizeof(buf), "%H:%M", &tm);
			fputs(buf, stdout);
		}
	} else if (!strcmp(fmt, "epoch")) {
		printf("%ld", (long)t);
	} else {
		localtime_r_safe(t, &tm);
		if (strftime(buf, sizeof(buf), fmt, &tm) > 0)
			fputs(buf, stdout);
	}
}

static void print_notefile(const char *note)
{
	char *path;
	FILE *fp;
	int c;

	if (!note) {
		fputs("\tNo note file found\n", stdout);
		return;
	}
