/* Date and time utilities. */

int ISLEAP(int y)
{
	return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
}

int month_days(int month, int year)
{
	if (month == 2)
		return ISLEAP(year) ? 29 : 28;
	return days[month - 1];
}

void localtime_r_safe(time_t t, struct tm *tm)
{
	struct tm *p = localtime(&t);
	if (p)
		*tm = *p;
	else
		memset(tm, 0, sizeof(*tm));
}

time_t now(void)
{
	return time(NULL);
}

time_t get_today(void)
{
	time_t t = time(NULL);
	struct tm tm;
	localtime_r_safe(t, &tm);
	tm.tm_hour = 0;
	tm.tm_min = 0;
	tm.tm_sec = 0;
	tm.tm_isdst = -1;
	return mktime(&tm);
}

time_t TODAY(void)
{
	return get_today();
}

time_t DAY(time_t t)
{
	return update_time_in_date(t, 0, 0);
}

time_t NEXTDAY(time_t t)
{
	return date_sec_change(DAY(t), 0, 1);
}

time_t ENDOFDAY(time_t t)
{
	return NEXTDAY(t) - 1;
}

time_t date2sec(struct date day, unsigned hour, unsigned min)
{
	struct tm tm;
	memset(&tm, 0, sizeof(tm));
	tm.tm_year = day.yyyy - TM_YEAR_BASE;
	tm.tm_mon = day.mm - 1;
	tm.tm_mday = day.dd;
	tm.tm_hour = hour;
	tm.tm_min = min;
	tm.tm_sec = 0;
	tm.tm_isdst = -1;
	return mktime(&tm);
}

time_t update_time_in_date(time_t date, unsigned hr, unsigned mn)
{
	struct tm tm;
	localtime_r_safe(date, &tm);
	tm.tm_hour = hr;
	tm.tm_min = mn;
	tm.tm_sec = 0;
	tm.tm_isdst = -1;
	return mktime(&tm);
}

time_t date_sec_change(time_t date, int delta_month, int delta_day)
{
	struct tm tm;
	localtime_r_safe(date, &tm);
	tm.tm_mon += delta_month;
	tm.tm_mday += delta_day;
	tm.tm_isdst = -1;
	return mktime(&tm);
}

/* Compare the dates (ignoring the time of day) of two timestamps. */
long date_cmp_day(time_t d1, time_t d2)
{
	struct tm t1, t2;
	localtime_r_safe(d1, &t1);
	localtime_r_safe(d2, &t2);
	if (t1.tm_year != t2.tm_year)
		return t1.tm_year - t2.tm_year;
	if (t1.tm_mon != t2.tm_mon)
		return t1.tm_mon - t2.tm_mon;
	return t1.tm_mday - t2.tm_mday;
}

long get_item_time(time_t date)
{
	return (long)(get_item_hour(date) * HOURINSEC + get_item_min(date) * MININSEC);
}

int get_item_hour(time_t date)
{
	struct tm tm;
	localtime_r_safe(date, &tm);
