int check_date(unsigned year, unsigned month, unsigned day)
{
	return (year >= 1 && month >= 1 && month <= 12 && day >= 1 &&
		day <= (unsigned)month_days(month, year));
}

int check_time(unsigned hours, unsigned minutes)
{
	return hours < DAYINHOUR && minutes < HOURINMIN;
}

int is_all_digit(const char *string)
{
	if (!*string)
		return 0;
	for (; *string; string++) {
		if (!isdigit((unsigned char)*string))
			return 0;
	}
	return 1;
}

/* Convert a string to a long; return 1 on success (whole string consumed). */
int strtol_safe(const char *s, long *val)
{
	char *end;
	long v;
	if (!s || !*s)
		return 0;
	errno = 0;
	v = strtol(s, &end, 10);
	if (errno || *end)
		return 0;
	*val = v;
	return 1;
}

static const char *wday_full[7] = {
	"sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"
};
static const char *wday_abbr[7] = { "sun", "mon", "tue", "wed", "thu", "fri", "sat" };

/*
 * Parse a date string.  Returns 1 on success with year/month/day set.
 * If slctd_date is non-NULL, incomplete dates are completed from it.
 */
int parse_date(const char *date_string, enum datefmt datefmt, int *year,
	       int *month, int *day, struct date *slctd_date)
{
	const char sep = (datefmt == DATEFMT_ISO) ? '-' : '/';
	const char *p;
	int in[3] = { 0, 0, 0 }, n = 0;
	int d, m, y;
	int i;

	if (!date_string)
		return 0;

	if (!strcasecmp(date_string, "today") || !strcasecmp(date_string, "now")) {
		time_t t = get_today();
		struct tm tm;
		localtime_r_safe(t, &tm);
		y = tm.tm_year + TM_YEAR_BASE;
		m = tm.tm_mon + 1;
		d = tm.tm_mday;
		goto done;
	} else if (!strcasecmp(date_string, "yesterday")) {
		time_t t = date_sec_change(get_today(), 0, -1);
		struct tm tm;
		localtime_r_safe(t, &tm);
		y = tm.tm_year + TM_YEAR_BASE;
		m = tm.tm_mon + 1;
		d = tm.tm_mday;
		goto done;
	} else if (!strcasecmp(date_string, "tomorrow")) {
		time_t t = date_sec_change(get_today(), 0, 1);
		struct tm tm;
		localtime_r_safe(t, &tm);
		y = tm.tm_year + TM_YEAR_BASE;
		m = tm.tm_mon + 1;
		d = tm.tm_mday;
		goto done;
	}

	for (i = 0; i < 7; i++) {
		if (!strcasecmp(date_string, wday_abbr[i]) ||
		    !strcasecmp(date_string, wday_full[i])) {
			time_t t = get_today();
			struct tm tm;
			int delta;
			localtime_r_safe(t, &tm);
			delta = i - tm.tm_wday;
			if (delta <= 0)
				delta = 7;
			t = date_sec_change(t, 0, delta);
			localtime_r_safe(t, &tm);
			y = tm.tm_year + TM_YEAR_BASE;
			m = tm.tm_mon + 1;
			d = tm.tm_mday;
			goto done;
		}
	}

	/* parse string into in[], read up to three integers */
	for (p = date_string; *p; p++) {
		if (*p == sep) {
			if ((++n) > 2)
				return 0;
		} else if ((*p >= '0') && (*p <= '9')) {
			in[n] = in[n] * 10 + (int)(*p - '0');
		} else {
			return 0;
		}
	}

	if ((!slctd_date && n < 2) || in[n] == 0)
		return 0;

	/* convert into day, month, year, depending on the date format */
	switch (datefmt) {
	case DATEFMT_MMDDYYYY:
		m = (n >= 1) ? in[0] : 0;
		d = (n >= 1) ? in[1] : in[0];
		y = in[2];
		break;
	case DATEFMT_DDMMYYYY:
		d = in[0];
		m = in[1];
		y = in[2];
		break;
	case DATEFMT_YYYYMMDD:
	case DATEFMT_ISO:
		if (n == 1) {
			m = in[0];
			d = in[1];
			y = 0;
		} else {
			y = in[0];
			m = in[1];
			d = in[2];
		}
		break;
	default:
		return 0;
	}

	if (slctd_date) {
		if (y > 0 && y < 100) {
			/* convert "YY" format into "YYYY" */
			y += slctd_date->yyyy - slctd_date->yyyy % 100;
		} else if (y == 0) {
			y = slctd_date->yyyy;
		}
		if (m == 0)
			m = slctd_date->mm;
	}

	if (!check_date(y, m, d))
		return 0;

done:
	if (year)
		*year = y;
	if (month)
		*month = m;
	if (day)
		*day = d;
	return 1;
}

/* Parse a time string of the form hh:mm or hhmm (or h:mm, hmm?). */
int parse_time(const char *string, unsigned *hour, unsigned *minute)
{
	const char *p;
	unsigned in[2] = { 0, 0 }, n = 0;
	int ndig = 0;

	if (!string)
		return 0;

	for (p = string; *p; p++) {
		if (*p == ':') {
			if ((++n) > 1)
				return 0;
			ndig = 0;
		} else if ((*p >= '0') && (*p <= '9')) {
			if (ndig >= 2 && n == 1)
				return 0;
			in[n] = in[n] * 10 + (unsigned)(*p - '0');
			ndig++;
		} else {
			return 0;
		}
	}

	if (n == 0) {
		/* no colon: interpret as hhmm (3 or 4 digits) */
		if (ndig < 3)
			return 0;
		in[1] = in[0] % 100;
		in[0] = in[0] / 100;
	} else if (p == string + 1 || *(p - 1) == ':') {
		return 0;
	}

	if (!check_time(in[0], in[1]))
		return 0;

	*hour = in[0];
	*minute = in[1];
	return 1;
}

/*
 * Parse a duration: "+hh:mm", "+mm", "+xxdxxhxxm" (with leading + optional
 * when called from the appointment dialog).  Result in minutes.
 */
int parse_duration(const char *string, unsigned *duration, time_t start)
{
	const char *p;
	unsigned in = 0, frac = 0, denom = 1;
	unsigned dur = 0;
	int has_unit = 0;
	enum { STATE_INITIAL, STATE_HHMM_MM, STATE_DDHHMM_HH, STATE_DDHHMM_MM, STATE_DONE } state = STATE_INITIAL;

	if (!string || !*string)
		return 0;

	for (p = string; *p; p++) {
		if (*p == ':') {
			if (state != STATE_INITIAL)
				return 0;
			dur += in * HOURINMIN;
			in = 0;
			state = STATE_HHMM_MM;
		} else if (*p == 'd') {
			if (state != STATE_INITIAL)
				return 0;
			dur += in * DAYINMIN;
			in = 0;
			has_unit = 1;
			state = STATE_DDHHMM_HH;
		} else if (*p == 'h') {
			if (state != STATE_INITIAL && state != STATE_DDHHMM_HH)
				return 0;
			dur += in * HOURINMIN;
			in = 0;
			has_unit = 1;
			state = STATE_DDHHMM_MM;
		} else if (*p == 'm') {
			if (state != STATE_INITIAL && state != STATE_DDHHMM_HH && state != STATE_DDHHMM_MM)
				return 0;
			dur += in;
			in = 0;
			has_unit = 1;
			state = STATE_DONE;
		} else if (*p >= '0' && *p <= '9') {
			if (state == STATE_DONE)
				return 0;
			in = in * 10 + (unsigned)(*p - '0');
		} else {
			return 0;
		}
	}
	(void)frac;
	(void)denom;

	if (state == STATE_HHMM_MM) {
		if (in >= HOURINMIN)
			return 0;
		dur += in;
	} else if (state == STATE_INITIAL) {
		if (has_unit)
			return 0;
		dur += in;
	} else if (state == STATE_DDHHMM_HH || state == STATE_DDHHMM_MM) {
		/* trailing digits without unit */
		if (in != 0 || *(p - 1) >= '0' && *(p - 1) <= '9')
			return 0;
	} else if (state == STATE_DONE) {
		if (in != 0)
			return 0;
	}

	*duration = dur;
	return 1;
}

/*
 * Parse a date and optional time of the form "<date> [hh:mm]", used by
 * filter and day range options.  Returns the timestamp in *ts.
 */
int parse_datetime(const char *string, time_t *ts, time_t dur)
{
	char *t = mem_strdup(string);
	char *p = strchr(t, ' ');
	int y, m, d, ret = 0;
	unsigned hour = 0, min = 0;
	struct date dt;

	if (p) {
		*p = '\0';
		p++;
	}
	if (!parse_date(t, conf.input_datefmt, &y, &m, &d, NULL))
		goto out;
	if (p && !parse_time(p, &hour, &min))
		goto out;
	dt.yyyy = y;
	dt.mm = m;
	dt.dd = d;
	*ts = date2sec(dt, hour, min);
	ret = 1;
out:
	mem_free(t);
	return ret;
}

