const char *get_tempdir(void)
{
	const char *t = getenv("TMPDIR");
	if (t && *t)
		return t;
	return "/tmp";
}

/* Create a temporary file; returns the malloc'ed name (fd closed). */
char *new_tempfile(const char *prefix)
{
	char *fullname = strdup_printf("%s/%s.XXXXXX", get_tempdir(), prefix);
	int fd = mkstemp(fullname);
	if (fd == -1) {
		mem_free(fullname);
		return NULL;
	}
	close(fd);
	return fullname;
}

int mkdir_p(const char *path)
{
	char *p = mem_strdup(path);
	char *q;
	int ret = 0;
	struct stat st;

	for (q = p + 1; *q; q++) {
		if (*q == '/') {
			*q = '\0';
			if (stat(p, &st) != 0) {
				if (mkdir(p, 0700) != 0 && errno != EEXIST) {
					ret = -1;
					goto out;
				}
			}
			*q = '/';
		}
	}
	if (stat(p, &st) != 0) {
		if (mkdir(p, 0700) != 0 && errno != EEXIST)
			ret = -1;
	}
out:
	mem_free(p);
	return ret;
}

void file_close(FILE *f, const char *pos, int line)
{
