		EXIT_ON_ERROR(pos, line, "Error when closing file at %s", pos);
}

void psleep(unsigned secs)
{
	unsigned unslept;
	for (unslept = sleep(secs); unslept; unslept = sleep(unslept)) ;
}

int fork_exec(int *pfdin, int *pfdout, int *pfderr, const char *path, const char *const *arg)
{
	int pin[2], pout[2], perr[2];
	int pid;

	if (pfdin && (pipe(pin) == -1))
		return 0;
	if (pfdout && (pipe(pout) == -1))
		return 0;
	if (pfderr && (pipe(perr) == -1))
		return 0;

	if ((pid = fork()) == 0) {
		if (pfderr) {
			if (dup2(perr[0], STDERR_FILENO) < 0)
				_exit(127);
			close(perr[0]);
			close(perr[1]);
		}
		if (pfdout) {
			if (dup2(pout[0], STDIN_FILENO) < 0)
				_exit(127);
			close(pout[0]);
			close(pout[1]);
		}
		if (pfdin) {
			if (dup2(pin[1], STDOUT_FILENO) < 0)
				_exit(127);
			close(pin[0]);
			close(pin[1]);
		}
		execvp(path, (char *const *)arg);
		_exit(127);
	} else {
		if (pfdin)
			close(pin[1]);
		if (pfdout)
			close(pout[0]);
		if (pfderr)
			close(perr[0]);
		if (pid > 0) {
			if (pfdin) {
				fcntl(pin[0], F_SETFD, FD_CLOEXEC);
				*pfdin = pin[0];
			}
			if (pfdout) {
				fcntl(pout[1], F_SETFD, FD_CLOEXEC);
				*pfdout = pout[1];
			}
			if (pfderr) {
				fcntl(perr[1], F_SETFD, FD_CLOEXEC);
				*pfderr = perr[1];
			}
		} else {
			if (pfdin)
				close(pin[0]);
			if (pfdout)
				close(pout[1]);
			if (pfderr)
				close(perr[1]);
			return 0;
		}
	}
	return pid;
}

int shell_exec(int *pfdin, int *pfdout, int *pfderr, const char *path, const char *const *arg)
{
	int argc, i;
	const char **narg;
	char *arg0 = NULL;
	int ret;

	for (argc = 0; arg[argc]; argc++) ;
	if (argc < 1)
		return -1;
	narg = mem_calloc(argc + 4, sizeof(const char *));
	narg[0] = "sh";
	narg[1] = "-c";
	if (argc > 1) {
		arg0 = mem_malloc(strlen(path) + 6);
		sprintf(arg0, "%s \"$@\"", path);
		narg[2] = arg0;
		for (i = 0; i < argc; i++)
			narg[i + 3] = arg[i];
		narg[argc + 3] = NULL;
	} else {
		narg[2] = path;
		narg[3] = NULL;
	}
	ret = fork_exec(pfdin, pfdout, pfderr, "/bin/sh", narg);
	if (arg0)
		mem_free(arg0);
	mem_free(narg);
	return ret;
}

int child_wait(int *pfdin, int *pfdout, int *pfderr, int pid)
{
	int stat;
	if (pfdin)
		close(*pfdin);
	if (pfdout)
		close(*pfdout);
	if (pfderr)
		close(*pfderr);
	if (waitpid(pid, &stat, 0) == pid)
		return stat;
	return -1;
}

void str_toupper(char *s)
{
	for (; *s; s++)
		*s = toupper((unsigned char)*s);
}

char *trim(char *s)
{
	char *e;
	while (*s && isspace((unsigned char)*s))
		s++;
	e = s + strlen(s);
	while (e > s && isspace((unsigned char)*(e - 1)))
		e--;
	*e = '\0';
	return s;
}

int starts_with(const char *s, const char *p)
{
	for (; *p && *s; s++, p++) {
		if (*s != *p)
			return 0;
	}
	return (*p == '\0');
}

int starts_with_ci(const char *s, const char *p)
{
	for (; *p && *s; s++, p++) {
		if (tolower((unsigned char)*s) != tolower((unsigned char)*p))
			return 0;
	}
	return (*p == '\0');
}

int hash_matches(const char *pattern, const char *hash)
{
	int invert = 0, ret;
	if (pattern[0] == '!') {
		invert = 1;
		pattern++;
	}
	ret = (strncmp(pattern, hash, strlen(pattern)) == 0);
	return (ret != invert);
}

/* Width in columns of a UTF-8 string. */
int string_width(const char *s)
{
	int w = 0;
	size_t n;
	mbstate_t st;
	wchar_t wc;
	memset(&st, 0, sizeof(st));
	while (*s) {
		n = mbrtowc(&wc, s, MB_CUR_MAX, &st);
		if (n == (size_t)-1 || n == (size_t)-2) {
			w++;
			s++;
			memset(&st, 0, sizeof(st));
			continue;
		}
		if (n == 0)
			break;
		{
			int cw = wcwidth(wc);
			w += cw < 0 ? 1 : cw;
		}
		s += n;
	}
	return w;
}

long overflow_mul(long x, long y, long *z)
{
	if (y != 0 && (x > LONG_MAX / y || x < LONG_MIN / y))
		return 1;
	*z = x * y;
	return 0;
}

long overflow_add(long x, long y, long *z)
{
	if ((y > 0 && x > LONG_MAX - y) || (y < 0 && x < LONG_MIN - y))
		return 1;
	*z = x + y;
	return 0;
}

char *nowstr(void)
{
