}

static int print_escape(const char **pp)
{
	const char *p = *pp;
	switch (*p) {
	case 'a': putchar('\a'); break;
	case 'b': putchar('\b'); break;
	case 'f': putchar('\f'); break;
	case 'n': putchar('\n'); break;
	case 'r': putchar('\r'); break;
	case 't': putchar('\t'); break;
	case 'v': putchar('\v'); break;
	case '\\': putchar('\\'); break;
	case '\'': putchar('\''); break;
	case '"': putchar('"'); break;
	case '?': putchar('?'); break;
	case '0': putchar('\0'); break;
	case '\0': return 0;
	default: break;
	}
	return 1;
}

/*
 * Parse an extended specifier "%(name[:fmt])".  *pp points after the
 * opening parenthesis.  Returns 1 on success, 0 if the closing
 * parenthesis is missing (the rest of the string is then consumed).
 */
static int parse_extended(const char **pp, char *name, size_t nsz, char *fmt, size_t fsz)
{
	const char *p = *pp;
	size_t i = 0;

	name[0] = '\0';
	fmt[0] = '\0';
	while (*p && *p != ':' && *p != ')') {
		if (i + 1 < nsz)
			name[i++] = *p;
		p++;
	}
	name[i] = '\0';
	if (*p == ':') {
		p++;
		i = 0;
		while (*p && *p != ')') {
			if (i + 1 < fsz)
				fmt[i++] = *p;
			p++;
		}
		fmt[i] = '\0';
	}
	if (*p != ')') {
		*pp = p;
		return 0;
	}
	*pp = p + 1;
	return 1;
}

enum fmt_item_type { FMT_APT, FMT_RAPT, FMT_EV, FMT_REV, FMT_TODO };

struct fmt_item {
	enum fmt_item_type type;
	time_t day;
	time_t start;
	long dur;
	const char *mesg;
	const char *note;
	int priority;
	char *(*tostr)(void *);
	char *(*hash)(void *);
	void *ptr;
};

static void print_item(const char *format, struct fmt_item *it)
{
	const char *p;
	char name[BUFSIZ_LINE], fmt[BUFSIZ_LINE];
	int is_apt = (it->type == FMT_APT || it->type == FMT_RAPT);
	char *s;

	for (p = format; *p; p++) {
		if (*p == '\\') {
			p++;
			if (!print_escape(&p))
				return;
			continue;
		}
		if (*p != '%') {
			putchar(*p);
			continue;
		}
		p++;
		switch (*p) {
		case '\0':
			return;
		case '%':
			putchar('%');
			break;
		case 'm':
			fputs(it->mesg, stdout);
			break;
		case 'n':
			printf("%s", it->note);
			break;
		case 'N':
			print_notefile(it->note);
			break;
		case 's':
			if (is_apt)
				printf("%ld", (long)it->start);
			else
				putchar('?');
			break;
		case 'S':
			if (is_apt)
				print_time_fmt("default", it->start, it->day, 0);
			else
				putchar('?');
			break;
		case 'd':
			if (is_apt)
				printf("%ld", it->dur);
			else
				putchar('?');
			break;
		case 'e':
			if (is_apt)
				printf("%ld", (long)(it->start + it->dur));
			else
				putchar('?');
			break;
		case 'E':
			if (is_apt)
				print_time_fmt("default", it->start + it->dur, it->day, 1);
			else
				putchar('?');
			break;
		case 'r':
			if (is_apt)
				print_duration("%EH:%M", (long)(it->start - now()));
			else
				putchar('?');
			break;
		case 'p':
			if (it->type == FMT_TODO)
				printf("%d", it->priority);
			else
				putchar('?');
			break;
		case '(':
			p++;
			if (!parse_extended(&p, name, sizeof(name), fmt, sizeof(fmt)))
				return;
			p--;
			if (!strcmp(name, "message")) {
				fputs(it->mesg, stdout);
			} else if (!strcmp(name, "noteid")) {
				printf("%s", it->note);
			} else if (!strcmp(name, "note")) {
				print_notefile(it->note);
			} else if (!strcmp(name, "raw")) {
				s = it->tostr(it->ptr);
				fputs(s, stdout);
				mem_free(s);
			} else if (!strcmp(name, "hash")) {
				s = it->hash(it->ptr);
				fputs(s, stdout);
				mem_free(s);
			} else if (is_apt && !strcmp(name, "start")) {
				print_time_fmt(fmt, it->start, it->day, 0);
			} else if (is_apt && !strcmp(name, "end")) {
				print_time_fmt(fmt, it->start + it->dur, it->day, 1);
			} else if (is_apt && !strcmp(name, "duration")) {
				if (*fmt)
					print_duration(fmt, it->dur);
				else
					printf("%ld", it->dur);
			} else if (is_apt && !strcmp(name, "remaining")) {
				print_duration(*fmt ? fmt : "%EH:%M", (long)(it->start - now()));
			} else if (it->type == FMT_TODO && !strcmp(name, "priority")) {
				printf("%d", it->priority);
			} else {
				putchar('?');
			}
			break;
		default:
			putchar('?');
			break;
		}
	}
}

void print_apoint(const char *format, time_t day, struct apoint *apt)
{
	struct fmt_item it;
	it.type = FMT_APT;
	it.day = day;
	it.start = apt->start;
	it.dur = apt->dur;
	it.mesg = apt->mesg;
	it.note = apt->note;
	it.priority = 0;
	it.tostr = (char *(*)(void *))apoint_tostr;
	it.hash = (char *(*)(void *))apoint_hash;
	it.ptr = apt;
	print_item(format, &it);
}

void print_event(const char *format, time_t day, struct event *ev)
{
	struct fmt_item it;
	it.type = FMT_EV;
	it.day = day;
	it.start = ev->day;
	it.dur = 0;
	it.mesg = ev->mesg;
	it.note = ev->note;
	it.priority = 0;
	it.tostr = (char *(*)(void *))event_tostr;
	it.hash = (char *(*)(void *))event_hash;
	it.ptr = ev;
	print_item(format, &it);
}

void print_recur_apoint(const char *format, time_t day, time_t occurrence, struct recur_apoint *rapt)
{
	struct fmt_item it;
	it.type = FMT_RAPT;
	it.day = day;
	it.start = occurrence;
	it.dur = rapt->dur;
	it.mesg = rapt->mesg;
	it.note = rapt->note;
	it.priority = 0;
	it.tostr = (char *(*)(void *))recur_apoint_tostr;
	it.hash = (char *(*)(void *))recur_apoint_hash;
	it.ptr = rapt;
	print_item(format, &it);
}

void print_recur_event(const char *format, time_t day, struct recur_event *rev)
{
	struct fmt_item it;
	it.type = FMT_REV;
	it.day = day;
	it.start = rev->day;
	it.dur = 0;
	it.mesg = rev->mesg;
	it.note = rev->note;
	it.priority = 0;
	it.tostr = (char *(*)(void *))recur_event_tostr;
	it.hash = (char *(*)(void *))recur_event_hash;
	it.ptr = rev;
	print_item(format, &it);
}

void print_todo(const char *format, struct todo *todo)
{
	struct fmt_item it;
	it.type = FMT_TODO;
	it.day = 0;
	it.start = 0;
	it.dur = 0;
	it.mesg = todo->mesg;
	it.note = todo->note;
	it.priority = todo->id;
	it.tostr = (char *(*)(void *))todo_tostr;
	it.hash = (char *(*)(void *))todo_hash;
	it.ptr = todo;
	print_item(format, &it);
}
