}

void apoint_llist_free(void)
{
	LLIST_FREE_INNER(&alist_p, apoint_free);
	LLIST_FREE(&alist_p);
}

int apoint_cmp(struct apoint *a, struct apoint *b)
{
	if (a->start < b->start)
		return -1;
	if (a->start > b->start)
		return 1;
	if ((a->state & APOINT_NOTIFY) && !(b->state & APOINT_NOTIFY))
		return -1;
	if (!(a->state & APOINT_NOTIFY) && (b->state & APOINT_NOTIFY))
		return 1;
	return strcmp(a->mesg, b->mesg);
}

struct apoint *apoint_new(const char *mesg, const char *note, time_t start, long dur, char state)
{
	struct apoint *apt = mem_malloc(sizeof(struct apoint));
	apt->mesg = mem_strdup(mesg);
	apt->note = (note != NULL) ? mem_strdup(note) : NULL;
	apt->state = state;
	apt->start = start;
	apt->dur = dur;
	LLIST_ADD_SORTED(&alist_p, apt, apoint_cmp);
	return apt;
}

unsigned apoint_inday(struct apoint *i, time_t *start)
{
	time_t d = DAY(*start);
	return (i->start < d + DAYINSEC && i->start + i->dur > d);
}

void apoint_sec2str(struct apoint *o, time_t day, char *start, char *end)
{
	struct tm tm;
	time_t t;

	if (o->start < day) {
		strcpy(start, "..:..");
	} else {
		localtime_r_safe(o->start, &tm);
		strftime(start, HOURINMIN, "%H:%M", &tm);
	}
	t = o->start + o->dur;
	if (t > NEXTDAY(day)) {
		strcpy(end, "..:..");
	} else {
		localtime_r_safe(t, &tm);
		strftime(end, HOURINMIN, "%H:%M", &tm);
	}
}

char *apoint_tostr(struct apoint *o)
{
	struct tm tm;
	char str_start[BUFSIZ_LINE], str_end[BUFSIZ_LINE];
	time_t t;
	char *s;

	localtime_r_safe(o->start, &tm);
	strftime(str_start, sizeof(str_start), "%m/%d/%Y @ %H:%M", &tm);
	t = o->start + o->dur;
	localtime_r_safe(t, &tm);
	strftime(str_end, sizeof(str_end), "%m/%d/%Y @ %H:%M", &tm);

	if (o->note)
		s = strdup_printf("%s -> %s>%s %c%s\n", str_start, str_end, o->note,
				  (o->state & APOINT_NOTIFY) ? '!' : '|', o->mesg);
	else
		s = strdup_printf("%s -> %s%c%s\n", str_start, str_end,
				  (o->state & APOINT_NOTIFY) ? '!' : '|', o->mesg);
	return s;
}

char *apoint_hash(struct apoint *apt)
{
	char *raw = apoint_tostr(apt);
	char *sha = mem_malloc(41);
	size_t l = strlen(raw);
	if (l && raw[l - 1] == '\n')
		raw[l - 1] = '\0';
	sha1_digest(raw, sha);
	mem_free(raw);
	return sha;
}

void apoint_write(struct apoint *o, FILE *f)
{
	char *s = apoint_tostr(o);
	fputs(s, f);
	mem_free(s);
}

void apoint_delete(struct apoint *apt)
{
	llist_item_t *i = LLIST_FIND_FIRST(&alist_p, apt, NULL);
	int need_check_notify = 0;

	LLIST_FOREACH(&alist_p, i) {
		if (LLIST_GET_DATA(i) == apt)
			break;
	}
	if (!i)
		EXIT_ON_ERROR("apoint.c", 230, "no such appointment");

	if (ui_mode == UI_CURSES && notify_bar())
		need_check_notify = notify_same_item(apt->start);
	LLIST_REMOVE(&alist_p, i);
	apoint_free(apt);
	if (need_check_notify)
		notify_check_next_app(0);
}

void apoint_switch_notify(struct apoint *apt)
{
	apt->state ^= APOINT_NOTIFY;
	if (ui_mode == UI_CURSES && notify_bar())
		notify_check_added(apt->mesg, apt->start, apt->state);
}

void apoint_paste_item(struct apoint *apt, time_t date)
{
	apt->start = date + get_item_time(apt->start);
	LLIST_ADD_SORTED(&alist_p, apt, apoint_cmp);
}
