llist_t todolist;

void todo_free(struct todo *todo)
{
	mem_free(todo->mesg);
	erase_note(&todo->note);
	mem_free(todo);
}

int todo_cmp(struct todo *a, struct todo *b)
{
	int pa, pb;
	if (a->completed && !b->completed)
		return 1;
	if (!a->completed && b->completed)
		return -1;
	pa = a->id == 0 ? 10 : a->id;
	pb = b->id == 0 ? 10 : b->id;
	if (pa != pb)
		return pa - pb;
	return strcmp(a->mesg, b->mesg);
}

struct todo *todo_add(const char *mesg, int id, int completed, const char *note)
{
	struct todo *todo = mem_malloc(sizeof(struct todo));
	todo->mesg = mem_strdup(mesg);
	todo->id = id;
	todo->completed = completed;
	todo->note = (note != NULL && note[0] != '\0') ? mem_strdup(note) : NULL;
	LLIST_ADD_SORTED(&todolist, todo, todo_cmp);
	return todo;
}

char *todo_tostr(struct todo *todo)
{
	if (todo->note)
		return strdup_printf("[%s%d]>%s %s\n", todo->completed ? "-" : "",
				     todo->id, todo->note, todo->mesg);
	return strdup_printf("[%s%d] %s\n", todo->completed ? "-" : "", todo->id, todo->mesg);
}

