/* Create a note file from a string, return the (malloc'ed) note id. */
char *generate_note(const char *str)
{
	char *sha1 = mem_malloc(41);
	char *notepath;
	FILE *fp;

	sha1_digest(str, sha1);
	notepath = strdup_printf("%s%s", path_notes, sha1);
	fp = fopen(notepath, "w");
	if (fp) {
		fputs(str, fp);
		file_close(fp, "note.c", 50);
	}
	mem_free(notepath);
	return sha1;
}

/* Read the note id following a '>' in a data file (up to whitespace). */
void note_read(char *buffer, FILE *fp)
{
	int i;
	for (i = 0; i < MAX_NOTESIZ; i++) {
		buffer[i] = getc(fp);
		if (buffer[i] == ' ') {
			buffer[i] = '\0';
			return;
		}
	}
	while (getc(fp) != ' ') ;
	buffer[MAX_NOTESIZ] = '\0';
}

/* Read a note id into buffer; stops at whitespace, like fscanf("%s "). */
void note_read_contents(char *buffer, size_t bufsize, FILE *fp)
{
	size_t i = 0;
	int c;

	for (;;) {
		c = getc(fp);
		if (c == EOF)
			break;
		if (isspace(c)) {
			ungetc(c, fp);
			break;
		}
		if (i + 1 < bufsize)
			buffer[i++] = c;
	}
	buffer[i] = '\0';
}

char *note_read_file(const char *note)
{
	char *path, *buf = NULL;
	FILE *fp;
	long sz;
	size_t n;

	if (!note)
		return NULL;
	path = strdup_printf("%s%s", path_notes, note);
	fp = fopen(path, "r");
	mem_free(path);
	if (!fp)
		return NULL;
	fseek(fp, 0, SEEK_END);
	sz = ftell(fp);
	fseek(fp, 0, SEEK_SET);
	if (sz < 0)
		sz = 0;
	buf = mem_malloc(sz + 1);
	n = fread(buf, 1, sz, fp);
	buf[n] = '\0';
	fclose(fp);
	return buf;
}

void erase_note(char **note)
{
	if (*note == NULL)
		return;
	mem_free(*note);
	*note = NULL;
}

/* Edit a note with the external editor. */
void edit_note(char **note, const char *editor)
{
	char *tmpprefix = NULL, *tmppath = NULL;
	char *notepath = NULL;
	char *sha1 = mem_malloc(41);
	FILE *fp;
	uint8_t digest[20];
	int i;
	struct stat st;

	tmpprefix = strdup_printf("%s/calcurse-note", get_tempdir());
	if ((tmppath = new_tempfile(tmpprefix + strlen(get_tempdir()) + 1)) == NULL)
		goto cleanup;

	if (*note != NULL) {
		notepath = strdup_printf("%s%s", path_notes, *note);
		io_file_cp(notepath, tmppath);
		mem_free(notepath);
	}

	{
		const char *arg[] = { editor, tmppath, NULL };
		int pid = shell_exec(NULL, NULL, NULL, editor, arg);
		if (pid > 0)
			child_wait(NULL, NULL, NULL, pid);
	}

	if (stat(tmppath, &st) != 0 || st.st_size <= 0) {
		if (*note) {
			mem_free(*note);
			*note = NULL;
		}
		goto cleanup;
	}

	if ((fp = fopen(tmppath, "r")) == NULL)
		goto cleanup;
	sha1_stream(fp, digest);
	fclose(fp);
	for (i = 0; i < 20; i++)
		sprintf(sha1 + i * 2, "%02x", digest[i]);
	sha1[40] = '\0';

	if (*note)
		mem_free(*note);
	*note = sha1;
	sha1 = NULL;

	notepath = strdup_printf("%s%s", path_notes, *note);
	io_file_cp(tmppath, notepath);
	mem_free(notepath);

cleanup:
	if (tmppath) {
		unlink(tmppath);
		mem_free(tmppath);
	}
	if (tmpprefix)
		mem_free(tmpprefix);
	if (sha1)
		mem_free(sha1);
}

void view_note(const char *note, const char *pager)
{
	char *fullname;
	if (note == NULL)
		return;
	fullname = strdup_printf("%s%s", path_notes, note);
	{
		const char *arg[] = { pager, fullname, NULL };
		int pid = shell_exec(NULL, NULL, NULL, pager, arg);
		if (pid > 0)
			child_wait(NULL, NULL, NULL, pid);
	}
	mem_free(fullname);
}

static int note_gc_extract_note(const char *note, llist_t *l)
{
	if (note)
		LLIST_ADD(l, mem_strdup(note));
	return 0;
}

static int note_match(char *a, const char *b)
{
	return !strcmp(a, b);
}

void note_gc(void)
{
	llist_t notes;
	llist_item_t *i;
	DIR *dirp;
	struct dirent *dp;
	char *notepath;

	LLIST_INIT(&notes);

	LLIST_FOREACH(&alist_p, i)
		note_gc_extract_note(((struct apoint *)LLIST_GET_DATA(i))->note, &notes);
	LLIST_FOREACH(&eventlist, i)
		note_gc_extract_note(((struct event *)LLIST_GET_DATA(i))->note, &notes);
	LLIST_FOREACH(&recur_alist_p, i)
		note_gc_extract_note(((struct recur_apoint *)LLIST_GET_DATA(i))->note, &notes);
	LLIST_FOREACH(&recur_elist, i)
		note_gc_extract_note(((struct recur_event *)LLIST_GET_DATA(i))->note, &notes);
	LLIST_FOREACH(&todolist, i)
		note_gc_extract_note(((struct todo *)LLIST_GET_DATA(i))->note, &notes);

	if ((dirp = opendir(path_notes)) == NULL)
		goto out;
	while ((dp = readdir(dirp)) != NULL) {
		if (!strcmp(dp->d_name, ".") || !strcmp(dp->d_name, ".."))
			continue;
		if (LLIST_FIND_FIRST(&notes, dp->d_name, note_match))
			continue;
		notepath = strdup_printf("%s%s", path_notes, dp->d_name);
		unlink(notepath);
		mem_free(notepath);
	}
	closedir(dirp);
out:
	LLIST_FREE_INNER(&notes, mem_free);
	LLIST_FREE(&notes);
}
