/* ---- textual representation ---- */

/* Append the "{...}" recurrence specification to a string buffer. */
static char *rpt_tostr(struct rpt *rpt, llist_t *exc)
{
	char buf[BUFSIZ_LINE * 4];
	char tmp[BUFSIZ_LINE];
	struct tm tm;
	llist_item_t *i;
	size_t n = 0;

	n += sprintf(buf + n, "{%d%c", rpt->freq, recur_def2char(rpt->type));
	if (rpt->until != 0) {
		localtime_r_safe(rpt->until, &tm);
		strftime(tmp, sizeof(tmp), "%m/%d/%Y", &tm);
		n += sprintf(buf + n, " -> %s", tmp);
	}
	LLIST_FOREACH(&rpt->bymonthday, i)
		n += sprintf(buf + n, " d%d", *(int *)LLIST_GET_DATA(i));
	LLIST_FOREACH(&rpt->bywday, i)
		n += sprintf(buf + n, " w%d", *(int *)LLIST_GET_DATA(i));
	LLIST_FOREACH(&rpt->bymonth, i)
		n += sprintf(buf + n, " m%d", *(int *)LLIST_GET_DATA(i));
	LLIST_FOREACH(exc, i) {
		struct excp *p = LLIST_GET_DATA(i);
		localtime_r_safe(p->st, &tm);
		strftime(tmp, sizeof(tmp), "%m/%d/%Y", &tm);
		n += sprintf(buf + n, " !%s", tmp);
		if (n > sizeof(buf) - 64)
			break;
	}
	n += sprintf(buf + n, "}");
	return mem_strdup(buf);
}

char *recur_apoint_tostr(struct recur_apoint *o)
{
	struct tm tm;
	char str_start[BUFSIZ_LINE], str_end[BUFSIZ_LINE];
	char *rpt, *s;
	time_t t;

	localtime_r_safe(o->start, &tm);
	strftime(str_start, sizeof(str_start), "%m/%d/%Y @ %H:%M", &tm);
	t = o->start + o->dur;
	localtime_r_safe(t, &tm);
	strftime(str_end, sizeof(str_end), "%m/%d/%Y @ %H:%M", &tm);
	rpt = rpt_tostr(o->rpt, &o->exc);

	if (o->note)
		s = strdup_printf("%s -> %s %s >%s %c%s\n", str_start, str_end, rpt, o->note,
				  (o->state & APOINT_NOTIFY) ? '!' : '|', o->mesg);
	else
		s = strdup_printf("%s -> %s %s %c%s\n", str_start, str_end, rpt,
				  (o->state & APOINT_NOTIFY) ? '!' : '|', o->mesg);
	mem_free(rpt);
	return s;
}

char *recur_apoint_hash(struct recur_apoint *rapt)
{
	char *raw = recur_apoint_tostr(rapt);
	char *sha = mem_malloc(41);
	size_t l = strlen(raw);
	if (l && raw[l - 1] == '\n')
		raw[l - 1] = '\0';
	sha1_digest(raw, sha);
	mem_free(raw);
	return sha;
}

char *recur_event_tostr(struct recur_event *o)
{
