	char *sha = mem_malloc(41);
	size_t l = strlen(raw);
	if (l && raw[l - 1] == '\n')
		raw[l - 1] = '\0';
	sha1_digest(raw, sha);
	mem_free(raw);
	return sha;
}

void recur_apoint_write(struct recur_apoint *o, FILE *f)
{
	char *s = recur_apoint_tostr(o);
	fputs(s, f);
	mem_free(s);
}

void recur_event_write(struct recur_event *o, FILE *f)
{
	char *s = recur_event_tostr(o);
	fputs(s, f);
	mem_free(s);
}

/* ---- scanning the "{...}" specification from the data file ---- */

/*
 * Scan a recurrence rule.  The opening brace has already been read.
 * On error, an error message is returned (static string) and the
 * caller reports it; errors detected inside recur.c exit directly.
 */
const char *recur_scan_rpt(FILE *f, struct rpt *rpt, llist_t *exc, int is_event)
{
	int freq, c, v;
	char type;
	struct tm until;
	struct date dt;

	rpt->type = RECUR_NO;
	rpt->freq = 0;
	rpt->until = 0;
	LLIST_INIT(&rpt->bymonth);
	LLIST_INIT(&rpt->bywday);
	LLIST_INIT(&rpt->bymonthday);
	LLIST_INIT(exc);

	if (fscanf(f, " %d%c ", &freq, &type) != 2)
		return "syntax error in item repetition";
	rpt->freq = freq;
	rpt->type = recur_char2def(type);

	/* until date */
	c = getc(f);
	if (c == '-') {
		if (getc(f) != '>')
			return "syntax error in item repetition";
		if (fscanf(f, " %d / %d / %d ", &until.tm_mon, &until.tm_mday, &until.tm_year) != 3)
			return "syntax error in item repetition";
		if (!check_date(until.tm_year, until.tm_mon, until.tm_mday))
			return "until date error";
		dt.yyyy = until.tm_year;
		dt.mm = until.tm_mon;
		dt.dd = until.tm_mday;
		rpt->until = date2sec(dt, 0, 0);
	} else {
		ungetc(c, f);
	}

	/* bymonthday */
	for (;;) {
		c = getc(f);
		if (c != 'd') {
			ungetc(c, f);
			break;
		}
		if (fscanf(f, " %d ", &v) != 1)
			EXIT_ON_ERROR("recur.c", 1640, "syntax error in bymonthday");
		int_list_add(&rpt->bymonthday, v);
	}
	/* bywday */
	for (;;) {
		c = getc(f);
		if (c != 'w') {
			ungetc(c, f);
			break;
		}
		if (fscanf(f, " %d ", &v) != 1)
			EXIT_ON_ERROR("recur.c", 1659, "syntax error in bywday");
		if ((rpt->type == RECUR_DAILY || rpt->type == RECUR_WEEKLY) && (v < 0 || v > 6))
			EXIT_ON_ERROR("recur.c", 1661, "illegal BYDAY value");
		int_list_add(&rpt->bywday, v);
	}
	/* bymonth */
	for (;;) {
		c = getc(f);
		if (c != 'm') {
			ungetc(c, f);
			break;
		}
		if (fscanf(f, " %d ", &v) != 1)
			EXIT_ON_ERROR("recur.c", 1678, "syntax error in bymonth");
		if (v < 1 || v > 12)
			EXIT_ON_ERROR("recur.c", 1679, "illegal bymonth value");
		int_list_add(&rpt->bymonth, v);
	}
	/* exceptions */
	for (;;) {
		struct tm day;
		c = getc(f);
		if (c != '!') {
			ungetc(c, f);
			break;
		}
		if (fscanf(f, " %d / %d / %d ", &day.tm_mon, &day.tm_mday, &day.tm_year) != 3)
			return "missing end of recurrence";
		if (!check_date(day.tm_year, day.tm_mon, day.tm_mday))
			EXIT_ON_ERROR("recur.c", 1704, "date error in item exception");
		dt.yyyy = day.tm_year;
		dt.mm = day.tm_mon;
		dt.dd = day.tm_mday;
		recur_add_exc(exc, date2sec(dt, 0, 0));
	}
	c = getc(f);
	if (c != '}')
		return "missing end of recurrence";
	/* skip trailing whitespace */
	do {
		c = getc(f);
	} while (c == ' ' || c == '\t');
	ungetc(c, f);
	(void)is_event;
	return NULL;
}

/* ---- date arithmetic ---- */

/* Days since 1970-01-01 for a civil date (proleptic Gregorian). */
static long days_from_civil(int y, int m, int d)
{
	long era, yoe, doy, doe;
	y -= m <= 2;
	era = (y >= 0 ? y : y - 399) / 400;
	yoe = y - era * 400;
	doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
	doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
	return era * 146097 + doe - 719468;
}

static long daynum(time_t t)
{
	struct tm tm;
	localtime_r_safe(t, &tm);
	return days_from_civil(tm.tm_year + TM_YEAR_BASE, tm.tm_mon + 1, tm.tm_mday);
}

static time_t mkday(int y, int m, int d)
{
	struct tm tm;
	memset(&tm, 0, sizeof(tm));
	tm.tm_year = y - TM_YEAR_BASE;
	tm.tm_mon = m - 1;
	tm.tm_mday = d;
	tm.tm_isdst = -1;
	return mktime(&tm);
}

/* Weekday (0 = Sunday) for a civil date. */
static int civil_wday(int y, int m, int d)
{
	long dn = days_from_civil(y, m, d);
	long w = (dn + 4) % 7;	/* 1970-01-01 was a Thursday */
	if (w < 0)
		w += 7;
	return (int)w;
}

/* Does the given date pass the bymonth limit? */
static int bymonth_ok(struct rpt *rpt, int m)
{
	return int_list_empty(&rpt->bymonth) || int_list_has(&rpt->bymonth, m);
}

/* Does the given date pass the bymonthday list (as a limit)? */
static int bymonthday_match(llist_t *l, int y, int m, int d)
{
	int ndays = month_days(m, y);
	return int_list_has(l, d) || int_list_has(l, d - ndays - 1);
}

/* Decode a BYDAY value into order and weekday; returns 0 if illegal. */
static int bywday_decode(int v, int *order, int *wday)
{
	int o = v / 7;
	int r = v % 7;
	if (o == 0) {
		if (r < 0)
			return 0;
		*order = 0;
		*wday = r;
	} else if (o > 0) {
		if (r < 0)
			return 0;
		*order = o;
		*wday = r;
	} else {
		if (r > 0)
			return 0;
		*order = o;
		*wday = -r;
	}
	return 1;
}

/*
 * Does the day (y, m, d) match a bywday entry in the monthly sense,
 * i.e. the n-th weekday of the month (or any, if order is 0)?
 */
static int bywday_match_month(int v, int y, int m, int d, int line)
{
	int order, wday, w;
	if (!bywday_decode(v, &order, &wday))
		EXIT_ON_ERROR("recur.c", line, "illegal BYDAY value");
	w = civil_wday(y, m, d);
	if (w != wday)
		return 0;
	if (order == 0)
		return 1;
	if (order > 0)
		return (d - 1) / 7 + 1 == order;
	return (month_days(m, y) - d) / 7 + 1 == -order;
}

/* As above, but counted within the year. */
static int bywday_match_year(int v, int y, int m, int d, int line)
{
	int order, wday, w;
	long doy, ydays;
	if (!bywday_decode(v, &order, &wday))
		EXIT_ON_ERROR("recur.c", line, "illegal BYDAY value");
	w = civil_wday(y, m, d);
	if (w != wday)
		return 0;
	if (order == 0)
		return 1;
	doy = days_from_civil(y, m, d) - days_from_civil(y, 1, 1);	/* 0-based */
	if (order > 0)
		return doy / 7 + 1 == order;
	ydays = ISLEAP(y) ? 366 : 365;
	return (ydays - 1 - doy) / 7 + 1 == -order;
}

static int bywday_any_month(struct rpt *rpt, int y, int m, int d, int line)
{
	llist_item_t *i;
	LLIST_FOREACH(&rpt->bywday, i) {
		if (bywday_match_month(*(int *)LLIST_GET_DATA(i), y, m, d, line))
			return 1;
	}
	return 0;
}

static int bywday_any_year(struct rpt *rpt, int y, int m, int d, int line, int month_based)
{
	llist_item_t *i;
	LLIST_FOREACH(&rpt->bywday, i) {
		int v = *(int *)LLIST_GET_DATA(i);
		if (month_based ? bywday_match_month(v, y, m, d, line) : bywday_match_year(v, y, m, d, line))
			return 1;
	}
	return 0;
}

/*
 * Check whether day (y, m, d) is a candidate of the monthly rule within
 * its month (not considering the frequency alignment).
 */
static int monthly_day_ok(struct rpt *rpt, int sy, int sm, int sd, int y, int m, int d)
{
	int has_md = !int_list_empty(&rpt->bymonthday);
	int has_wd = !int_list_empty(&rpt->bywday);
	(void)sy;
	(void)sm;

	if (!bymonth_ok(rpt, m))
		return 0;
	if (has_md && has_wd)
		return bymonthday_match(&rpt->bymonthday, y, m, d) && bywday_any_month(rpt, y, m, d, 1267);
	if (has_md)
		return bymonthday_match(&rpt->bymonthday, y, m, d);
	if (has_wd)
		return bywday_any_month(rpt, y, m, d, 1267);
	return d == sd;
}

static int yearly_day_ok(struct rpt *rpt, int sy, int sm, int sd, int y, int m, int d)
{
	int has_md = !int_list_empty(&rpt->bymonthday);
	int has_wd = !int_list_empty(&rpt->bywday);
	int has_m = !int_list_empty(&rpt->bymonth);
	(void)sy;

	if (has_m) {
		if (!int_list_has(&rpt->bymonth, m))
			return 0;
	} else if (!has_wd || has_md) {
		if (m != sm)
			return 0;
	}
	if (has_md && has_wd)
		return bymonthday_match(&rpt->bymonthday, y, m, d) && bywday_any_year(rpt, y, m, d, 1418, has_m);
	if (has_md)
		return bymonthday_match(&rpt->bymonthday, y, m, d);
	if (has_wd)
		return bywday_any_year(rpt, y, m, d, 1418, has_m);
	return d == sd;
}

static int daily_day_ok(struct rpt *rpt, int y, int m, int d)
{
	if (!bymonth_ok(rpt, m))
		return 0;
	if (!int_list_empty(&rpt->bywday) && !int_list_has(&rpt->bywday, civil_wday(y, m, d)))
		return 0;
	if (!int_list_empty(&rpt->bymonthday) && !bymonthday_match(&rpt->bymonthday, y, m, d))
		return 0;
	return 1;
}

static int weekly_day_ok(struct rpt *rpt, int swday, int y, int m, int d)
{
	int w = civil_wday(y, m, d);
	if (!bymonth_ok(rpt, m))
		return 0;
	if (int_list_empty(&rpt->bywday))
		return w == swday;
	return int_list_has(&rpt->bywday, w);
}

static void civil_from_days(long z, int *y, int *m, int *d)
{
	long era, doe, yoe, doy, mp;
	z += 719468;
	era = (z >= 0 ? z : z - 146096) / 146097;
	doe = z - era * 146097;
	yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
	doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
	mp = (5 * doy + 2) / 153;
	*d = (int)(doy - (153 * mp + 2) / 5 + 1);
	*m = (int)(mp < 10 ? mp + 3 : mp - 9);
	*y = (int)(yoe + era * 400 + (*m <= 2));
}

/* Monday-based week number relative to the epoch for a day number. */
static long week_index(long dn)
{
	/* 1970-01-01 is Thursday; Monday of that week is dn = -3 */
	long w = dn + 3;
	return (w >= 0 ? w : w - 6) / 7;
}

/*
 * Find the latest occurrence date (as day number) <= target day number
 * following the rule; returns 0 if none, 1 otherwise.
 */
static int recur_prev_daynum(long sdn, struct rpt *rpt, long tdn, long *res)
{
	int sy, sm, sd, y, m, d;
	long k, dn;

	if (tdn < sdn)
		return 0;
	if (rpt->freq <= 0)
		rpt->freq = rpt->freq;	/* division by zero below mimics the original */
	civil_from_days(sdn, &sy, &sm, &sd);

	switch (rpt->type) {
	case RECUR_DAILY: {
		long diff = tdn - sdn;
		long maxiter = 400 * 7 + 400;
		k = diff / rpt->freq;
		for (; k >= 0 && maxiter-- > 0; k--) {
			dn = sdn + k * rpt->freq;
			civil_from_days(dn, &y, &m, &d);
			if (daily_day_ok(rpt, y, m, d)) {
				*res = dn;
				return 1;
			}
		}
		return 0;
	}
	case RECUR_WEEKLY: {
		long sw = week_index(sdn), tw = week_index(tdn);
		long diff = tw - sw;
		int swday = civil_wday(sy, sm, sd);
		long maxiter = 60;
		k = diff / rpt->freq;
		for (; k >= 0 && maxiter-- > 0; k--) {
			long wk = sw + k * rpt->freq;
			long first = wk * 7 - 3;	/* Monday of that week */
			int i;
			for (i = 6; i >= 0; i--) {
				dn = first + i;
				if (dn > tdn || dn < sdn)
					continue;
				civil_from_days(dn, &y, &m, &d);
				if (weekly_day_ok(rpt, swday, y, m, d)) {
					*res = dn;
					return 1;
				}
			}
		}
		return 0;
	}
	case RECUR_MONTHLY: {
		long smon = (long)sy * 12 + (sm - 1);
		long tmon;
		long maxiter = 12 * 10;
		civil_from_days(tdn, &y, &m, &d);
		tmon = (long)y * 12 + (m - 1);
		k = (tmon - smon) / rpt->freq;
		for (; k >= 0 && maxiter-- > 0; k--) {
			long mon = smon + k * rpt->freq;
			int yy = (int)(mon / 12), mm = (int)(mon % 12) + 1, nd, dd;
			nd = month_days(mm, yy);
			for (dd = nd; dd >= 1; dd--) {
				dn = days_from_civil(yy, mm, dd);
				if (dn > tdn || dn < sdn)
					continue;
				if (monthly_day_ok(rpt, sy, sm, sd, yy, mm, dd)) {
					*res = dn;
					return 1;
				}
			}
		}
		return 0;
	}
	case RECUR_YEARLY: {
		long maxiter = 10;
		civil_from_days(tdn, &y, &m, &d);
		k = (y - sy) / rpt->freq;
		for (; k >= 0 && maxiter-- > 0; k--) {
			int yy = sy + (int)(k * rpt->freq), mm, dd;
			for (mm = 12; mm >= 1; mm--) {
				int nd = month_days(mm, yy);
				for (dd = nd; dd >= 1; dd--) {
					dn = days_from_civil(yy, mm, dd);
					if (dn > tdn || dn < sdn)
						continue;
					if (yearly_day_ok(rpt, sy, sm, sd, yy, mm, dd)) {
						*res = dn;
						return 1;
					}
				}
			}
		}
		return 0;
	}
	default:
		return 0;
	}
}

/*
 * Find the earliest occurrence date (day number) >= target day number.
 */
static int recur_next_daynum(long sdn, struct rpt *rpt, long tdn, long *res)
{
	int sy, sm, sd, y, m, d;
	long k, dn;

	if (tdn < sdn)
		tdn = sdn;
	civil_from_days(sdn, &sy, &sm, &sd);

	switch (rpt->type) {
	case RECUR_DAILY: {
		long diff = tdn - sdn;
		long maxiter = 400 * 7 + 400;
		k = (diff + rpt->freq - 1) / rpt->freq;
		for (; maxiter-- > 0; k++) {
			dn = sdn + k * rpt->freq;
			civil_from_days(dn, &y, &m, &d);
			if (daily_day_ok(rpt, y, m, d)) {
				*res = dn;
				return 1;
			}
		}
		return 0;
	}
	case RECUR_WEEKLY: {
		long sw = week_index(sdn), tw = week_index(tdn);
		long diff = tw - sw;
		int swday = civil_wday(sy, sm, sd);
		long maxiter = 60;
		k = diff / rpt->freq;
		for (; maxiter-- > 0; k++) {
			long wk = sw + k * rpt->freq;
			long first = wk * 7 - 3;
			int i;
			for (i = 0; i < 7; i++) {
				dn = first + i;
				if (dn < tdn || dn < sdn)
					continue;
				civil_from_days(dn, &y, &m, &d);
				if (weekly_day_ok(rpt, swday, y, m, d)) {
					*res = dn;
					return 1;
				}
			}
		}
		return 0;
	}
	case RECUR_MONTHLY: {
		long smon = (long)sy * 12 + (sm - 1);
		long tmon;
		long maxiter = 12 * 10;
		civil_from_days(tdn, &y, &m, &d);
		tmon = (long)y * 12 + (m - 1);
		k = (tmon - smon) / rpt->freq;
		for (; maxiter-- > 0; k++) {
			long mon = smon + k * rpt->freq;
			int yy = (int)(mon / 12), mm = (int)(mon % 12) + 1, nd, dd;
			nd = month_days(mm, yy);
			for (dd = 1; dd <= nd; dd++) {
				dn = days_from_civil(yy, mm, dd);
				if (dn < tdn || dn < sdn)
					continue;
				if (monthly_day_ok(rpt, sy, sm, sd, yy, mm, dd)) {
					*res = dn;
					return 1;
				}
			}
		}
		return 0;
	}
	case RECUR_YEARLY: {
		long maxiter = 10;
		civil_from_days(tdn, &y, &m, &d);
		k = (y - sy) / rpt->freq;
		for (; maxiter-- > 0; k++) {
			int yy = sy + (int)(k * rpt->freq), mm, dd;
			for (mm = 1; mm <= 12; mm++) {
				int nd = month_days(mm, yy);
				for (dd = 1; dd <= nd; dd++) {
					dn = days_from_civil(yy, mm, dd);
					if (dn < tdn || dn < sdn)
						continue;
					if (yearly_day_ok(rpt, sy, sm, sd, yy, mm, dd)) {
						*res = dn;
						return 1;
					}
				}
			}
		}
		return 0;
	}
	default:
		return 0;
	}
}

static time_t daynum_to_time(long dn, time_t start)
{
	int y, m, d;
	struct tm tm;
	civil_from_days(dn, &y, &m, &d);
	localtime_r_safe(start, &tm);
	tm.tm_year = y - TM_YEAR_BASE;
	tm.tm_mon = m - 1;
	tm.tm_mday = d;
	tm.tm_isdst = -1;
	return mktime(&tm);
}

/*
 * Return 1 if an occurrence of the recurrent item overlaps the day
 * starting at day_start.  The occurrence start is stored in *occurrence.
 */
int recur_item_find_occurrence(time_t item_start, long item_dur, struct rpt *rpt,
			       llist_t *item_exc, time_t day_start, time_t *occurrence)
{
	long sdn, tdn, odn;
	time_t t;

	if (rpt->freq == 0) {
		/* The original divides by zero here. */
		volatile int zero = 0;
		volatile int x = 1 / zero;
		(void)x;
	}

	sdn = daynum(item_start);
	tdn = daynum(day_start);
	if (tdn < sdn)
		return 0;
	if (!recur_prev_daynum(sdn, rpt, tdn, &odn))
		return 0;
	t = daynum_to_time(odn, item_start);
	if (rpt->until != 0 && t > rpt->until)
		return 0;
	if (item_exc && LLIST_FIND_FIRST(item_exc, &t, exc_inday))
		return 0;
	if (t < day_start + DAYINSEC && t + item_dur > day_start) {
		if (occurrence)
			*occurrence = t;
		return 1;
	}
	return 0;
}

/*
 * Find the next occurrence strictly after the day containing 'after'.
 * Used for stepping through repetitions and for the count conversion.
 */
int recur_next_occurrence(time_t item_start, long item_dur, llist_t *item_exc,
			  struct rpt *rpt, time_t after, time_t *next)
{
	long sdn = daynum(item_start), tdn = daynum(after) + 1, odn;
	time_t t;
	int guard = 0;

	(void)item_dur;
	for (;;) {
		if (!recur_next_daynum(sdn, rpt, tdn, &odn))
			return 0;
		t = daynum_to_time(odn, item_start);
		if (rpt->until != 0 && t > rpt->until)
			return 0;
		if (item_exc && LLIST_FIND_FIRST(item_exc, &t, exc_inday)) {
			tdn = odn + 1;
			if (++guard > 100000)
				return 0;
			continue;
		}
		*next = t;
		return 1;
	}
}

/*
 * Find the n-th occurrence (counting the start as number one and
 * skipping exceptions).  Returns 0 if there is none.
 */
int recur_nth_occurrence(time_t item_start, long item_dur, llist_t *item_exc,
			 struct rpt *rpt, int n, time_t *res)
{
	time_t t = item_start, nx;
	int count = 0;

	/* Is the start itself an occurrence? */
	if (recur_item_find_occurrence(item_start, item_dur, rpt, item_exc, DAY(item_start), &nx))
		count = 1;
	if (count == 0) {
		if (!recur_next_occurrence(item_start, item_dur, item_exc, rpt, item_start, &t))
			return 0;
		count = 1;
	}
	while (count < n) {
		if (!recur_next_occurrence(item_start, item_dur, item_exc, rpt, t, &nx))
			return 0;
		t = nx;
		count++;
	}
	*res = t;
	return 1;
}

int recur_apoint_find_occurrence(struct recur_apoint *rapt, time_t day_start, time_t *occurrence)
{
	return recur_item_find_occurrence(rapt->start, rapt->dur, rapt->rpt, &rapt->exc, day_start, occurrence);
}

int recur_event_find_occurrence(struct recur_event *rev, time_t day_start, time_t *occurrence)
{
	return recur_item_find_occurrence(rev->day, DAYINSEC, rev->rpt, &rev->exc, day_start, occurrence);
}

unsigned recur_item_inday(time_t item_start, long item_dur, llist_t *item_exc,
			  struct rpt *rpt, time_t day_start)
{
	return recur_item_find_occurrence(item_start, item_dur, rpt, item_exc, day_start, NULL);
}

unsigned recur_apoint_inday(struct recur_apoint *rapt, time_t *day_start)
{
	return recur_item_inday(rapt->start, rapt->dur, &rapt->exc, rapt->rpt, *day_start);
}

unsigned recur_event_inday(struct recur_event *rev, time_t *day_start)
{
	return recur_item_inday(rev->day, DAYINSEC, &rev->exc, rev->rpt, *day_start);
}

/* Validate a rule against its start day; returns 0 if the start is not an occurrence. */
int recur_check_rule(time_t start, struct rpt *rpt)
{
	return recur_item_find_occurrence(start, 1, rpt, NULL, DAY(start), NULL);
}

void recur_event_erase(struct recur_event *rev)
{
	llist_item_t *i;
	LLIST_FOREACH(&recur_elist, i) {
		if (LLIST_GET_DATA(i) == rev)
			break;
	}
	if (!i)
		EXIT_ON_ERROR("recur.c", 900, "no such recurrent event");
	LLIST_REMOVE(&recur_elist, i);
	recur_event_free(rev);
}

void recur_apoint_erase(struct recur_apoint *rapt)
{
	llist_item_t *i;
	int need_check_notify = 0;
	LLIST_FOREACH(&recur_alist_p, i) {
		if (LLIST_GET_DATA(i) == rapt)
			break;
	}
	if (!i)
		EXIT_ON_ERROR("recur.c", 920, "no such recurrent appointment");
	if (ui_mode == UI_CURSES && notify_bar())
		need_check_notify = notify_same_recur_item(rapt);
	LLIST_REMOVE(&recur_alist_p, i);
	recur_apoint_free(rapt);
	if (need_check_notify)
		notify_check_next_app(0);
}

/* Look for the next recurrent appointment after 'start' within 24 hours. */
int recur_apoint_check_next(struct notify_app *app, time_t start, time_t day)
{
	llist_item_t *i;
	time_t real_recur_start_time;

	LLIST_FOREACH(&recur_alist_p, i) {
		struct recur_apoint *rapt = LLIST_GET_DATA(i);
		time_t d;
		for (d = DAY(start); d < start + DAYINSEC + DAYINSEC; d = date_sec_change(d, 0, 1)) {
			if (recur_apoint_find_occurrence(rapt, d, &real_recur_start_time)) {
				if (real_recur_start_time > start && real_recur_start_time < app->time &&
				    (!app->got_app || real_recur_start_time < app->time)) {
					app->time = real_recur_start_time;
					app->got_app = 1;
					app->state = rapt->state;
					if (app->txt)
						mem_free(app->txt);
					app->txt = mem_strdup(rapt->mesg);
				}
			}
		}
	}
	(void)day;
	return app->got_app;
}

void recur_apoint_switch_notify(struct recur_apoint *rapt)
{
	rapt->state ^= APOINT_NOTIFY;
	if (ui_mode == UI_CURSES && notify_bar())
		notify_check_repeated(rapt);
}

void recur_event_paste_item(struct recur_event *rev, time_t date)
{
	long time_shift;
	llist_item_t *i;

	time_shift = date - rev->day;
	rev->day += time_shift;
	if (rev->rpt->until != 0)
		rev->rpt->until += time_shift;
	LLIST_FOREACH(&rev->exc, i) {
		struct excp *exc = LLIST_GET_DATA(i);
		exc->st += time_shift;
	}
	LLIST_ADD_SORTED(&recur_elist, rev, recur_event_cmp);
}

void recur_apoint_paste_item(struct recur_apoint *rapt, time_t date)
{
	time_t ostart = rapt->start;
	long time_shift;
	llist_item_t *i;

	rapt->start = date + get_item_time(rapt->start);
	time_shift = rapt->start - ostart;
	if (rapt->rpt->until != 0)
		rapt->rpt->until += time_shift;
	LLIST_FOREACH(&rapt->exc, i) {
		struct excp *exc = LLIST_GET_DATA(i);
		exc->st += time_shift;
	}
	LLIST_ADD_SORTED(&recur_alist_p, rapt, recur_apoint_cmp);
}

/* Weekday name (abbreviated) for a BYDAY value. */
char *recur_wday_str(int v)
{
	int order, wday;
	static const char *names[7] = { "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat" };
	if (!bywday_decode(v, &order, &wday))
		return strdup_printf("%d", v);
	if (order == 0)
		return mem_strdup(names[wday]);
	return strdup_printf("%d%s", order, names[wday]);
}
