int dump_imported = 0;
const char *grep_fmt_default = "%(raw)";
const char *fmt_apt = NULL, *fmt_rapt = NULL, *fmt_ev = NULL, *fmt_rev = NULL, *fmt_todo = NULL;

static int modified = 0;
static int lock_set = 0;

#define LOAD_ERROR(file, line, msg) \
