static int path_is_dir(const char *p)
{
	struct stat st;
	return stat(p, &st) == 0 && S_ISDIR(st.st_mode);
}

/*
 * Initialize the data and configuration paths.
 */
void io_init(const char *cfile, const char *datadir, const char *confdir)
{
	const char *home, *xdg;
	char home_dotcalcurse[BUFSIZ_LINE];
	int use_dotcalcurse = 0;

	home = getenv("HOME");
	if (!home)
		home = ".";

	snprintf(home_dotcalcurse, sizeof(home_dotcalcurse), "%s/.calcurse", home);
	if (path_is_dir(home_dotcalcurse))
		use_dotcalcurse = 1;

	if (datadir) {
		snprintf(path_ddir, sizeof(path_ddir), "%s/", datadir);
		/* collapse double slashes */
		{
			size_t l = strlen(path_ddir);
			while (l > 1 && path_ddir[l - 1] == '/' && path_ddir[l - 2] == '/')
				path_ddir[--l] = '\0';
		}
	} else if (use_dotcalcurse) {
		snprintf(path_ddir, sizeof(path_ddir), "%s/", home_dotcalcurse);
	} else {
		xdg = getenv("XDG_DATA_HOME");
		if (xdg && *xdg)
			snprintf(path_ddir, sizeof(path_ddir), "%s/calcurse/", xdg);
		else
			snprintf(path_ddir, sizeof(path_ddir), "%s/.local/share/calcurse/", home);
	}

	if (confdir) {
		snprintf(path_cdir, sizeof(path_cdir), "%s/", confdir);
		{
			size_t l = strlen(path_cdir);
			while (l > 1 && path_cdir[l - 1] == '/' && path_cdir[l - 2] == '/')
				path_cdir[--l] = '\0';
		}
	} else if (datadir) {
		strcpy(path_cdir, path_ddir);
	} else if (use_dotcalcurse) {
		snprintf(path_cdir, sizeof(path_cdir), "%s/", home_dotcalcurse);
	} else {
		xdg = getenv("XDG_CONFIG_HOME");
		if (xdg && *xdg)
			snprintf(path_cdir, sizeof(path_cdir), "%s/calcurse/", xdg);
		else
			snprintf(path_cdir, sizeof(path_cdir), "%s/.config/calcurse/", home);
	}

	snprintf(path_todo, sizeof(path_todo), "%stodo", path_ddir);
	snprintf(path_notes, sizeof(path_notes), "%snotes/", path_ddir);
	snprintf(path_cpid, sizeof(path_cpid), "%s.calcurse.pid", path_ddir);
	snprintf(path_dpid, sizeof(path_dpid), "%s.daemon.pid", path_ddir);
	snprintf(path_dmon_log, sizeof(path_dmon_log), "%sdaemon.log", path_ddir);
	snprintf(path_conf, sizeof(path_conf), "%sconf", path_cdir);
	snprintf(path_keys, sizeof(path_keys), "%skeys", path_cdir);
	snprintf(path_hooks, sizeof(path_hooks), "%shooks/", path_cdir);

	if (cfile) {
		snprintf(path_apts, sizeof(path_apts), "%s", cfile);
		if (!io_file_exists(path_apts))
			EXIT_ON_ERROR("io.c", 189, "%s does not exist", path_apts);
	} else {
		snprintf(path_apts, sizeof(path_apts), "%sapts", path_ddir);
	}
}

unsigned io_dir_exists(const char *path)
{
	return path_is_dir(path);
}

unsigned io_file_exists(const char *file)
{
	FILE *fd;
	if (file && (fd = fopen(file, "r")) != NULL) {
		fclose(fd);
		return 1;
	}
	return 0;
}

void io_check_dir(const char *dir)
{
	char *path = mem_strdup(dir);
	size_t l = strlen(path);
	if (read_only) {
		mem_free(path);
		return;
	}
	while (l > 1 && path[l - 1] == '/')
		path[--l] = '\0';
	if (mkdir_p(path) != 0) {
		fprintf(stderr, _("FATAL ERROR: could not create %s: %s\n"), path, strerror(errno));
		exit_calcurse(EXIT_FAILURE);
	}
	mem_free(path);
}

void io_check_file(const char *file)
{
	FILE *fd;
	if (read_only)
		return;
	if (!io_file_exists(file)) {
		if ((fd = fopen(file, "w")) == NULL) {
			fprintf(stderr, _("FATAL ERROR: could not create %s: %s\n"), file, strerror(errno));
			exit_calcurse(EXIT_FAILURE);
		}
		file_close(fd, "io.c", 300);
	}
}

/*
 * Create the data files and directories if missing.  Returns 1 if any
 * was missing (first run).
 */
int io_check_data_files(void)
{
	int missing = 0;

	missing += io_file_exists(path_apts) ? 0 : 1;
	missing += io_file_exists(path_todo) ? 0 : 1;
	missing += io_file_exists(path_conf) ? 0 : 1;
	missing += io_file_exists(path_keys) ? 0 : 1;

	io_check_dir(path_ddir);
	io_check_dir(path_notes);
	io_check_dir(path_cdir);
	io_check_dir(path_hooks);
	io_check_file(path_todo);
	io_check_file(path_apts);
	io_check_file(path_conf);
	return missing;
}

/* ---- loading ---- */

static int filter_match_time(struct item_filter *f, time_t start, time_t end)
{
	if (f->start_from != -1 && start < f->start_from)
		return 0;
	if (f->start_to != -1 && start > f->start_to)
		return 0;
	if (f->end_from != -1 && end < f->end_from)
		return 0;
	if (f->end_to != -1 && end > f->end_to)
		return 0;
	return 1;
}

static int filter_match_common(struct item_filter *f, int type_mask, const char *mesg, char *(*hashfn)(void *), void *item)
{
	if (!(f->type_mask & type_mask))
		return 0;
	if (f->regex && regexec(f->regex, mesg, 0, 0, 0))
		return 0;
	if (f->hash) {
		char *h = hashfn(item);
		int ok = hash_matches(f->hash, h);
		mem_free(h);
		if (!ok)
			return 0;
	}
	return 1;
}

static int filter_decide(struct item_filter *f, int match)
{
	if (!f)
		return 1;
	return f->invert ? !match : match;
}

static int apoint_filter(struct item_filter *f, struct apoint *apt)
{
	int m = filter_match_common(f, TYPE_MASK_APPT, apt->mesg, (char *(*)(void *))apoint_hash, apt) &&
		filter_match_time(f, apt->start, apt->start + apt->dur);
	return filter_decide(f, m);
}

static int event_filter(struct item_filter *f, struct event *ev)
{
	int m = filter_match_common(f, TYPE_MASK_EVENT, ev->mesg, (char *(*)(void *))event_hash, ev) &&
		filter_match_time(f, ev->day, ev->day + DAYINSEC - 1);
	return filter_decide(f, m);
}

static int recur_apoint_filter(struct item_filter *f, struct recur_apoint *rapt)
{
	int m = filter_match_common(f, TYPE_MASK_RECUR_APPT, rapt->mesg, (char *(*)(void *))recur_apoint_hash, rapt) &&
		filter_match_time(f, rapt->start, rapt->start + rapt->dur);
	return filter_decide(f, m);
}

static int recur_event_filter(struct item_filter *f, struct recur_event *rev)
{
	int m = filter_match_common(f, TYPE_MASK_RECUR_EVENT, rev->mesg, (char *(*)(void *))recur_event_hash, rev) &&
		filter_match_time(f, rev->day, rev->day + DAYINSEC - 1);
	return filter_decide(f, m);
}

static int todo_filter(struct item_filter *f, struct todo *t)
{
	int m = filter_match_common(f, TYPE_MASK_TODO, t->mesg, (char *(*)(void *))todo_hash, t);
	if (m && f->priority && t->id != f->priority)
		m = 0;
	if (m && f->completed && !t->completed)
		m = 0;
	if (m && f->uncompleted && t->completed)
		m = 0;
	return filter_decide(f, m);
}

/* Read the rest of the line into buf (without the newline). */
static void read_mesg(FILE *f, char *buf, size_t size)
{
	size_t i = 0;
	int c;
	for (;;) {
		c = getc(f);
		if (c == EOF || c == '\n')
			break;
		if (i + 1 < size)
			buf[i++] = c;
	}
	buf[i] = '\0';
}

static void skip_blanks(FILE *f)
{
	int c;
	do {
		c = getc(f);
	} while (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f');
	if (c != EOF)
		ungetc(c, f);
}

void io_load_app(struct item_filter *filter)
{
	FILE *data_file;
	int c, is_appointment, is_event, is_recursive;
	struct tm start, end, until;
	struct rpt rpt;
	llist_t exc;
	char buf[BUFSIZ_LINE * 4], note[MAX_NOTESIZ + 1];
	char state = 0;
	int id = 0;
	int line = 0;
	const char *err;
	struct date dstart, dend;

	data_file = fopen(path_apts, "r");
	if (!data_file)
		EXIT_ON_ERROR("io.c", 380, "failed to open appointment file");

	for (;;) {
		line++;
		c = getc(data_file);
		if (c == EOF)
			break;
		ungetc(c, data_file);

		is_appointment = is_event = is_recursive = 0;
		memset(&start, 0, sizeof(start));
		memset(&end, 0, sizeof(end));
		memset(&until, 0, sizeof(until));
		memset(&rpt, 0, sizeof(rpt));
		LLIST_INIT(&exc);
		note[0] = '\0';
		state = 0;
		id = 0;

		/* Read the date */
		if (fscanf(data_file, "%d / %d / %d ", &start.tm_mon, &start.tm_mday, &start.tm_year) != 3)
			LOAD_ERROR(path_apts, line, _("syntax error in the item date"));

		c = getc(data_file);
		if (c == '@') {
			if (fscanf(data_file, " %d : %d -> %d / %d / %d @ %d : %d ",
				   &start.tm_hour, &start.tm_min, &end.tm_mon, &end.tm_mday,
				   &end.tm_year, &end.tm_hour, &end.tm_min) != 7)
				LOAD_ERROR(path_apts, line, _("syntax error in item time or duration"));
			is_appointment = 1;
		} else if (c == '[') {
			if (fscanf(data_file, " %d ", &id) != 1 || getc(data_file) != ']')
				LOAD_ERROR(path_apts, line, _("syntax error in item identifier"));
			skip_blanks(data_file);
			is_event = 1;
		} else {
			LOAD_ERROR(path_apts, line, _("no event nor appointment found"));
		}

		/* Check if we have a recurrent item. */
		c = getc(data_file);
		if (c == '{') {
			is_recursive = 1;
			err = recur_scan_rpt(data_file, &rpt, &exc, is_event);
			if (err)
				LOAD_ERROR(path_apts, line, err);
		} else {
			ungetc(c, data_file);
		}

		/* Check if a note is attached to the item. */
		c = getc(data_file);
		if (c == '>') {
			note_read(note, data_file);
		} else {
			ungetc(c, data_file);
		}

		if (is_appointment) {
			c = getc(data_file);
			if (c == '|')
				state = 0L;
			else if (c == '!')
				state = APOINT_NOTIFY;
			else
				LOAD_ERROR(path_apts, line, _("syntax error in item state"));
		}

		read_mesg(data_file, buf, sizeof(buf));

		/* Validate. */
		if (is_appointment) {
			if (!check_date(start.tm_year, start.tm_mon, start.tm_mday) ||
			    !check_time(start.tm_hour, start.tm_min) ||
			    !check_date(end.tm_year, end.tm_mon, end.tm_mday) ||
			    !check_time(end.tm_hour, end.tm_min))
				LOAD_ERROR(path_apts, line, _("illegal date in appointment"));
			dstart.yyyy = start.tm_year;
			dstart.mm = start.tm_mon;
			dstart.dd = start.tm_mday;
			dend.yyyy = end.tm_year;
			dend.mm = end.tm_mon;
			dend.dd = end.tm_mday;
			{
				time_t tstart = date2sec(dstart, start.tm_hour, start.tm_min);
				time_t tend = date2sec(dend, end.tm_hour, end.tm_min);
				if (tstart > tend)
					LOAD_ERROR(path_apts, line, _("date error in appointment"));
				if (is_recursive) {
					struct rpt *r = recur_rpt_dup(&rpt);
					struct recur_apoint *rapt;
					recur_free_int_list(&rpt.bymonth);
					recur_free_int_list(&rpt.bywday);
					recur_free_int_list(&rpt.bymonthday);
					if (r->until != 0)
						r->until = update_time_in_date(r->until, start.tm_hour, start.tm_min);
					if (r->type == RECUR_WEEKLY && LLIST_FIRST(&r->bymonthday))
						LOAD_ERROR(path_apts, line, _("BYMONTHDAY illegal with WEEKLY"));
					if (!recur_check_rule(tstart, r)) {
						char dbuf[BUFSIZ_LINE], msg[BUFSIZ_LINE];
						struct tm tm;
						localtime_r_safe(tstart, &tm);
						strftime(dbuf, sizeof(dbuf), "%m/%d/%Y", &tm);
						snprintf(msg, sizeof(msg), _("recurrence error: not on start day (%s)"), dbuf);
						LOAD_ERROR(path_apts, line, msg);
					}
					rapt = recur_apoint_new(buf, note[0] ? note : NULL, tstart,
								tend - tstart, state, r, &exc);
					if (filter && !recur_apoint_filter(filter, rapt))
						recur_apoint_erase(rapt);
				} else {
					struct apoint *apt = apoint_new(buf, note[0] ? note : NULL, tstart,
									tend - tstart, state);
					if (filter && !apoint_filter(filter, apt))
						apoint_delete(apt);
				}
			}
		} else if (is_event) {
			time_t tday;
			if (!check_date(start.tm_year, start.tm_mon, start.tm_mday))
				LOAD_ERROR(path_apts, line, _("illegal date in event"));
			dstart.yyyy = start.tm_year;
			dstart.mm = start.tm_mon;
			dstart.dd = start.tm_mday;
			tday = date2sec(dstart, 0, 0);
			if (is_recursive) {
				struct rpt *r = recur_rpt_dup(&rpt);
				struct recur_event *rev;
				recur_free_int_list(&rpt.bymonth);
				recur_free_int_list(&rpt.bywday);
				recur_free_int_list(&rpt.bymonthday);
				if (r->type == RECUR_WEEKLY && LLIST_FIRST(&r->bymonthday))
					LOAD_ERROR(path_apts, line, _("BYMONTHDAY illegal with WEEKLY"));
				if (!recur_check_rule(tday, r)) {
					char dbuf[BUFSIZ_LINE], msg[BUFSIZ_LINE];
					struct tm tm;
					localtime_r_safe(tday, &tm);
					strftime(dbuf, sizeof(dbuf), "%m/%d/%Y", &tm);
					snprintf(msg, sizeof(msg), _("recurrence error: not on start day (%s)"), dbuf);
					LOAD_ERROR(path_apts, line, msg);
				}
				rev = recur_event_new(buf, note[0] ? note : NULL, tday, id, r, &exc);
				if (filter && !recur_event_filter(filter, rev))
					recur_event_erase(rev);
			} else {
				struct event *ev = event_new(buf, note[0] ? note : NULL, tday, id);
				if (filter && !event_filter(filter, ev))
					event_delete(ev);
			}
		}
	}
	file_close(data_file, "io.c", 560);
}

void io_load_todo(struct item_filter *filter)
{
	FILE *data_file;
	char *newline;
	int nb_tod = 0;
	int c, id, completed;
	char buf[BUFSIZ_LINE * 4], e_todo[BUFSIZ_LINE * 4], note[MAX_NOTESIZ + 1];
	int line = 0;

	data_file = fopen(path_todo, "r");
	if (!data_file)
		EXIT_ON_ERROR("io.c", 580, "failed to open todo file");

	for (;;) {
		line++;
		c = getc(data_file);
		if (c == EOF)
			break;
		ungetc(c, data_file);

		/* Read the priority */
		if (c == '[') {
			getc(data_file);
			if (fscanf(data_file, " %d ", &id) != 1 || getc(data_file) != ']')
				LOAD_ERROR(path_todo, line, _("syntax error in item identifier"));
			skip_blanks(data_file);
			if (id < 0) {
				completed = 1;
				id = -id;
			} else {
				completed = 0;
			}
			/* Check if a note is attached to the item. */
			c = getc(data_file);
			if (c == '>') {
				note_read(note, data_file);
				skip_blanks(data_file);
			} else {
				note[0] = '\0';
				ungetc(c, data_file);
			}
		} else {
			id = 9;
			completed = 0;
			note[0] = '\0';
		}

		/* Now read the attached note, if any. */
		if (fgets(buf, sizeof(buf), data_file) == NULL)
			buf[0] = '\0';
		newline = strchr(buf, '\n');
		if (newline)
			*newline = '\0';
		strncpy(e_todo, buf, sizeof(e_todo));
		{
			struct todo *t = todo_add(e_todo, id, completed, note[0] ? note : NULL);
			if (filter && !todo_filter(filter, t))
				todo_delete(t);
		}
		++nb_tod;
	}
	file_close(data_file, "io.c", 620);
}

int io_load_data(struct item_filter *filter, int force)
{
	(void)force;
	run_hook("pre-load");
	io_load_app(filter);
	io_load_todo(filter);
	io_unset_modified();
	run_hook("post-load");
	return 0;
}

/* ---- saving ---- */

void io_dump_apts(const char *fmt_apt, const char *fmt_rapt, const char *fmt_ev, const char *fmt_rev)
{
	llist_item_t *i;

	LLIST_FOREACH(&recur_elist, i) {
		struct recur_event *rev = LLIST_GET_DATA(i);
		print_recur_event(fmt_rev, 0, rev);
	}
	LLIST_FOREACH(&recur_alist_p, i) {
		struct recur_apoint *rapt = LLIST_GET_DATA(i);
		print_recur_apoint(fmt_rapt, 0, rapt->start, rapt);
	}
	LLIST_FOREACH(&alist_p, i) {
		struct apoint *apt = LLIST_GET_DATA(i);
		print_apoint(fmt_apt, 0, apt);
	}
	LLIST_FOREACH(&eventlist, i) {
		struct event *ev = LLIST_GET_DATA(i);
		print_event(fmt_ev, 0, ev);
	}
}

void io_save_apts(const char *aptsfile)
{
	llist_item_t *i;
	FILE *fp;

	if (read_only)
		return;
	if ((fp = fopen(aptsfile, "w")) == NULL)
		EXIT_ON_ERROR("io.c", 700, "failed to open appointment file");

	LLIST_FOREACH(&recur_elist, i)
		recur_event_write(LLIST_GET_DATA(i), fp);
	LLIST_FOREACH(&recur_alist_p, i)
		recur_apoint_write(LLIST_GET_DATA(i), fp);
	LLIST_FOREACH(&alist_p, i)
		apoint_write(LLIST_GET_DATA(i), fp);
	LLIST_FOREACH(&eventlist, i)
		event_write(LLIST_GET_DATA(i), fp);
	file_close(fp, "io.c", 715);
}

void io_dump_todo(const char *fmt_todo)
{
	llist_item_t *i;
	LLIST_FOREACH(&todolist, i)
		print_todo(fmt_todo, LLIST_GET_DATA(i));
}

void io_save_todo(const char *todofile)
{
	llist_item_t *i;
	FILE *fp;

	if (read_only)
		return;
	if ((fp = fopen(todofile, "w")) == NULL)
		EXIT_ON_ERROR("io.c", 740, "failed to open todo file");
	LLIST_FOREACH(&todolist, i)
		todo_write(LLIST_GET_DATA(i), fp);
	file_close(fp, "io.c", 745);
}

/* ---- lock files ---- */

unsigned io_dump_pid(char *file)
{
	pid_t pid;
	FILE *fp;

	if (!file)
		return 0;
	pid = getpid();
	if (!(fp = fopen(file, "w")) || fprintf(fp, "%ld\n", (long)pid) < 0 || fclose(fp) != 0)
		return 0;
	return 1;
}

unsigned io_get_pid(char *file)
{
	unsigned pid;
	FILE *fp;

	if (!file)
		return 0;
	if ((fp = fopen(file, "r")) == NULL)
		return 0;
	if (fscanf(fp, "%u", &pid) != 1) {
		fclose(fp);
		return 0;
	}
	fclose(fp);
	return pid;
}

int io_set_lock_quiet(void)
{
	pid_t pid = io_get_pid(path_cpid);
	if (pid && kill(pid, 0) == 0)
		return 0;
	if (!io_dump_pid(path_cpid))
		return 0;
	lock_set = 1;
	return 1;
}

void io_unset_lock(void)
{
	if (lock_set) {
		unlink(path_cpid);
		lock_set = 0;
	}
}

int io_files_equal(const char *file1, const char *file2)
{
	FILE *fp1, *fp2;
	int ret = 0;

	if (!(fp1 = fopen(file1, "rb")))
		return 0;
	if (!(fp2 = fopen(file2, "rb"))) {
		fclose(fp1);
		return 0;
	}
	for (;;) {
		int c1 = getc(fp1), c2 = getc(fp2);
		if (c1 != c2)
			break;
		if (c1 == EOF) {
			ret = 1;
			break;
		}
	}
	fclose(fp1);
	fclose(fp2);
	return ret;
}

int io_file_cp(const char *src, const char *dst)
{
	FILE *fp_src, *fp_dst;
	char buf[BUFSIZ];
	size_t n;

	if (!(fp_src = fopen(src, "rb")))
		return 0;
	if (!(fp_dst = fopen(dst, "wb"))) {
		fclose(fp_src);
		return 0;
	}
	while ((n = fread(buf, 1, sizeof(buf), fp_src)) > 0)
		fwrite(buf, 1, n, fp_dst);
	fclose(fp_src);
	fclose(fp_dst);
	return 1;
}

/* ---- import log ---- */

struct io_file *io_log_init(void)
{
	char *logprefix, *logname;
	struct io_file *log;

	logprefix = "calcurse_log";
	logname = new_tempfile(logprefix);
	if (!logname) {
		ERROR_MSG(_("Warning: could not create temporary log file, Aborting..."));
		return NULL;
	}
	log = mem_malloc(sizeof(struct io_file));
	strncpy(log->name, logname, sizeof(log->name) - 1);
	log->name[sizeof(log->name) - 1] = '\0';
	mem_free(logname);
	if ((log->fd = fopen(log->name, "w")) == NULL) {
		ERROR_MSG(_("Warning: could not open temporary log file, Aborting..."));
		mem_free(log);
		return NULL;
	}
	return log;
}

void io_log_print(struct io_file *log, int line, const char *msg)
{
	if (log && log->fd)
		fprintf(log->fd, "%s\n", msg);
	(void)line;
}

void io_log_free(struct io_file *log)
{
	if (!log)
		return;
	if (log->fd)
		fclose(log->fd);
	mem_free(log);
}

/* ---- export ---- */

void io_export_data(enum export_type type, int export_uid)
{
	FILE *stream = stdout;
	if (type == IO_EXPORT_ICAL)
		ical_export_data(stream, export_uid);
	else
		pcal_export_data(stream);
}

/* ---- import ---- */

void io_import_data(enum import_type type, const char *file_name, const char *fmt_ev,
		    const char *fmt_rev, const char *fmt_apt, const char *fmt_rapt, const char *fmt_todo)
{
	const char *proc_report = _("Import process report: %04d lines read");
	char *stats_str[4];
	FILE *stream = NULL;
	struct io_file *log;
	unsigned events, apoints, todos, lines, skipped;

	if (file_name) {
		stream = fopen(file_name, "r");
	} else if (ui_mode == UI_CURSES) {
		extern char *ui_ask_import_file(void);
		char *fn = ui_ask_import_file();
		if (!fn)
			return;
		stream = fopen(fn, "r");
		mem_free(fn);
	}

	if (stream == NULL) {
		if (ui_mode == UI_CURSES) {
			ui_warnbox(_("The file cannot be accessed, please enter another file name."));
			return;
		}
		EXIT_ON_ERROR("io.c", 1278, "FATAL ERROR: the input file cannot be accessed, Aborting...");
	}

	if ((log = io_log_init()) == NULL) {
		if (stream != stdin)
			fclose(stream);
		return;
	}

	ical_import_data(file_name, stream, log->fd, &events, &apoints, &todos, &lines, &skipped,
			 fmt_ev, fmt_rev, fmt_apt, fmt_rapt, fmt_todo);
	if (stream != stdin)
		fclose(stream);

	asprintf_safe(&stats_str[0], "%d %s", events, (events == 1) ? _("event") : _("events"));
	asprintf_safe(&stats_str[1], "%d %s", apoints, (apoints == 1) ? _("app") : _("apps"));
	asprintf_safe(&stats_str[2], "%d %s", todos, (todos == 1) ? _("todo") : _("todos"));
	asprintf_safe(&stats_str[3], "%d %s", skipped, _("skipped"));

	if (ui_mode == UI_CURSES) {
		extern void ui_import_report(const char *, unsigned, char **);
		ui_import_report(proc_report, lines, stats_str);
	} else if (!quiet) {
		printf(proc_report, lines);
		printf("\n%s / %s / %s / %s\n", stats_str[1], stats_str[0], stats_str[2], stats_str[3]);
	}

	/* User has the possibility to look at the log file. */
	if (skipped > 0) {
		fclose(log->fd);
		log->fd = NULL;
		if (ui_mode == UI_CURSES) {
			extern void ui_import_log_ask(const char *);
			ui_import_log_ask(log->name);
		} else {
			fprintf(stderr, "\n%s\n%s %s %s\n", _("Some items could not be imported."),
				_("See"), log->name, _("for details."));
		}
	} else {
		fclose(log->fd);
		log->fd = NULL;
		unlink(log->name);
	}
	mem_free(stats_str[0]);
	mem_free(stats_str[1]);
	mem_free(stats_str[2]);
	mem_free(stats_str[3]);
	io_log_free(log);
	if (ui_mode == UI_CURSES && apoints + events + todos > 0)
		io_set_modified();
}
