int day_item_cmp(struct day_item *a, struct day_item *b)
{
	if (a->order < b->order)
		return -1;
	if (a->order > b->order)
		return 1;
	/* Events before appointments. */
	{
		int ae = (a->type == EVNT || a->type == RECUR_EVNT);
		int be = (b->type == EVNT || b->type == RECUR_EVNT);
		if (ae && !be)
			return -1;
		if (!ae && be)
			return 1;
		if (ae && be)
