/*
 * Print the items of a day to stdout (used by the -Q query); returns
 * whether anything was printed.  The limit counts down.
 */
void day_write_stdout(time_t date, const char *fmt_apt, const char *fmt_rapt,
		      const char *fmt_ev, const char *fmt_rev, int *limit)
{
	llist_item_t *i;

	LLIST_FOREACH(&day_items, i) {
		struct day_item *day = LLIST_GET_DATA(i);
		if (*limit == 0)
			break;
		switch (day->type) {
		case APPT:
			print_apoint(fmt_apt, date, day->item.apt);
			break;
		case EVNT:
			print_event(fmt_ev, date, day->item.ev);
			break;
		case RECUR_APPT:
			print_recur_apoint(fmt_rapt, date, day->start, day->item.rapt);
			break;
		case RECUR_EVNT:
			print_recur_event(fmt_rev, date, day->item.rev);
			break;
		default:
			continue;
		}
		(*limit)--;
	}
}

int day_check_if_item(struct date day)
{
	time_t t = date2sec(day, 0, 0);
	llist_item_t *i;

	LLIST_FOREACH(&recur_elist, i)
		if (recur_event_inday(LLIST_GET_DATA(i), &t))
			return 1;
	LLIST_FOREACH(&recur_alist_p, i)
		if (recur_apoint_inday(LLIST_GET_DATA(i), &t))
			return 1;
	LLIST_FOREACH(&eventlist, i)
		if (event_inday(LLIST_GET_DATA(i), &t))
			return 1;
	LLIST_FOREACH(&alist_p, i)
		if (apoint_inday(LLIST_GET_DATA(i), &t))
			return 1;
	return 0;
}

static unsigned fill_slices(int *slices, int slicesno, int first, int last)
{
	int i;
	if (first < 0 || last < first)
		return 0;
	if (last >= slicesno)
		last = slicesno - 1;
	for (i = first; i <= last; i++)
		slices[i] = 1;
	return 1;
}

/*
 * Fill slices with busy time slots of the given day (for the weekly
 * calendar view).
 */
unsigned day_chk_busy_slices(struct date day, int slicesno, int *slices)
{
	llist_item_t *i;
	time_t t = date2sec(day, 0, 0);
	int slicelen = DAYINSEC / slicesno;

#define SLICENUM(tsec) ((tsec) / slicelen % slicesno)

	LLIST_FOREACH(&recur_alist_p, i) {
		struct recur_apoint *rapt = LLIST_GET_DATA(i);
		time_t occurrence;
		long start, end;
		if (!recur_apoint_find_occurrence(rapt, t, &occurrence))
			continue;
		if (occurrence >= t)
			start = get_item_time(occurrence);
		else
			start = 0;
		if (occurrence + rapt->dur < t + DAYINSEC)
			end = get_item_time(occurrence + rapt->dur);
		else
			end = DAYINSEC - 1;
		if (!fill_slices(slices, slicesno, SLICENUM(start), SLICENUM(end)))
			return 0;
	}
	LLIST_FOREACH(&alist_p, i) {
		struct apoint *apt = LLIST_GET_DATA(i);
		long start, end;
		if (!apoint_inday(apt, &t))
			continue;
		if (apt->start >= t)
			start = get_item_time(apt->start);
		else
			start = 0;
		if (apt->start + apt->dur < t + DAYINSEC)
			end = get_item_time(apt->start + apt->dur);
		else
			end = DAYINSEC - 1;
		if (!fill_slices(slices, slicesno, SLICENUM(start), SLICENUM(end)))
			return 0;
	}
#undef SLICENUM
	return 1;
}
