	day_out->start = day_in->start;
	switch (day_in->type) {
	case APPT:
		day_out->item.apt = apoint_dup(day_in->item.apt);
		break;
	case EVNT:
		day_out->item.ev = event_dup(day_in->item.ev, day_in->item.ev->day);
		break;
	case RECUR_APPT:
		day_out->item.rapt = recur_apoint_dup(day_in->item.rapt);
		break;
	case RECUR_EVNT:
		day_out->item.rev = recur_event_dup(day_in->item.rev);
		break;
	default:
		day_out->item.ptr = NULL;
		break;
	}
}

int day_store_events(time_t date)
{
	llist_item_t *i;
	int n = 0;
	LLIST_FOREACH(&eventlist, i) {
		struct event *ev = LLIST_GET_DATA(i);
		if (!event_inday(ev, &date))
			continue;
		day_add_item_raw(EVNT, date, ev->day, ev);
		n++;
	}
	return n;
}

int day_store_recur_events(time_t date)
{
	llist_item_t *i;
	int n = 0;
	LLIST_FOREACH(&recur_elist, i) {
		struct recur_event *rev = LLIST_GET_DATA(i);
		time_t occurrence;
		if (!recur_event_find_occurrence(rev, date, &occurrence))
			continue;
		day_add_item_raw(RECUR_EVNT, date, occurrence, rev);
		n++;
	}
	return n;
}

int day_store_apoints(time_t date)
