 * Store all items of a day; returns the number of items.
 */
static int day_store_one_day(time_t date)
{
	int n = 0;
	n += day_store_recur_events(date);
	n += day_store_events(date);
	n += day_store_recur_apoints(date);
	n += day_store_apoints(date);
	return n;
}

