#define NB_OPTIONS (sizeof(config_options) / sizeof(config_options[0]))

static const struct config_option *config_find(const char *key)
{
	size_t i;
	for (i = 0; i < NB_OPTIONS; i++) {
		if (!strcmp(config_options[i].name, key))
			return &config_options[i];
	}
	return NULL;
}

/* Parse one configuration line; returns 1 if it was a known option. */
static int config_set_from_line(char *line)
{
	char *key, *val;
	const struct config_option *o;

	key = line;
	val = strchr(line, '=');
	if (!val)
		EXIT_ON_ERROR("config.c", 588, "invalid configuration directive: \"%s\"", line);
	*val = '\0';
	val++;
	o = config_find(key);
	if (!o) {
		fprintf(stderr, _("unknown user option: \"%s\" (ignored)\n"), key);
		return 0;
	}
	if (!o->parse(val)) {
		fprintf(stderr, _("invalid option format: \"%s\" (ignored)\n"), key);
		return 0;
	}
	return 1;
}

void config_load(void)
{
	FILE *fp;
	char buf[BUFSIZ_LINE * 4];

	fp = fopen(path_conf, "r");
	if (!fp)
		return;
	while (fgets(buf, sizeof(buf), fp)) {
		char *p = buf;
		size_t l = strlen(p);
		while (l > 0 && (p[l - 1] == '\n' || p[l - 1] == '\r'))
			p[--l] = '\0';
		if (*p == '\0' || *p == '#')
			continue;
		config_set_from_line(p);
	}
	fclose(fp);
}

void config_save(void)
{
	FILE *fp_in, *fp_out;
	char buf[BUFSIZ_LINE * 4], val[BUFSIZ_LINE * 2];
	char *tmp;
	int written[NB_OPTIONS];
	size_t i;

	if (read_only)
		return;
	memset(written, 0, sizeof(written));
	tmp = strdup_printf("%s.XXXXXX", path_conf);
	{
		int fd = mkstemp(tmp);
		if (fd < 0) {
			mem_free(tmp);
			return;
		}
		fp_out = fdopen(fd, "w");
	}
	if (!fp_out) {
		mem_free(tmp);
		return;
	}
	fp_in = fopen(path_conf, "r");
	if (fp_in) {
		while (fgets(buf, sizeof(buf), fp_in)) {
			char *p = buf, *eq;
			size_t l = strlen(p);
			const struct config_option *o;
			while (l > 0 && (p[l - 1] == '\n' || p[l - 1] == '\r'))
				p[--l] = '\0';
			if (*p == '\0' || *p == '#' || !(eq = strchr(p, '='))) {
				fprintf(fp_out, "%s\n", p);
				continue;
			}
			*eq = '\0';
			o = config_find(p);
			if (!o) {
