int config_parse_bool(unsigned *dest, const char *val)
{
	if (strcmp(val, "yes") == 0)
		*dest = 1;
	else if (strcmp(val, "no") == 0)
		*dest = 0;
	else
		return 0;
	return 1;
}

static int config_parse_int(int *dest, const char *val)
{
	long v;
	if (!is_all_digit(val) && !(val[0] == '-' && is_all_digit(val + 1)))
		return 0;
	if (!strtol_safe(val, &v))
		return 0;
	*dest = (int)v;
	return 1;
}

static int config_parse_unsigned(unsigned *dest, const char *val)
{
	long v;
	if (!is_all_digit(val))
		return 0;
	if (!strtol_safe(val, &v))
		return 0;
	*dest = (unsigned)v;
	return 1;
}

static int config_parse_str(char *dest, const char *val)
{
	strncpy(dest, val, BUFSIZ_LINE - 1);
	dest[BUFSIZ_LINE - 1] = '\0';
