/* Print all days in the given range. */
static void date_arg_from_to(time_t from, time_t to, int add_line, const char *fmt_apt,
			     const char *fmt_rapt, const char *fmt_ev, const char *fmt_rev, int *limit)
{
	time_t date;
	char buf[BUFSIZ_LINE];

	for (date = from; date <= to; date = date_sec_change(date, 0, 1)) {
		day_store_items(date, 0, 0);
		if (day_item_count(0) == 0)
			continue;
		if (add_line)
			fputs("\n", stdout);
		date_sec2date_fmt(date, conf.output_datefmt, buf);
		fputs(buf, stdout);
		fputs(":\n", stdout);
		day_write_stdout(date, fmt_apt, fmt_rapt, fmt_ev, fmt_rev, limit);
		add_line = 1;
	}
}

