/* Parse a type mask like "event,apt,recur,todo". */
static int parse_type_mask(const char *str)
{
	char *buf = mem_strdup(str), *p;
	int mask = 0;

	p = strtok(buf, ",");
	while (p) {
		if (!strcmp(p, "event"))
			mask |= TYPE_MASK_EVENT;
		else if (!strcmp(p, "apt"))
			mask |= TYPE_MASK_APPT;
		else if (!strcmp(p, "recur-event"))
			mask |= TYPE_MASK_RECUR_EVENT;
		else if (!strcmp(p, "recur-apt"))
			mask |= TYPE_MASK_RECUR_APPT;
		else if (!strcmp(p, "recur"))
			mask |= TYPE_MASK_RECUR;
		else if (!strcmp(p, "cal"))
			mask |= TYPE_MASK_CAL;
		else if (!strcmp(p, "todo"))
			mask |= TYPE_MASK_TODO;
		else {
			mask = 0;
			break;
		}
		p = strtok(NULL, ",");
	}
	mem_free(buf);
	return mask;
}

/* Parse a date for a filter option: midnight if no time is given. */
static int parse_datearg(const char *str, time_t *ts)
{
	return parse_datetime(str, ts, 0);
}

/* As above, but end of day if no time is given. */
static int parse_datearg_eod(const char *str, time_t *ts)
{
	time_t t;
	if (!parse_datetime(str, &t, 0))
		return 0;
	if (!strchr(str, ' '))
		t = t + DAYINSEC - 1;
	*ts = t;
	return 1;
}

static int parse_daterange(const char *str, time_t *from, time_t *to)
{
	char *buf = mem_strdup(str), *comma;
	int ret = 0;

	comma = strchr(buf, ',');
	if (!comma)
		goto out;
	*comma = '\0';
	if (!parse_datearg(buf, from))
		goto out;
	if (!parse_datearg_eod(comma + 1, to))
		goto out;
	ret = 1;
out:
	mem_free(buf);
	return ret;
}

