static const char *optstr = "FgGhvnNaqQ::t::c:C:d:D:i:l:r::s::S:x::P";

/* Parse an integer with strtol, accepting trailing garbage (atoi-like). */
static long atoi_like(const char *s)
{
	return strtol(s, NULL, 10);
}

/* Strict integer (optional leading minus). */
static int strict_int(const char *s, long *v)
{
	const char *p = s;
	if (*p == '-')
		p++;
	if (!is_all_digit(p))
		return 0;
	return strtol_safe(s, v);
}

int parse_args(int argc, char **argv)
{
	/* Command-line flags */
	int grep = 0, purge = 0, query = 0, next = 0, filter_opt = 0, gc = 0;
	int version = 0, help = 0, status = 0, daemon = 0, import = 0, export = 0;
	int range = 0, limit = INT_MAX, export_uid = 0;
	time_t from = -1, to = -1;
	int fmt_set = 0, range_set = 0, from_set = 0, to_set = 0;
	int cal_flags = 0, todo_flags = 0, type_mask_set = 0;
	int todo_priority = 0;
	int xfmt = IO_EXPORT_ICAL;
	int input_datefmt = -1;
	const char *input_datefmt_str = NULL;
	const char *output_datefmt = NULL;
	const char *cfile = NULL, *datadir = NULL, *confdir = NULL, *ifile = NULL;
	int ch;
	long num;
	int non_interactive;
	const char *fmt_apt_s = NULL, *fmt_rapt_s = NULL, *fmt_ev_s = NULL, *fmt_rev_s = NULL, *fmt_todo_s = NULL;
	int filter_set = 0;
	int use_daemon_check = 0;

	(void)use_daemon_check;

	while ((ch = getopt_long(argc, argv, optstr, longopts, NULL)) != -1) {
		if (help || version)
			continue;
		switch (ch) {
		case 'a':
			query = 1;
			cal_flags = 1;
			break;
		case 'c':
			cfile = optarg;
			break;
		case 'C':
			confdir = optarg;
			break;
		case 'd':
			query = 1;
			cal_flags = 1;
			if (strict_int(optarg, &num)) {
				range = (int)num;
				range_set = 1;
				if (range == 0)
					EXIT_ON_ERROR("args.c", 546, "invalid range: %s", optarg);
			} else {
				if (!parse_datetime(optarg, &from, 0))
					EXIT_ON_ERROR("args.c", 550, "invalid date: %s", optarg);
				from_set = 1;
			}
			break;
		case 'D':
			datadir = optarg;
			break;
		case 'F':
			filter_opt = 1;
			break;
		case 'g':
			gc = 1;
			break;
		case 'G':
			grep = 1;
			break;
		case 'h':
			help = 1;
			break;
		case 'i':
			import = 1;
			ifile = optarg;
			break;
		case 'l':
			limit = (int)atoi_like(optarg);
			break;
		case 'n':
			next = 1;
			break;
		case 'N':
			break;
		case 'P':
			purge = 1;
			break;
		case 'q':
			quiet = 1;
			break;
		case 'Q':
			query = 1;
			break;
		case 'r':
			query = 1;
			cal_flags = 1;
			if (optarg) {
				range = (int)atoi_like(optarg);
				if (range == 0)
					EXIT_ON_ERROR("args.c", 590, "invalid range: %s", optarg);
			} else {
				range = 1;
			}
			range_set = 1;
			break;
		case 's':
			query = 1;
			cal_flags = 1;
			if (optarg) {
				if (!parse_datetime(optarg, &from, 0))
					EXIT_ON_ERROR("args.c", 598, "invalid date: %s", optarg);
			} else {
				from = get_today();
			}
			from_set = 1;
			break;
		case 'S':
			if (filter.regex)
				EXIT_ON_ERROR("args.c", 657, "cannot handle more than one regular expression");
			filter.regex = mem_malloc(sizeof(regex_t));
			if (regcomp(filter.regex, optarg, REG_EXTENDED | REG_NOSUB))
				EXIT_ON_ERROR("args.c", 660, "could not compile regular expression: %s", optarg);
			filter_set = 1;
			break;
		case 't':
			query = 1;
			todo_flags = 1;
			filter.uncompleted = 1;
			if (optarg) {
				if (!is_all_digit(optarg))
					EXIT_ON_ERROR("args.c", 605, "invalid priority: %s", optarg);
				num = atoi_like(optarg);
				if (num < 0 || num > 9)
					EXIT_ON_ERROR("args.c", 612, "invalid priority: %s", optarg);
				todo_priority = (int)num;
				if (todo_priority == 0) {
					filter.completed = 1;
					filter.uncompleted = 0;
					filter.priority = 0;
				} else {
					filter.priority = todo_priority;
				}
			}
			break;
		case 'v':
			version = 1;
			break;
		case 'x':
			export = 1;
			if (optarg) {
				if (!strcmp(optarg, "ical"))
					xfmt = IO_EXPORT_ICAL;
				else if (!strcmp(optarg, "pcal"))
					xfmt = IO_EXPORT_PCAL;
				else
					EXIT_ON_ERROR("args.c", 631, "invalid export format: %s", optarg);
			}
			break;
		case OPT_FILTER_INVERT:
			filter.invert = 1;
			filter_set = 1;
			break;
		case OPT_FILTER_TYPE:
			filter.type_mask = parse_type_mask(optarg);
			if (!filter.type_mask)
				EXIT_ON_ERROR("args.c", 647, "invalid filter mask");
			type_mask_set = 1;
			filter_set = 1;
			break;
		case OPT_FILTER_HASH:
			filter.hash = mem_strdup(optarg);
			filter_set = 1;
			break;
		case OPT_FILTER_PATTERN:
			if (filter.regex)
				EXIT_ON_ERROR("args.c", 657, "cannot handle more than one regular expression");
			filter.regex = mem_malloc(sizeof(regex_t));
			if (regcomp(filter.regex, optarg, REG_EXTENDED | REG_NOSUB))
				EXIT_ON_ERROR("args.c", 660, "could not compile regular expression: %s", optarg);
			filter_set = 1;
			break;
		case OPT_FILTER_START_FROM:
			if (filter.start_from != -1)
				EXIT_ON_ERROR("args.c", 670, "filter criterion already in use: %s", "--filter-start-from");
			if (!parse_datearg(optarg, &filter.start_from))
				EXIT_ON_ERROR("args.c", 673, "invalid date: %s", optarg);
			filter_set = 1;
			break;
		case OPT_FILTER_START_TO:
			if (filter.start_to != -1)
				EXIT_ON_ERROR("args.c", 680, "filter criterion already in use: %s", "--filter-start-to");
			if (!parse_datearg_eod(optarg, &filter.start_to))
				EXIT_ON_ERROR("args.c", 683, "invalid date: %s", optarg);
			filter_set = 1;
			break;
		case OPT_FILTER_START_AFTER:
			if (filter.start_from != -1)
				EXIT_ON_ERROR("args.c", 690, "filter criterion already in use: %s", "--filter-start-after");
			if (!parse_datearg_eod(optarg, &filter.start_from))
				EXIT_ON_ERROR("args.c", 693, "invalid date: %s", optarg);
			filter.start_from++;
			filter_set = 1;
			break;
		case OPT_FILTER_START_BEFORE:
			if (filter.start_to != -1)
				EXIT_ON_ERROR("args.c", 700, "filter criterion already in use: %s", "--filter-start-before");
			if (!parse_datearg(optarg, &filter.start_to))
				EXIT_ON_ERROR("args.c", 703, "invalid date: %s", optarg);
			filter.start_to--;
			filter_set = 1;
			break;
		case OPT_FILTER_START_RANGE:
			if (filter.start_from != -1 || filter.start_to != -1)
				EXIT_ON_ERROR("args.c", 714, "filter criterion already in use: %s", "--filter-start-range");
			if (!parse_daterange(optarg, &filter.start_from, &filter.start_to))
				EXIT_ON_ERROR("args.c", 719, "invalid date range: %s", optarg);
			filter_set = 1;
			break;
		case OPT_FILTER_END_FROM:
			if (filter.end_from != -1)
				EXIT_ON_ERROR("args.c", 726, "filter criterion already in use: %s", "--filter-end-from");
			if (!parse_datearg(optarg, &filter.end_from))
				EXIT_ON_ERROR("args.c", 729, "invalid date: %s", optarg);
			filter_set = 1;
			break;
		case OPT_FILTER_END_TO:
			if (filter.end_to != -1)
				EXIT_ON_ERROR("args.c", 736, "filter criterion already in use: %s", "--filter-end-to");
			if (!parse_datearg_eod(optarg, &filter.end_to))
				EXIT_ON_ERROR("args.c", 739, "invalid date: %s", optarg);
			filter_set = 1;
			break;
		case OPT_FILTER_END_AFTER:
			if (filter.end_from != -1)
				EXIT_ON_ERROR("args.c", 746, "filter criterion already in use: %s", "--filter-end-after");
			if (!parse_datearg_eod(optarg, &filter.end_from))
				EXIT_ON_ERROR("args.c", 749, "invalid date: %s", optarg);
			filter.end_from++;
			filter_set = 1;
			break;
		case OPT_FILTER_END_BEFORE:
			if (filter.end_to != -1)
				EXIT_ON_ERROR("args.c", 756, "filter criterion already in use: %s", "--filter-end-before");
			if (!parse_datearg(optarg, &filter.end_to))
				EXIT_ON_ERROR("args.c", 759, "invalid date: %s", optarg);
			filter.end_to--;
			filter_set = 1;
			break;
		case OPT_FILTER_END_RANGE:
			if (filter.end_from != -1 || filter.end_to != -1)
				EXIT_ON_ERROR("args.c", 770, "filter criterion already in use: %s", "--filter-end-range");
			if (!parse_daterange(optarg, &filter.end_from, &filter.end_to))
				EXIT_ON_ERROR("args.c", 775, "invalid date range: %s", optarg);
			filter_set = 1;
			break;
		case OPT_FILTER_PRIORITY:
			num = atoi_like(optarg);
			if (!is_all_digit(optarg) || num < 1 || num > 9)
				EXIT_ON_ERROR("args.c", 783, "invalid priority: %s", optarg);
			filter.priority = (int)num;
			filter_set = 1;
			break;
		case OPT_FILTER_COMPLETED:
			filter.completed = 1;
			filter_set = 1;
			break;
		case OPT_FILTER_UNCOMPLETED:
			filter.uncompleted = 1;
			filter_set = 1;
			break;
		case OPT_FROM:
			if (!parse_datetime(optarg, &from, 0))
				EXIT_ON_ERROR("args.c", 797, "invalid date: %s", optarg);
			from_set = 1;
			break;
		case OPT_TO:
			if (!parse_datetime(optarg, &to, 0))
				EXIT_ON_ERROR("args.c", 803, "invalid date: %s", optarg);
			to_set = 1;
			break;
		case OPT_DAYS:
			range = (int)atoi_like(optarg);
			if (range == 0)
				EXIT_ON_ERROR("args.c", 809, "invalid range: %s", optarg);
			range_set = 1;
			break;
		case OPT_FMT_APT:
			fmt_apt_s = optarg;
			fmt_set = 1;
			break;
		case OPT_FMT_RAPT:
			fmt_rapt_s = optarg;
			fmt_set = 1;
			break;
		case OPT_FMT_EV:
			fmt_ev_s = optarg;
			fmt_set = 1;
			break;
		case OPT_FMT_REV:
			fmt_rev_s = optarg;
			fmt_set = 1;
			break;
		case OPT_FMT_TODO:
			fmt_todo_s = optarg;
			fmt_set = 1;
			break;
		case OPT_EXPORT_UID:
			export_uid = 1;
			break;
		case OPT_DUMP_IMPORTED:
			dump_imported = 1;
			break;
		case OPT_INPUT_DATEFMT:
			input_datefmt_str = optarg;
			input_datefmt = (int)atoi_like(optarg);
			if (!is_all_digit(optarg) || input_datefmt < DATEFMT_MMDDYYYY || input_datefmt >= DATEFMT_MAX)
				EXIT_ON_ERROR("args.c", 852, "invalid input date format: %s", optarg);
			conf.input_datefmt = input_datefmt;
			break;
		case OPT_OUTPUT_DATEFMT:
			output_datefmt = optarg;
			strncpy(conf.output_datefmt, optarg, BUFSIZ_LINE - 1);
			conf.output_datefmt[BUFSIZ_LINE - 1] = '\0';
			break;
		case OPT_READ_ONLY:
			read_only = 1;
			break;
		case OPT_STATUS:
			status = 1;
			break;
		case OPT_DAEMON:
			daemon = 1;
			break;
		default:
			usage_try();
			exit_calcurse(EXIT_FAILURE);
		}
	}
	(void)input_datefmt_str;
	(void)output_datefmt;

	if (help) {
		help_arg();
		exit_calcurse(EXIT_SUCCESS);
	}
	if (version) {
		version_arg();
		exit_calcurse(EXIT_SUCCESS);
	}

	argc -= optind;
	argv += optind;
	if (argc > 0)
		EXIT_ON_ERROR("args.c", 880, "invalid argument combination");

	if (daemon) {
		int cpid = io_get_pid(path_cpid);
		(void)cpid;
	}

	non_interactive = status + gc + import + export + grep + purge + next + query + daemon;
	if (non_interactive > 1)
		EXIT_ON_ERROR("args.c", 880, "invalid argument combination");
	if (filter_set && !(query || grep || purge || export))
		EXIT_ON_ERROR("args.c", 880, "invalid argument combination");
	if (fmt_set && !(query || grep || dump_imported))
		EXIT_ON_ERROR("args.c", 880, "invalid argument combination");
	if ((from_set || to_set || range_set) && !query)
		EXIT_ON_ERROR("args.c", 880, "invalid argument combination");
	if (purge && filter.invert)
		EXIT_ON_ERROR("args.c", 880, "invalid argument combination");
	if (range_set && to_set)
		EXIT_ON_ERROR("args.c", 882, "cannot specify a range and an end date");

	if (query) {
		if (from == -1)
			from = get_today();
		if (range_set) {
			if (range > 0) {
				to = date_sec_change(from, 0, range - 1);
			} else {
				to = date_sec_change(from, 0, 1) - 1;
				from = date_sec_change(to, 0, range + 1);
			}
		} else if (to == -1) {
			to = from;
		}
		if (from > to)
			EXIT_ON_ERROR("args.c", 887, "end date cannot come before start date");
	}

	if (filter_opt) {
		/* deprecated -F: keep matching items */
		purge = 1;
		filter.invert = !filter.invert;
	}

	/* Type mask from the short forms. */
	if (!type_mask_set) {
		if (cal_flags && !todo_flags)
			filter.type_mask = TYPE_MASK_CAL;
		else if (todo_flags && !cal_flags)
			filter.type_mask = TYPE_MASK_TODO;
		else
			filter.type_mask = TYPE_MASK_ALL;
	}

	io_init(cfile, datadir, confdir);

	if (status) {
		status_arg();
		return 1;
	}
	if (daemon) {
		dmon_start_from_cmdline(cfile, datadir, confdir);
		return 1;
	}

	if (!(query || grep || purge || export || gc || import || next))
		return 0;	/* interactive mode */

	/* Non-interactive mode. */
	ui_mode = UI_CMDLINE;

	if (gc) {
		io_check_data_files_quiet();
		config_load();
		io_load_data(NULL, 0);
		note_gc();
		return 1;
	}

	if (import) {
		io_check_data_files_quiet();
		config_load();
		if (input_datefmt > 0)
			conf.input_datefmt = input_datefmt;
		if (output_datefmt)
			strncpy(conf.output_datefmt, output_datefmt, BUFSIZ_LINE - 1);
		io_load_data(NULL, 0);
		if (dump_imported) {
			fmt_apt = fmt_apt_s ? fmt_apt_s : grep_fmt_default;
			fmt_rapt = fmt_rapt_s ? fmt_rapt_s : grep_fmt_default;
			fmt_ev = fmt_ev_s ? fmt_ev_s : grep_fmt_default;
			fmt_rev = fmt_rev_s ? fmt_rev_s : grep_fmt_default;
			fmt_todo = fmt_todo_s ? fmt_todo_s : grep_fmt_default;
		}
		io_import_data(IO_IMPORT_ICAL, ifile, fmt_ev, fmt_rev, fmt_apt, fmt_rapt, fmt_todo);
		io_save_apts(path_apts);
		io_save_todo(path_todo);
		return 1;
	}

	if (export) {
		io_check_data_files_quiet();
		config_load();
		if (input_datefmt > 0)
			conf.input_datefmt = input_datefmt;
		if (output_datefmt)
			strncpy(conf.output_datefmt, output_datefmt, BUFSIZ_LINE - 1);
		io_load_data(&filter, 0);
		io_export_data(xfmt, export_uid);
		return 1;
	}

	if (grep) {
		io_check_data_files_quiet();
		config_load();
		if (input_datefmt > 0)
			conf.input_datefmt = input_datefmt;
		if (output_datefmt)
			strncpy(conf.output_datefmt, output_datefmt, BUFSIZ_LINE - 1);
		io_load_data(&filter, 0);
		{
			int l = limit;
			int add_line = 0;
			(void)add_line;
			io_dump_todo(fmt_todo_s ? fmt_todo_s : grep_fmt_default);
			io_dump_apts(fmt_apt_s ? fmt_apt_s : grep_fmt_default,
				     fmt_rapt_s ? fmt_rapt_s : grep_fmt_default,
				     fmt_ev_s ? fmt_ev_s : grep_fmt_default,
				     fmt_rev_s ? fmt_rev_s : grep_fmt_default);
			(void)l;
		}
		return 1;
	}

	if (purge) {
		io_check_data_files_quiet();
		config_load();
		if (input_datefmt > 0)
			conf.input_datefmt = input_datefmt;
		filter.invert = !filter.invert;
		io_load_data(&filter, 0);
		io_save_apts(path_apts);
		io_save_todo(path_todo);
		return 1;
	}

	if (next) {
		io_check_data_files_quiet();
		config_load();
		io_load_app(NULL);
		next_arg();
		return 1;
	}

	if (query) {
		int add_line = 0;
		io_check_data_files_quiet();
		config_load();
		if (input_datefmt > 0)
			conf.input_datefmt = input_datefmt;
		if (output_datefmt) {
			strncpy(conf.output_datefmt, output_datefmt, BUFSIZ_LINE - 1);
			conf.output_datefmt[BUFSIZ_LINE - 1] = '\0';
		}
		io_load_data(&filter, 0);
		if (filter.type_mask & TYPE_MASK_TODO)
			todo_arg(filter.priority, filter.completed,
				 fmt_todo_s ? fmt_todo_s : "%p. %m\n", &limit, &add_line);
		if (filter.type_mask & TYPE_MASK_CAL)
			date_arg_from_to(from, to, add_line,
					 fmt_apt_s ? fmt_apt_s : " - %S -> %E\n\t%m\n",
					 fmt_rapt_s ? fmt_rapt_s : " - %S -> %E\n\t%m\n",
					 fmt_ev_s ? fmt_ev_s : " * %m\n",
					 fmt_rev_s ? fmt_rev_s : " * %m\n", &limit);
		return 1;
	}

	return 0;
}
EOF
echo ok"}

