static void status_arg(void)
{
	int cpid, dpid;

	cpid = io_get_pid(path_cpid);
	dpid = io_get_pid(path_dpid);

	if (cpid && kill(cpid, 0) == 0)
		printf(_("calcurse is running (pid %d)\n"), cpid);
	else if (dpid && kill(dpid, 0) == 0)
		printf(_("calcurse is running in background (pid %d)\n"), dpid);
	else
		puts(_("calcurse is not running"));
}

static void next_arg(void)
{
	struct notify_app next_app;
	const long current_time = now();
	int time_left, hours_left, min_left;

	next_app.time = current_time + DAYINSEC;
	next_app.got_app = 0;
	next_app.txt = NULL;
	next_app.state = 0;

	next_app = *(struct notify_app *)recur_apoint_check_next_ptr(&next_app, current_time, get_today());
	apoint_check_next(&next_app, current_time);

	if (next_app.got_app) {
		time_left = next_app.time - current_time;
		hours_left = (time_left / HOURINSEC);
		min_left = (time_left - hours_left * HOURINSEC) / MININSEC;
		fputs(_("next appointment:\n"), stdout);
		printf("   [%02d:%02d] %s\n", hours_left, min_left, next_app.txt);
		mem_free(next_app.txt);
	}
}

/* Print all days in the given range. */
static void date_arg_from_to(time_t from, time_t to, int add_line, const char *fmt_apt,
			     const char *fmt_rapt, const char *fmt_ev, const char *fmt_rev, int *limit)
{
	time_t date;
	char buf[BUFSIZ_LINE];

	for (date = from; date <= to; date = date_sec_change(date, 0, 1)) {
		day_store_items(date, 0, 0);
		if (day_item_count(0) == 0)
			continue;
		if (add_line)
			fputs("\n", stdout);
		date_sec2date_fmt(date, conf.output_datefmt, buf);
		fputs(buf, stdout);
		fputs(":\n", stdout);
		day_write_stdout(date, fmt_apt, fmt_rapt, fmt_ev, fmt_rev, limit);
		add_line = 1;
	}
}

static void todo_arg(int priority, int completed, const char *fmt_todo, int *limit, int *add_line)
{
	llist_item_t *i;
	int title = 1;
	char *titlestr;

	(void)priority;
	titlestr = completed ? _("completed tasks:\n") : _("to do:\n");

	LLIST_FOREACH(&todolist, i) {
		struct todo *todo = LLIST_GET_DATA(i);
		if (*limit == 0)
			break;
		if (title) {
			if (*add_line)
				fputs("\n", stdout);
			fputs(titlestr, stdout);
			title = 0;
			*add_line = 1;
		}
		print_todo(fmt_todo, todo);
		(*limit)--;
	}
}

/* Parse a type mask like "event,apt,recur,todo". */
static int parse_type_mask(const char *str)
{
	char *buf = mem_strdup(str), *p;
	int mask = 0;

	p = strtok(buf, ",");
	while (p) {
		if (!strcmp(p, "event"))
			mask |= TYPE_MASK_EVENT;
		else if (!strcmp(p, "apt"))
			mask |= TYPE_MASK_APPT;
		else if (!strcmp(p, "recur-event"))
			mask |= TYPE_MASK_RECUR_EVENT;
		else if (!strcmp(p, "recur-apt"))
			mask |= TYPE_MASK_RECUR_APPT;
		else if (!strcmp(p, "recur"))
			mask |= TYPE_MASK_RECUR;
		else if (!strcmp(p, "cal"))
			mask |= TYPE_MASK_CAL;
		else if (!strcmp(p, "todo"))
			mask |= TYPE_MASK_TODO;
		else {
			mask = 0;
			break;
		}
		p = strtok(NULL, ",");
	}
	mem_free(buf);
	return mask;
}

/* Parse a date for a filter option: midnight if no time is given. */
static int parse_datearg(const char *str, time_t *ts)
{
	return parse_datetime(str, ts, 0);
}

/* As above, but end of day if no time is given. */
static int parse_datearg_eod(const char *str, time_t *ts)
{
	time_t t;
	if (!parse_datetime(str, &t, 0))
		return 0;
	if (!strchr(str, ' '))
		t = t + DAYINSEC - 1;
	*ts = t;
	return 1;
}

static int parse_daterange(const char *str, time_t *from, time_t *to)
{
	char *buf = mem_strdup(str), *comma;
	int ret = 0;

	comma = strchr(buf, ',');
	if (!comma)
		goto out;
	*comma = '\0';
	if (!parse_datearg(buf, from))
		goto out;
	if (!parse_datearg_eod(comma + 1, to))
		goto out;
	ret = 1;
out:
	mem_free(buf);
	return ret;
}

