{"command":"cd /workspace; cat > src/ical.c <<'EOF'
#include "calcurse.h"

#define ICALDATEFMT		"%Y%m%d"
#define ICALDATETIMEFMT		"%Y%m%dT%H%M%S"
#define SEPARATOR		"-- \n"
#define INDENT			"    "

typedef enum { UNDEFINED, APPOINTMENT, EVENT } ical_vevent_e;

typedef struct {
	enum recur_type type;
	int freq;
	time_t until;
	int count;
	llist_t bymonth;
	llist_t bywday;
	llist_t bymonthday;
} ical_rpt_t;

/* ---- export ---- */

static void ical_export_header(FILE *stream)
{
	fputs("BEGIN:VCALENDAR\n", stream);
	fputs("VERSION:2.0\n", stream);
	fprintf(stream, "PRODID:-//calcurse//NONSGML v%s//EN\n", VERSION);
}

static void ical_export_footer(FILE *stream)
{
	fputs("END:VCALENDAR\n", stream);
}

/* Escape a TEXT value: backslash, comma, semicolon and newline. */
static void ical_export_text(FILE *stream, const char *s)
{
	for (; *s; s++) {
		switch (*s) {
		case '\\':
			fputs("\\\\", stream);
			break;
		case ',':
			fputs("\\,", stream);
			break;
		case ';':
			fputs("\\;", stream);
			break;
		case '\n':
			fputs("\\n", stream);
			break;
		default:
			putc(*s, stream);
		}
	}
}

static void ical_export_valarm(FILE *stream)
{
	fputs("BEGIN:VALARM\n", stream);
	fprintf(stream, "TRIGGER:-PT%dS\n", conf.notify_warning);
	fputs("ACTION:DISPLAY\n", stream);
	fputs("END:VALARM\n", stream);
}

/*
 * Export the note of an item as DESCRIPTION, LOCATION and COMMENT.
 */
static void ical_export_note(FILE *stream, const char *note)
{
	char *buf, *p, *end, *sep;
	char *desc = NULL, *loc = NULL, *com = NULL;
	size_t len;

	if (!note)
		return;
	buf = note_read_file(note);
	if (!buf)
		return;
	len = strlen(buf);
	if (len == 0) {
		mem_free(buf);
		return;
	}
	/* Remove the trailing character (assumed to be a newline). */
	buf[len - 1] = '\0';

	/* Find the separator at the start of a line. */
	sep = NULL;
	if (starts_with(buf, SEPARATOR))
		sep = buf;
	else {
		p = buf;
		while ((p = strstr(p, "\n" SEPARATOR)) != NULL) {
			sep = p + 1;
			break;
		}
	}
	if (sep) {
		if (sep > buf) {
			/* description is everything before the newline preceding the separator */
			*(sep - 1) = '\0';
			desc = buf;
		}
		p = sep + strlen(SEPARATOR);
		/* parse Location:, Comment: lines */
		while (*p) {
			end = strchr(p, '\n');
			if (end)
				*end = '\0';
			if (starts_with(p, "Location: ")) {
				loc = p + strlen("Location: ");
			} else if (starts_with(p, "Comment: ")) {
				/* comment with indented continuation lines */
				char *c = p + strlen("Comment: ");
				char *q = end ? end + 1 : NULL;
				char *out = mem_strdup(c);
				while (q && starts_with(q, INDENT)) {
					char *e2 = strchr(q, '\n');
					char *tmp;
					if (e2)
						*e2 = '\0';
					tmp = strdup_printf("%s\n%s", out, q + strlen(INDENT));
					mem_free(out);
					out = tmp;
					q = e2 ? e2 + 1 : NULL;
				}
				com = out;
				if (!q)
					break;
				p = q;
				continue;
			}
			if (!end)
				break;
			p = end + 1;
		}
	} else {
		desc = buf;
	}

	if (desc) {
		fputs("DESCRIPTION:", stream);
		ical_export_text(stream, desc);
		putc('\n', stream);
	}
	if (loc) {
		fputs("LOCATION:", stream);
		ical_export_text(stream, loc);
		putc('\n', stream);
	}
	if (com) {
		fputs("COMMENT:", stream);
		ical_export_text(stream, com);
		putc('\n', stream);
		mem_free(com);
	}
	mem_free(buf);
}

static void ical_export_rpt(FILE *stream, struct rpt *rpt, int with_time)
{
	char buf[BUFSIZ_LINE];
	struct tm tm;
	llist_item_t *i;
	const char *freq;

	switch (rpt->type) {
	case RECUR_DAILY:
		freq = "DAILY";
		break;
	case RECUR_WEEKLY:
		freq = "WEEKLY";
		break;
	case RECUR_MONTHLY:
		freq = "MONTHLY";
		break;
	case RECUR_YEARLY:
		freq = "YEARLY";
		break;
	default:
		freq = "DAILY";
		break;
	}
	fprintf(stream, "RRULE:FREQ=%s", freq);
	if (rpt->freq > 1)
		fprintf(stream, ";INTERVAL=%d", rpt->freq);
	if (rpt->until != 0) {
		localtime_r_safe(rpt->until, &tm);
		strftime(buf, sizeof(buf), with_time ? ICALDATETIMEFMT : ICALDATEFMT, &tm);
		fprintf(stream, ";UNTIL=%s", buf);
	}
	if (LLIST_FIRST(&rpt->bymonth)) {
		fputs(";BYMONTH=", stream);
		LLIST_FOREACH(&rpt->bymonth, i)
			fprintf(stream, "%s%d", i == LLIST_FIRST(&rpt->bymonth) ? "" : ",", *(int *)LLIST_GET_DATA(i));
	}
	if (LLIST_FIRST(&rpt->bywday)) {
		static const char *wd[7] = { "SU", "MO", "TU", "WE", "TH", "FR", "SA" };
		fputs(";BYDAY=", stream);
		LLIST_FOREACH(&rpt->bywday, i) {
			int v = *(int *)LLIST_GET_DATA(i);
			int order = v / 7, r = v % 7, wday;
			if (i != LLIST_FIRST(&rpt->bywday))
				putc(',', stream);
			if (order == 0) {
				wday = r < 0 ? 0 : r;
				fprintf(stream, "%s", wd[wday]);
			} else if (order > 0) {
				fprintf(stream, "+%d%s", order, wd[r < 0 ? 0 : r]);
			} else {
				fprintf(stream, "%d%s", order, wd[-r]);
			}
		}
	}
	if (LLIST_FIRST(&rpt->bymonthday)) {
		fputs(";BYMONTHDAY=", stream);
		LLIST_FOREACH(&rpt->bymonthday, i)
			fprintf(stream, "%s%d", i == LLIST_FIRST(&rpt->bymonthday) ? "" : ",", *(int *)LLIST_GET_DATA(i));
	}
	putc('\n', stream);
}

static void ical_export_exc(FILE *stream, llist_t *exc, int is_event, time_t start)
{
	llist_item_t *i;
	char buf[BUFSIZ_LINE];
	struct tm tm;

	if (!LLIST_FIRST(exc))
		return;
	fputs(is_event ? "EXDATE;VALUE=DATE:" : "EXDATE:", stream);
	LLIST_FOREACH(exc, i) {
		struct excp *e = LLIST_GET_DATA(i);
		time_t t = e->st;
		if (!is_event)
			t = update_time_in_date(t, get_item_hour(start), get_item_min(start));
		localtime_r_safe(t, &tm);
		strftime(buf, sizeof(buf), ICALDATETIMEFMT, &tm);
		fprintf(stream, "%s%s", i == LLIST_FIRST(exc) ? "" : ",", buf);
	}
	putc('\n', stream);
}

static void ical_export_uid(FILE *stream, char *hash)
{
	fprintf(stream, "UID:%s\n", hash);
	mem_free(hash);
}

static void ical_export_recur_events(FILE *stream, int export_uid)
{
	llist_item_t *i;
	char buf[BUFSIZ_LINE];
	struct tm tm;

	LLIST_FOREACH(&recur_elist, i) {
		struct recur_event *rev = LLIST_GET_DATA(i);
		localtime_r_safe(rev->day, &tm);
		strftime(buf, sizeof(buf), ICALDATEFMT, &tm);
		fputs("BEGIN:VEVENT\n", stream);
		if (export_uid)
			ical_export_uid(stream, recur_event_hash(rev));
		fprintf(stream, "DTSTART;VALUE=DATE:%s\n", buf);
		ical_export_rpt(stream, rev->rpt, 0);
		ical_export_exc(stream, &rev->exc, 1, rev->day);
		fputs("SUMMARY:", stream);
		ical_export_text(stream, rev->mesg);
		putc('\n', stream);
		ical_export_note(stream, rev->note);
		fputs("END:VEVENT\n", stream);
	}
}

static void ical_export_events(FILE *stream, int export_uid)
{
	llist_item_t *i;
	char buf[BUFSIZ_LINE];
	struct tm tm;

	LLIST_FOREACH(&eventlist, i) {
		struct event *ev = LLIST_GET_DATA(i);
		localtime_r_safe(ev->day, &tm);
		strftime(buf, sizeof(buf), ICALDATEFMT, &tm);
		fputs("BEGIN:VEVENT\n", stream);
		if (export_uid)
			ical_export_uid(stream, event_hash(ev));
		fprintf(stream, "DTSTART;VALUE=DATE:%s\n", buf);
		fputs("SUMMARY:", stream);
		ical_export_text(stream, ev->mesg);
		putc('\n', stream);
		ical_export_note(stream, ev->note);
		fputs("END:VEVENT\n", stream);
	}
}

static void ical_export_duration(FILE *stream, long dur)
{
	long days, hours, mins, secs;
	if (dur <= 0)
		return;
	days = dur / DAYINSEC;
	hours = (dur % DAYINSEC) / HOURINSEC;
	mins = (dur % HOURINSEC) / MININSEC;
	secs = dur % MININSEC;
	fprintf(stream, "DURATION:P%ldDT%ldH%ldM%ldS\n", days, hours, mins, secs);
}

static void ical_export_recur_apoints(FILE *stream, int export_uid)
{
	llist_item_t *i;
	char buf[BUFSIZ_LINE];
	struct tm tm;

	LLIST_FOREACH(&recur_alist_p, i) {
		struct recur_apoint *rapt = LLIST_GET_DATA(i);
		localtime_r_safe(rapt->start, &tm);
		strftime(buf, sizeof(buf), ICALDATETIMEFMT, &tm);
		fputs("BEGIN:VEVENT\n", stream);
		if (export_uid)
			ical_export_uid(stream, recur_apoint_hash(rapt));
		fprintf(stream, "DTSTART:%s\n", buf);
		ical_export_duration(stream, rapt->dur);
		ical_export_rpt(stream, rapt->rpt, 1);
		ical_export_exc(stream, &rapt->exc, 0, rapt->start);
		fputs("SUMMARY:", stream);
		ical_export_text(stream, rapt->mesg);
		putc('\n', stream);
		ical_export_note(stream, rapt->note);
		if (rapt->state & APOINT_NOTIFY)
			ical_export_valarm(stream);
		fputs("END:VEVENT\n", stream);
	}
}

static void ical_export_apoints(FILE *stream, int export_uid)
{
	llist_item_t *i;
	char buf[BUFSIZ_LINE];
	struct tm tm;

	LLIST_FOREACH(&alist_p, i) {
		struct apoint *apt = LLIST_GET_DATA(i);
		localtime_r_safe(apt->start, &tm);
		strftime(buf, sizeof(buf), ICALDATETIMEFMT, &tm);
		fputs("BEGIN:VEVENT\n", stream);
		if (export_uid)
			ical_export_uid(stream, apoint_hash(apt));
		fprintf(stream, "DTSTART:%s\n", buf);
		ical_export_duration(stream, apt->dur);
		fputs("SUMMARY:", stream);
		ical_export_text(stream, apt->mesg);
		putc('\n', stream);
		ical_export_note(stream, apt->note);
		if (apt->state & APOINT_NOTIFY)
			ical_export_valarm(stream);
		fputs("END:VEVENT\n", stream);
	}
}

static void ical_export_todo(FILE *stream, int export_uid)
{
	llist_item_t *i;

	LLIST_FOREACH(&todolist, i) {
		struct todo *todo = LLIST_GET_DATA(i);
		fputs("BEGIN:VTODO\n", stream);
		if (export_uid)
			ical_export_uid(stream, todo_hash(todo));
		fprintf(stream, "PRIORITY:%d\n", todo->id);
		fputs("SUMMARY:", stream);
		ical_export_text(stream, todo->mesg);
		putc('\n', stream);
		ical_export_note(stream, todo->note);
		if (todo->completed)
			fputs("STATUS:COMPLETED\n", stream);
		fputs("END:VTODO\n", stream);
	}
}

void ical_export_data(FILE *stream, int export_uid)
{
	ical_export_header(stream);
	ical_export_recur_events(stream, export_uid);
	ical_export_events(stream, export_uid);
	ical_export_recur_apoints(stream, export_uid);
	ical_export_apoints(stream, export_uid);
	ical_export_todo(stream, export_uid);
	ical_export_footer(stream);
}

/* ---- import ---- */

static void ical_log_init(FILE *log, const char *file, float version)
{
	const char *header =
	    "+-------------------------------------------------------------------+\n"
	    "| Calcurse icalendar import log.                                    |\n"
	    "|                                                                   |\n"
	    "| Import from icalendar file                                        |\n"
	    "|       %-60s|\n"
	    "| version %.1f at %s.                                  |\n"
	    "|                                                                   |\n"
	    "| Items which could not be imported are described below.            |\n"
	    "| The log line format is as follows:                                |\n"
	    "|                                                                   |\n"
	    "|       TYPE [LINE]: DESCRIPTION                                    |\n"
	    "|                                                                   |\n"
	    "| where:                                                            |\n"
	    "|  * TYPE is the item type, 'VEVENT' or 'VTODO'                     |\n"
	    "|  * LINE is the line in the import file where the item begins      |\n"
	    "|  * DESCRIPTION explains why the item could not be imported        |\n"
	    "+-------------------------------------------------------------------+\n\n";
	char *date;
	time_t t = now();
	struct tm tm;
	char buf[BUFSIZ_LINE];

	localtime_r_safe(t, &tm);
	strftime(buf, sizeof(buf), "%m/%d/%Y %H:%M", &tm);
	date = buf;
	if (log)
		fprintf(log, header, file ? file : "(stdin)", version, date);
}

static void ical_log(FILE *log, const char *type, unsigned lineno, const char *msg)
{
	if (log)
		fprintf(log, "%s [%u]: %s\n", type, lineno, msg);
}

static int ical_readline_init(FILE *fdi, char *buf, char *lstore, unsigned *ln)
{
	char *eol;

	*buf = *lstore = '\0';
	if (fgets(lstore, BUFSIZ_LINE, fdi)) {
		(*ln)++;
		if ((eol = strchr(lstore, '\n')) != NULL) {
			if (eol > lstore && *(eol - 1) == '\r')
				*(eol - 1) = '\0';
			else
				*eol = '\0';
		}
		return 1;
	}
	return 0;
}

/*
 * Read a logical line, unfolding continuation lines.  lstore holds the
 * look-ahead physical line.
 */
static int ical_readline(FILE *fdi, char *buf, char *lstore, unsigned *ln)
{
	char *eol;

	strncpy(buf, lstore, BUFSIZ_LINE);
	buf[BUFSIZ_LINE - 1] = '\0';
	(*ln)++;

	while (fgets(lstore, BUFSIZ_LINE, fdi) != NULL) {
		if ((eol = strchr(lstore, '\n')) != NULL) {
			if (eol > lstore && *(eol - 1) == '\r')
				*(eol - 1) = '\0';
			else
				*eol = '\0';
		}
		if (*lstore != ' ' && *lstore != '\t')
			break;
		if (strlen(buf) + strlen(lstore + 1) < BUFSIZ_LINE)
			strcat(buf, lstore + 1);
		(*ln)++;
		*lstore = '\0';
	}
	if (feof(fdi) && *lstore == '\0' && *buf == '\0')
		return 0;
	if (*buf == '\0' && *lstore == '\0' && feof(fdi))
		return 0;
	return 1;
}

static int ical_chk_header(FILE *fd, char *buf, char *lstore, unsigned *lineno, float *version)
{
	if (!ical_readline(fd, buf, lstore, lineno))
		return 0;
	if (!starts_with_ci(buf, "BEGIN:VCALENDAR"))
		return 0;
	while (!feof(fd) || *lstore) {
		if (!ical_readline(fd, buf, lstore, lineno))
			return 1;
		if (starts_with_ci(buf, "VERSION")) {
			const char *p = strchr(buf, ':');
			if (!p)
				return 0;
			*version = atof(p + 1);
			if (*version != 2.0f)
				return 0;
			return 1;
		}
	}
	return 1;
}

/* Unescape a TEXT value; returns NULL if malformed (unescaped , or ;). */
static char *ical_unformat_line(const char *line, int eol_to_space)
{
	char *p, *out, *o;

	out = mem_malloc(strlen(line) + 1);
	o = out;
	for (p = (char *)line; *p; p++) {
		switch (*p) {
		case ',':
		case ';':
			mem_free(out);
			return NULL;
		case '\\':
			p++;
			switch (*p) {
			case 'n':
			case 'N':
				*o++ = eol_to_space ? ' ' : '\n';
				break;
			case ',':
			case ';':
			case '\\':
				*o++ = *p;
				break;
			case '\0':
				mem_free(out);
				return NULL;
			default:
				*o++ = '\\';
				*o++ = *p;
				break;
			}
			break;
		default:
			*o++ = *p;
		}
	}
	*o = '\0';
	return out;
}

/* Return the value part of a property line, or NULL. */
static const char *ical_get_value(const char *p)
{
	const char *q;
	int in_quote = 0;
	for (q = p; *q; q++) {
		if (*q == '"')
			in_quote = !in_quote;
		else if (*q == ':' && !in_quote)
			return q + 1;
	}
	return NULL;
}

/* Does the property have a parameter (case-insensitive)? Returns pointer after '='. */
static const char *ical_get_param(const char *p, const char *name)
{
	const char *q = p, *end = ical_get_value(p);
	size_t n = strlen(name);
	if (!end)
		end = p + strlen(p);
	while ((q = strchr(q, ';')) != NULL && q < end) {
		q++;
		if (!strncasecmp(q, name, n) && q[n] == '=')
			return q + n + 1;
	}
	return NULL;
}

/* Parse a date or date-time value.  type: 0 = unknown, 1 = DATE, 2 = DATE-TIME */
static time_t ical_datetime2time_t(const char *datestr, const char *tzid, int *type)
{
	int year, month, day, hour, min, sec, n;
	char c;
	struct date dt;
	time_t t;
	int len = strlen(datestr);

	(void)tzid;
	if (len == 8) {
		n = sscanf(datestr, "%04d%02d%02d", &year, &month, &day);
		if (n != 3 || !check_date(year, month, day))
			return 0;
		dt.yyyy = year;
		dt.mm = month;
		dt.dd = day;
		*type = 1;
		return date2sec(dt, 0, 0);
	} else if (len == 15 || len == 16) {
		n = sscanf(datestr, "%04d%02d%02dT%02d%02d%02d%c", &year, &month, &day, &hour, &min, &sec, &c);
		if (n < 6 || !check_date(year, month, day) || hour > 23 || min > 59 || sec > 60)
			return 0;
		if (len == 16 && (n != 7 || c != 'Z'))
			return 0;
		if (len == 15 && n != 6)
			return 0;
		dt.yyyy = year;
		dt.mm = month;
		dt.dd = day;
		*type = 2;
		if (len == 16) {
			/* UTC */
			struct tm tm;
			memset(&tm, 0, sizeof(tm));
			tm.tm_year = year - TM_YEAR_BASE;
			tm.tm_mon = month - 1;
			tm.tm_mday = day;
			tm.tm_hour = hour;
			tm.tm_min = min;
			tm.tm_sec = sec;
			t = timegm(&tm);
			return t;
		}
		t = date2sec(dt, hour, min) + sec;
		return t;
	}
	return 0;
}

/* Parse a DURATION value; returns seconds or -1 on error; sets *days_only. */
static long ical_dur2long(const char *durstr, int *days_only)
{
	const char *p = durstr;
	long dur = 0, n = 0;
	int sign = 1, in_time = 0, seen = 0;
	int has_time_part = 0;

	*days_only = 1;
	if (*p == '+')
		p++;
	else if (*p == '-') {
		sign = -1;
		p++;
	}
	if (*p != 'P')
		return -1;
	p++;
	if (!*p)
		return -1;
	for (; *p; p++) {
		if (isdigit((unsigned char)*p)) {
			n = n * 10 + (*p - '0');
			seen = 1;
			continue;
		}
		switch (*p) {
		case 'T':
			if (in_time)
				return -1;
			in_time = 1;
			if (seen)
				return -1;
			continue;
		case 'W':
			if (in_time || !seen)
				return -1;
			dur += n * WEEKINSEC;
			break;
		case 'D':
			if (in_time || !seen)
				return -1;
			dur += n * DAYINSEC;
			break;
		case 'H':
			if (!in_time || !seen)
				return -1;
			dur += n * HOURINSEC;
			has_time_part = 1;
			break;
		case 'M':
			if (!in_time || !seen)
				return -1;
			dur += n * MININSEC;
			has_time_part = 1;
			break;
		case 'S':
			if (!in_time || !seen)
				return -1;
			dur += n;
			has_time_part = 1;
			break;
		default:
			return -1;
		}
		n = 0;
		seen = 0;
	}
	if (seen)
		return -1;
	if (has_time_part)
		*days_only = 0;
	return sign * dur;
}

/* Parse a BYDAY value like "+1SA", "-1SU", "MO". */
static int ical_parse_wday(const char *s, int *val)
{
	static const char *wd[7] = { "SU", "MO", "TU", "WE", "TH", "FR", "SA" };
	int order = 0, sign = 1, i;
	const char *p = s;

	if (*p == '+' || *p == '-') {
		if (*p == '-')
			sign = -1;
		p++;
	}
	while (isdigit((unsigned char)*p)) {
		order = order * 10 + (*p - '0');
		p++;
	}
	if (strlen(p) != 2)
		return 0;
	for (i = 0; i < 7; i++) {
		if (!strcasecmp(p, wd[i]))
			break;
	}
	if (i == 7)
		return 0;
	if (order == 0) {
		if (p != s && !(s[0] == '+' || s[0] == '-'))
			return 0;	/* "0MO" */
		*val = i;
	} else {
		*val = sign * (order * 7 + i);
	}
	return 1;
}

static int ical_parse_int_list(const char *s, llist_t *l, int min, int max, int allow_neg)
{
	char *buf = mem_strdup(s), *p, *end;
	long v;

	for (p = strtok(buf, ","); p; p = strtok(NULL, ",")) {
		v = strtol(p, &end, 10);
		if (*end || end == p) {
			mem_free(buf);
			return 0;
		}
		if (v == 0 || v > max || v < -max || (!allow_neg && v < min)) {
			mem_free(buf);
			return 0;
		}
		{
			int *pv = mem_malloc(sizeof(int));
			*pv = (int)v;
			LLIST_ADD(l, pv);
		}
	}
	mem_free(buf);
	return 1;
}

static void ical_rpt_init(ical_rpt_t *rpt)
{
	rpt->type = RECUR_NO;
	rpt->freq = 1;
	rpt->until = 0;
	rpt->count = 0;
	LLIST_INIT(&rpt->bymonth);
	LLIST_INIT(&rpt->bywday);
	LLIST_INIT(&rpt->bymonthday);
}

static void ical_rpt_free(ical_rpt_t *rpt)
{
	recur_free_int_list(&rpt->bymonth);
	recur_free_int_list(&rpt->bywday);
	recur_free_int_list(&rpt->bymonthday);
}

/*
 * Parse an RRULE property.  Returns NULL on success or an error message.
 */
static const char *ical_read_rrule(const char *rrulestr, ical_rpt_t *rpt, int start_is_date)
{
	const char *val = ical_get_value(rrulestr);
	char *buf, *p;
	int has_until = 0, has_count = 0;

	if (!val)
		return _("malformed recurrence line.");
	ical_rpt_init(rpt);
	buf = mem_strdup(val);
	for (p = strtok(buf, ";"); p; p = strtok(NULL, ";")) {
		char *eq = strchr(p, '=');
		if (!eq) {
			mem_free(buf);
			return _("malformed recurrence rule.");
		}
		*eq = '\0';
		eq++;
		if (!strcasecmp(p, "FREQ")) {
			if (!strcasecmp(eq, "DAILY"))
				rpt->type = RECUR_DAILY;
			else if (!strcasecmp(eq, "WEEKLY"))
				rpt->type = RECUR_WEEKLY;
			else if (!strcasecmp(eq, "MONTHLY"))
				rpt->type = RECUR_MONTHLY;
			else if (!strcasecmp(eq, "YEARLY"))
				rpt->type = RECUR_YEARLY;
			else {
				mem_free(buf);
				return _("rrule frequency not supported.");
			}
		} else if (!strcasecmp(p, "INTERVAL")) {
			long v = atol(eq);
			if (v <= 0) {
				mem_free(buf);
				return _("invalid interval.");
			}
			rpt->freq = (int)v;
		} else if (!strcasecmp(p, "UNTIL")) {
			int type = 0;
			time_t t = ical_datetime2time_t(eq, NULL, &type);
			if (!t) {
				mem_free(buf);
				return _("invalid until format.");
			}
			if (start_is_date && type != 1) {
				mem_free(buf);
				return _("invalid until format.");
			}
			rpt->until = t;
			has_until = 1;
		} else if (!strcasecmp(p, "COUNT")) {
			long v = atol(eq);
			if (v <= 0) {
				mem_free(buf);
				return _("invalid count value.");
			}
			rpt->count = (int)v;
			has_count = 1;
		} else if (!strcasecmp(p, "BYMONTH")) {
			if (!ical_parse_int_list(eq, &rpt->bymonth, 1, 12, 0)) {
				mem_free(buf);
				return _("invalid bymonth list.");
			}
		} else if (!strcasecmp(p, "BYMONTHDAY")) {
			if (!ical_parse_int_list(eq, &rpt->bymonthday, 1, 31, 1)) {
				mem_free(buf);
				return _("invalid bymonthday list.");
			}
		} else if (!strcasecmp(p, "BYDAY")) {
			char *q, *save = NULL;
			char *list = mem_strdup(eq);
			for (q = strtok_r(list, ",", &save); q; q = strtok_r(NULL, ",", &save)) {
				int v;
				if (!ical_parse_wday(q, &v)) {
					mem_free(list);
					mem_free(buf);
					return _("invalid byday list.");
				}
				{
					int *pv = mem_malloc(sizeof(int));
					*pv = v;
					LLIST_ADD(&rpt->bywday, pv);
				}
			}
			mem_free(list);
		} else if (!strcasecmp(p, "WKST") || !strcasecmp(p, "BYSECOND") || !strcasecmp(p, "BYMINUTE") ||
			   !strcasecmp(p, "BYHOUR") || !strcasecmp(p, "BYYEARDAY") || !strcasecmp(p, "BYWEEKNO") ||
			   !strcasecmp(p, "BYSETPOS")) {
			/* ignored */
		}
	}
	mem_free(buf);
	if (rpt->type == RECUR_NO)
		return _("frequency not set in rrule.");
	if (has_until && has_count)
		return _("both until and count.");
	return NULL;
}

/*
 * Parse an EXDATE property, appending to the exception list.  Returns
 * NULL on success or an error message.
 */
static const char *ical_read_exdate(llist_t *exc, const char *exstr, int start_is_date)
{
	const char *val = ical_get_value(exstr);
	const char *vparam = ical_get_param(exstr, "VALUE");
	int exc_is_date = 0;
	char *buf, *p;

	if (!val)
		return _("malformed exceptions line.");
	if (vparam && !strncasecmp(vparam, "DATE", 4) && !(vparam[4] == '-'))
		exc_is_date = 1;
	if (exc_is_date != start_is_date)
		return _("invalid exception date value type.");

	buf = mem_strdup(val);
	for (p = strtok(buf, ","); p; p = strtok(NULL, ",")) {
		int type = 0;
		time_t t = ical_datetime2time_t(p, NULL, &type);
		if (!t || (exc_is_date && type != 1) || (!exc_is_date && type != 2)) {
			mem_free(buf);
			return _("invalid exception.");
		}
		{
			extern void recur_add_exc(llist_t *, time_t);
			recur_add_exc(exc, DAY(t));
		}
	}
	mem_free(buf);
	return NULL;
}

/* Append a line to a string (which may be NULL). */
static char *str_append(char *s, const char *add)
{
	char *r;
	if (!s)
		return mem_strdup(add);
	r = strdup_printf("%s%s", s, add);
	mem_free(s);
	return r;
}

/* Build a note from description, location, comments and import messages. */
static char *ical_build_note(const char *desc, const char *loc, llist_t *comments, llist_t *imports)
{
	char *note = NULL;
	llist_item_t *i;
	int has_extra = loc || LLIST_FIRST(comments) || LLIST_FIRST(imports);

	if (!desc && !has_extra)
		return NULL;
	if (desc) {
		note = str_append(note, desc);
		note = str_append(note, "\n");
	}
	if (has_extra) {
		note = str_append(note, SEPARATOR);
		if (loc) {
			note = str_append(note, "Location: ");
			note = str_append(note, loc);
			note = str_append(note, "\n");
		}
		LLIST_FOREACH(comments, i) {
			const char *c = LLIST_GET_DATA(i);
			const char *p = c, *nl;
			note = str_append(note, "Comment: ");
			while ((nl = strchr(p, '\n')) != NULL) {
				char *seg = mem_malloc(nl - p + 1);
				memcpy(seg, p, nl - p);
				seg[nl - p] = '\0';
				note = str_append(note, seg);
				note = str_append(note, "\n" INDENT);
				mem_free(seg);
				p = nl + 1;
			}
			note = str_append(note, p);
			note = str_append(note, "\n");
		}
		LLIST_FOREACH(imports, i) {
			note = str_append(note, "Import: ");
			note = str_append(note, LLIST_GET_DATA(i));
			note = str_append(note, "\n");
		}
	}
	return note;
}

static void ical_store_note(char **note, const char *desc, const char *loc, llist_t *comments, llist_t *imports)
{
	char *n = ical_build_note(desc, loc, comments, imports);
	if (n) {
		*note = generate_note(n);
		mem_free(n);
	} else {
		*note = NULL;
	}
}

static void ical_read_event(FILE *fdi, FILE *log, unsigned *noevents, unsigned *noapoints,
			    unsigned *noskipped, char *buf, char *lstore, unsigned *lineno,
			    const char *fmt_ev, const char *fmt_rev, const char *fmt_apt, const char *fmt_rapt)
{
	const char *endevent = "END:VEVENT";
	const char *summary_line = "SUMMARY";
	const char *dtstart_line = "DTSTART";
	const char *dtend_line = "DTEND";
	const char *duration_line = "DURATION";
	const char *rrule_line = "RRULE";
	const char *exdate_line = "EXDATE";
	const char *desc_line = "DESCRIPTION";
	const char *location_line = "LOCATION";
	const char *comment_line = "COMMENT";
	const char *alarm_line = "BEGIN:VALARM";
	const char *endalarm_line = "END:VALARM";
	const unsigned item_lnum = *lineno;

	time_t start = 0, end = 0;
	long dur = 0;
	int has_start = 0, has_end = 0, has_dur = 0, has_rrule = 0, has_alarm = 0;
	int start_is_date = 0, end_is_date = 0;
	int dur_days_only = 1;
	char *mesg = NULL, *desc = NULL, *loc = NULL, *note = NULL;
	llist_t comments, imports, exc;
	ical_rpt_t rpt;
	const char *err = NULL;
	int skip_alarm = 0;
	const char *tzid = NULL;
	char tzidbuf[BUFSIZ_LINE];

	LLIST_INIT(&comments);
	LLIST_INIT(&imports);
	LLIST_INIT(&exc);
	ical_rpt_init(&rpt);

	while (ical_readline(fdi, buf, lstore, lineno)) {
		if (skip_alarm) {
			if (starts_with_ci(buf, endalarm_line))
				skip_alarm = 0;
			continue;
		}
		if (starts_with_ci(buf, endevent)) {
			int is_event;
			/* finished: validate */
			if (!has_start) {
				err = _("item start date not defined.");
				goto skip;
			}
			if (has_end && end < start) {
				err = _("end must be later than start.");
				goto skip;
			}
			if (!mesg)
				mesg = mem_strdup(_("(empty)"));
			is_event = start_is_date;
			if (is_event) {
				long ndays = 1;
				if (has_end) {
					ndays = (long)((end - start + DAYINSEC / 2) / DAYINSEC);
					if (ndays < 1)
						ndays = 1;
				} else if (has_dur) {
					ndays = dur / DAYINSEC;
					if (ndays < 1)
						ndays = 1;
				}
				if (ndays > 1) {
					struct rpt *r;
					if (has_rrule) {
						/* keep the rrule, but note the change */
					}
					if (!has_rrule) {
						r = recur_rpt_new();
						r->type = RECUR_DAILY;
						r->freq = 1;
						r->until = date_sec_change(start, 0, (int)(ndays - 1));
						LLIST_ADD(&imports, mem_strdup(_("multi-day event changed to one-day event")));
						ical_store_note(&note, desc, loc, &comments, &imports);
						{
							struct recur_event *rev = recur_event_new(mesg, note, start, 1, r, &exc);
							LLIST_INIT(&exc);
							if (dump_imported)
								print_recur_event(fmt_rev, 0, rev);
						}
						(*noevents)++;
						goto done;
					}
					LLIST_ADD(&imports, mem_strdup(_("multi-day event changed to one-day event")));
				}
				if (has_rrule) {
					struct rpt *r = recur_rpt_new();
					struct recur_event *rev;
					r->type = rpt.type;
					r->freq = rpt.freq;
					r->until = rpt.until;
					recur_int_list_dup(&r->bymonth, &rpt.bymonth);
					recur_int_list_dup(&r->bywday, &rpt.bywday);
					recur_int_list_dup(&r->bymonthday, &rpt.bymonthday);
					if (!recur_check_rule(start, r)) {
						recur_rpt_free(r);
						err = _("rrule does not match start day (%s).");
						goto skip;
					}
					if (rpt.count) {
						time_t nth;
						if (!recur_nth_occurrence(start, DAYINSEC, &exc, r, rpt.count, &nth)) {
							recur_rpt_free(r);
							err = _("rrule does not match start day (%s).");
							goto skip;
						}
						r->until = nth;
					} else if (r->until) {
						time_t occ;
						if (recur_item_find_occurrence(start, DAYINSEC, r, NULL, DAY(r->until), &occ) && occ > r->until)
							r->until = date_sec_change(DAY(r->until), 0, -1);
						else
							r->until = DAY(r->until);
					}
					ical_store_note(&note, desc, loc, &comments, &imports);
					rev = recur_event_new(mesg, note, start, 1, r, &exc);
					LLIST_INIT(&exc);
					if (dump_imported)
						print_recur_event(fmt_rev, 0, rev);
				} else {
					struct event *ev;
					ical_store_note(&note, desc, loc, &comments, &imports);
					ev = event_new(mesg, note, start, 1);
					if (dump_imported)
						print_event(fmt_ev, 0, ev);
				}
				(*noevents)++;
			} else {
				char state = has_alarm ? APOINT_NOTIFY : 0;
				if (has_end)
					dur = end - start;
				else if (!has_dur)
					dur = 0;
				if (has_rrule) {
					struct rpt *r = recur_rpt_new();
					struct recur_apoint *rapt;
					r->type = rpt.type;
					r->freq = rpt.freq;
					r->until = rpt.until;
					recur_int_list_dup(&r->bymonth, &rpt.bymonth);
					recur_int_list_dup(&r->bywday, &rpt.bywday);
					recur_int_list_dup(&r->bymonthday, &rpt.bymonthday);
					if (!recur_check_rule(start, r)) {
						recur_rpt_free(r);
						err = _("rrule does not match start day (%s).");
						goto skip;
					}
					if (rpt.count) {
						time_t nth;
						if (!recur_nth_occurrence(start, dur, &exc, r, rpt.count, &nth)) {
							recur_rpt_free(r);
							err = _("rrule does not match start day (%s).");
							goto skip;
						}
						r->until = nth;
					} else if (r->until) {
						time_t occ;
						time_t u = r->until;
						if (recur_item_find_occurrence(start, dur, r, NULL, DAY(u), &occ) && occ > u)
							r->until = date_sec_change(update_time_in_date(u, get_item_hour(start), get_item_min(start)), 0, -1);
						else
							r->until = update_time_in_date(u, get_item_hour(start), get_item_min(start));
					}
					ical_store_note(&note, desc, loc, &comments, &imports);
					rapt = recur_apoint_new(mesg, note, start, dur, state, r, &exc);
					LLIST_INIT(&exc);
					if (dump_imported)
						print_recur_apoint(fmt_rapt, 0, rapt->start, rapt);
				} else {
					struct apoint *apt;
					ical_store_note(&note, desc, loc, &comments, &imports);
					apt = apoint_new(mesg, note, start, dur, state);
					if (dump_imported)
						print_apoint(fmt_apt, 0, apt);
				}
				(*noapoints)++;
			}
			goto done;
		} else if (starts_with_ci(buf, alarm_line)) {
			has_alarm = 1;
			skip_alarm = 1;
		} else if (starts_with_ci(buf, dtstart_line)) {
			const char *val = ical_get_value(buf);
			const char *vparam = ical_get_param(buf, "VALUE");
			const char *tz = ical_get_param(buf, "TZID");
			int type = 0;
			if (!val || !*val) {
				err = _("invalid or malformed event start time.");
				goto skip;
			}
			if (tz) {
				const char *e = tz;
				while (*e && *e != ';' && *e != ':')
					e++;
				snprintf(tzidbuf, sizeof(tzidbuf), "%.*s", (int)(e - tz), tz);
				tzid = tzidbuf;
			}
			start = ical_datetime2time_t(val, tzid, &type);
			if (!start) {
				err = _("invalid or malformed event start time.");
				goto skip;
			}
			if (vparam && !strncasecmp(vparam, "DATE", 4) && vparam[4] != '-') {
				if (type != 1) {
					err = _("invalid or malformed event start time.");
					goto skip;
				}
				start_is_date = 1;
			} else if (type != 2) {
				err = _("invalid or malformed event start time.");
				goto skip;
			}
			has_start = 1;
			if (tzid) {
				char *imp = strdup_printf("TZID=%s", tzid);
				LLIST_ADD(&imports, imp);
			}
		} else if (starts_with_ci(buf, dtend_line)) {
			const char *val = ical_get_value(buf);
			const char *vparam = ical_get_param(buf, "VALUE");
			int type = 0;
			if (has_dur) {
				err = _("either end or duration.");
				goto skip;
			}
			if (!val || !*val) {
				err = _("invalid or malformed event end time.");
				goto skip;
			}
			end = ical_datetime2time_t(val, NULL, &type);
			if (!end) {
				err = _("invalid or malformed event end time.");
				goto skip;
			}
			end_is_date = (vparam && !strncasecmp(vparam, "DATE", 4) && vparam[4] != '-');
			if (end_is_date && type != 1) {
				err = _("invalid or malformed event end time.");
				goto skip;
			}
			if (!end_is_date && type != 2) {
				err = _("invalid end time value type.");
				goto skip;
			}
			has_end = 1;
		} else if (starts_with_ci(buf, duration_line)) {
			const char *val = ical_get_value(buf);
			if (has_end) {
				err = _("either end or duration.");
				goto skip;
			}
			if (!val) {
				err = _("invalid duration.");
				goto skip;
			}
			dur = ical_dur2long(val, &dur_days_only);
			if (dur < 0) {
				err = _("invalid duration.");
				goto skip;
			}
			has_dur = 1;
		} else if (starts_with_ci(buf, rrule_line)) {
			if (has_rrule) {
				err = _("only one recurrence rule allowed.");
				goto skip;
			}
			err = ical_read_rrule(buf, &rpt, start_is_date);
			if (err)
				goto skip;
			has_rrule = 1;
		} else if (starts_with_ci(buf, exdate_line)) {
			if (!has_rrule) {
				/* check for malformed line first */
				if (!ical_get_value(buf)) {
					err = _("malformed exceptions line.");
					goto skip;
				}
				err = _("exception date, but no recurrence rule.");
				goto skip;
			}
			err = ical_read_exdate(&exc, buf, start_is_date);
			if (err)
				goto skip;
		} else if (starts_with_ci(buf, summary_line)) {
			const char *val = ical_get_value(buf);
			if (!val) {
				err = _("malformed summary line.");
				goto skip;
			}
			if (mesg)
				mem_free(mesg);
			mesg = ical_unformat_line(val, 1);
			if (!mesg) {
				err = _("malformed summary.");
				goto skip;
			}
		} else if (starts_with_ci(buf, desc_line)) {
			const char *val = ical_get_value(buf);
			if (!val) {
				err = _("malformed description line.");
				goto skip;
			}
			if (desc)
				mem_free(desc);
			desc = ical_unformat_line(val, 0);
			if (!desc) {
				err = _("malformed description.");
				goto skip;
			}
		} else if (starts_with_ci(buf, location_line)) {
			const char *val = ical_get_value(buf);
			if (!val) {
				err = _("malformed location line.");
				goto skip;
			}
			if (loc) {
				err = _("only one location allowed.");
				goto skip;
			}
			loc = ical_unformat_line(val, 0);
			if (!loc) {
				err = _("malformed location.");
				goto skip;
			}
		} else if (starts_with_ci(buf, comment_line)) {
			const char *val = ical_get_value(buf);
			char *c;
			if (!val) {
				err = _("malformed comment line.");
				goto skip;
			}
			c = ical_unformat_line(val, 0);
			if (!c) {
				err = _("malformed comment.");
				goto skip;
			}
			LLIST_ADD(&comments, c);
		}
	}

	err = _("The ical file seems to be malformed. The end of item was not found.");
	ical_log(log, "VEVENT", item_lnum, err);
	(*noskipped)++;
	goto cleanup;

skip:
	ical_log(log, "VEVENT", item_lnum, err);
	(*noskipped)++;
	/* skip until END:VEVENT */
	while (!starts_with_ci(buf, endevent)) {
		if (!ical_readline(fdi, buf, lstore, lineno)) {
			ical_log(log, "VEVENT", item_lnum,
				 _("The ical file seems to be malformed. The end of item was not found."));
			break;
		}
	}
	goto cleanup;

done:
cleanup:
	if (mesg)
		mem_free(mesg);
	if (desc)
		mem_free(desc);
	if (loc)
		mem_free(loc);
	if (note)
		mem_free(note);
	LLIST_FREE_INNER(&comments, mem_free);
	LLIST_FREE(&comments);
	LLIST_FREE_INNER(&imports, mem_free);
	LLIST_FREE(&imports);
	recur_free_exc_list(&exc);
	ical_rpt_free(&rpt);
	(void)dur_days_only;
}

static void ical_read_todo(FILE *fdi, FILE *log, unsigned *notodos, unsigned *noskipped,
			   char *buf, char *lstore, unsigned *lineno, const char *fmt_todo)
{
	const char *endtodo = "END:VTODO";
	const char *summary_line = "SUMMARY";
	const char *priority_line = "PRIORITY";
	const char *desc_line = "DESCRIPTION";
	const char *location_line = "LOCATION";
	const char *comment_line = "COMMENT";
	const char *status_line = "STATUS";
	const char *alarm_line = "BEGIN:VALARM";
	const char *endalarm_line = "END:VALARM";
	const unsigned item_lnum = *lineno;
	char *mesg = NULL, *desc = NULL, *loc = NULL, *note = NULL;
	llist_t comments, imports;
	int priority = 0, completed = 0;
	const char *err = NULL;
	int skip_alarm = 0;

	LLIST_INIT(&comments);
	LLIST_INIT(&imports);

	while (ical_readline(fdi, buf, lstore, lineno)) {
		if (skip_alarm) {
			if (starts_with_ci(buf, endalarm_line))
				skip_alarm = 0;
			continue;
		}
		if (starts_with_ci(buf, endtodo)) {
			struct todo *t;
			if (!mesg)
				mesg = mem_strdup(_("(empty)"));
			ical_store_note(&note, desc, loc, &comments, &imports);
			t = todo_add(mesg, priority, completed, note);
			if (dump_imported)
				print_todo(fmt_todo, t);
			(*notodos)++;
			goto cleanup;
		} else if (starts_with_ci(buf, alarm_line)) {
			skip_alarm = 1;
		} else if (starts_with_ci(buf, priority_line)) {
			const char *val = ical_get_value(buf);
			long v;
			char *end;
			if (!val) {
				err = _("item priority is invalid (must be between 0 and 9).");
				goto skip;
			}
			v = strtol(val, &end, 10);
			if (end == val || *end || v < 0 || v > 9) {
				err = _("item priority is invalid (must be between 0 and 9).");
				goto skip;
			}
			priority = (int)v;
		} else if (starts_with_ci(buf, status_line)) {
			const char *val = ical_get_value(buf);
			if (val && !strcasecmp(val, "COMPLETED"))
				completed = 1;
		} else if (starts_with_ci(buf, summary_line)) {
			const char *val = ical_get_value(buf);
			if (!val) {
				err = _("malformed summary line.");
				goto skip;
			}
			if (mesg)
				mem_free(mesg);
			mesg = ical_unformat_line(val, 1);
			if (!mesg) {
				err = _("malformed summary.");
				goto skip;
			}
		} else if (starts_with_ci(buf, desc_line)) {
			const char *val = ical_get_value(buf);
			if (!val) {
				err = _("malformed description line.");
				goto skip;
			}
			if (desc)
				mem_free(desc);
			desc = ical_unformat_line(val, 0);
			if (!desc) {
				err = _("malformed description.");
				goto skip;
			}
		} else if (starts_with_ci(buf, location_line)) {
			const char *val = ical_get_value(buf);
			if (!val) {
				err = _("malformed location line.");
				goto skip;
			}
			if (loc) {
				err = _("only one location allowed.");
				goto skip;
			}
			loc = ical_unformat_line(val, 0);
			if (!loc) {
				err = _("malformed location.");
				goto skip;
			}
		} else if (starts_with_ci(buf, comment_line)) {
			const char *val = ical_get_value(buf);
			char *c;
			if (!val) {
				err = _("malformed comment line.");
				goto skip;
			}
			c = ical_unformat_line(val, 0);
			if (!c) {
				err = _("malformed comment.");
				goto skip;
			}
			LLIST_ADD(&comments, c);
		}
	}

	err = _("The ical file seems to be malformed. The end of item was not found.");
	ical_log(log, "VTODO", item_lnum, err);
	(*noskipped)++;
	goto cleanup;

skip:
	ical_log(log, "VTODO", item_lnum, err);
	(*noskipped)++;
	while (!starts_with_ci(buf, endtodo)) {
		if (!ical_readline(fdi, buf, lstore, lineno)) {
			ical_log(log, "VTODO", item_lnum,
				 _("The ical file seems to be malformed. The end of item was not found."));
			break;
		}
	}

cleanup:
	if (mesg)
		mem_free(mesg);
	if (desc)
		mem_free(desc);
	if (loc)
		mem_free(loc);
	if (note)
		mem_free(note);
	LLIST_FREE_INNER(&comments, mem_free);
	LLIST_FREE(&comments);
	LLIST_FREE_INNER(&imports, mem_free);
	LLIST_FREE(&imports);
}

void ical_import_data(const char *file_name, FILE *stream, FILE *log, unsigned *events,
		      unsigned *apoints, unsigned *todos, unsigned *lines, unsigned *skipped,
		      const char *fmt_ev, const char *fmt_rev, const char *fmt_apt,
		      const char *fmt_rapt, const char *fmt_todo)
{
	const char *vevent = "BEGIN:VEVENT";
	const char *vtodo = "BEGIN:VTODO";
	char buf[BUFSIZ_LINE], lstore[BUFSIZ_LINE];
	float version = 0;

	*events = *apoints = *todos = *lines = *skipped = 0;

	ical_readline_init(stream, buf, lstore, lines);
	if (!ical_chk_header(stream, buf, lstore, lines, &version)) {
		WARN_MSG("ical.c", 1879, "Warning: ical header malformed or wrong version number. Aborting...");
		return;
	}
	ical_log_init(log, file_name, version);

	while (ical_readline(stream, buf, lstore, lines)) {
		if (starts_with_ci(buf, vevent)) {
			ical_read_event(stream, log, events, apoints, skipped, buf, lstore, lines,
					fmt_ev, fmt_rev, fmt_apt, fmt_rapt);
		} else if (starts_with_ci(buf, vtodo)) {
			ical_read_todo(stream, log, todos, skipped, buf, lstore, lines, fmt_todo);
		}
	}
}
EOF
echo ok"}

actions.command:
cd /workspace; cat > src/ical.c <<'EOF'
#include "calcurse.h"

#define ICALDATEFMT		"%Y%m%d"
#define ICALDATETIMEFMT		"%Y%m%dT%H%M%S"
#define SEPARATOR		"-- \n"
#define INDENT			"    "

typedef enum { UNDEFINED, APPOINTMENT, EVENT } ical_vevent_e;

typedef struct {
	enum recur_type type;
	int freq;
	time_t until;
	int count;
	llist_t bymonth;
	llist_t bywday;
	llist_t bymonthday;
} ical_rpt_t;

/* ---- export ---- */

static void ical_export_header(FILE *stream)
{
	fputs("BEGIN:VCALENDAR\n", stream);
	fputs("VERSION:2.0\n", stream);
	fprintf(stream, "PRODID:-//calcurse//NONSGML v%s//EN\n", VERSION);
}

static void ical_export_footer(FILE *stream)
{
	fputs("END:VCALENDAR\n", stream);
}

/* Escape a TEXT value: backslash, comma, semicolon and newline. */
static void ical_export_text(FILE *stream, const char *s)
{
	for (; *s; s++) {
		switch (*s) {
		case '\\':
			fputs("\\\\", stream);
			break;
		case ',':
			fputs("\\,", stream);
			break;
		case ';':
			fputs("\\;", stream);
			break;
		case '\n':
			fputs("\\n", stream);
			break;
		default:
			putc(*s, stream);
		}
	}
}

static void ical_export_valarm(FILE *stream)
{
	fputs("BEGIN:VALARM\n", stream);
	fprintf(stream, "TRIGGER:-PT%dS\n", conf.notify_warning);
	fputs("ACTION:DISPLAY\n", stream);
	fputs("END:VALARM\n", stream);
}

/*
 * Export the note of an item as DESCRIPTION, LOCATION and COMMENT.
 */
static void ical_export_note(FILE *stream, const char *note)
{
	char *buf, *p, *end, *sep;
	char *desc = NULL, *loc = NULL, *com = NULL;
	size_t len;

	if (!note)
		return;
	buf = note_read_file(note);
	if (!buf)
		return;
	len = strlen(buf);
	if (len == 0) {
		mem_free(buf);
		return;
	}
	/* Remove the trailing character (assumed to be a newline). */
	buf[len - 1] = '\0';

	/* Find the separator at the start of a line. */
	sep = NULL;
	if (starts_with(buf, SEPARATOR))
		sep = buf;
	else {
		p = buf;
		while ((p = strstr(p, "\n" SEPARATOR)) != NULL) {
			sep = p + 1;
			break;
		}
	}
	if (sep) {
		if (sep > buf) {
			/* description is everything before the newline preceding the separator */
			*(sep - 1) = '\0';
			desc = buf;
		}
		p = sep + strlen(SEPARATOR);
		/* parse Location:, Comment: lines */
		while (*p) {
			end = strchr(p, '\n');
			if (end)
				*end = '\0';
			if (starts_with(p, "Location: ")) {
				loc = p + strlen("Location: ");
			} else if (starts_with(p, "Comment: ")) {
				/* comment with indented continuation lines */
				char *c = p + strlen("Comment: ");
				char *q = end ? end + 1 : NULL;
				char *out = mem_strdup(c);
				while (q && starts_with(q, INDENT)) {
					char *e2 = strchr(q, '\n');
					char *tmp;
					if (e2)
						*e2 = '\0';
					tmp = strdup_printf("%s\n%s", out, q + strlen(INDENT));
					mem_free(out);
					out = tmp;
					q = e2 ? e2 + 1 : NULL;
				}
				com = out;
				if (!q)
					break;
				p = q;
				continue;
			}
			if (!end)
				break;
			p = end + 1;
		}
	} else {
		desc = buf;
	}

	if (desc) {
		fputs("DESCRIPTION:", stream);
		ical_export_text(stream, desc);
		putc('\n', stream);
	}
	if (loc) {
		fputs("LOCATION:", stream);
		ical_export_text(stream, loc);
		putc('\n', stream);
	}
	if (com) {
		fputs("COMMENT:", stream);
		ical_export_text(stream, com);
		putc('\n', stream);
		mem_free(com);
	}
	mem_free(buf);
}

static void ical_export_rpt(FILE *stream, struct rpt *rpt, int with_time)
{
	char buf[BUFSIZ_LINE];
	struct tm tm;
	llist_item_t *i;
	const char *freq;

	switch (rpt->type) {
	case RECUR_DAILY:
		freq = "DAILY";
		break;
	case RECUR_WEEKLY:
		freq = "WEEKLY";
		break;
	case RECUR_MONTHLY:
		freq = "MONTHLY";
		break;
	case RECUR_YEARLY:
		freq = "YEARLY";
		break;
	default:
		freq = "DAILY";
		break;
	}
	fprintf(stream, "RRULE:FREQ=%s", freq);
	if (rpt->freq > 1)
		fprintf(stream, ";INTERVAL=%d", rpt->freq);
	if (rpt->until != 0) {
		localtime_r_safe(rpt->until, &tm);
		strftime(buf, sizeof(buf), with_time ? ICALDATETIMEFMT : ICALDATEFMT, &tm);
		fprintf(stream, ";UNTIL=%s", buf);
	}
	if (LLIST_FIRST(&rpt->bymonth)) {
		fputs(";BYMONTH=", stream);
		LLIST_FOREACH(&rpt->bymonth, i)
			fprintf(stream, "%s%d", i == LLIST_FIRST(&rpt->bymonth) ? "" : ",", *(int *)LLIST_GET_DATA(i));
	}
	if (LLIST_FIRST(&rpt->bywday)) {
		static const char *wd[7] = { "SU", "MO", "TU", "WE", "TH", "FR", "SA" };
		fputs(";BYDAY=", stream);
		LLIST_FOREACH(&rpt->bywday, i) {
			int v = *(int *)LLIST_GET_DATA(i);
			int order = v / 7, r = v % 7, wday;
			if (i != LLIST_FIRST(&rpt->bywday))
				putc(',', stream);
			if (order == 0) {
				wday = r < 0 ? 0 : r;
				fprintf(stream, "%s", wd[wday]);
			} else if (order > 0) {
				fprintf(stream, "+%d%s", order, wd[r < 0 ? 0 : r]);
			} else {
				fprintf(stream, "%d%s", order, wd[-r]);
			}
		}
	}
	if (LLIST_FIRST(&rpt->bymonthday)) {
		fputs(";BYMONTHDAY=", stream);
		LLIST_FOREACH(&rpt->bymonthday, i)
			fprintf(stream, "%s%d", i == LLIST_FIRST(&rpt->bymonthday) ? "" : ",", *(int *)LLIST_GET_DATA(i));
	}
	putc('\n', stream);
}

static void ical_export_exc(FILE *stream, llist_t *exc, int is_event, time_t start)
{
	llist_item_t *i;
	char buf[BUFSIZ_LINE];
	struct tm tm;

	if (!LLIST_FIRST(exc))
		return;
	fputs(is_event ? "EXDATE;VALUE=DATE:" : "EXDATE:", stream);
	LLIST_FOREACH(exc, i) {
		struct excp *e = LLIST_GET_DATA(i);
		time_t t = e->st;
		if (!is_event)
			t = update_time_in_date(t, get_item_hour(start), get_item_min(start));
		localtime_r_safe(t, &tm);
		strftime(buf, sizeof(buf), ICALDATETIMEFMT, &tm);
		fprintf(stream, "%s%s", i == LLIST_FIRST(exc) ? "" : ",", buf);
	}
	putc('\n', stream);
}

static void ical_export_uid(FILE *stream, char *hash)
{
	fprintf(stream, "UID:%s\n", hash);
	mem_free(hash);
}

static void ical_export_recur_events(FILE *stream, int export_uid)
{
	llist_item_t *i;
	char buf[BUFSIZ_LINE];
	struct tm tm;

	LLIST_FOREACH(&recur_elist, i) {
		struct recur_event *rev = LLIST_GET_DATA(i);
		localtime_r_safe(rev->day, &tm);
		strftime(buf, sizeof(buf), ICALDATEFMT, &tm);
		fputs("BEGIN:VEVENT\n", stream);
		if (export_uid)
			ical_export_uid(stream, recur_event_hash(rev));
		fprintf(stream, "DTSTART;VALUE=DATE:%s\n", buf);
		ical_export_rpt(stream, rev->rpt, 0);
		ical_export_exc(stream, &rev->exc, 1, rev->day);
		fputs("SUMMARY:", stream);
		ical_export_text(stream, rev->mesg);
		putc('\n', stream);
		ical_export_note(stream, rev->note);
		fputs("END:VEVENT\n", stream);
	}
}

static void ical_export_events(FILE *stream, int export_uid)
{
	llist_item_t *i;
	char buf[BUFSIZ_LINE];
	struct tm tm;

	LLIST_FOREACH(&eventlist, i) {
		struct event *ev = LLIST_GET_DATA(i);
		localtime_r_safe(ev->day, &tm);
		strftime(buf, sizeof(buf), ICALDATEFMT, &tm);
		fputs("BEGIN:VEVENT\n", stream);
		if (export_uid)
			ical_export_uid(stream, event_hash(ev));
		fprintf(stream, "DTSTART;VALUE=DATE:%s\n", buf);
		fputs("SUMMARY:", stream);
		ical_export_text(stream, ev->mesg);
		putc('\n', stream);
		ical_export_note(stream, ev->note);
		fputs("END:VEVENT\n", stream);
	}
}

static void ical_export_duration(FILE *stream, long dur)
{
	long days, hours, mins, secs;
	if (dur <= 0)
		return;
	days = dur / DAYINSEC;
	hours = (dur % DAYINSEC) / HOURINSEC;
	mins = (dur % HOURINSEC) / MININSEC;
	secs = dur % MININSEC;
	fprintf(stream, "DURATION:P%ldDT%ldH%ldM%ldS\n", days, hours, mins, secs);
}

static void ical_export_recur_apoints(FILE *stream, int export_uid)
{
	llist_item_t *i;
	char buf[BUFSIZ_LINE];
	struct tm tm;

	LLIST_FOREACH(&recur_alist_p, i) {
		struct recur_apoint *rapt = LLIST_GET_DATA(i);
		localtime_r_safe(rapt->start, &tm);
		strftime(buf, sizeof(buf), ICALDATETIMEFMT, &tm);
		fputs("BEGIN:VEVENT\n", stream);
		if (export_uid)
			ical_export_uid(stream, recur_apoint_hash(rapt));
		fprintf(stream, "DTSTART:%s\n", buf);
		ical_export_duration(stream, rapt->dur);
		ical_export_rpt(stream, rapt->rpt, 1);
		ical_export_exc(stream, &rapt->exc, 0, rapt->start);
		fputs("SUMMARY:", stream);
		ical_export_text(stream, rapt->mesg);
		putc('\n', stream);
		ical_export_note(stream, rapt->note);
		if (rapt->state & APOINT_NOTIFY)
			ical_export_valarm(stream);
		fputs("END:VEVENT\n", stream);
	}
}

static void ical_export_apoints(FILE *stream, int export_uid)
{
	llist_item_t *i;
	char buf[BUFSIZ_LINE];
	struct tm tm;

	LLIST_FOREACH(&alist_p, i) {
		struct apoint *apt = LLIST_GET_DATA(i);
		localtime_r_safe(apt->start, &tm);
		strftime(buf, sizeof(buf), ICALDATETIMEFMT, &tm);
		fputs("BEGIN:VEVENT\n", stream);
		if (export_uid)
			ical_export_uid(stream, apoint_hash(apt));
		fprintf(stream, "DTSTART:%s\n", buf);
		ical_export_duration(stream, apt->dur);
		fputs("SUMMARY:", stream);
		ical_export_text(stream, apt->mesg);
		putc('\n', stream);
		ical_export_note(stream, apt->note);
		if (apt->state & APOINT_NOTIFY)
			ical_export_valarm(stream);
		fputs("END:VEVENT\n", stream);
	}
}

static void ical_export_todo(FILE *stream, int export_uid)
{
	llist_item_t *i;

	LLIST_FOREACH(&todolist, i) {
		struct todo *todo = LLIST_GET_DATA(i);
		fputs("BEGIN:VTODO\n", stream);
		if (export_uid)
			ical_export_uid(stream, todo_hash(todo));
		fprintf(stream, "PRIORITY:%d\n", todo->id);
		fputs("SUMMARY:", stream);
		ical_export_text(stream, todo->mesg);
		putc('\n', stream);
		ical_export_note(stream, todo->note);
		if (todo->completed)
			fputs("STATUS:COMPLETED\n", stream);
		fputs("END:VTODO\n", stream);
	}
}

void ical_export_data(FILE *stream, int export_uid)
{
	ical_export_header(stream);
	ical_export_recur_events(stream, export_uid);
	ical_export_events(stream, export_uid);
	ical_export_recur_apoints(stream, export_uid);
	ical_export_apoints(stream, export_uid);
	ical_export_todo(stream, export_uid);
	ical_export_footer(stream);
}

/* ---- import ---- */

static void ical_log_init(FILE *log, const char *file, float version)
{
	const char *header =
	    "+-------------------------------------------------------------------+\n"
	    "| Calcurse icalendar import log.                                    |\n"
	    "|                                                                   |\n"
	    "| Import from icalendar file                                        |\n"
	    "|       %-60s|\n"
	    "| version %.1f at %s.                                  |\n"
	    "|                                                                   |\n"
	    "| Items which could not be imported are described below.            |\n"
	    "| The log line format is as follows:                                |\n"
	    "|                                                                   |\n"
	    "|       TYPE [LINE]: DESCRIPTION                                    |\n"
	    "|                                                                   |\n"
	    "| where:                                                            |\n"
	    "|  * TYPE is the item type, 'VEVENT' or 'VTODO'                     |\n"
	    "|  * LINE is the line in the import file where the item begins      |\n"
	    "|  * DESCRIPTION explains why the item could not be imported        |\n"
	    "+-------------------------------------------------------------------+\n\n";
	char *date;
	time_t t = now();
	struct tm tm;
	char buf[BUFSIZ_LINE];

	localtime_r_safe(t, &tm);
	strftime(buf, sizeof(buf), "%m/%d/%Y %H:%M", &tm);
	date = buf;
	if (log)
		fprintf(log, header, file ? file : "(stdin)", version, date);
}

static void ical_log(FILE *log, const char *type, unsigned lineno, const char *msg)
{
	if (log)
		fprintf(log, "%s [%u]: %s\n", type, lineno, msg);
}

static int ical_readline_init(FILE *fdi, char *buf, char *lstore, unsigned *ln)
{
	char *eol;

	*buf = *lstore = '\0';
	if (fgets(lstore, BUFSIZ_LINE, fdi)) {
		(*ln)++;
		if ((eol = strchr(lstore, '\n')) != NULL) {
			if (eol > lstore && *(eol - 1) == '\r')
				*(eol - 1) = '\0';
			else
				*eol = '\0';
		}
		return 1;
	}
	return 0;
}

/*
 * Read a logical line, unfolding continuation lines.  lstore holds the
 * look-ahead physical line.
 */
static int ical_readline(FILE *fdi, char *buf, char *lstore, unsigned *ln)
{
	char *eol;

	strncpy(buf, lstore, BUFSIZ_LINE);
	buf[BUFSIZ_LINE - 1] = '\0';
	(*ln)++;

	while (fgets(lstore, BUFSIZ_LINE, fdi) != NULL) {
		if ((eol = strchr(lstore, '\n')) != NULL) {
			if (eol > lstore && *(eol - 1) == '\r')
				*(eol - 1) = '\0';
			else
				*eol = '\0';
		}
		if (*lstore != ' ' && *lstore != '\t')
			break;
		if (strlen(buf) + strlen(lstore + 1) < BUFSIZ_LINE)
			strcat(buf, lstore + 1);
		(*ln)++;
		*lstore = '\0';
	}
	if (feof(fdi) && *lstore == '\0' && *buf == '\0')
		return 0;
	if (*buf == '\0' && *lstore == '\0' && feof(fdi))
		return 0;
	return 1;
}

static int ical_chk_header(FILE *fd, char *buf, char *lstore, unsigned *lineno, float *version)
{
	if (!ical_readline(fd, buf, lstore, lineno))
		return 0;
	if (!starts_with_ci(buf, "BEGIN:VCALENDAR"))
		return 0;
	while (!feof(fd) || *lstore) {
		if (!ical_readline(fd, buf, lstore, lineno))
			return 1;
		if (starts_with_ci(buf, "VERSION")) {
			const char *p = strchr(buf, ':');
			if (!p)
				return 0;
			*version = atof(p + 1);
			if (*version != 2.0f)
				return 0;
			return 1;
		}
	}
	return 1;
}

/* Unescape a TEXT value; returns NULL if malformed (unescaped , or ;). */
static char *ical_unformat_line(const char *line, int eol_to_space)
{
	char *p, *out, *o;

	out = mem_malloc(strlen(line) + 1);
	o = out;
	for (p = (char *)line; *p; p++) {
		switch (*p) {
		case ',':
		case ';':
			mem_free(out);
			return NULL;
		case '\\':
			p++;
			switch (*p) {
			case 'n':
			case 'N':
				*o++ = eol_to_space ? ' ' : '\n';
				break;
			case ',':
			case ';':
			case '\\':
				*o++ = *p;
				break;
			case '\0':
				mem_free(out);
				return NULL;
			default:
				*o++ = '\\';
				*o++ = *p;
				break;
			}
			break;
		default:
			*o++ = *p;
		}
	}
	*o = '\0';
	return out;
}

/* Return the value part of a property line, or NULL. */
static const char *ical_get_value(const char *p)
{
	const char *q;
	int in_quote = 0;
	for (q = p; *q; q++) {
		if (*q == '"')
			in_quote = !in_quote;
		else if (*q == ':' && !in_quote)
			return q + 1;
	}
	return NULL;
}

/* Does the property have a parameter (case-insensitive)? Returns pointer after '='. */
static const char *ical_get_param(const char *p, const char *name)
{
	const char *q = p, *end = ical_get_value(p);
	size_t n = strlen(name);
	if (!end)
		end = p + strlen(p);
	while ((q = strchr(q, ';')) != NULL && q < end) {
		q++;
		if (!strncasecmp(q, name, n) && q[n] == '=')
			return q + n + 1;
	}
	return NULL;
}

/* Parse a date or date-time value.  type: 0 = unknown, 1 = DATE, 2 = DATE-TIME */
static time_t ical_datetime2time_t(const char *datestr, const char *tzid, int *type)
{
	int year, month, day, hour, min, sec, n;
	char c;
	struct date dt;
	time_t t;
	int len = strlen(datestr);

	(void)tzid;
	if (len == 8) {
		n = sscanf(datestr, "%04d%02d%02d", &year, &month, &day);
		if (n != 3 || !check_date(year, month, day))
			return 0;
		dt.yyyy = year;
		dt.mm = month;
		dt.dd = day;
		*type = 1;
		return date2sec(dt, 0, 0);
	} else if (len == 15 || len == 16) {
		n = sscanf(datestr, "%04d%02d%02dT%02d%02d%02d%c", &year, &month, &day, &hour, &min, &sec, &c);
		if (n < 6 || !check_date(year, month, day) || hour > 23 || min > 59 || sec > 60)
			return 0;
		if (len == 16 && (n != 7 || c != 'Z'))
			return 0;
		if (len == 15 && n != 6)
			return 0;
		dt.yyyy = year;
		dt.mm = month;
		dt.dd = day;
		*type = 2;
		if (len == 16) {
			/* UTC */
			struct tm tm;
			memset(&tm, 0, sizeof(tm));
			tm.tm_year = year - TM_YEAR_BASE;
			tm.tm_mon = month - 1;
			tm.tm_mday = day;
			tm.tm_hour = hour;
			tm.tm_min = min;
			tm.tm_sec = sec;
			t = timegm(&tm);
			return t;
		}
		t = date2sec(dt, hour, min) + sec;
		return t;
	}
	return 0;
}

/* Parse a DURATION value; returns seconds or -1 on error; sets *days_only. */
static long ical_dur2long(const char *durstr, int *days_only)
{
	const char *p = durstr;
	long dur = 0, n = 0;
	int sign = 1, in_time = 0, seen = 0;
	int has_time_part = 0;

	*days_only = 1;
	if (*p == '+')
		p++;
	else if (*p == '-') {
		sign = -1;
		p++;
	}
	if (*p != 'P')
		return -1;
	p++;
	if (!*p)
		return -1;
	for (; *p; p++) {
		if (isdigit((unsigned char)*p)) {
			n = n * 10 + (*p - '0');
			seen = 1;
			continue;
		}
		switch (*p) {
		case 'T':
			if (in_time)
				return -1;
			in_time = 1;
			if (seen)
				return -1;
			continue;
		case 'W':
			if (in_time || !seen)
				return -1;
			dur += n * WEEKINSEC;
			break;
		case 'D':
			if (in_time || !seen)
				return -1;
			dur += n * DAYINSEC;
			break;
		case 'H':
			if (!in_time || !seen)
				return -1;
			dur += n * HOURINSEC;
			has_time_part = 1;
			break;
		case 'M':
			if (!in_time || !seen)
				return -1;
			dur += n * MININSEC;
			has_time_part = 1;
			break;
		case 'S':
			if (!in_time || !seen)
				return -1;
			dur += n;
			has_time_part = 1;
			break;
		default:
			return -1;
		}
		n = 0;
		seen = 0;
	}
	if (seen)
		return -1;
	if (has_time_part)
		*days_only = 0;
	return sign * dur;
}

/* Parse a BYDAY value like "+1SA", "-1SU", "MO". */
static int ical_parse_wday(const char *s, int *val)
{
	static const char *wd[7] = { "SU", "MO", "TU", "WE", "TH", "FR", "SA" };
	int order = 0, sign = 1, i;
	const char *p = s;

	if (*p == '+' || *p == '-') {
		if (*p == '-')
			sign = -1;
		p++;
	}
	while (isdigit((unsigned char)*p)) {
		order = order * 10 + (*p - '0');
		p++;
	}
	if (strlen(p) != 2)
		return 0;
	for (i = 0; i < 7; i++) {
		if (!strcasecmp(p, wd[i]))
			break;
	}
	if (i == 7)
		return 0;
	if (order == 0) {
		if (p != s && !(s[0] == '+' || s[0] == '-'))
			return 0;	/* "0MO" */
		*val = i;
	} else {
		*val = sign * (order * 7 + i);
	}
	return 1;
}

static int ical_parse_int_list(const char *s, llist_t *l, int min, int max, int allow_neg)
{
	char *buf = mem_strdup(s), *p, *end;
	long v;

	for (p = strtok(buf, ","); p; p = strtok(NULL, ",")) {
		v = strtol(p, &end, 10);
		if (*end || end == p) {
			mem_free(buf);
			return 0;
		}
		if (v == 0 || v > max || v < -max || (!allow_neg && v < min)) {
			mem_free(buf);
			return 0;
		}
		{
			int *pv = mem_malloc(sizeof(int));
			*pv = (int)v;
			LLIST_ADD(l, pv);
		}
	}
	mem_free(buf);
	return 1;
}

static void ical_rpt_init(ical_rpt_t *rpt)
{
	rpt->type = RECUR_NO;
	rpt->freq = 1;
	rpt->until = 0;
	rpt->count = 0;
	LLIST_INIT(&rpt->bymonth);
	LLIST_INIT(&rpt->bywday);
	LLIST_INIT(&rpt->bymonthday);
}

static void ical_rpt_free(ical_rpt_t *rpt)
{
	recur_free_int_list(&rpt->bymonth);
	recur_free_int_list(&rpt->bywday);
	recur_free_int_list(&rpt->bymonthday);
}

/*
 * Parse an RRULE property.  Returns NULL on success or an error message.
 */
static const char *ical_read_rrule(const char *rrulestr, ical_rpt_t *rpt, int start_is_date)
{
	const char *val = ical_get_value(rrulestr);
	char *buf, *p;
	int has_until = 0, has_count = 0;

	if (!val)
		return _("malformed recurrence line.");
	ical_rpt_init(rpt);
	buf = mem_strdup(val);
	for (p = strtok(buf, ";"); p; p = strtok(NULL, ";")) {
		char *eq = strchr(p, '=');
		if (!eq) {
			mem_free(buf);
			return _("malformed recurrence rule.");
		}
		*eq = '\0';
		eq++;
		if (!strcasecmp(p, "FREQ")) {
			if (!strcasecmp(eq, "DAILY"))
				rpt->type = RECUR_DAILY;
			else if (!strcasecmp(eq, "WEEKLY"))
				rpt->type = RECUR_WEEKLY;
			else if (!strcasecmp(eq, "MONTHLY"))
				rpt->type = RECUR_MONTHLY;
			else if (!strcasecmp(eq, "YEARLY"))
				rpt->type = RECUR_YEARLY;
			else {
				mem_free(buf);
				return _("rrule frequency not supported.");
			}
		} else if (!strcasecmp(p, "INTERVAL")) {
			long v = atol(eq);
			if (v <= 0) {
				mem_free(buf);
				return _("invalid interval.");
			}
			rpt->freq = (int)v;
		} else if (!strcasecmp(p, "UNTIL")) {
			int type = 0;
			time_t t = ical_datetime2time_t(eq, NULL, &type);
			if (!t) {
				mem_free(buf);
				return _("invalid until format.");
			}
			if (start_is_date && type != 1) {
				mem_free(buf);
				return _("invalid until format.");
			}
			rpt->until = t;
			has_until = 1;
		} else if (!strcasecmp(p, "COUNT")) {
			long v = atol(eq);
			if (v <= 0) {
				mem_free(buf);
				return _("invalid count value.");
			}
			rpt->count = (int)v;
			has_count = 1;
		} else if (!strcasecmp(p, "BYMONTH")) {
			if (!ical_parse_int_list(eq, &rpt->bymonth, 1, 12, 0)) {
				mem_free(buf);
				return _("invalid bymonth list.");
			}
		} else if (!strcasecmp(p, "BYMONTHDAY")) {
			if (!ical_parse_int_list(eq, &rpt->bymonthday, 1, 31, 1)) {
				mem_free(buf);
				return _("invalid bymonthday list.");
			}
		} else if (!strcasecmp(p, "BYDAY")) {
			char *q, *save = NULL;
			char *list = mem_strdup(eq);
			for (q = strtok_r(list, ",", &save); q; q = strtok_r(NULL, ",", &save)) {
				int v;
				if (!ical_parse_wday(q, &v)) {
					mem_free(list);
					mem_free(buf);
					return _("invalid byday list.");
				}
				{
					int *pv = mem_malloc(sizeof(int));
					*pv = v;
					LLIST_ADD(&rpt->bywday, pv);
				}
			}
			mem_free(list);
		} else if (!strcasecmp(p, "WKST") || !strcasecmp(p, "BYSECOND") || !strcasecmp(p, "BYMINUTE") ||
			   !strcasecmp(p, "BYHOUR") || !strcasecmp(p, "BYYEARDAY") || !strcasecmp(p, "BYWEEKNO") ||
			   !strcasecmp(p, "BYSETPOS")) {
			/* ignored */
		}
	}
	mem_free(buf);
	if (rpt->type == RECUR_NO)
		return _("frequency not set in rrule.");
	if (has_until && has_count)
		return _("both until and count.");
	return NULL;
}

/*
 * Parse an EXDATE property, appending to the exception list.  Returns
 * NULL on success or an error message.
 */
static const char *ical_read_exdate(llist_t *exc, const char *exstr, int start_is_date)
{
	const char *val = ical_get_value(exstr);
	const char *vparam = ical_get_param(exstr, "VALUE");
	int exc_is_date = 0;
	char *buf, *p;

	if (!val)
		return _("malformed exceptions line.");
	if (vparam && !strncasecmp(vparam, "DATE", 4) && !(vparam[4] == '-'))
		exc_is_date = 1;
	if (exc_is_date != start_is_date)
		return _("invalid exception date value type.");

	buf = mem_strdup(val);
	for (p = strtok(buf, ","); p; p = strtok(NULL, ",")) {
		int type = 0;
		time_t t = ical_datetime2time_t(p, NULL, &type);
		if (!t || (exc_is_date && type != 1) || (!exc_is_date && type != 2)) {
			mem_free(buf);
			return _("invalid exception.");
		}
		{
			extern void recur_add_exc(llist_t *, time_t);
			recur_add_exc(exc, DAY(t));
		}
	}
	mem_free(buf);
	return NULL;
}

/* Append a line to a string (which may be NULL). */
static char *str_append(char *s, const char *add)
{
	char *r;
	if (!s)
		return mem_strdup(add);
	r = strdup_printf("%s%s", s, add);
	mem_free(s);
	return r;
}

/* Build a note from description, location, comments and import messages. */
static char *ical_build_note(const char *desc, const char *loc, llist_t *comments, llist_t *imports)
{
	char *note = NULL;
	llist_item_t *i;
	int has_extra = loc || LLIST_FIRST(comments) || LLIST_FIRST(imports);

	if (!desc && !has_extra)
		return NULL;
	if (desc) {
		note = str_append(note, desc);
		note = str_append(note, "\n");
	}
	if (has_extra) {
		note = str_append(note, SEPARATOR);
		if (loc) {
			note = str_append(note, "Location: ");
			note = str_append(note, loc);
			note = str_append(note, "\n");
		}
		LLIST_FOREACH(comments, i) {
			const char *c = LLIST_GET_DATA(i);
			const char *p = c, *nl;
			note = str_append(note, "Comment: ");
			while ((nl = strchr(p, '\n')) != NULL) {
				char *seg = mem_malloc(nl - p + 1);
				memcpy(seg, p, nl - p);
				seg[nl - p] = '\0';
				note = str_append(note, seg);
				note = str_append(note, "\n" INDENT);
				mem_free(seg);
				p = nl + 1;
			}
			note = str_append(note, p);
			note = str_append(note, "\n");
		}
		LLIST_FOREACH(imports, i) {
			note = str_append(note, "Import: ");
			note = str_append(note, LLIST_GET_DATA(i));
			note = str_append(note, "\n");
		}
	}
	return note;
}

static void ical_store_note(char **note, const char *desc, const char *loc, llist_t *comments, llist_t *imports)
{
	char *n = ical_build_note(desc, loc, comments, imports);
	if (n) {
		*note = generate_note(n);
		mem_free(n);
	} else {
		*note = NULL;
	}
}

static void ical_read_event(FILE *fdi, FILE *log, unsigned *noevents, unsigned *noapoints,
			    unsigned *noskipped, char *buf, char *lstore, unsigned *lineno,
			    const char *fmt_ev, const char *fmt_rev, const char *fmt_apt, const char *fmt_rapt)
{
	const char *endevent = "END:VEVENT";
	const char *summary_line = "SUMMARY";
	const char *dtstart_line = "DTSTART";
	const char *dtend_line = "DTEND";
	const char *duration_line = "DURATION";
	const char *rrule_line = "RRULE";
	const char *exdate_line = "EXDATE";
	const char *desc_line = "DESCRIPTION";
	const char *location_line = "LOCATION";
	const char *comment_line = "COMMENT";
	const char *alarm_line = "BEGIN:VALARM";
	const char *endalarm_line = "END:VALARM";
	const unsigned item_lnum = *lineno;

	time_t start = 0, end = 0;
	long dur = 0;
	int has_start = 0, has_end = 0, has_dur = 0, has_rrule = 0, has_alarm = 0;
	int start_is_date = 0, end_is_date = 0;
	int dur_days_only = 1;
	char *mesg = NULL, *desc = NULL, *loc = NULL, *note = NULL;
	llist_t comments, imports, exc;
	ical_rpt_t rpt;
	const char *err = NULL;
	int skip_alarm = 0;
	const char *tzid = NULL;
	char tzidbuf[BUFSIZ_LINE];

	LLIST_INIT(&comments);
	LLIST_INIT(&imports);
	LLIST_INIT(&exc);
	ical_rpt_init(&rpt);

	while (ical_readline(fdi, buf, lstore, lineno)) {
		if (skip_alarm) {
			if (starts_with_ci(buf, endalarm_line))
				skip_alarm = 0;
			continue;
		}
		if (starts_with_ci(buf, endevent)) {
			int is_event;
			/* finished: validate */
			if (!has_start) {
				err = _("item start date not defined.");
				goto skip;
			}
			if (has_end && end < start) {
				err = _("end must be later than start.");
				goto skip;
			}
			if (!mesg)
				mesg = mem_strdup(_("(empty)"));
			is_event = start_is_date;
			if (is_event) {
				long ndays = 1;
				if (has_end) {
					ndays = (long)((end - start + DAYINSEC / 2) / DAYINSEC);
					if (ndays < 1)
						ndays = 1;
				} else if (has_dur) {
					ndays = dur / DAYINSEC;
					if (ndays < 1)
						ndays = 1;
				}
				if (ndays > 1) {
					struct rpt *r;
					if (has_rrule) {
						/* keep the rrule, but note the change */
					}
					if (!has_rrule) {
						r = recur_rpt_new();
						r->type = RECUR_DAILY;
						r->freq = 1;
						r->until = date_sec_change(start, 0, (int)(ndays - 1));
						LLIST_ADD(&imports, mem_strdup(_("multi-day event changed to one-day event")));
						ical_store_note(&note, desc, loc, &comments, &imports);
						{
							struct recur_event *rev = recur_event_new(mesg, note, start, 1, r, &exc);
							LLIST_INIT(&exc);
							if (dump_imported)
								print_recur_event(fmt_rev, 0, rev);
						}
						(*noevents)++;
						goto done;
					}
					LLIST_ADD(&imports, mem_strdup(_("multi-day event changed to one-day event")));
				}
				if (has_rrule) {
					struct rpt *r = recur_rpt_new();
					struct recur_event *rev;
					r->type = rpt.type;
					r->freq = rpt.freq;
					r->until = rpt.until;
					recur_int_list_dup(&r->bymonth, &rpt.bymonth);
					recur_int_list_dup(&r->bywday, &rpt.bywday);
					recur_int_list_dup(&r->bymonthday, &rpt.bymonthday);
					if (!recur_check_rule(start, r)) {
						recur_rpt_free(r);
						err = _("rrule does not match start day (%s).");
						goto skip;
					}
					if (rpt.count) {
						time_t nth;
						if (!recur_nth_occurrence(start, DAYINSEC, &exc, r, rpt.count, &nth)) {
							recur_rpt_free(r);
							err = _("rrule does not match start day (%s).");
							goto skip;
						}
						r->until = nth;
					} else if (r->until) {
						time_t occ;
						if (recur_item_find_occurrence(start, DAYINSEC, r, NULL, DAY(r->until), &occ) && occ > r->until)
							r->until = date_sec_change(DAY(r->until), 0, -1);
						else
							r->until = DAY(r->until);
					}
					ical_store_note(&note, desc, loc, &comments, &imports);
					rev = recur_event_new(mesg, note, start, 1, r, &exc);
					LLIST_INIT(&exc);
					if (dump_imported)
						print_recur_event(fmt_rev, 0, rev);
				} else {
					struct event *ev;
					ical_store_note(&note, desc, loc, &comments, &imports);
					ev = event_new(mesg, note, start, 1);
					if (dump_imported)
						print_event(fmt_ev, 0, ev);
				}
				(*noevents)++;
			} else {
				char state = has_alarm ? APOINT_NOTIFY : 0;
				if (has_end)
					dur = end - start;
				else if (!has_dur)
					dur = 0;
				if (has_rrule) {
					struct rpt *r = recur_rpt_new();
					struct recur_apoint *rapt;
					r->type = rpt.type;
					r->freq = rpt.freq;
					r->until = rpt.until;
					recur_int_list_dup(&r->bymonth, &rpt.bymonth);
					recur_int_list_dup(&r->bywday, &rpt.bywday);
					recur_int_list_dup(&r->bymonthday, &rpt.bymonthday);
					if (!recur_check_rule(start, r)) {
						recur_rpt_free(r);
						err = _("rrule does not match start day (%s).");
						goto skip;
					}
					if (rpt.count) {
						time_t nth;
						if (!recur_nth_occurrence(start, dur, &exc, r, rpt.count, &nth)) {
							recur_rpt_free(r);
							err = _("rrule does not match start day (%s).");
							goto skip;
						}
						r->until = nth;
					} else if (r->until) {
						time_t occ;
						time_t u = r->until;
						if (recur_item_find_occurrence(start, dur, r, NULL, DAY(u), &occ) && occ > u)
							r->until = date_sec_change(update_time_in_date(u, get_item_hour(start), get_item_min(start)), 0, -1);
						else
							r->until = update_time_in_date(u, get_item_hour(start), get_item_min(start));
					}
					ical_store_note(&note, desc, loc, &comments, &imports);
					rapt = recur_apoint_new(mesg, note, start, dur, state, r, &exc);
					LLIST_INIT(&exc);
					if (dump_imported)
						print_recur_apoint(fmt_rapt, 0, rapt->start, rapt);
				} else {
					struct apoint *apt;
					ical_store_note(&note, desc, loc, &comments, &imports);
					apt = apoint_new(mesg, note, start, dur, state);
					if (dump_imported)
						print_apoint(fmt_apt, 0, apt);
				}
				(*noapoints)++;
			}
			goto done;
		} else if (starts_with_ci(buf, alarm_line)) {
			has_alarm = 1;
			skip_alarm = 1;
		} else if (starts_with_ci(buf, dtstart_line)) {
			const char *val = ical_get_value(buf);
			const char *vparam = ical_get_param(buf, "VALUE");
			const char *tz = ical_get_param(buf, "TZID");
			int type = 0;
			if (!val || !*val) {
				err = _("invalid or malformed event start time.");
				goto skip;
			}
			if (tz) {
				const char *e = tz;
				while (*e && *e != ';' && *e != ':')
					e++;
				snprintf(tzidbuf, sizeof(tzidbuf), "%.*s", (int)(e - tz), tz);
				tzid = tzidbuf;
			}
			start = ical_datetime2time_t(val, tzid, &type);
			if (!start) {
				err = _("invalid or malformed event start time.");
				goto skip;
			}
			if (vparam && !strncasecmp(vparam, "DATE", 4) && vparam[4] != '-') {
				if (type != 1) {
					err = _("invalid or malformed event start time.");
					goto skip;
				}
				start_is_date = 1;
			} else if (type != 2) {
				err = _("invalid or malformed event start time.");
				goto skip;
			}
			has_start = 1;
			if (tzid) {
				char *imp = strdup_printf("TZID=%s", tzid);
				LLIST_ADD(&imports, imp);
			}
		} else if (starts_with_ci(buf, dtend_line)) {
			const char *val = ical_get_value(buf);
			const char *vparam = ical_get_param(buf, "VALUE");
			int type = 0;
			if (has_dur) {
				err = _("either end or duration.");
				goto skip;
			}
			if (!val || !*val) {
				err = _("invalid or malformed event end time.");
				goto skip;
			}
			end = ical_datetime2time_t(val, NULL, &type);
			if (!end) {
				err = _("invalid or malformed event end time.");
				goto skip;
			}
			end_is_date = (vparam && !strncasecmp(vparam, "DATE", 4) && vparam[4] != '-');
			if (end_is_date && type != 1) {
				err = _("invalid or malformed event end time.");
				goto skip;
			}
			if (!end_is_date && type != 2) {
				err = _("invalid end time value type.");
				goto skip;
			}
			has_end = 1;
		} else if (starts_with_ci(buf, duration_line)) {
			const char *val = ical_get_value(buf);
			if (has_end) {
				err = _("either end or duration.");
				goto skip;
			}
			if (!val) {
				err = _("invalid duration.");
				goto skip;
			}
			dur = ical_dur2long(val, &dur_days_only);
			if (dur < 0) {
				err = _("invalid duration.");
				goto skip;
			}
			has_dur = 1;
		} else if (starts_with_ci(buf, rrule_line)) {
			if (has_rrule) {
				err = _("only one recurrence rule allowed.");
				goto skip;
			}
			err = ical_read_rrule(buf, &rpt, start_is_date);
			if (err)
				goto skip;
			has_rrule = 1;
		} else if (starts_with_ci(buf, exdate_line)) {
			if (!has_rrule) {
				/* check for malformed line first */
				if (!ical_get_value(buf)) {
					err = _("malformed exceptions line.");
					goto skip;
				}
				err = _("exception date, but no recurrence rule.");
				goto skip;
			}
			err = ical_read_exdate(&exc, buf, start_is_date);
			if (err)
				goto skip;
		} else if (starts_with_ci(buf, summary_line)) {
			const char *val = ical_get_value(buf);
			if (!val) {
				err = _("malformed summary line.");
				goto skip;
			}
			if (mesg)
				mem_free(mesg);
			mesg = ical_unformat_line(val, 1);
			if (!mesg) {
				err = _("malformed summary.");
				goto skip;
			}
		} else if (starts_with_ci(buf, desc_line)) {
			const char *val = ical_get_value(buf);
			if (!val) {
				err = _("malformed description line.");
				goto skip;
			}
			if (desc)
				mem_free(desc);
			desc = ical_unformat_line(val, 0);
			if (!desc) {
				err = _("malformed description.");
				goto skip;
			}
		} else if (starts_with_ci(buf, location_line)) {
			const char *val = ical_get_value(buf);
			if (!val) {
				err = _("malformed location line.");
				goto skip;
			}
			if (loc) {
				err = _("only one location allowed.");
				goto skip;
			}
			loc = ical_unformat_line(val, 0);
			if (!loc) {
				err = _("malformed location.");
				goto skip;
			}
		} else if (starts_with_ci(buf, comment_line)) {
			const char *val = ical_get_value(buf);
			char *c;
			if (!val) {
				err = _("malformed comment line.");
				goto skip;
			}
			c = ical_unformat_line(val, 0);
			if (!c) {
				err = _("malformed comment.");
				goto skip;
			}
			LLIST_ADD(&comments, c);
		}
	}

	err = _("The ical file seems to be malformed. The end of item was not found.");
	ical_log(log, "VEVENT", item_lnum, err);
	(*noskipped)++;
	goto cleanup;

skip:
	ical_log(log, "VEVENT", item_lnum, err);
	(*noskipped)++;
	/* skip until END:VEVENT */
	while (!starts_with_ci(buf, endevent)) {
		if (!ical_readline(fdi, buf, lstore, lineno)) {
			ical_log(log, "VEVENT", item_lnum,
				 _("The ical file seems to be malformed. The end of item was not found."));
			break;
		}
	}
	goto cleanup;

done:
cleanup:
	if (mesg)
		mem_free(mesg);
	if (desc)
		mem_free(desc);
	if (loc)
		mem_free(loc);
	if (note)
		mem_free(note);
	LLIST_FREE_INNER(&comments, mem_free);
	LLIST_FREE(&comments);
	LLIST_FREE_INNER(&imports, mem_free);
	LLIST_FREE(&imports);
	recur_free_exc_list(&exc);
	ical_rpt_free(&rpt);
	(void)dur_days_only;
}

static void ical_read_todo(FILE *fdi, FILE *log, unsigned *notodos, unsigned *noskipped,
			   char *buf, char *lstore, unsigned *lineno, const char *fmt_todo)
{
	const char *endtodo = "END:VTODO";
	const char *summary_line = "SUMMARY";
	const char *priority_line = "PRIORITY";
	const char *desc_line = "DESCRIPTION";
	const char *location_line = "LOCATION";
	const char *comment_line = "COMMENT";
	const char *status_line = "STATUS";
	const char *alarm_line = "BEGIN:VALARM";
	const char *endalarm_line = "END:VALARM";
	const unsigned item_lnum = *lineno;
	char *mesg = NULL, *desc = NULL, *loc = NULL, *note = NULL;
	llist_t comments, imports;
	int priority = 0, completed = 0;
	const char *err = NULL;
	int skip_alarm = 0;

	LLIST_INIT(&comments);
	LLIST_INIT(&imports);

	while (ical_readline(fdi, buf, lstore, lineno)) {
		if (skip_alarm) {
			if (starts_with_ci(buf, endalarm_line))
				skip_alarm = 0;
			continue;
		}
		if (starts_with_ci(buf, endtodo)) {
			struct todo *t;
			if (!mesg)
				mesg = mem_strdup(_("(empty)"));
			ical_store_note(&note, desc, loc, &comments, &imports);
			t = todo_add(mesg, priority, completed, note);
			if (dump_imported)
				print_todo(fmt_todo, t);
			(*notodos)++;
			goto cleanup;
		} else if (starts_with_ci(buf, alarm_line)) {
			skip_alarm = 1;
		} else if (starts_with_ci(buf, priority_line)) {
			const char *val = ical_get_value(buf);
			long v;
			char *end;
			if (!val) {
				err = _("item priority is invalid (must be between 0 and 9).");
				goto skip;
			}
			v = strtol(val, &end, 10);
			if (end == val || *end || v < 0 || v > 9) {
				err = _("item priority is invalid (must be between 0 and 9).");
				goto skip;
			}
			priority = (int)v;
		} else if (starts_with_ci(buf, status_line)) {
			const char *val = ical_get_value(buf);
			if (val && !strcasecmp(val, "COMPLETED"))
				completed = 1;
		} else if (starts_with_ci(buf, summary_line)) {
			const char *val = ical_get_value(buf);
			if (!val) {
				err = _("malformed summary line.");
				goto skip;
			}
			if (mesg)
				mem_free(mesg);
			mesg = ical_unformat_line(val, 1);
			if (!mesg) {
				err = _("malformed summary.");
				goto skip;
			}
		} else if (starts_with_ci(buf, desc_line)) {
			const char *val = ical_get_value(buf);
			if (!val) {
				err = _("malformed description line.");
				goto skip;
			}
			if (desc)
				mem_free(desc);
			desc = ical_unformat_line(val, 0);
			if (!desc) {
				err = _("malformed description.");
				goto skip;
			}
		} else if (starts_with_ci(buf, location_line)) {
			const char *val = ical_get_value(buf);
			if (!val) {
				err = _("malformed location line.");
				goto skip;
			}
			if (loc) {
				err = _("only one location allowed.");
				goto skip;
			}
			loc = ical_unformat_line(val, 0);
			if (!loc) {
				err = _("malformed location.");
				goto skip;
			}
		} else if (starts_with_ci(buf, comment_line)) {
			const char *val = ical_get_value(buf);
			char *c;
			if (!val) {
				err = _("malformed comment line.");
				goto skip;
			}
			c = ical_unformat_line(val, 0);
			if (!c) {
				err = _("malformed comment.");
				goto skip;
			}
			LLIST_ADD(&comments, c);
		}
	}

	err = _("The ical file seems to be malformed. The end of item was not found.");
	ical_log(log, "VTODO", item_lnum, err);
	(*noskipped)++;
	goto cleanup;

skip:
	ical_log(log, "VTODO", item_lnum, err);
	(*noskipped)++;
	while (!starts_with_ci(buf, endtodo)) {
		if (!ical_readline(fdi, buf, lstore, lineno)) {
			ical_log(log, "VTODO", item_lnum,
				 _("The ical file seems to be malformed. The end of item was not found."));
			break;
		}
	}

cleanup:
	if (mesg)
		mem_free(mesg);
	if (desc)
		mem_free(desc);
	if (loc)
		mem_free(loc);
	if (note)
		mem_free(note);
	LLIST_FREE_INNER(&comments, mem_free);
	LLIST_FREE(&comments);
	LLIST_FREE_INNER(&imports, mem_free);
	LLIST_FREE(&imports);
}

void ical_import_data(const char *file_name, FILE *stream, FILE *log, unsigned *events,
		      unsigned *apoints, unsigned *todos, unsigned *lines, unsigned *skipped,
		      const char *fmt_ev, const char *fmt_rev, const char *fmt_apt,
		      const char *fmt_rapt, const char *fmt_todo)
{
	const char *vevent = "BEGIN:VEVENT";
	const char *vtodo = "BEGIN:VTODO";
	char buf[BUFSIZ_LINE], lstore[BUFSIZ_LINE];
	float version = 0;

	*events = *apoints = *todos = *lines = *skipped = 0;

	ical_readline_init(stream, buf, lstore, lines);
	if (!ical_chk_header(stream, buf, lstore, lines, &version)) {
		WARN_MSG("ical.c", 1879, "Warning: ical header malformed or wrong version number. Aborting...");
		return;
	}
	ical_log_init(log, file_name, version);

	while (ical_readline(stream, buf, lstore, lines)) {
		if (starts_with_ci(buf, vevent)) {
			ical_read_event(stream, log, events, apoints, skipped, buf, lstore, lines,
					fmt_ev, fmt_rev, fmt_apt, fmt_rapt);
		} else if (starts_with_ci(buf, vtodo)) {
			ical_read_todo(stream, log, todos, skipped, buf, lstore, lines, fmt_todo);
		}
	}
}
EOF
echo ok

