{"command":"cd /workspace; python3 - <<'EOF'
p='src/recur.c'
s=open(p).read()
start=s.index("/* Does the given date pass the bymonth limit? */")
end=s.index("int recur_apoint_find_occurrence(")
new=r'''/* Does the given date pass the bymonth limit? */
static int bymonth_ok(struct rpt *rpt, int m)
{
	return int_list_empty(&rpt->bymonth) || int_list_has(&rpt->bymonth, m);
}

/* Decode a BYDAY value into order and weekday; returns 0 if illegal. */
static int bywday_decode(int v, int *order, int *wday)
{
	int o = v / 7;
	int r = v % 7;
	if (o == 0) {
		if (r < 0)
			return 0;
		*order = 0;
		*wday = r;
	} else if (o > 0) {
		if (r < 0)
			return 0;
		*order = o;
		*wday = r;
	} else {
		if (r > 0)
			return 0;
		*order = o;
		*wday = -r;
	}
	return 1;
}

static void civil_from_days(long z, int *y, int *m, int *d)
{
	long era, doe, yoe, doy, mp;
	z += 719468;
	era = (z >= 0 ? z : z - 146096) / 146097;
	doe = z - era * 146097;
	yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
	doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
	mp = (5 * doy + 2) / 153;
	*d = (int)(doy - (153 * mp + 2) / 5 + 1);
	*m = (int)(mp < 10 ? mp + 3 : mp - 9);
	*y = (int)(yoe + era * 400 + (*m <= 2));
}

/* Weekday (0 = Sunday) for a day number. */
static int dn_wday(long dn)
{
	long w = (dn + 4) % 7;
	if (w < 0)
		w += 7;
	return (int)w;
}

/* Monday-based week number relative to the epoch for a day number. */
static long week_index(long dn)
{
	long w = dn + 3;
	return (w >= 0 ? w : w - 6) / 7;
}

/* Day number of the n-th weekday of a month (n > 0 from start, n < 0 from end); -1 if none. */
static long nth_wday_in_month(int y, int m, int order, int wday)
{
	long first = days_from_civil(y, m, 1);
	int nd = month_days(m, y);
	int w1 = dn_wday(first);
	int d;
	if (order > 0) {
		d = 1 + ((wday - w1 + 7) % 7) + (order - 1) * 7;
		if (d > nd)
			return -1;
		return first + d - 1;
	} else if (order < 0) {
		long last = first + nd - 1;
		int wl = dn_wday(last);
		d = nd - ((wl - wday + 7) % 7) - (-order - 1) * 7;
		if (d < 1)
			return -1;
		return first + d - 1;
	}
	return -1;
}

/* Day number of the n-th weekday of a year; -1 if none. */
static long nth_wday_in_year(int y, int order, int wday)
{
	long first = days_from_civil(y, 1, 1);
	long ydays = ISLEAP(y) ? 366 : 365;
	int w1 = dn_wday(first);
	long d;
	if (order > 0) {
		d = 1 + ((wday - w1 + 7) % 7) + (long)(order - 1) * 7;
		if (d > ydays)
			return -1;
		return first + d - 1;
	} else if (order < 0) {
		long last = first + ydays - 1;
		int wl = dn_wday(last);
		d = ydays - ((wl - wday + 7) % 7) - (long)(-order - 1) * 7;
		if (d < 1)
			return -1;
		return first + d - 1;
	}
	return -1;
}

/* Does day (y, m, d) match the bymonthday list? */
static int bymonthday_match(llist_t *l, int y, int m, int d)
{
	int ndays = month_days(m, y);
	return int_list_has(l, d) || int_list_has(l, d - ndays - 1);
}

/* Does day match any bywday entry, counted within the month? */
static int bywday_any_month(struct rpt *rpt, long dn, int line)
{
	llist_item_t *i;
	int y, m, d;
	civil_from_days(dn, &y, &m, &d);
	LLIST_FOREACH(&rpt->bywday, i) {
		int order, wday;
		if (!bywday_decode(*(int *)LLIST_GET_DATA(i), &order, &wday))
			EXIT_ON_ERROR("recur.c", line, "illegal BYDAY value");
		if (dn_wday(dn) != wday)
			continue;
		if (order == 0 || nth_wday_in_month(y, m, order, wday) == dn)
			return 1;
	}
	return 0;
}

/* Does day match any bywday entry, counted within the year (or month if month_based)? */
static int bywday_any_year(struct rpt *rpt, long dn, int line, int month_based)
{
	llist_item_t *i;
	int y, m, d;
	civil_from_days(dn, &y, &m, &d);
	LLIST_FOREACH(&rpt->bywday, i) {
		int order, wday;
		if (!bywday_decode(*(int *)LLIST_GET_DATA(i), &order, &wday))
			EXIT_ON_ERROR("recur.c", line, "illegal BYDAY value");
		if (dn_wday(dn) != wday)
			continue;
		if (order == 0)
			return 1;
		if (month_based ? nth_wday_in_month(y, m, order, wday) == dn : nth_wday_in_year(y, order, wday) == dn)
			return 1;
	}
	return 0;
}

static time_t daynum_to_time(long dn, time_t start)
{
	int y, m, d;
	struct tm tm;
	civil_from_days(dn, &y, &m, &d);
	localtime_r_safe(start, &tm);
	tm.tm_year = y - TM_YEAR_BASE;
	tm.tm_mon = m - 1;
	tm.tm_mday = d;
	tm.tm_isdst = -1;
	return mktime(&tm);
}

/*
 * Context for the candidate search.
 */
struct rsearch {
	time_t start;		/* item start */
	long dur;		/* item duration */
	struct rpt *rpt;
	long sdn;		/* start day number */
	long D;			/* target day number */
	time_t day_start;	/* target day start time */
	int exact;		/* candidate must be D itself */
	long result;		/* resulting candidate day number */
};

/* Accept a candidate if it is in range; returns 1 if accepted. */
static int accept(struct rsearch *rs, long cand)
{
	time_t t;
	if (cand < 0 || cand < rs->sdn || cand > rs->D)
		return 0;
	if (rs->exact) {
		if (cand != rs->D)
			return 0;
	} else {
		t = daynum_to_time(cand, rs->start);
		if (!(t < rs->day_start + DAYINSEC && t + rs->dur > rs->day_start))
			return 0;
	}
	rs->result = cand;
	return 1;
}

static int search_daily(struct rsearch *rs)
{
	struct rpt *rpt = rs->rpt;
	long diff = rs->D - rs->sdn;
	long cand = rs->sdn + (diff / rpt->freq) * rpt->freq;
	int y, m, d;

	civil_from_days(cand, &y, &m, &d);
	if (!bymonth_ok(rpt, m))
		return 0;
	if (!int_list_empty(&rpt->bywday) && !int_list_has(&rpt->bywday, dn_wday(cand)))
		return 0;
	if (!int_list_empty(&rpt->bymonthday) && !bymonthday_match(&rpt->bymonthday, y, m, d))
		return 0;
	return accept(rs, cand);
}

/* Latest day <= D with the given weekday in a week aligned with the start week. */
static long weekly_latest(struct rsearch *rs, int wday)
{
	long sw = week_index(rs->sdn), tw = week_index(rs->D);
	long k = (tw - sw) / rs->rpt->freq;
	long wk, first, cand;
	int off = (wday + 6) % 7;	/* Monday-based offset */

	for (; k >= 0; k--) {
		wk = sw + k * rs->rpt->freq;
		first = wk * 7 - 3;	/* Monday of that week */
		cand = first + off;
		if (cand <= rs->D)
			return cand;
	}
	return -1;
}

static int search_weekly(struct rsearch *rs)
{
	struct rpt *rpt = rs->rpt;
	llist_item_t *i;
	int y, m, d;
	long cand;

	if (int_list_empty(&rpt->bywday)) {
		cand = weekly_latest(rs, dn_wday(rs->sdn));
		if (cand < 0)
			return 0;
		civil_from_days(cand, &y, &m, &d);
		if (!bymonth_ok(rpt, m))
			return 0;
		return accept(rs, cand);
	}
	LLIST_FOREACH(&rpt->bywday, i) {
		int wday = *(int *)LLIST_GET_DATA(i);
		cand = weekly_latest(rs, wday);
		if (cand < 0)
			continue;
		civil_from_days(cand, &y, &m, &d);
		if (!bymonth_ok(rpt, m))
			continue;
		if (accept(rs, cand))
			return 1;
	}
	return 0;
}

static int search_monthly(struct rsearch *rs)
{
	struct rpt *rpt = rs->rpt;
	int sy, sm, sd, y, m, d;
	long smon, tmon;
	llist_item_t *i;
	int has_md = !int_list_empty(&rpt->bymonthday);
	int has_wd = !int_list_empty(&rpt->bywday);
	long cand;

	civil_from_days(rs->sdn, &sy, &sm, &sd);
	civil_from_days(rs->D, &y, &m, &d);
	smon = (long)sy * 12 + (sm - 1);
	tmon = (long)y * 12 + (m - 1);
	if ((tmon - smon) % rpt->freq != 0)
		return 0;

	if (has_wd && !has_md) {
		long X = rs->D;
		LLIST_FOREACH(&rpt->bywday, i) {
			int order, wday;
			if (!bywday_decode(*(int *)LLIST_GET_DATA(i), &order, &wday))
				EXIT_ON_ERROR("recur.c", 1267, "illegal BYDAY value");
			if (order != 0) {
				cand = nth_wday_in_month(y, m, order, wday);
				if (cand >= 0 && cand <= rs->D) {
					X = cand;
				} else {
					int py = y, pm = m - 1;
					X = rs->D;
					if (pm < 1) {
						pm = 12;
						py--;
					}
					cand = nth_wday_in_month(py, pm, order, wday);
					if (cand >= 0 && !bymonth_ok(rpt, pm))
						cand = -1;
				}
			} else {
				long c = X;
				int cy, cm, cd;
				while (dn_wday(c) != wday)
					c--;
				civil_from_days(c, &cy, &cm, &cd);
				cand = bymonth_ok(rpt, cm) ? c : -1;
			}
			if (cand >= 0 && accept(rs, cand))
				return 1;
		}
		return 0;
	}

	if (!bymonth_ok(rpt, m) && !has_md && !has_wd) {
		/* fall through to the previous aligned month below */
	}

	if (has_md) {
		int nd = month_days(m, y);
		LLIST_FOREACH(&rpt->bymonthday, i) {
			int dd = *(int *)LLIST_GET_DATA(i);
			int cy = y, cm = m;
			if (dd < 0)
				dd = nd + 1 + dd;
			cand = -1;
			if (dd >= 1 && dd <= nd) {
				cand = days_from_civil(y, m, dd);
				if (cand > rs->D)
					cand = -1;
			}
			if (cand < 0) {
				long pmon = tmon - rpt->freq;
				cy = (int)(pmon / 12);
				cm = (int)(pmon % 12) + 1;
				if (dd >= 1 && dd <= month_days(cm, cy))
					cand = days_from_civil(cy, cm, dd);
			}
			if (cand < 0)
				continue;
			if (!bymonth_ok(rpt, cm))
				continue;
			if (has_wd && !bywday_any_month(rpt, cand, 1267))
				continue;
			if (accept(rs, cand))
				return 1;
		}
		return 0;
	}

	/* no lists: same day of month as the start */
	{
		int nd = month_days(m, y);
		int cy = y, cm = m;
		cand = -1;
		if (sd <= nd) {
			cand = days_from_civil(y, m, sd);
			if (cand > rs->D)
				cand = -1;
		}
		if (cand < 0) {
			long pmon = tmon - rpt->freq;
			cy = (int)(pmon / 12);
			cm = (int)(pmon % 12) + 1;
			if (sd <= month_days(cm, cy))
				cand = days_from_civil(cy, cm, sd);
		}
		if (cand < 0 || !bymonth_ok(rpt, cm))
			return 0;
		return accept(rs, cand);
	}
}

/* Is month m (1-12) allowed for a yearly rule? */
static int yearly_month_ok(struct rpt *rpt, int sm, int m)
{
	if (!int_list_empty(&rpt->bymonth))
		return int_list_has(&rpt->bymonth, m);
	return m == sm;
}

static int search_yearly(struct rsearch *rs)
{
	struct rpt *rpt = rs->rpt;
	int sy, sm, sd, y, m, d;
	llist_item_t *i;
	int has_md = !int_list_empty(&rpt->bymonthday);
	int has_wd = !int_list_empty(&rpt->bywday);
	int has_m = !int_list_empty(&rpt->bymonth);
	long cand, c;
	int k;

	civil_from_days(rs->sdn, &sy, &sm, &sd);
	civil_from_days(rs->D, &y, &m, &d);
	if ((y - sy) % rpt->freq != 0)
		return 0;

	if (has_wd && !has_md) {
		LLIST_FOREACH(&rpt->bywday, i) {
			int order, wday;
			if (!bywday_decode(*(int *)LLIST_GET_DATA(i), &order, &wday))
				EXIT_ON_ERROR("recur.c", 1418, "illegal BYDAY value");
			cand = -1;
			for (k = 0; k < 2 && cand < 0; k++) {
				int yy = y - k * rpt->freq;
				long ystart = days_from_civil(yy, 1, 1);
				if (order == 0) {
					c = (k == 0) ? rs->D : ystart + (ISLEAP(yy) ? 365 : 364);
					while (c >= ystart) {
						int cy, cm, cd;
						civil_from_days(c, &cy, &cm, &cd);
						if (dn_wday(c) == wday && yearly_month_ok(rpt, sm, cm)) {
							cand = c;
							break;
						}
						c--;
					}
				} else if (has_m) {
					int mm;
					for (mm = 12; mm >= 1 && cand < 0; mm--) {
						if (!int_list_has(&rpt->bymonth, mm))
							continue;
						c = nth_wday_in_month(yy, mm, order, wday);
						if (c >= 0 && c <= rs->D)
							cand = c;
					}
				} else {
					c = nth_wday_in_year(yy, order, wday);
					if (c >= 0 && c <= rs->D)
						cand = c;
				}
			}
			if (cand >= 0 && accept(rs, cand))
				return 1;
		}
		return 0;
	}

	if (has_md) {
		LLIST_FOREACH(&rpt->bymonthday, i) {
			int dd = *(int *)LLIST_GET_DATA(i);
			cand = -1;
			for (k = 0; k < 2 && cand < 0; k++) {
				int yy = y - k * rpt->freq, mm;
				for (mm = 12; mm >= 1 && cand < 0; mm--) {
					int nd = month_days(mm, yy), rd = dd;
					if (!yearly_month_ok(rpt, sm, mm))
						continue;
					if (rd < 0)
						rd = nd + 1 + rd;
					if (rd < 1 || rd > nd)
						continue;
					c = days_from_civil(yy, mm, rd);
					if (c > rs->D)
						continue;
					if (has_wd && !bywday_any_year(rpt, c, 1418, has_m))
						continue;
					cand = c;
				}
			}
			if (cand >= 0 && accept(rs, cand))
				return 1;
		}
		return 0;
	}

	/* no day lists: same day of month as the start, in allowed months */
	cand = -1;
	for (k = 0; k < 2 && cand < 0; k++) {
		int yy = y - k * rpt->freq, mm;
		for (mm = 12; mm >= 1 && cand < 0; mm--) {
			if (!yearly_month_ok(rpt, sm, mm))
				continue;
			if (sd > month_days(mm, yy))
				continue;
			c = days_from_civil(yy, mm, sd);
			if (c > rs->D)
				continue;
			cand = c;
		}
	}
	if (cand < 0)
		return 0;
	return accept(rs, cand);
}

static int recur_search(struct rsearch *rs)
{
	if (rs->D < rs->sdn)
		return 0;
	switch (rs->rpt->type) {
	case RECUR_DAILY:
		return search_daily(rs);
	case RECUR_WEEKLY:
		return search_weekly(rs);
	case RECUR_MONTHLY:
		return search_monthly(rs);
	case RECUR_YEARLY:
		return search_yearly(rs);
	default:
		return 0;
	}
}

/*
 * Return 1 if an occurrence of the recurrent item overlaps the day
 * starting at day_start.  The occurrence start is stored in *occurrence.
 */
int recur_item_find_occurrence(time_t item_start, long item_dur, struct rpt *rpt,
			       llist_t *item_exc, time_t day_start, time_t *occurrence)
{
	struct rsearch rs;
	time_t t;

	if (rpt->freq == 0) {
		/* The original divides by zero here. */
		volatile int zero = 0;
		volatile int x = 1 / zero;
		(void)x;
	}

	rs.start = item_start;
	rs.dur = item_dur;
	rs.rpt = rpt;
	rs.sdn = daynum(item_start);
	rs.D = daynum(day_start);
	rs.day_start = day_start;
	rs.exact = 0;
	rs.result = -1;
	if (!recur_search(&rs))
		return 0;
	t = daynum_to_time(rs.result, item_start);
	if (rpt->until != 0 && t > rpt->until)
		return 0;
	if (item_exc && LLIST_FIND_FIRST(item_exc, &t, exc_inday))
		return 0;
	if (occurrence)
		*occurrence = t;
	return 1;
}

/* Is the given day (day number) an occurrence day of the rule (ignoring until/exc)? */
static int recur_day_matches(time_t item_start, struct rpt *rpt, long dn)
{
	struct rsearch rs;
	rs.start = item_start;
	rs.dur = 0;
	rs.rpt = rpt;
	rs.sdn = daynum(item_start);
	rs.D = dn;
	rs.day_start = 0;
	rs.exact = 1;
	rs.result = -1;
	return recur_search(&rs);
}

/*
 * Find the next occurrence strictly after the day containing 'after'.
 * Used for stepping through repetitions and for the count conversion.
 */
int recur_next_occurrence(time_t item_start, long item_dur, llist_t *item_exc,
			  struct rpt *rpt, time_t after, time_t *next)
{
	long sdn = daynum(item_start), dn = daynum(after) + 1;
	long limit = dn + 366 * 60;
	time_t t;

	(void)item_dur;
	if (dn < sdn)
		dn = sdn;
	for (; dn < limit; dn++) {
		if (!recur_day_matches(item_start, rpt, dn))
			continue;
		t = daynum_to_time(dn, item_start);
		if (rpt->until != 0 && t > rpt->until)
			return 0;
		if (item_exc && LLIST_FIND_FIRST(item_exc, &t, exc_inday))
			continue;
		*next = t;
		return 1;
	}
	return 0;
}

/*
 * Find the n-th occurrence (counting the start as number one and
 * skipping exceptions).  Returns 0 if there is none.
 */
int recur_nth_occurrence(time_t item_start, long item_dur, llist_t *item_exc,
			 struct rpt *rpt, int n, time_t *res)
{
	time_t t = item_start, nx;
	int count = 0;

	if (recur_day_matches(item_start, rpt, daynum(item_start)) &&
	    !(item_exc && LLIST_FIND_FIRST(item_exc, &t, exc_inday)))
		count = 1;
	if (count == 0) {
		if (!recur_next_occurrence(item_start, item_dur, item_exc, rpt, item_start, &t))
			return 0;
		count = 1;
	}
	while (count < n) {
		if (!recur_next_occurrence(item_start, item_dur, item_exc, rpt, t, &nx))
			return 0;
		t = nx;
		count++;
	}
	*res = t;
	return 1;
}

