	{ "lower-priority", "-", "Prio.-" },
};

/* Key -> action map and per-action list of keys. */
static llist_t keys[NBVKEYS];
static enum vkey actions[MAXKEYVAL];

struct keystr {
	int key;
};

void keys_init(void)
{
	int i;
	for (i = 0; i < MAXKEYVAL; i++)
		actions[i] = KEY_UNDEF;
	for (i = 0; i < NBVKEYS; i++)
		LLIST_INIT(&keys[i]);
}

static void keys_free_list(llist_t *l)
{
	LLIST_FREE_INNER(l, mem_free);
	LLIST_FREE(l);
}

void keys_free(void)
{
	int i;
	for (i = 0; i < NBVKEYS; i++)
		keys_free_list(&keys[i]);
}

void keys_dump_defaults(char *buf)
{
	int i;
	buf[0] = '\0';
	for (i = 0; i < NBVKEYS; i++) {
		strcat(buf, keydef[i].label);
		strcat(buf, "  ");
		strcat(buf, keydef[i].binding);
		strcat(buf, "\n");
	}
}

const char *keys_get_label(enum vkey key)
{
	if (key < 0 || key >= NBVKEYS)
		return NULL;
	return keydef[key].label;
}

const char *keys_get_binding(enum vkey key)
{
	if (key < 0 || key >= NBVKEYS)
		return NULL;
	return keydef[key].binding;
}

const char *keys_get_sb_label(enum vkey key)
{
	if (key < 0 || key >= NBVKEYS)
		return "";
	return keydef[key].sb_label;
}

int keys_get_action(int pressed)
{
	if (pressed < 0 || pressed >= MAXKEYVAL)
		return KEY_UNDEF;
	return actions[pressed];
}

/* Returns 0 on success, 1 if the key is already bound, 2 if the key is invalid. */
int keys_assign_binding(int key, enum vkey action)
{
	struct keystr *p;
	if (key < 0 || key >= MAXKEYVAL)
		return 2;
	if (actions[key] != KEY_UNDEF)
		return 1;
	actions[key] = action;
	p = mem_malloc(sizeof(struct keystr));
	p->key = key;
	LLIST_ADD(&keys[action], p);
	return 0;
}

static int key_match(struct keystr *p, int *key)
{
	return p->key == *key;
}

void keys_remove_binding(int key, enum vkey action)
{
	llist_item_t *i;
	if (key < 0 || key >= MAXKEYVAL)
		return;
	i = LLIST_FIND_FIRST(&keys[action], &key, key_match);
	if (i) {
		mem_free(LLIST_GET_DATA(i));
		LLIST_REMOVE(&keys[action], i);
	}
	actions[key] = KEY_UNDEF;
}

int keys_str2int(const char *key)
{
	if (!key)
		return -1;
	if (strlen(key) == 1)
		return (int)(unsigned char)key[0];
	if (key[0] == '^' && strlen(key) == 2) {
		int c = toupper((unsigned char)key[1]);
		if (c >= '@' && c <= '_')
			return c - '@';
		return -1;
	}
	if (!strcmp(key, "ESC"))
		return 27;
	if (!strcmp(key, "SPC"))
		return ' ';
	if (!strcmp(key, "TAB"))
		return '\t';
	if (!strcmp(key, "RET"))
		return '\n';
	if (!strcmp(key, "KEY_BTAB"))
		return KEY_BTAB;
	if (!strcmp(key, "UP"))
		return KEY_UP;
	if (!strcmp(key, "DWN"))
		return KEY_DOWN;
	if (!strcmp(key, "LFT"))
		return KEY_LEFT;
	if (!strcmp(key, "RGT"))
		return KEY_RIGHT;
	if (!strcmp(key, "HOM"))
		return KEY_HOME;
	if (!strcmp(key, "END"))
		return KEY_END;
	if (!strcmp(key, "INS"))
		return KEY_IC;
	if (!strcmp(key, "DEL"))
		return KEY_DC;
	if (!strcmp(key, "PgU"))
		return KEY_PPAGE;
	if (!strcmp(key, "PgD"))
		return KEY_NPAGE;
	if (!strncmp(key, "KEY_F(", 6)) {
		int n = atoi(key + 6);
		if (n >= 1 && n <= 12)
			return KEY_F(n);
	}
	return -1;
}

const char *keys_int2str(int key)
{
	static char buf[16];
	switch (key) {
	case 27:
		return "ESC";
	case ' ':
		return "SPC";
	case '\t':
		return "TAB";
	case '\n':
	case '\r':
	case KEY_ENTER:
		return "RET";
	case KEY_BTAB:
		return "KEY_BTAB";
	case KEY_UP:
		return "UP";
	case KEY_DOWN:
		return "DWN";
	case KEY_LEFT:
		return "LFT";
	case KEY_RIGHT:
		return "RGT";
	case KEY_HOME:
		return "HOM";
	case KEY_END:
		return "END";
	case KEY_IC:
		return "INS";
	case KEY_DC:
		return "DEL";
	case KEY_PPAGE:
		return "PgU";
	case KEY_NPAGE:
		return "PgD";
	default:
		break;
	}
	if (key >= KEY_F(1) && key <= KEY_F(12)) {
		snprintf(buf, sizeof(buf), "KEY_F(%d)", key - KEY_F(0));
		return buf;
	}
	if (key >= 1 && key < 32) {
		snprintf(buf, sizeof(buf), "^%c", key + '@');
		return buf;
	}
	if (key >= 32 && key < 127) {
		snprintf(buf, sizeof(buf), "%c", key);
		return buf;
	}
	return NULL;
}

/* Short key name as shown in the status bar. */
const char *keys_int2sbstr(int key)
{
	if (key == KEY_BTAB)
		return "...";
	return keys_int2str(key);
}

int keys_action_count_keys(enum vkey action)
{
	return llist_count(&keys[action]);
}

const char *keys_action_firstkey(enum vkey action)
{
	llist_item_t *i = LLIST_FIRST(&keys[action]);
	if (!i)
		return NULL;
	return keys_int2str(((struct keystr *)LLIST_GET_DATA(i))->key);
}

const char *keys_action_firstkey_sb(enum vkey action)
{
	llist_item_t *i = LLIST_FIRST(&keys[action]);
	if (!i)
		return "?";
	return keys_int2sbstr(((struct keystr *)LLIST_GET_DATA(i))->key);
}

const char *keys_action_nkey(enum vkey action, int n)
{
	llist_item_t *i = LLIST_NTH(&keys[action], n);
	if (!i)
		return NULL;
	return keys_int2str(((struct keystr *)LLIST_GET_DATA(i))->key);
}

char *keys_action_allkeys(enum vkey action)
{
	llist_item_t *i;
	char *res = mem_strdup("");
	LLIST_FOREACH(&keys[action], i) {
		const char *k = keys_int2str(((struct keystr *)LLIST_GET_DATA(i))->key);
		char *tmp = strdup_printf("%s%s%s", res, *res ? " " : "", k ? k : "?");
		mem_free(res);
		res = tmp;
	}
	return res;
}

/* Assign default bindings for actions that have none. */
void keys_fill_missing(void)
{
	int i;
	for (i = 0; i < NBVKEYS; i++) {
		if (LLIST_FIRST(&keys[i]))
			continue;
		{
			char *buf = mem_strdup(keydef[i].binding), *p, *sv = NULL;
			for (p = strtok_r(buf, " ", &sv); p; p = strtok_r(NULL, " ", &sv)) {
				int k = keys_str2int(p);
				if (k >= 0)
					keys_assign_binding(k, i);
			}
			mem_free(buf);
		}
	}
}

void keys_save_bindings(FILE *fd)
{
	int i;
	llist_item_t *j;

	fputs("#\n# Calcurse keys configuration file\n#\n", fd);
	fputs("# In this file the keybindings used by Calcurse are defined.\n", fd);
	fputs("# It is generated automatically by Calcurse and is maintained\n", fd);
	fputs("# via the key configuration menu of the interactive user\n", fd);
	fputs("# interface. It should not be edited directly.\n\n", fd);
	for (i = 0; i < NBVKEYS; i++) {
		fprintf(fd, "%s ", keydef[i].label);
		LLIST_FOREACH(&keys[i], j) {
			const char *k = keys_int2str(((struct keystr *)LLIST_GET_DATA(j))->key);
			fprintf(fd, " %s", k ? k : "?");
		}
		fputc('\n', fd);
	}
}

int keys_check_missing_bindings(void)
{
	int i;
	for (i = 0; i < NBVKEYS; i++) {
		if (!LLIST_FIRST(&keys[i]))
			return 1;
	}
	return 0;
}

/*
 * Load the key bindings file.  Returns the number of unknown or
 * duplicate bindings (0 if everything was fine), -1 if the file could
 * not be read.
 */
int keys_load_bindings(void)
{
	FILE *fd;
	char buf[BUFSIZ_LINE * 4], *p, *sv = NULL, *label;
	int i, errors = 0;

	fd = fopen(path_keys, "r");
	if (!fd)
		return -1;
