static void wins_init_panels(void)
{
	int i;
	for (i = 0; i < NBWINS; i++) {
		win[i].p = NULL;
		win[i].w = win[i].h = 0;
		win[i].x = win[i].y = 0;
	}
}

/* Compute panel geometry from the layout. */
void wins_get_config(void)
{
	int sbw = wins_sbar_width();
	int calh = 12;
	int nbh = conf.notify_bar ? 1 : 0;
	int stah = 2;	/* status bar height */
	int panh;
	struct window *big, *top, *bottom;

	panh = row - nbh - stah;
	if (panh < 0)
		panh = 0;
	win[STA].h = stah;
	win[STA].w = col;
	win[STA].x = 0;
	win[STA].y = row - stah;
	win[NOT].h = nbh;
	win[NOT].w = col;
	win[NOT].x = 0;
	win[NOT].y = row - stah - nbh;

	switch (layout) {
	case 1: big = &win[APP]; top = &win[CAL]; bottom = &win[TOD]; break;
	case 2: big = &win[APP]; top = &win[CAL]; bottom = &win[TOD]; break;
	case 3: big = &win[TOD]; top = &win[CAL]; bottom = &win[APP]; break;
	case 4: big = &win[TOD]; top = &win[CAL]; bottom = &win[APP]; break;
	case 5: big = &win[APP]; top = &win[TOD]; bottom = &win[CAL]; break;
	case 6: big = &win[APP]; top = &win[TOD]; bottom = &win[CAL]; break;
	case 7: big = &win[TOD]; top = &win[APP]; bottom = &win[CAL]; break;
	case 8: big = &win[TOD]; top = &win[APP]; bottom = &win[CAL]; break;
	default: big = &win[APP]; top = &win[CAL]; bottom = &win[TOD]; break;
	}

	big->h = panh;
	big->w = col - sbw;
	big->y = 0;
	if (layout % 2 == 1) {
		big->x = 0;
		top->x = bottom->x = col - sbw;
	} else {
		big->x = sbw;
		top->x = bottom->x = 0;
	}
	top->w = bottom->w = sbw;
	top->y = 0;
	if (&win[CAL] == top) {
		top->h = calh;
	} else {
		top->h = panh - calh;
	}
	if (top->h > panh)
		top->h = panh;
	bottom->y = top->h;
	bottom->h = panh - top->h;
}

static void wins_create(void)
{
	int i;
	for (i = 0; i < NBWINS; i++) {
		if (win[i].p) {
			delwin(win[i].p);
			win[i].p = NULL;
		}
		if (i == NOT && !conf.notify_bar)
			continue;
		if (win[i].h <= 0 || win[i].w <= 0)
			continue;
		win[i].p = newwin(win[i].h, win[i].w, win[i].y, win[i].x);
	}
}

