static const char *panel_label(int i)
{
	switch (i) {
	case CAL:
		return _("Calendar");
	case APP:
		return _("Appointments");
	case TOD:
		return _("TODO");
	default:
		return "";
	}
}

/* Draw the border of a panel, highlighted if selected. */
void wins_update_border(int flags)
{
	int i;
	for (i = 0; i < NBWINS; i++) {
		if (!(flags & (1 << i)))
			continue;
		if (i != CAL && i != APP && i != TOD)
			continue;
		if (!win[i].p)
			continue;
		if (i == slctd_win)
			custom_apply_attr(win[i].p, ATTR_HIGHEST);
		else
			custom_remove_attr(win[i].p, ATTR_HIGHEST);
		box(win[i].p, 0, 0);
		mvwaddch(win[i].p, 2, 0, ACS_LTEE);
		mvwhline(win[i].p, 2, 1, ACS_HLINE, win[i].w - 2);
		mvwaddch(win[i].p, 2, win[i].w - 1, ACS_RTEE);
		if (i == slctd_win)
			custom_remove_attr(win[i].p, ATTR_HIGHEST);
		if (!conf.compact_panels) {
			int len = string_width(panel_label(i));
			custom_apply_attr(win[i].p, ATTR_HIGHEST);
			mvwaddstr(win[i].p, 1, ((int)win[i].w - len) / 2, panel_label(i));
			custom_remove_attr(win[i].p, ATTR_HIGHEST);
		}
	}
}

