/*
 * Display a page of key bindings in the status bar window.
 */
void keys_display_bindings_bar(WINDOW *w, int *bindings, int count, int page_base, int page_size)
{
	int i, n = 0;
	int items;
	int cmdlen;
	extern const char *keys_action_firstkey_sb(enum vkey);
	extern const char *keys_get_sb_label(enum vkey);

	if (!w)
		return;
	werase(w);

	items = count - page_base;
	if (items > page_size)
		items = page_size;
	/* Number of entries on this page, including OtherCmd if there are more. */
	n = items;
	if (page_base + items < count)
		n++;
	if (n <= 0)
		return;
	cmdlen = (int)win[STA].w * 2 / n;
	if (cmdlen < 1)
		cmdlen = 1;

	for (i = 0; i < n; i++) {
		int key;
		const char *keystr, *label;
		int x, y;
		if (i < items) {
			key = bindings[page_base + i];
		} else {
			key = KEY_GENERIC_OTHER_CMD;
		}
		keystr = keys_action_firstkey_sb(key);
		label = keys_get_sb_label(key);
		x = (i / 2) * cmdlen;
		y = i % 2;
		{
			int klen = (int)strlen(keystr);
			int kx = x + KEYS_KEYLEN - klen;
			if (kx < x)
				kx = x;
			custom_apply_attr(w, ATTR_HIGHEST);
			mvwaddstr(w, y, kx, keystr);
			custom_remove_attr(w, ATTR_HIGHEST);
			mvwaddstr(w, y, x + KEYS_KEYLEN + 1, label);
		}
	}
	wnoutrefresh(w);
}

void wins_status_bar(void)
{
	int n;
	int *keys = sbar_keys(&n);
	int pages = sbar_nb_pages(n);
	if (status_page >= pages)
		status_page = 0;
	keys_display_bindings_bar(win[STA].p, keys, n, status_page * SBAR_ITEMS, SBAR_ITEMS);
}

void wins_status_bar_keys(int *keys, int n, int page)
{
	keys_display_bindings_bar(win[STA].p, keys, n, page * SBAR_ITEMS, SBAR_ITEMS);
}

/* Leave curses mode to run an external program. */
void wins_prepare_external(void)
{
	if (notify_bar())
		notify_stop_main_thread();
	def_prog_mode();
	ui_mode = UI_CMDLINE;
	clear();
	wins_wrefresh(stdscr);
	wrefresh(stdscr);
	endwin();
}

void wins_unprepare_external(void)
{
	reset_prog_mode();
	clearok(curscr, TRUE);
	ui_mode = UI_CURSES;
	if (notify_bar())
		notify_start_main_thread();
	wins_reinit();
	ui_refresh_all();
}

void wins_launch_external(const char *const *arg)
{
	int pid;
	wins_prepare_external();
	if ((pid = shell_exec(NULL, NULL, NULL, *arg, arg)))
		child_wait(NULL, NULL, NULL, pid);
	wins_unprepare_external();
}

/* ---- scroll windows ---- */

void wins_scrollwin_init(struct scrollwin *sw, int y, int x, int h, int w, const char *label)
{
	sw->win.y = y;
	sw->win.x = x;
	sw->win.h = h;
	sw->win.w = w;
	sw->win.p = newwin(h, w, y, x);
	sw->inner_w = w - 2;
	sw->inner_h = h - 3;
	sw->line_off = 0;
	sw->line_num = 0;
	sw->inner = newpad(1, sw->inner_w > 0 ? sw->inner_w : 1);
	sw->label = label;
	keypad(sw->win.p, TRUE);
}

void wins_scrollwin_resize(struct scrollwin *sw, int y, int x, int h, int w)
{
	if (sw->win.p)
		delwin(sw->win.p);
	sw->win.y = y;
	sw->win.x = x;
	sw->win.h = h;
	sw->win.w = w;
	sw->win.p = newwin(h, w, y, x);
	sw->inner_w = w - 2;
	sw->inner_h = h - 3;
	keypad(sw->win.p, TRUE);
	wins_scrollwin_set_linecount(sw, sw->line_num);
}

void wins_scrollwin_set_linecount(struct scrollwin *sw, unsigned lines)
{
	sw->line_num = lines;
	if (sw->inner)
		delwin(sw->inner);
	sw->inner = newpad(lines > 0 ? lines : 1, sw->inner_w > 0 ? sw->inner_w : 1);
}

void wins_scrollwin_delete(struct scrollwin *sw)
{
	if (sw->win.p) {
		delwin(sw->win.p);
		sw->win.p = NULL;
	}
	if (sw->inner) {
		delwin(sw->inner);
		sw->inner = NULL;
	}
}

void wins_scrollwin_draw_deco(struct scrollwin *sw, int hilt)
{
	if (hilt)
		custom_apply_attr(sw->win.p, ATTR_HIGHEST);
	box(sw->win.p, 0, 0);
	mvwaddch(sw->win.p, 2, 0, ACS_LTEE);
	mvwhline(sw->win.p, 2, 1, ACS_HLINE, sw->win.w - 2);
	mvwaddch(sw->win.p, 2, sw->win.w - 1, ACS_RTEE);
	if (hilt)
		custom_remove_attr(sw->win.p, ATTR_HIGHEST);
	if (sw->label && !conf.compact_panels) {
		int len = string_width(sw->label);
		custom_apply_attr(sw->win.p, ATTR_HIGHEST);
		mvwaddstr(sw->win.p, 1, ((int)sw->win.w - len) / 2, sw->label);
		custom_remove_attr(sw->win.p, ATTR_HIGHEST);
	}
}

void wins_scrollwin_display(struct scrollwin *sw, int hilt)
{
	int inner_y = 3, inner_x = 1;
	int h = sw->inner_h, w = sw->inner_w;

	if (conf.compact_panels) {
		inner_y = 1;
		h = sw->win.h - 2;
	}
	if (sw->line_num > (unsigned)h) {
		/* scroll bar */
		float ratio = (float)h / (float)sw->line_num;
		int sbar_h = (int)(ratio * h);
		int sbar_y = inner_y + (int)(ratio * sw->line_off);
		int sbar_x = sw->win.w - 1;
		if (sbar_h < 1)
			sbar_h = 1;
		if (sbar_y + sbar_h > inner_y + h)
			sbar_y = inner_y + h - sbar_h;
		if (hilt)
			custom_apply_attr(sw->win.p, ATTR_HIGHEST);
		mvwvline(sw->win.p, inner_y, sbar_x, ACS_VLINE, h);
		if (hilt)
			custom_remove_attr(sw->win.p, ATTR_HIGHEST);
		custom_apply_attr(sw->win.p, ATTR_HIGHEST);
		mvwvline(sw->win.p, sbar_y, sbar_x, ' ' | A_REVERSE, sbar_h);
		custom_remove_attr(sw->win.p, ATTR_HIGHEST);
	}
	wnoutrefresh(sw->win.p);
	if (sw->inner && h > 0 && w > 0) {
		int maxrow = sw->win.y + inner_y + h - 1;
		int maxcol = sw->win.x + inner_x + w - 1;
		pnoutrefresh(sw->inner, sw->line_off, 0, sw->win.y + inner_y, sw->win.x + inner_x, maxrow, maxcol);
	}
}

void wins_scrollwin_up(struct scrollwin *sw, int amount)
{
	if ((int)sw->line_off - amount < 0)
		sw->line_off = 0;
	else
		sw->line_off -= amount;
}

void wins_scrollwin_down(struct scrollwin *sw, int amount)
{
	int h = conf.compact_panels ? (int)sw->win.h - 2 : (int)sw->inner_h;
	if ((int)sw->line_num <= h)
		return;
	if (sw->line_off + amount > sw->line_num - h)
		sw->line_off = sw->line_num - h;
	else
		sw->line_off += amount;
}

int wins_scrollwin_is_visible(struct scrollwin *sw, unsigned line)
{
	int h = conf.compact_panels ? (int)sw->win.h - 2 : (int)sw->inner_h;
	return line >= sw->line_off && line < sw->line_off + (unsigned)h;
}

void wins_scrollwin_ensure_visible(struct scrollwin *sw, unsigned line)
{
	int h = conf.compact_panels ? (int)sw->win.h - 2 : (int)sw->inner_h;
	if (h <= 0)
		return;
	if (line < sw->line_off)
		sw->line_off = line;
	else if (line >= sw->line_off + (unsigned)h)
		sw->line_off = line - h + 1;
}

void wins_scrollwin_set_lower(struct scrollwin *sw, unsigned line)
{
	int h = conf.compact_panels ? (int)sw->win.h - 2 : (int)sw->inner_h;
	if (h <= 0)
		return;
	if (line + 1 >= (unsigned)h)
		sw->line_off = line + 1 - h;
	else
		sw->line_off = 0;
}
