	box(w, 0, 0);
	mvwaddch(w, 2, 0, ACS_LTEE);
	mvwhline(w, 2, 1, ACS_HLINE, width - 2);
	mvwaddch(w, 2, width - 1, ACS_RTEE);
	len = string_width(label);
	custom_apply_attr(w, ATTR_HIGHEST);
	mvwaddstr(w, 1, (width - len) / 2, label);
	custom_remove_attr(w, ATTR_HIGHEST);
}

static const char *panel_label(int i)
