		delwin(sw->win.p);
	sw->win.y = y;
	sw->win.x = x;
	sw->win.h = h;
	sw->win.w = w;
	sw->win.p = newwin(h, w, y, x);
	sw->inner_w = w - 2;
	sw->inner_h = h - 3;
	keypad(sw->win.p, TRUE);
	wins_scrollwin_set_linecount(sw, sw->line_num);
}

void wins_scrollwin_set_linecount(struct scrollwin *sw, unsigned lines)
{
	sw->line_num = lines;
	if (sw->inner)
		delwin(sw->inner);
	sw->inner = newpad(lines > 0 ? lines : 1, sw->inner_w > 0 ? sw->inner_w : 1);
}

void wins_scrollwin_delete(struct scrollwin *sw)
{
	if (sw->win.p) {
		delwin(sw->win.p);
		sw->win.p = NULL;
	}
	if (sw->inner) {
		delwin(sw->inner);
		sw->inner = NULL;
	}
}

void wins_scrollwin_draw_deco(struct scrollwin *sw, int hilt)
{
	if (hilt)
		custom_apply_attr(sw->win.p, ATTR_HIGHEST);
	box(sw->win.p, 0, 0);
	mvwaddch(sw->win.p, 2, 0, ACS_LTEE);
	mvwhline(sw->win.p, 2, 1, ACS_HLINE, sw->win.w - 2);
	mvwaddch(sw->win.p, 2, sw->win.w - 1, ACS_RTEE);
	if (hilt)
		custom_remove_attr(sw->win.p, ATTR_HIGHEST);
	if (sw->label && !conf.compact_panels) {
		int len = string_width(sw->label);
		custom_apply_attr(sw->win.p, ATTR_HIGHEST);
		mvwaddstr(sw->win.p, 1, ((int)sw->win.w - len) / 2, sw->label);
		custom_remove_attr(sw->win.p, ATTR_HIGHEST);
	}
}

void wins_scrollwin_display(struct scrollwin *sw, int hilt)
{
	int inner_y = 3, inner_x = 1;
	int h = sw->inner_h, w = sw->inner_w;

	if (conf.compact_panels) {
		inner_y = 1;
		h = sw->win.h - 2;
	}
	if (sw->line_num > (unsigned)h) {
		/* scroll bar */
		float ratio = (float)h / (float)sw->line_num;
		int sbar_h = (int)(ratio * h);
		int sbar_y = inner_y + (int)(ratio * sw->line_off);
		int sbar_x = sw->win.w - 1;
		if (sbar_h < 1)
			sbar_h = 1;
		if (sbar_y + sbar_h > inner_y + h)
			sbar_y = inner_y + h - sbar_h;
		if (hilt)
			custom_apply_attr(sw->win.p, ATTR_HIGHEST);
		mvwvline(sw->win.p, inner_y, sbar_x, ACS_VLINE, h);
		if (hilt)
			custom_remove_attr(sw->win.p, ATTR_HIGHEST);
		custom_apply_attr(sw->win.p, ATTR_HIGHEST);
		mvwvline(sw->win.p, sbar_y, sbar_x, ' ' | A_REVERSE, sbar_h);
		custom_remove_attr(sw->win.p, ATTR_HIGHEST);
	}
	wnoutrefresh(sw->win.p);
	if (sw->inner && h > 0 && w > 0) {
		int maxrow = sw->win.y + inner_y + h - 1;
		int maxcol = sw->win.x + inner_x + w - 1;
		pnoutrefresh(sw->inner, sw->line_off, 0, sw->win.y + inner_y, sw->win.x + inner_x, maxrow, maxcol);
	}
}

void wins_scrollwin_up(struct scrollwin *sw, int amount)
{
	if ((int)sw->line_off - amount < 0)
		sw->line_off = 0;
	else
		sw->line_off -= amount;
}

void wins_scrollwin_down(struct scrollwin *sw, int amount)
{
	int h = conf.compact_panels ? (int)sw->win.h - 2 : (int)sw->inner_h;
	if ((int)sw->line_num <= h)
		return;
	if (sw->line_off + amount > sw->line_num - h)
		sw->line_off = sw->line_num - h;
	else
		sw->line_off += amount;
}

int wins_scrollwin_is_visible(struct scrollwin *sw, unsigned line)
{
	int h = conf.compact_panels ? (int)sw->win.h - 2 : (int)sw->inner_h;
	return line >= sw->line_off && line < sw->line_off + (unsigned)h;
}

void wins_scrollwin_ensure_visible(struct scrollwin *sw, unsigned line)
{
	int h = conf.compact_panels ? (int)sw->win.h - 2 : (int)sw->inner_h;
	if (h <= 0)
		return;
	if (line < sw->line_off)
		sw->line_off = line;
	else if (line >= sw->line_off + (unsigned)h)
		sw->line_off = line - h + 1;
}

void wins_scrollwin_set_lower(struct scrollwin *sw, unsigned line)
{
	int h = conf.compact_panels ? (int)sw->win.h - 2 : (int)sw->inner_h;
	if (h <= 0)
		return;
	if (line + 1 >= (unsigned)h)
		sw->line_off = line + 1 - h;
	else
		sw->line_off = 0;
}
