void ui_calendar_monthly_view_cache_set_invalid(void)
{
}

static int day_has_item(struct date d)
{
	return day_check_if_item(d);
}

/* Draw the monthly view. */
static void draw_monthly_view(WINDOW *cwin, struct date *current_day, int sunday_first)
{
	int ofs_x = ((int)win[CAL].w - 32) / 2;
	int ofs_y = 2;
	int c_day, c_day_1, day_1_sav, numdays, j;
	unsigned yr, mo;
	struct date check_day;
	char ws[32];
	int w = 0;
	struct tm t;
	const char **names = sunday_first ? weekday_names_sun : weekday_names_mon;
	int label_x;
	char label[16];

	mo = slctd_day.mm;
	yr = slctd_day.yyyy;

	/* day of year label */
	{
		time_t ts = date2sec(slctd_day, 0, 0);
		localtime_r_safe(ts, &t);
		snprintf(label, sizeof(label), "(#%3d)", t.tm_yday + 1);
	}
	label_x = (int)win[CAL].w - 2 - (int)strlen(label);
	custom_apply_attr(cwin, ATTR_HIGHEST);
	mvwaddstr(cwin, ofs_y, label_x, label);
	custom_remove_attr(cwin, ATTR_HIGHEST);

	/* Month and year */
	snprintf(ws, sizeof(ws), "%s %u", monthnames[mo - 1], yr);
	w = strlen(ws);
	custom_apply_attr(cwin, ATTR_HIGHEST);
	mvwaddstr(cwin, ofs_y + 1, ofs_x + (32 - w) / 2, ws);
	custom_remove_attr(cwin, ATTR_HIGHEST);

	/* Weekday names */
	for (j = 0; j < 7; j++) {
		custom_apply_attr(cwin, ATTR_HIGHEST);
		mvwaddstr(cwin, ofs_y + 2, ofs_x + 4 + 4 * j, names[j]);
		custom_remove_attr(cwin, ATTR_HIGHEST);
	}

	numdays = month_days(mo, yr);
	/* weekday of the first day of the month */
	check_day.dd = 1;
	check_day.mm = mo;
	check_day.yyyy = yr;
	c_day_1 = ui_calendar_get_wday(&check_day);	/* 0 = Sunday */
	if (!sunday_first)
		c_day_1 = (c_day_1 + 6) % 7;	/* 0 = Monday */
	day_1_sav = c_day_1;

	/* Days of the previous month shown in the first week. */
	{
		int prev_mo = mo == 1 ? 12 : mo - 1;
		int prev_yr = mo == 1 ? yr - 1 : yr;
		int prev_days = month_days(prev_mo, prev_yr);
		int line = 0, colx;
		struct date d;
		int wn_line = -1;

		/* week number for first line */
		for (j = 0; j < c_day_1; j++) {
			d.dd = prev_days - c_day_1 + 1 + j;
			d.mm = prev_mo;
			d.yyyy = prev_yr;
			if (j == 0) {
				unsigned wn = ui_calendar_get_week_number(&d);
				custom_apply_attr(cwin, ATTR_HIGHEST);
				mvwprintw(cwin, ofs_y + 3, ofs_x + 1, "%2u", wn);
				custom_remove_attr(cwin, ATTR_HIGHEST);
				wn_line = 0;
			}
			colx = ofs_x + 4 + 4 * j;
			if (day_has_item(d))
				custom_apply_attr(cwin, ATTR_TRUE);
			mvwprintw(cwin, ofs_y + 3, colx, "%3d ", d.dd);
			if (day_has_item(d))
				custom_remove_attr(cwin, ATTR_TRUE);
		}

		for (c_day = 1; c_day <= numdays; c_day++, c_day_1++) {
			int is_today, is_selected, has_item;
			if (c_day_1 == 7) {
				c_day_1 = 0;
				line++;
			}
			d.dd = c_day;
			d.mm = mo;
			d.yyyy = yr;
			if (c_day_1 == 0 || c_day == 1) {
				if (wn_line != line) {
					unsigned wn = ui_calendar_get_week_number(&d);
					custom_apply_attr(cwin, ATTR_HIGHEST);
					mvwprintw(cwin, ofs_y + 3 + line, ofs_x + 1, "%2u", wn);
					custom_remove_attr(cwin, ATTR_HIGHEST);
					wn_line = line;
				}
			}
			colx = ofs_x + 4 + 4 * c_day_1;
			is_today = (current_day->dd == d.dd && current_day->mm == d.mm && current_day->yyyy == d.yyyy);
			is_selected = (slctd_day.dd == d.dd && slctd_day.mm == d.mm && slctd_day.yyyy == d.yyyy);
			has_item = day_has_item(d);
			if (is_selected) {
				custom_apply_attr(cwin, ATTR_HIGHEST);
				wattron(cwin, A_BOLD);
				mvwaddch(cwin, ofs_y + 3 + line, colx, '[');
				wattroff(cwin, A_BOLD);
				custom_remove_attr(cwin, ATTR_HIGHEST);
				if (is_today)
					custom_apply_attr(cwin, ATTR_LOWEST);
				else if (has_item)
					custom_apply_attr(cwin, ATTR_TRUE);
				mvwprintw(cwin, ofs_y + 3 + line, colx + 1, "%2d", c_day);
				if (is_today)
					custom_remove_attr(cwin, ATTR_LOWEST);
				else if (has_item)
					custom_remove_attr(cwin, ATTR_TRUE);
				custom_apply_attr(cwin, ATTR_HIGHEST);
				wattron(cwin, A_BOLD);
				mvwaddch(cwin, ofs_y + 3 + line, colx + 3, ']');
				wattroff(cwin, A_BOLD);
				custom_remove_attr(cwin, ATTR_HIGHEST);
			} else {
				if (is_today)
					custom_apply_attr(cwin, ATTR_LOWEST);
				else if (has_item)
					custom_apply_attr(cwin, ATTR_TRUE);
				mvwprintw(cwin, ofs_y + 3 + line, colx, "%3d ", c_day);
				if (is_today)
					custom_remove_attr(cwin, ATTR_LOWEST);
				else if (has_item)
					custom_remove_attr(cwin, ATTR_TRUE);
			}
		}
		/* Days of the next month. */
		{
			int next_mo = mo == 12 ? 1 : mo + 1;
			int next_yr = mo == 12 ? yr + 1 : yr;
			int nd = 1;
			for (j = c_day_1; j < 7 && c_day_1 != 0; j++, nd++) {
				d.dd = nd;
				d.mm = next_mo;
				d.yyyy = next_yr;
				colx = ofs_x + 4 + 4 * j;
				if (day_has_item(d))
					custom_apply_attr(cwin, ATTR_TRUE);
				mvwprintw(cwin, ofs_y + 3 + line, colx, "%3d ", nd);
				if (day_has_item(d))
					custom_remove_attr(cwin, ATTR_TRUE);
			}
		}
		(void)day_1_sav;
	}
}

#define WEEKINDAYS_C 7
#define SLICESNO 6

/* Draw the weekly view. */
static void draw_weekly_view(WINDOW *cwin, struct date *current_day, int sunday_first)
{
	int ofs_x = ((int)win[CAL].w - 32) / 2;
	int ofs_y = 2;
	int j, wday;
	time_t t;
	struct date d, monday;
	const char **names = sunday_first ? weekday_names_sun : weekday_names_mon;
	char label[16];
	int label_x;
	int slices[SLICESNO];
	int i;

	/* week number */
	{
		unsigned wn = ui_calendar_get_week_number(&slctd_day);
		snprintf(label, sizeof(label), "(#%3u)", wn);
	}
	label_x = (int)win[CAL].w - 2 - (int)strlen(label);
	custom_apply_attr(cwin, ATTR_HIGHEST);
	mvwaddstr(cwin, ofs_y, label_x, label);
	custom_remove_attr(cwin, ATTR_HIGHEST);

	/* Weekday names */
	for (j = 0; j < 7; j++) {
		custom_apply_attr(cwin, ATTR_HIGHEST);
		mvwaddstr(cwin, ofs_y + 1, ofs_x + 2 + 4 * j, names[j]);
		custom_remove_attr(cwin, ATTR_HIGHEST);
	}

	/* first day of the week */
	wday = ui_calendar_get_wday(&slctd_day);
	t = date2sec(slctd_day, 0, 0);
	if (sunday_first)
		t = date_sec_change(t, 0, -wday);
	else
		t = date_sec_change(t, 0, -((wday + 6) % 7));
	{
		struct tm tm;
		localtime_r_safe(t, &tm);
		monday.dd = tm.tm_mday;
		monday.mm = tm.tm_mon + 1;
		monday.yyyy = tm.tm_year + TM_YEAR_BASE;
	}

	for (j = 0; j < 7; j++) {
		int is_today, is_selected, has_item;
		time_t td = date_sec_change(t, 0, j);
		struct tm tm;
		localtime_r_safe(td, &tm);
		d.dd = tm.tm_mday;
		d.mm = tm.tm_mon + 1;
		d.yyyy = tm.tm_year + TM_YEAR_BASE;
		is_today = (current_day->dd == d.dd && current_day->mm == d.mm && current_day->yyyy == d.yyyy);
		is_selected = (slctd_day.dd == d.dd && slctd_day.mm == d.mm && slctd_day.yyyy == d.yyyy);
		has_item = day_has_item(d);
		if (is_selected) {
			custom_apply_attr(cwin, ATTR_HIGHEST);
			wattron(cwin, A_BOLD);
		} else if (is_today) {
			custom_apply_attr(cwin, ATTR_LOWEST);
		} else if (has_item) {
			custom_apply_attr(cwin, ATTR_LOW);
		}
		mvwprintw(cwin, ofs_y + 2, ofs_x + 3 + 4 * j, "%02d", d.dd);
		if (is_selected) {
			wattroff(cwin, A_BOLD);
			custom_remove_attr(cwin, ATTR_HIGHEST);
		} else if (is_today) {
			custom_remove_attr(cwin, ATTR_LOWEST);
		} else if (has_item) {
			custom_remove_attr(cwin, ATTR_LOW);
		}

		/* busy slices */
		memset(slices, 0, sizeof(slices));
		day_chk_busy_slices(d, SLICESNO, slices);
		for (i = 0; i < SLICESNO; i++) {
			int y = ofs_y + 3 + i;
			if (slices[i]) {
				if (is_selected) {
					custom_apply_attr(cwin, ATTR_HIGHEST);
					wattron(cwin, A_BOLD | A_REVERSE);
				} else {
					wattron(cwin, A_REVERSE);
				}
				mvwaddstr(cwin, y, ofs_x + 3 + 4 * j, "  ");
				if (is_selected) {
					wattroff(cwin, A_BOLD | A_REVERSE);
					custom_remove_attr(cwin, ATTR_HIGHEST);
				} else {
					wattroff(cwin, A_REVERSE);
				}
			}
			if (i < SLICESNO - 1 && j < 6)
				mvwaddstr(cwin, y, ofs_x + 5 + 4 * j, "__");
		}
	}
	/* midday markers */
	custom_apply_attr(cwin, ATTR_HIGHEST);
	mvwaddch(cwin, ofs_y + 3 + 2, ofs_x + 2, '<');
	mvwaddch(cwin, ofs_y + 3 + 2, ofs_x + 29, '>');
	custom_remove_attr(cwin, ATTR_HIGHEST);
	(void)monday;
}

void ui_calendar_update_panel(void)
{
	WINDOW *cwin = win[CAL].p;
	struct date current_day;
	int sunday_first = !week_begins_on_monday;
	int y, x;
	int inner_y = conf.compact_panels ? 1 : 3;

	if (!cwin)
		return;
	date_from_time(get_today(), &current_day);
	/* clear the inner area */
	for (y = inner_y; y < (int)win[CAL].h - 1; y++) {
		for (x = 1; x < (int)win[CAL].w - 1; x++)
			mvwaddch(cwin, y, x, ' ');
	}
	if (calendar_view == CAL_WEEK_VIEW)
		draw_weekly_view(cwin, &current_day, sunday_first);
	else
		draw_monthly_view(cwin, &current_day, sunday_first);
	wnoutrefresh(cwin);
}

time_t ui_calendar_start_of_year(void)
{
	struct date d = { 1, 1, slctd_day.yyyy };
	return date2sec(d, 0, 0);
}

time_t ui_calendar_end_of_year(void)
{
	struct date d = { 1, 1, slctd_day.yyyy + 1 };
	return date2sec(d, 0, 0) - 1;
}
EOF
echo ok"}

