void ui_calendar_set_slctd_day(struct date day)
{
	slctd_day = day;
}

void ui_calendar_goto_today(void)
{
	ui_calendar_set_current_date();
}

/* Weekday of a date (0 = Sunday). */
int ui_calendar_get_wday(struct date *d)
{
	return wday_of(date2sec(*d, 0, 0));
}

/* ISO-like week number as shown in the calendar. */
unsigned ui_calendar_get_week_number(struct date *d)
{
	struct tm tm;
	char buf[8];
	time_t t = date2sec(*d, 0, 0);
	localtime_r_safe(t, &tm);
	strftime(buf, sizeof(buf), week_begins_on_monday ? "%V" : "%U", &tm);
	return (unsigned)atoi(buf);
}

/* Change the selected day by a number of days. */
void ui_calendar_change_day(int days)
{
	time_t t = date_sec_change(date2sec(slctd_day, 0, 0), 0, days);
	date_from_time(t, &slctd_day);
}

static void ui_calendar_change_month(int months)
{
	struct tm tm;
	time_t t;
	int ndays;
	memset(&tm, 0, sizeof(tm));
	tm.tm_year = slctd_day.yyyy - TM_YEAR_BASE;
	tm.tm_mon = slctd_day.mm - 1 + months;
	tm.tm_mday = 1;
	tm.tm_isdst = -1;
	t = mktime(&tm);
	localtime_r_safe(t, &tm);
	ndays = month_days(tm.tm_mon + 1, tm.tm_year + TM_YEAR_BASE);
	slctd_day.yyyy = tm.tm_year + TM_YEAR_BASE;
	slctd_day.mm = tm.tm_mon + 1;
	if ((int)slctd_day.dd > ndays)
		slctd_day.dd = ndays;
}

/*
 * Move the selection in the calendar.
 */
void ui_calendar_move(int move, int count)
{
	int wday;
	switch (move) {
	case CAL_UP:
		ui_calendar_change_day(-7 * count);
		break;
	case CAL_DOWN:
		ui_calendar_change_day(7 * count);
		break;
	case CAL_LEFT:
		ui_calendar_change_day(-count);
		break;
	case CAL_RIGHT:
		ui_calendar_change_day(count);
		break;
	case CAL_WEEK_START:
		wday = ui_calendar_get_wday(&slctd_day);
		if (week_begins_on_monday)
			ui_calendar_change_day(-((wday + 6) % 7));
		else
			ui_calendar_change_day(-wday);
		break;
	case CAL_WEEK_END:
		wday = ui_calendar_get_wday(&slctd_day);
		if (week_begins_on_monday)
			ui_calendar_change_day(6 - ((wday + 6) % 7));
		else
			ui_calendar_change_day(6 - wday);
		break;
	default:
		break;
	}
	(void)ui_calendar_change_month;
}

void ui_calendar_monthly_view_cache_set_invalid(void)
