#include "ui.h"

/*
 * The appointment panel shows a range of days starting at day_first.
 * For every day the items are stored in a per-day list.
 */

enum line_type {
	L_HEADING,
	L_EVENT,
	L_APT_TIME,
	L_APT_MESG,
	L_APT_EMPTY,
	L_EMPTY_DAY,
	L_BLANK,
	L_HLINE
};

struct pline {
	enum line_type type;
	int dayidx;		/* index into days[] */
	int itemidx;		/* index into the day's items, or -1 */
};

struct pday {
	time_t date;
	struct day_item *items;
	int nitems;
};

static struct pday *days = NULL;
static int ndays = 0;
static struct pline *lines = NULL;
static int nlines = 0;

static time_t day_first = 0;
static int sel_dayidx = 0;		/* index of selected day in days[] */
static int sel_item = 0;		/* selected item within the day (0 if empty day) */
static unsigned line_off = 0;		/* scroll offset */
static int cut_item_set = 0;

static struct day_item cut_item;	/* copied / cut item */
static int have_cut = 0;

void ui_day_cut_set(int v)
{
	cut_item_set = v;
}

int ui_day_cut_get(void)
{
	return cut_item_set;
}

static void days_free(void)
{
	int i;
	for (i = 0; i < ndays; i++)
		mem_free(days[i].items);
	mem_free(days);
	days = NULL;
	ndays = 0;
	mem_free(lines);
	lines = NULL;
	nlines = 0;
}

static int inner_height(void)
{
	int h = conf.compact_panels ? (int)win[APP].h - 2 : (int)win[APP].h - 4;
	return h < 0 ? 0 : h;
}

static int inner_width(void)
{
	return (int)win[APP].w - 2;
}

/* Load the items of one day into a pday. */
static void load_day(struct pday *pd, time_t date)
{
	llist_item_t *i;
	int n = 0, k = 0;

	pd->date = date;
	day_store_items(date, 0, 0);
	LLIST_FOREACH(&day_items, i)
		n++;
	pd->nitems = n;
	pd->items = n ? mem_malloc(n * sizeof(struct day_item)) : NULL;
	LLIST_FOREACH(&day_items, i) {
		struct day_item *d = LLIST_GET_DATA(i);
		pd->items[k++] = *d;
	}
}

static void add_line(enum line_type t, int dayidx, int itemidx)
{
	lines = mem_realloc(lines, nlines + 1, sizeof(struct pline));
	lines[nlines].type = t;
	lines[nlines].dayidx = dayidx;
	lines[nlines].itemidx = itemidx;
	nlines++;
}

static int is_event(struct day_item *d)
{
	return d->type == EVNT || d->type == RECUR_EVNT;
}

/* Build the line list for all loaded days. */
static void build_lines(void)
{
	int d, j;
	mem_free(lines);
	lines = NULL;
	nlines = 0;
	for (d = 0; d < ndays; d++) {
		struct pday *pd = &days[d];
		int nev = 0, napt = 0;
		if (conf.multiple_days)
			add_line(L_HEADING, d, -1);
		for (j = 0; j < pd->nitems; j++) {
			if (is_event(&pd->items[j]))
				nev++;
			else
				napt++;
		}
		for (j = 0; j < pd->nitems; j++) {
			if (is_event(&pd->items[j]))
				add_line(L_EVENT, d, j);
		}
		if (nev && napt && conf.event_separator)
			add_line(L_BLANK, d, -1);
		for (j = 0; j < pd->nitems; j++) {
			if (!is_event(&pd->items[j])) {
				add_line(L_APT_TIME, d, j);
				add_line(L_APT_MESG, d, j);
				if (conf.empty_appt_line)
					add_line(L_APT_EMPTY, d, j);
			}
		}
		if (pd->nitems == 0) {
			add_line(L_EMPTY_DAY, d, -1);
			if (conf.empty_appt_line && conf.multiple_days)
				add_line(L_BLANK, d, -1);
		}
		if (conf.multiple_days) {
			if (conf.day_separator)
				add_line(L_BLANK, d, -1);
			if (conf.header_line)
				add_line(L_HLINE, d, -1);
		}
	}
}

static void append_day(void)
{
	time_t next;
	if (ndays == 0)
		next = day_first;
	else
		next = date_sec_change(days[ndays - 1].date, 0, 1);
	days = mem_realloc(days, ndays + 1, sizeof(struct pday));
	load_day(&days[ndays], next);
	ndays++;
}

/* Make sure enough days are loaded to fill the window and include the selection. */
static void fill_days(void)
{
	int h = inner_height();
	int guard = 0;
	if (!conf.multiple_days) {
		build_lines();
		return;
	}
	build_lines();
	while ((nlines < h || ndays <= sel_dayidx) && guard++ < 1000) {
		append_day();
		build_lines();
	}
}

/*
 * Reload the panel with the selected day as the first day.
 */
void ui_day_load_items(void)
{
	days_free();
	day_first = ui_calendar_get_slctd_day_sec();
	sel_dayidx = 0;
	append_day();
	fill_days();
	line_off = 0;
	if (sel_item >= days[0].nitems)
		sel_item = days[0].nitems > 0 ? days[0].nitems - 1 : 0;
	if (sel_item < 0)
		sel_item = 0;
}

void ui_day_sel_reset(void)
{
	sel_item = 0;
	sel_dayidx = 0;
	line_off = 0;
}

/* Find the lines of the selected item: first and last line indices. */
static int sel_lines(int *first, int *last)
{
	int i;
	*first = -1;
	*last = -1;
	for (i = 0; i < nlines; i++) {
		struct pline *l = &lines[i];
		if (l->dayidx != sel_dayidx)
			continue;
		if (days[sel_dayidx].nitems == 0) {
			if (l->type == L_EMPTY_DAY) {
				*first = *last = i;
				return 1;
			}
			continue;
		}
		if (l->itemidx != sel_item)
			continue;
		if (l->type == L_EVENT) {
			*first = *last = i;
			return 1;
		}
		if (l->type == L_APT_TIME && *first < 0)
			*first = i;
		if (l->type == L_APT_TIME || l->type == L_APT_MESG || l->type == L_APT_EMPTY)
			*last = i;
	}
	return *first >= 0;
}

static void ensure_sel_visible(void)
{
	int first, last;
	int h = inner_height();
	if (h <= 0)
		return;
	if (!sel_lines(&first, &last))
		return;
	if ((unsigned)first < line_off)
		line_off = first;
	else if ((unsigned)last >= line_off + h)
		line_off = last - h + 1;
}

static void sync_calendar(void)
{
	struct tm tm;
	struct date d;
	localtime_r_safe(days[sel_dayidx].date, &tm);
	d.dd = tm.tm_mday;
	d.mm = tm.tm_mon + 1;
	d.yyyy = tm.tm_year + TM_YEAR_BASE;
	ui_calendar_set_slctd_day(d);
}

/*
 * Move the selection by delta items (positive: down).  Returns 1 if the
 * selected day changed.
 */
int ui_day_sel_move(int delta)
{
	int changed = 0;
	while (delta > 0) {
		int n = days[sel_dayidx].nitems;
		if (sel_item + 1 < n) {
			sel_item++;
		} else {
			if (!conf.multiple_days) {
				break;
			}
			if (sel_dayidx + 1 >= ndays)
				append_day();
			sel_dayidx++;
			sel_item = 0;
			changed = 1;
		}
		delta--;
	}
	while (delta < 0) {
		if (sel_item > 0) {
			sel_item--;
		} else {
			if (!conf.multiple_days)
				break;
			if (sel_dayidx == 0) {
				/* reload with the previous day first */
				struct date d;
				struct tm tm;
				time_t prev = date_sec_change(day_first, 0, -1);
				localtime_r_safe(prev, &tm);
				d.dd = tm.tm_mday;
				d.mm = tm.tm_mon + 1;
				d.yyyy = tm.tm_year + TM_YEAR_BASE;
				ui_calendar_set_slctd_day(d);
				ui_day_load_items();
				sel_item = days[0].nitems > 0 ? days[0].nitems - 1 : 0;
				changed = 1;
			} else {
				sel_dayidx--;
				sel_item = days[sel_dayidx].nitems > 0 ? days[sel_dayidx].nitems - 1 : 0;
				changed = 1;
			}
		}
		delta++;
	}
	fill_days();
	sync_calendar();
	ensure_sel_visible();
	return changed;
}

/* Jump to the first item of the day (or the day itself). */
void ui_day_sel_daybegin(int n)
{
	(void)n;
	sel_item = 0;
	ensure_sel_visible();
}

void ui_day_sel_dayend(void)
{
	int n = days[sel_dayidx].nitems;
	sel_item = n > 0 ? n - 1 : 0;
	ensure_sel_visible();
}

