/* Format "..:.." aware time strings for an appointment occurrence. */
static void apt_times(time_t day, time_t start, long dur, char *s, char *e)
{
	struct tm tm;
	time_t end = start + dur;
	if (start < day) {
		strcpy(s, "..:..");
	} else {
		localtime_r_safe(start, &tm);
		strftime(s, 16, conf.timefmt, &tm);
	}
	if (end > NEXTDAY(day)) {
		strcpy(e, "..:..");
	} else {
		localtime_r_safe(end, &tm);
		strftime(e, 16, conf.timefmt, &tm);
	}
}

/* Truncate a string to a display width, adding "..." if needed. */
static void fit_string(const char *src, char *dst, size_t dstsz, int width)
{
	int w = string_width(src);
	if (w <= width) {
		snprintf(dst, dstsz, "%s", src);
		return;
	}
	{
		/* copy chars until width - 3 */
		int cur = 0;
		size_t i = 0, o = 0;
		mbstate_t st;
		memset(&st, 0, sizeof(st));
		while (src[i] && o + 1 < dstsz) {
			wchar_t wc;
			size_t n = mbrtowc(&wc, src + i, MB_CUR_MAX, &st);
			int cw;
			if (n == (size_t)-1 || n == (size_t)-2 || n == 0) {
				n = 1;
				cw = 1;
			} else {
				cw = wcwidth(wc);
				if (cw < 0)
					cw = 1;
			}
			if (cur + cw > width - 3)
				break;
			memcpy(dst + o, src + i, n);
			o += n;
			i += n;
			cur += cw;
		}
		dst[o] = '\0';
		if (o + 4 < dstsz)
			strcat(dst, "...");
	}
}

/*
 * Draw the appointment panel.
 */
void ui_day_update_panel(int which_pan)
{
	WINDOW *w = win[APP].p;
	int inner_y = conf.compact_panels ? 1 : 3;
	int h = inner_height();
	int iw = inner_width();
	int y, i;
	int hilt = (which_pan == APP);
	char buf[BUFSIZ_LINE * 2];
	char mesg[BUFSIZ_LINE * 2];
	int selfirst = -1, sellast = -1;

	if (!w)
		return;
	if (ndays == 0)
		ui_day_load_items();
	sel_lines(&selfirst, &sellast);

	/* clear */
	for (y = inner_y; y < inner_y + h; y++) {
		wmove(w, y, 1);
		for (i = 0; i < iw; i++)
			waddch(w, ' ');
	}

	for (y = 0; y < h; y++) {
		int li = line_off + y;
		int wy = inner_y + y;
		struct pline *l;
		int selected;
		if (li >= nlines)
			break;
		l = &lines[li];
		selected = hilt && li >= selfirst && li <= sellast && selfirst >= 0;
		switch (l->type) {
		case L_HEADING: {
			struct tm tm;
			int len, x;
			localtime_r_safe(days[l->dayidx].date, &tm);
			strftime(buf, sizeof(buf), conf.day_heading, &tm);
			len = string_width(buf);
			if (conf.heading_pos == RIGHT)
				x = iw - len;
			else if (conf.heading_pos == CENTER)
				x = (iw - len) / 2 + 1;
			else
				x = 1;
			if (x < 1)
				x = 1;
			custom_apply_attr(w, ATTR_HIGHEST);
			if (l->dayidx == sel_dayidx)
				wattron(w, A_BOLD);
			mvwaddstr(w, wy, x, buf);
			if (l->dayidx == sel_dayidx)
				wattroff(w, A_BOLD);
			custom_remove_attr(w, ATTR_HIGHEST);
			break;
		}
		case L_HLINE:
			mvwhline(w, wy, 1, ACS_HLINE, iw);
			break;
		case L_BLANK:
			break;
		case L_EMPTY_DAY:
			snprintf(buf, sizeof(buf), "   %s", conf.empty_day);
			if (selected)
				custom_apply_attr(w, ATTR_HIGHEST);
			mvwaddstr(w, wy, 2, buf);
			if (selected)
				custom_remove_attr(w, ATTR_HIGHEST);
			break;
		case L_EVENT: {
			struct day_item *d = &days[l->dayidx].items[l->itemidx];
			char *note = day_item_get_note(d);
			fit_string(day_item_get_mesg(d), mesg, sizeof(mesg), iw - 2 - 3);
			snprintf(buf, sizeof(buf), " %c %s", note ? '>' : ' ', mesg);
			if (selected)
				custom_apply_attr(w, ATTR_HIGHEST);
			mvwaddstr(w, wy, 2, buf);
			if (selected)
				custom_remove_attr(w, ATTR_HIGHEST);
			break;
		}
		case L_APT_TIME: {
			struct day_item *d = &days[l->dayidx].items[l->itemidx];
			char s[32], e[32];
			char *note = day_item_get_note(d);
			int state = day_item_get_state(d);
			apt_times(days[l->dayidx].date, d->start, day_item_get_duration(d), s, e);
			snprintf(buf, sizeof(buf), " %c%c%s -> %s", note ? '>' : '-',
				 (state & APOINT_NOTIFY) ? '!' : ' ', s, e);
			if (selected)
				custom_apply_attr(w, ATTR_HIGHEST);
			mvwaddstr(w, wy, 2, buf);
			if (selected)
				custom_remove_attr(w, ATTR_HIGHEST);
			break;
		}
		case L_APT_MESG: {
			struct day_item *d = &days[l->dayidx].items[l->itemidx];
			fit_string(day_item_get_mesg(d), mesg, sizeof(mesg), iw - 2 - 3);
			snprintf(buf, sizeof(buf), "   %s", mesg);
			if (selected)
				custom_apply_attr(w, ATTR_HIGHEST);
			mvwaddstr(w, wy, 2, buf);
			if (selected)
				custom_remove_attr(w, ATTR_HIGHEST);
			break;
		}
		case L_APT_EMPTY:
			break;
		}
	}
	wnoutrefresh(w);
}

