/* Load the items of one day into a pday. */
static void load_day(struct pday *pd, time_t date)
{
	llist_item_t *i;
	int n = 0, k = 0;

	pd->date = date;
	day_store_items(date, 0, 0);
	LLIST_FOREACH(&day_items, i)
		n++;
	pd->nitems = n;
	pd->items = n ? mem_malloc(n * sizeof(struct day_item)) : NULL;
	LLIST_FOREACH(&day_items, i) {
		struct day_item *d = LLIST_GET_DATA(i);
		pd->items[k++] = *d;
	}
}

static void add_line(enum line_type t, int dayidx, int itemidx)
{
	lines = mem_realloc(lines, nlines + 1, sizeof(struct pline));
	lines[nlines].type = t;
	lines[nlines].dayidx = dayidx;
	lines[nlines].itemidx = itemidx;
	nlines++;
}

