static void build_lines(void)
{
	int d, j;
	mem_free(lines);
	lines = NULL;
	nlines = 0;
	for (d = 0; d < ndays; d++) {
		struct pday *pd = &days[d];
		int nev = 0, napt = 0;
		if (conf.multiple_days)
			add_line(L_HEADING, d, -1);
		for (j = 0; j < pd->nitems; j++) {
			if (is_event(&pd->items[j]))
				nev++;
			else
				napt++;
		}
		for (j = 0; j < pd->nitems; j++) {
			if (is_event(&pd->items[j]))
				add_line(L_EVENT, d, j);
		}
		if (nev && napt && conf.event_separator)
			add_line(L_BLANK, d, -1);
		for (j = 0; j < pd->nitems; j++) {
			if (!is_event(&pd->items[j])) {
				add_line(L_APT_TIME, d, j);
				add_line(L_APT_MESG, d, j);
				if (conf.empty_appt_line)
					add_line(L_APT_EMPTY, d, j);
			}
		}
		if (pd->nitems == 0) {
			add_line(L_EMPTY_DAY, d, -1);
			if (conf.empty_appt_line && conf.multiple_days)
				add_line(L_BLANK, d, -1);
		}
		if (conf.multiple_days) {
			if (conf.day_separator)
				add_line(L_BLANK, d, -1);
			if (conf.header_line)
				add_line(L_HLINE, d, -1);
		}
	}
