	time_t next;
	if (ndays == 0)
		next = day_first;
	else
		next = date_sec_change(days[ndays - 1].date, 0, 1);
	days = mem_realloc(days, ndays + 1, sizeof(struct pday));
	load_day(&days[ndays], next);
	ndays++;
}

