	int inner_y = conf.compact_panels ? 1 : 3;
	int h = inner_height();
	int iw = inner_width();
	int y, i;
	int hilt = (which_pan == APP);
	char buf[BUFSIZ_LINE * 2];
	char mesg[BUFSIZ_LINE * 2];
	int selfirst = -1, sellast = -1;

	if (!w)
		return;
	if (ndays == 0)
		ui_day_load_items();
	sel_lines(&selfirst, &sellast);

	/* clear */
	for (y = inner_y; y < inner_y + h; y++) {
		wmove(w, y, 1);
		for (i = 0; i < iw; i++)
			waddch(w, ' ');
	}

	for (y = 0; y < h; y++) {
		int li = line_off + y;
		int wy = inner_y + y;
		struct pline *l;
		int selected;
		if (li >= nlines)
			break;
		l = &lines[li];
		selected = hilt && li >= selfirst && li <= sellast && selfirst >= 0;
		switch (l->type) {
		case L_HEADING: {
			struct tm tm;
			int len, x;
			localtime_r_safe(days[l->dayidx].date, &tm);
			strftime(buf, sizeof(buf), conf.day_heading, &tm);
			len = string_width(buf);
			if (conf.heading_pos == RIGHT)
				x = iw - len;
			else if (conf.heading_pos == CENTER)
				x = (iw - len) / 2 + 1;
			else
				x = 1;
			if (x < 1)
				x = 1;
			custom_apply_attr(w, ATTR_HIGHEST);
			if (l->dayidx == sel_dayidx)
				wattron(w, A_BOLD);
			mvwaddstr(w, wy, x, buf);
			if (l->dayidx == sel_dayidx)
				wattroff(w, A_BOLD);
			custom_remove_attr(w, ATTR_HIGHEST);
			break;
		}
		case L_HLINE:
			mvwhline(w, wy, 1, ACS_HLINE, iw);
			break;
		case L_BLANK:
			break;
		case L_EMPTY_DAY:
			snprintf(buf, sizeof(buf), "   %s", conf.empty_day);
			if (selected)
				custom_apply_attr(w, ATTR_HIGHEST);
			mvwaddstr(w, wy, 2, buf);
			if (selected)
				custom_remove_attr(w, ATTR_HIGHEST);
			break;
		case L_EVENT: {
			struct day_item *d = &days[l->dayidx].items[l->itemidx];
			char *note = day_item_get_note(d);
			fit_string(day_item_get_mesg(d), mesg, sizeof(mesg), iw - 2 - 3);
			snprintf(buf, sizeof(buf), " %c %s", note ? '>' : ' ', mesg);
			if (selected)
				custom_apply_attr(w, ATTR_HIGHEST);
			mvwaddstr(w, wy, 2, buf);
			if (selected)
				custom_remove_attr(w, ATTR_HIGHEST);
			break;
		}
		case L_APT_TIME: {
			struct day_item *d = &days[l->dayidx].items[l->itemidx];
			char s[32], e[32];
			char *note = day_item_get_note(d);
			int state = day_item_get_state(d);
			apt_times(days[l->dayidx].date, d->start, day_item_get_duration(d), s, e);
			snprintf(buf, sizeof(buf), " %c%c%s -> %s", note ? '>' : '-',
				 (state & APOINT_NOTIFY) ? '!' : ' ', s, e);
			if (selected)
				custom_apply_attr(w, ATTR_HIGHEST);
			mvwaddstr(w, wy, 2, buf);
			if (selected)
				custom_remove_attr(w, ATTR_HIGHEST);
			break;
		}
		case L_APT_MESG: {
			struct day_item *d = &days[l->dayidx].items[l->itemidx];
			fit_string(day_item_get_mesg(d), mesg, sizeof(mesg), iw - 2 - 3);
			snprintf(buf, sizeof(buf), "   %s", mesg);
			if (selected)
				custom_apply_attr(w, ATTR_HIGHEST);
			mvwaddstr(w, wy, 2, buf);
			if (selected)
				custom_remove_attr(w, ATTR_HIGHEST);
			break;
		}
		case L_APT_EMPTY:
			break;
		}
	}
	wnoutrefresh(w);
}

/* Return the index of the day item with the given start on the selected day. */
int ui_day_find_item(time_t start, int type)
{
	int j;
	if (ndays == 0)
		return -1;
	for (j = 0; j < days[sel_dayidx].nitems; j++) {
		struct day_item *d = &days[sel_dayidx].items[j];
		if (d->start == start && d->type == type)
			return j;
	}
	return -1;
}

/* ---- item manipulation (implemented in ui-day-edit.c) ---- */

struct day_item *ui_day_cut_item_get(void)
{
	return have_cut ? &cut_item : NULL;
}

void ui_day_cut_item_set(struct day_item *d)
{
	cut_item = *d;
	have_cut = 1;
}

void ui_day_cut_item_clear(void)
{
	have_cut = 0;
}
EOF
echo ok

