#include "ui.h"

static int todo_view = TODO_SHOW_COMPLETED_VIEW;
static int sel = 0;		/* index of selected item among the displayed ones */
static unsigned line_off = 0;

void ui_todo_set_view(int view)
{
	todo_view = view;
}

int ui_todo_get_view(void)
{
	return todo_view;
}

void ui_todo_view_next(void)
{
	todo_view++;
	if (todo_view == TODO_VIEWS)
		todo_view = 0;
}

void ui_todo_view_prev(void)
{
	if (todo_view == 0)
		todo_view = TODO_VIEWS;
	todo_view--;
}

static int skip_completed(void)
{
	return todo_view == TODO_HIDE_COMPLETED_VIEW;
}

static int count_displayed(void)
{
	llist_item_t *i;
	int n = 0;
	LLIST_FOREACH(&todolist, i) {
		struct todo *t = LLIST_GET_DATA(i);
		if (skip_completed() && t->completed)
			continue;
		n++;
	}
	return n;
}

struct todo *ui_todo_selitem(void)
{
	return todo_get_item(sel, skip_completed());
}

void ui_todo_load_items(void)
{
	int n = count_displayed();
	if (sel >= n)
		sel = n > 0 ? n - 1 : 0;
	if (sel < 0)
		sel = 0;
}

void ui_todo_sel_reset(void)
{
	sel = 0;
	line_off = 0;
}

static int inner_height(void)
{
	int h = conf.compact_panels ? (int)win[TOD].h - 2 : (int)win[TOD].h - 4;
	return h < 0 ? 0 : h;
}

static void ensure_visible(void)
{
	int h = inner_height();
	if (h <= 0)
		return;
	if ((unsigned)sel < line_off)
		line_off = sel;
	else if ((unsigned)sel >= line_off + h)
		line_off = sel - h + 1;
}

int ui_todo_sel_move(int delta)
{
	int n = count_displayed();
	int old = sel;
	sel += delta;
	if (sel < 0)
		sel = 0;
	if (sel >= n)
		sel = n > 0 ? n - 1 : 0;
	ensure_visible();
	return sel != old;
}

/* Select a given todo item. */
void ui_todo_set_sel(struct todo *t)
{
	int pos = todo_get_position(t, skip_completed());
	if (pos >= 0)
		sel = pos;
	ensure_visible();
}

static void fit_string(const char *src, char *dst, size_t dstsz, int width)
{
	int w = string_width(src);
	if (w <= width) {
		snprintf(dst, dstsz, "%s", src);
		return;
	}
	{
		int cur = 0;
		size_t i = 0, o = 0;
		mbstate_t st;
		memset(&st, 0, sizeof(st));
		while (src[i] && o + 1 < dstsz) {
			wchar_t wc;
			size_t n = mbrtowc(&wc, src + i, MB_CUR_MAX, &st);
			int cw;
			if (n == (size_t)-1 || n == (size_t)-2 || n == 0) {
				n = 1;
				cw = 1;
			} else {
				cw = wcwidth(wc);
				if (cw < 0)
					cw = 1;
			}
			if (cur + cw > width - 3)
				break;
			memcpy(dst + o, src + i, n);
			o += n;
			i += n;
			cur += cw;
		}
		dst[o] = '\0';
		if (o + 4 < dstsz)
			strcat(dst, "...");
	}
}

void ui_todo_update_panel(void)
{
	WINDOW *w = win[TOD].p;
	int inner_y = conf.compact_panels ? 1 : 3;
	int h = inner_height();
	int iw = (int)win[TOD].w - 2;
	int y, i, n = 0;
	llist_item_t *it;
	int hilt = (wins_slctd() == TOD);
	char buf[BUFSIZ_LINE * 2], mesg[BUFSIZ_LINE * 2];

	if (!w)
		return;
	ui_todo_load_items();
	ensure_visible();
	for (y = inner_y; y < inner_y + h; y++) {
		wmove(w, y, 1);
		for (i = 0; i < iw; i++)
			waddch(w, ' ');
	}
	y = 0;
	LLIST_FOREACH(&todolist, it) {
		struct todo *t = LLIST_GET_DATA(it);
		if (skip_completed() && t->completed)
			continue;
		if ((unsigned)n >= line_off && y < h) {
			char mark[8];
			if (t->completed)
				strcpy(mark, "X. ");
			else if (t->id == 0)
				strcpy(mark, "");
			else
				snprintf(mark, sizeof(mark), "%d. ", t->id);
			fit_string(t->mesg, mesg, sizeof(mesg), iw - (int)strlen(mark) - (t->note ? 1 : 0));
			snprintf(buf, sizeof(buf), "%s%s%s", mark, t->note ? ">" : "", mesg);
			if (hilt && n == sel)
				custom_apply_attr(w, ATTR_HIGHEST);
			mvwaddstr(w, inner_y + y, 1, buf);
			if (hilt && n == sel)
				custom_remove_attr(w, ATTR_HIGHEST);
			y++;
		}
		n++;
	}
	wnoutrefresh(w);
}
EOF
