#include "ui.h"
#include <sys/wait.h>

struct notify_vars {
	char *apts_file;
	char time[BUFSIZ_LINE];
	char date[BUFSIZ_LINE];
};

static struct notify_vars notify;
static struct notify_app notify_app;
static int notify_started = 0;

int notify_bar(void)
{
	return conf.notify_bar;
}

void notify_init_vars(void)
{
	const char *p = strrchr(path_apts, '/');
	notify.apts_file = (char *)(p ? p + 1 : path_apts);
	notify.time[0] = '\0';
	notify.date[0] = '\0';
	notify_app.time = 0;
	notify_app.got_app = 0;
	notify_app.txt = NULL;
	notify_app.state = 0;
}

void notify_free_app(void)
{
	notify_app.time = 0;
	notify_app.got_app = 0;
	notify_app.state = APOINT_NULL;
	if (notify_app.txt)
		mem_free(notify_app.txt);
	notify_app.txt = NULL;
}

void notify_init_bar(void)
{
	notify_init_vars();
	notify_check_next_app(1);
}

void notify_reinit_bar(void)
{
	notify_check_next_app(1);
}

void notify_start_main_thread(void)
{
	notify_started = 1;
}

void notify_stop_main_thread(void)
{
	notify_started = 0;
}

/* Is a reminder needed for the next appointment? */
int notify_needs_reminder(void)
{
	if (!notify_app.got_app)
		return 0;
	if (conf.notify_all == NOTIFY_ALL)
		return 1;
	if (conf.notify_all == NOTIFY_FLAGGED_ONLY)
		return (notify_app.state & APOINT_NOTIFY) != 0;
	return (notify_app.state & APOINT_NOTIFY) == 0;
}

/* Run the notification command. */
unsigned notify_launch_cmd(void)
{
	int pid;
	const char *arg[] = { conf.notify_cmd, NULL };

	if (notify_app.state & APOINT_NOTIFIED)
		return 1;
	notify_app.state |= APOINT_NOTIFIED;
	pid = shell_exec(NULL, NULL, NULL, conf.notify_cmd, arg);
	if (pid > 0) {
		/* reap later */
		(void)arg;
	}
	return 1;
}

/* Collect zombie children of notification commands. */
void notify_catch_children(void)
{
	int status;
	while (waitpid(-1, &status, WNOHANG) > 0) ;
}

/* Find the next appointment within the next 24 hours. */
unsigned notify_get_next(struct notify_app *a)
{
	time_t current_time = now();
	a->time = current_time + DAYINSEC;
	a->got_app = 0;
	a->state = 0;
	a->txt = NULL;
	recur_apoint_check_next(a, current_time, get_today());
	apoint_check_next(a, current_time);
	return 1;
}

void notify_check_next_app(int force)
{
	struct notify_app a;
	(void)force;
	notify_get_next(&a);
	if (a.got_app) {
		if (notify_app.got_app && notify_app.time == a.time && notify_app.txt &&
		    !strcmp(notify_app.txt, a.txt) && (notify_app.state & APOINT_NOTIFY) == (a.state & APOINT_NOTIFY)) {
			mem_free(a.txt);
			return;
		}
		notify_free_app();
		notify_app = a;
	} else {
		notify_free_app();
	}
}

/* Is the item the one shown in the notify bar? */
int notify_same_item(time_t time)
{
	return notify_app.got_app && notify_app.time == time;
}

int notify_same_recur_item(struct recur_apoint *i)
{
	time_t occurrence;
	time_t day = get_today();
	if (!notify_app.got_app)
		return 0;
	if (recur_apoint_find_occurrence(i, day, &occurrence) && occurrence == notify_app.time)
		return 1;
	if (recur_apoint_find_occurrence(i, date_sec_change(day, 0, 1), &occurrence) && occurrence == notify_app.time)
		return 1;
	return 0;
}

void notify_check_added(const char *mesg, time_t start, char state)
{
	(void)mesg;
	(void)start;
	(void)state;
	notify_check_next_app(0);
}

void notify_check_repeated(struct recur_apoint *i)
{
	(void)i;
	notify_check_next_app(0);
}

void notify_update_app(time_t start, char state, char *msg)
{
	(void)start;
	(void)state;
	(void)msg;
	notify_check_next_app(0);
}

/*
 * Draw the notification bar.
 */
void notify_update_bar(void)
{
	const int space = 3;
	int file_pos, date_pos, app_pos, txt_max_len, too_long = 0;
	int time_left, hours_left, minutes_left;
	int blinking;
	char buf[BUFSIZ_LINE];
	time_t t;
	struct tm tm;
	WINDOW *w = win[NOT].p;
	int i;

	if (!conf.notify_bar || !w)
		return;

	t = now();
	localtime_r_safe(t, &tm);
	strftime(notify.date, sizeof(notify.date), conf.notify_date, &tm);
	strftime(notify.time, sizeof(notify.time), conf.notify_time, &tm);

	notify_check_next_app(0);

	date_pos = space;
	file_pos = date_pos + (int)strlen(notify.date) + (int)strlen(notify.time) + 7 + space;
	app_pos = file_pos + (int)strlen(notify.apts_file) + 2 + space;
	txt_max_len = (int)win[NOT].w - (app_pos + 12 + space);

	custom_apply_attr(w, ATTR_HIGHEST);
	wattron(w, A_UNDERLINE | A_REVERSE);
	werase(w);
	wmove(w, 0, 0);
	for (i = 0; i < (int)win[NOT].w; i++)
		waddch(w, ACS_HLINE);
	mvwprintw(w, 0, date_pos, "[ %s | %s ]", notify.date, notify.time);
	mvwprintw(w, 0, file_pos, "(%s)", notify.apts_file);

	if (notify_app.got_app) {
		time_left = (int)(notify_app.time - t);
		if (time_left > 0) {
			hours_left = time_left / HOURINSEC;
			minutes_left = (time_left - hours_left * HOURINSEC) / MININSEC;
			if (time_left < conf.notify_warning && notify_needs_reminder())
				blinking = 1;
			else
				blinking = 0;
			if (string_width(notify_app.txt) > txt_max_len && txt_max_len > 3) {
				too_long = 1;
				/* truncate */
				{
					char *tmp = mem_strdup(notify_app.txt);
					int cur = 0;
					size_t o = 0;
					mbstate_t st;
					memset(&st, 0, sizeof(st));
					while (tmp[o]) {
						wchar_t wc;
						size_t n = mbrtowc(&wc, tmp + o, MB_CUR_MAX, &st);
						int cw;
						if (n == (size_t)-1 || n == (size_t)-2 || n == 0) {
							n = 1;
							cw = 1;
						} else {
							cw = wcwidth(wc);
							if (cw < 0)
								cw = 1;
						}
						if (cur + cw > txt_max_len - 3)
							break;
						o += n;
						cur += cw;
					}
					tmp[o] = '\0';
					snprintf(buf, sizeof(buf), "%s...", tmp);
					mem_free(tmp);
				}
			} else {
				snprintf(buf, sizeof(buf), "%s", notify_app.txt);
			}
			if (blinking)
				wattron(w, A_BLINK);
			mvwprintw(w, 0, app_pos, "> %02d:%02d :: %s <", hours_left, minutes_left, buf);
			if (blinking)
				wattroff(w, A_BLINK);
			if (blinking)
				notify_launch_cmd();
			(void)too_long;
		} else {
			notify_check_next_app(1);
		}
	}
	wattroff(w, A_UNDERLINE | A_REVERSE);
	custom_remove_attr(w, ATTR_HIGHEST);
	wnoutrefresh(w);
}

/* Called once a second by the main loop. */
void notify_tick(void)
{
	notify_catch_children();
	if (notify_bar()) {
		notify_update_bar();
		doupdate();
	}
}

char *notify_app_txt(void)
{
	return notify_app.txt;
}
