cat > src/getstring.c <<'EOF'
#include "ui.h"

/*
 * Simple line editor for the status bar.
 */

enum getstr { GS_VALID, GS_ESC, GS_RET };

struct getstr_charinfo {
	unsigned int offset;
	unsigned int dpyoff;
};

struct getstr_status {
	char *s;
	struct getstr_charinfo *ci;
	int len;
	int pos;
	int scrpos;
};

static void getstr_init(struct getstr_status *st, char *str, struct getstr_charinfo *ci)
{
	int width;

	st->s = str;
	st->ci = ci;
	st->len = 0;
	width = 0;
	while (str[st->len]) {
		int n = UTF8_LENGTH(str[st->len]);
		int cw;
		wchar_t wc;
		mbstate_t ms;
		memset(&ms, 0, sizeof(ms));
		if (mbrtowc(&wc, str + st->len, n, &ms) == (size_t)-1)
			cw = 1;
		else {
			cw = wcwidth(wc);
			if (cw < 0)
				cw = 1;
		}
		st->ci[st->len].offset = st->len;
		st->ci[st->len].dpyoff = width;
		width += cw;
		st->len += n > 0 ? n : 1;
	}
	st->ci[st->len].offset = st->len;
	st->ci[st->len].dpyoff = width;
	st->pos = st->len;
	st->scrpos = 0;
}

/* Count characters in the string (positions in bytes mapping). */
static int getstr_charwidth(const char *s, int off)
{
	wchar_t wc;
	mbstate_t ms;
	int cw;
	memset(&ms, 0, sizeof(ms));
	if (mbrtowc(&wc, s + off, MB_CUR_MAX, &ms) == (size_t)-1)
		return 1;
	cw = wcwidth(wc);
	return cw < 0 ? 1 : cw;
}

static int getstr_dpywidth(const char *s, int from, int to)
{
	int w = 0, i = from;
	while (i < to) {
		int n = UTF8_LENGTH(s[i]);
		w += getstr_charwidth(s, i);
		i += n;
	}
	return w;
}

static int getstr_prev(const char *s, int pos)
{
	if (pos <= 0)
		return 0;
	pos--;
	while (pos > 0 && UTF8_ISCONT(s[pos]))
		pos--;
	return pos;
}

static int getstr_next(const char *s, int pos, int len)
{
	if (pos >= len)
		return len;
	pos += UTF8_LENGTH(s[pos]);
	if (pos > len)
		pos = len;
	return pos;
}

static void getstr_print(WINDOW *w, int x, int y, struct getstr_status *st, int maxw)
{
	int total = getstr_dpywidth(st->s, 0, st->len);
	int posw = getstr_dpywidth(st->s, 0, st->pos);
	int i, cw, dp;
	char c;

	/* adjust scroll position so that the cursor is visible */
	if (posw < st->scrpos)
		st->scrpos = posw;
	if (posw - st->scrpos >= maxw - 1)
		st->scrpos = posw - (maxw - 1) + 1;
	if (st->scrpos < 0)
		st->scrpos = 0;

	mvwhline(w, y, x, ' ', maxw);
	wmove(w, y, x);
	/* print visible part */
	dp = 0;
	i = 0;
	while (i < st->len && dp < st->scrpos) {
		dp += getstr_charwidth(st->s, i);
		i += UTF8_LENGTH(st->s[i]);
	}
	cw = 0;
	while (i < st->len) {
		int w1 = getstr_charwidth(st->s, i);
		int n = UTF8_LENGTH(st->s[i]);
		if (cw + w1 > maxw - 1)
			break;
		waddnstr(w, st->s + i, n);
		cw += w1;
		i += n;
	}
	/* scroll indicator */
	if (st->scrpos > 0 && total - st->scrpos > maxw - 1)
		c = '*';
	else if (st->scrpos > 0)
		c = '<';
	else if (total - st->scrpos > maxw - 1)
		c = '>';
	else
		c = ' ';
	if (c != ' ')
		mvwaddch(w, y, x + maxw - 1, c);
	wmove(w, y, x + posw - st->scrpos);
	wrefresh(w);
}

static void getstr_del_char(struct getstr_status *st)
{
	int n;
	if (st->pos >= st->len)
		return;
	n = UTF8_LENGTH(st->s[st->pos]);
	memmove(st->s + st->pos, st->s + st->pos + n, st->len - st->pos - n + 1);
	st->len -= n;
}

static void getstr_backspace(struct getstr_status *st)
{
	int p;
	if (st->pos <= 0)
		return;
	p = getstr_prev(st->s, st->pos);
	memmove(st->s + p, st->s + st->pos, st->len - st->pos + 1);
	st->len -= st->pos - p;
	st->pos = p;
}

static void getstr_ins_char(struct getstr_status *st, const char *ch, int n, int maxlen)
{
	if (st->len + n >= maxlen)
		return;
	memmove(st->s + st->pos + n, st->s + st->pos, st->len - st->pos + 1);
	memcpy(st->s + st->pos, ch, n);
	st->len += n;
	st->pos += n;
}

/*
 * Read a string from the user.  Returns GETSTRING_VALID if a non-empty
 * string was entered, GETSTRING_RET if empty, GETSTRING_ESC if cancelled.
 */
int getstring(WINDOW *w, char *str, int l, int x, int y)
{
	struct getstr_status st;
	struct getstr_charinfo *ci = mem_malloc((l + 1) * sizeof(struct getstr_charinfo));
	int ch, maxw;
	char mb[UTF8_MAXLEN + 1];
	int ret = GETSTRING_VALID;

	maxw = getmaxx(w) - x;
	if (maxw < 2)
		maxw = 2;
	getstr_init(&st, str, ci);
	curs_set(1);
	for (;;) {
		getstr_print(w, x, y, &st, maxw);
		ch = wgetch(w);
		switch (ch) {
		case KEY_BACKSPACE:
		case 127:
		case 8:	/* ^H */
			getstr_backspace(&st);
			break;
		case KEY_DC:
		case 4:	/* ^D */
			getstr_del_char(&st);
			break;
		case 11:	/* ^K */
			st.s[st.pos] = '\0';
			st.len = st.pos;
			break;
		case 1:	/* ^A */
		case KEY_HOME:
			st.pos = 0;
			break;
		case 5:	/* ^E */
		case KEY_END:
			st.pos = st.len;
			break;
		case 2:	/* ^B */
		case KEY_LEFT:
			st.pos = getstr_prev(st.s, st.pos);
			break;
		case 6:	/* ^F */
		case KEY_RIGHT:
			st.pos = getstr_next(st.s, st.pos, st.len);
			break;
		case 23: {	/* ^W */
			int p = st.pos;
			while (p > 0 && st.s[p - 1] == ' ')
				p--;
			while (p > 0 && st.s[p - 1] != ' ')
				p--;
			memmove(st.s + p, st.s + st.pos, st.len - st.pos + 1);
			st.len -= st.pos - p;
			st.pos = p;
			break;
		}
		case 27:	/* ESC */
			ret = GETSTRING_ESC;
			goto out;
		case '\n':
		case '\r':
		case KEY_ENTER:
			ret = st.len == 0 ? GETSTRING_RET : GETSTRING_VALID;
			goto out;
		case ERR:
		case KEY_RESIZE:
			break;
		default:
			if (ch >= 32 && ch < 256 && ch != KEY_MIN) {
				int n = 1, i;
				mb[0] = (char)ch;
				if (UTF8_ISMULTI(ch)) {
					n = UTF8_LENGTH(ch);
					for (i = 1; i < n; i++) {
						int c2 = wgetch(w);
						if (c2 == ERR)
							break;
						mb[i] = (char)c2;
					}
				}
				getstr_ins_char(&st, mb, n, l);
			}
			break;
		}
	}
out:
	curs_set(0);
	mem_free(ci);
	return ret;
}

/* Update a string with the editor; the string is reallocated. */
int updatestring(WINDOW *w, char **str, int x, int y)
{
	int len = strlen(*str);
	char *buf = mem_malloc(BUFSIZ_LINE);
	int ret;

	if (len >= BUFSIZ_LINE)
		len = BUFSIZ_LINE - 1;
	memcpy(buf, *str, len);
	buf[len] = '\0';
	ret = getstring(w, buf, BUFSIZ_LINE, x, y);
	if (ret == GETSTRING_VALID) {
		mem_free(*str);
		*str = buf;
	} else {
		mem_free(buf);
	}
	return ret;
}
