/*
 * Ask the user for a choice; choice[] holds the key characters,
 * returns the 1-based index, or -1 if cancelled.
 */
int status_ask_choice(const char *message, const char choice[], int nb_choice)
{
	int i, ch;
	char *buf;
	char tmp[8];
	size_t n = strlen(message) + nb_choice * 4 + 8;

	buf = mem_malloc(n);
	snprintf(buf, n, "%s [", message);
	for (i = 0; i < nb_choice; i++) {
		snprintf(tmp, sizeof(tmp), "%c%s", choice[i], i == nb_choice - 1 ? "]" : "/");
		strcat(buf, tmp);
	}
	status_mesg(buf, "");
	mem_free(buf);
	for (;;) {
		ch = ui_wgetch(win[STA].p);
		for (i = 0; i < nb_choice; i++) {
			if (ch == choice[i])
				return i + 1;
		}
		if (ch == 27 || (keys_get_action(ch) == KEY_GENERIC_CANCEL))
			return -1;
	}
}

int status_ask_bool(const char *msg)
{
	int ret;
	status_mesg(msg, "[y/n] ");
	for (;;) {
		int ch = ui_wgetch(win[STA].p);
		if (ch == 'y' || ch == 'Y') {
			ret = 1;
			break;
		}
		if (ch == 'n' || ch == 'N' || ch == 27 || keys_get_action(ch) == KEY_GENERIC_CANCEL) {
			ret = 0;
			break;
		}
	}
	return ret;
}

int status_ask_simplechoice(const char *prefix, const char *choice[], int nb_choice)
{
	int i, ret;
	char *buf;
	char *tmp;
	size_t n = strlen(prefix) + 1;
	char *keys = mem_malloc(nb_choice + 1);

	for (i = 0; i < nb_choice; i++)
		n += strlen(choice[i]) + 8;
	buf = mem_malloc(n);
	snprintf(buf, n, "%s", prefix);
	for (i = 0; i < nb_choice; i++) {
		tmp = strdup_printf("(%d) %s%s", i + 1, choice[i], i == nb_choice - 1 ? "" : ", ");
		strcat(buf, tmp);
		mem_free(tmp);
		keys[i] = '1' + i;
	}
	keys[nb_choice] = '\0';
	ret = status_ask_choice(buf, keys, nb_choice);
	mem_free(buf);
	mem_free(keys);
	return ret;
}

