/* Create the data files without the first-run message. */
void io_check_data_files_quiet(void)
{
	io_check_data_files();
}

/* ---- status bar messages and prompts ---- */

void status_mesg(const char *msg1, const char *msg2)
{
	WINDOW *w = win[STA].p;
	if (!w)
		return;
	werase(w);
	custom_apply_attr(w, ATTR_HIGHEST);
	mvwaddstr(w, 0, 0, msg1);
	custom_remove_attr(w, ATTR_HIGHEST);
	mvwaddstr(w, 1, 0, msg2);
	wnoutrefresh(w);
	doupdate();
}

/* Read a key, handling resizes and timer ticks. */
int ui_wgetch(WINDOW *w)
{
	int ch;
	for (;;) {
		ch = wgetch(w);
		if (ch == KEY_RESIZE) {
			ui_handle_resize();
			continue;
		}
		if (ch == ERR) {
			notify_tick();
			continue;
		}
		return ch;
	}
}

/*
 * Ask the user for a choice; choice[] holds the key characters,
 * returns the 1-based index, or -1 if cancelled.
 */
int status_ask_choice(const char *message, const char choice[], int nb_choice)
{
	int i, ch;
	char *buf;
	char tmp[8];
	size_t n = strlen(message) + nb_choice * 4 + 8;

	buf = mem_malloc(n);
	snprintf(buf, n, "%s [", message);
	for (i = 0; i < nb_choice; i++) {
		snprintf(tmp, sizeof(tmp), "%c%s", choice[i], i == nb_choice - 1 ? "]" : "/");
		strcat(buf, tmp);
	}
	status_mesg(buf, "");
	mem_free(buf);
	for (;;) {
		ch = ui_wgetch(win[STA].p);
		for (i = 0; i < nb_choice; i++) {
			if (ch == choice[i])
				return i + 1;
		}
		if (ch == 27 || (keys_get_action(ch) == KEY_GENERIC_CANCEL))
			return -1;
	}
}

int status_ask_bool(const char *msg)
{
	int ret;
	status_mesg(msg, "[y/n] ");
	for (;;) {
		int ch = ui_wgetch(win[STA].p);
		if (ch == 'y' || ch == 'Y') {
			ret = 1;
			break;
		}
		if (ch == 'n' || ch == 'N' || ch == 27 || keys_get_action(ch) == KEY_GENERIC_CANCEL) {
			ret = 0;
			break;
		}
	}
	return ret;
}

int status_ask_simplechoice(const char *prefix, const char *choice[], int nb_choice)
{
	int i, ret;
	char *buf;
	char *tmp;
	size_t n = strlen(prefix) + 1;
	char *keys = mem_malloc(nb_choice + 1);

	for (i = 0; i < nb_choice; i++)
		n += strlen(choice[i]) + 8;
	buf = mem_malloc(n);
	snprintf(buf, n, "%s", prefix);
	for (i = 0; i < nb_choice; i++) {
		tmp = strdup_printf("(%d) %s%s", i + 1, choice[i], i == nb_choice - 1 ? "" : ", ");
		strcat(buf, tmp);
		mem_free(tmp);
		keys[i] = '1' + i;
	}
	keys[nb_choice] = '\0';
	ret = status_ask_choice(buf, keys, nb_choice);
	mem_free(buf);
	mem_free(keys);
	return ret;
}

/* Display a popup window with a message and wait for a key. */
void wins_show_popup(const char *title, const char *msg)
{
	WINDOW *popup;
	int h = 11, w = col - 2, y = (row - h) / 2 - 1, x = 1;
	int len;

	if (w < 4)
		w = col;
	if (y < 0)
		y = 0;
	popup = newwin(h, w, y, x);
	keypad(popup, TRUE);
	box(popup, 0, 0);
	mvwaddch(popup, 2, 0, ACS_LTEE);
	mvwhline(popup, 2, 1, ACS_HLINE, w - 2);
	mvwaddch(popup, 2, w - 1, ACS_RTEE);
	len = string_width(title);
	custom_apply_attr(popup, ATTR_HIGHEST);
	mvwaddstr(popup, 1, (w - len) / 2, title);
	custom_remove_attr(popup, ATTR_HIGHEST);
	len = string_width(msg);
	mvwaddstr(popup, 5, (w - len) / 2, msg);
	wrefresh(popup);
	ui_wgetch(popup);
	delwin(popup);
	ui_refresh_all();
}

void ui_warnbox(const char *msg)
{
	wins_show_popup(_("/!\\"), msg);
}

void ui_refresh_all(void)
{
	wins_update(FLAG_ALL);
}

void ui_handle_resize(void)
{
	wins_resize();
	ui_day_load_items();
	wins_update(FLAG_ALL);
}

/* ---- startup / shutdown ---- */

static void ui_init(void)
{
	initscr();
	raw();
	noecho();
	nonl();
	curs_set(0);
	keypad(stdscr, TRUE);
	custom_init_colors();
	custom_init_attr();
	ui_started = 1;
}

static void ui_first_run(void)
{
	/* nothing: the original shows a welcome screen only if docs exist */
}

/* Save the configuration, keys and data. */
static void ui_save(int quiet)
{
	if (read_only)
		return;
	run_hook("pre-save");
	io_save_apts(path_apts);
	io_save_todo(path_todo);
	{
		FILE *fp = fopen(path_keys, "w");
		if (fp) {
			keys_save_bindings(fp);
			fclose(fp);
		}
	}
	run_hook("post-save");
	io_unset_modified();
	last_save_time = now();
	(void)quiet;
}

void ui_save_cal(void)
{
	ui_save(0);
}

static void ui_reload(void)
{
	if (io_get_modified()) {
		const char *choices[] = { _("Discard"), _("Keep"), _("Merge") };
		int c = status_ask_simplechoice(_("There are unsaved modifications: "), choices, 3);
		if (c == 2 || c == -1) {
			wins_update(FLAG_STA);
			return;
		}
		if (c == 3) {
			/* merge not supported: keep */
			wins_update(FLAG_STA);
			return;
		}
	}
	apoint_llist_free();
	event_llist_free();
	recur_apoint_llist_free();
	recur_event_llist_free();
	todo_free_list();
	apoint_llist_init();
	event_llist_init();
	recur_apoint_llist_init();
	recur_event_llist_init();
	todo_init_list();
	io_load_data(NULL, 0);
	ui_day_load_items();
	ui_todo_load_items();
	notify_check_next_app(1);
	wins_update(FLAG_ALL);
}

/* Interactive command line (":"). */
static void ui_command(void)
{
	char cmd[BUFSIZ_LINE] = "";
	int ret;
	char *args;

	status_mesg(_("Command: [ h(elp) | w(rite)(!) | q(uit)(!) | wq(!) | n(ext) | p(rev) ]"), "");
	ret = getstring(win[STA].p, cmd, BUFSIZ_LINE, 0, 1);
	if (ret != GETSTRING_VALID) {
		wins_update(FLAG_STA);
		return;
	}
	args = strchr(cmd, ' ');
	if (args) {
		*args = '\0';
		args++;
		while (*args == ' ')
			args++;
	}
	if (!strcmp(cmd, "h") || !strcmp(cmd, "help")) {
		display_help(args && *args ? args : NULL);
	} else if (!strcmp(cmd, "w") || !strcmp(cmd, "write") || !strcmp(cmd, "w!") || !strcmp(cmd, "write!")) {
		ui_save(0);
	} else if (!strcmp(cmd, "q") || !strcmp(cmd, "quit")) {
		extern int ui_quit_request;
		ui_quit_request = 1;
	} else if (!strcmp(cmd, "q!") || !strcmp(cmd, "quit!")) {
		extern int ui_quit_request;
		ui_quit_request = 2;
	} else if (!strcmp(cmd, "wq") || !strcmp(cmd, "wq!")) {
		extern int ui_quit_request;
		ui_save(0);
		ui_quit_request = 2;
	} else if (!strcmp(cmd, "n") || !strcmp(cmd, "next")) {
		ui_day_nextocc();
	} else if (!strcmp(cmd, "p") || !strcmp(cmd, "prev")) {
		extern void ui_day_prevocc(void);
		ui_day_prevocc();
	} else {
		char *msg = strdup_printf(_("Command '%s' not found."), cmd);
		status_mesg(msg, "");
		mem_free(msg);
		ui_wgetch(win[STA].p);
	}
	wins_update(FLAG_ALL);
}

int ui_quit_request = 0;

static void ui_quit(int force)
{
	if (!force && conf.confirm_quit) {
		if (!status_ask_bool(_("Do you really want to quit?"))) {
			wins_update(FLAG_STA);
			return;
		}
	}
	if (conf.auto_save)
		ui_save(1);
	else if (io_get_modified() && !read_only) {
		if (status_ask_bool(_("There are unsaved modifications. Save them?")))
			ui_save(1);
	}
	if (conf.auto_gc)
		note_gc();
	if (conf.daemon_enable && !read_only)
		dmon_start(0);
	exit_calcurse(EXIT_SUCCESS);
}

/* Toggle the panel-specific "next view". */
static void ui_scroll_down(void)
{
	switch (wins_slctd()) {
	case CAL:
		ui_calendar_view_next();
		wins_update(FLAG_CAL);
		break;
	case TOD:
		ui_todo_view_next();
		ui_todo_sel_reset();
		wins_update(FLAG_TOD);
		break;
	default:
		break;
	}
}

static void ui_scroll_up(void)
{
	switch (wins_slctd()) {
	case CAL:
		ui_calendar_view_prev();
		wins_update(FLAG_CAL);
		break;
	case TOD:
		ui_todo_view_prev();
		ui_todo_sel_reset();
		wins_update(FLAG_TOD);
		break;
	default:
		break;
	}
}

static void ui_move_day(int days)
{
	ui_calendar_change_day(days);
	ui_day_sel_reset();
	ui_day_load_items();
	wins_update(FLAG_CAL | FLAG_APP);
}

static void ui_move_month(int months)
{
	struct date *d = ui_calendar_get_slctd_day();
	struct tm tm;
	time_t t;
	int ndays;
	memset(&tm, 0, sizeof(tm));
	tm.tm_year = d->yyyy - TM_YEAR_BASE;
	tm.tm_mon = d->mm - 1 + months;
	tm.tm_mday = 1;
	tm.tm_isdst = -1;
	t = mktime(&tm);
	localtime_r_safe(t, &tm);
	ndays = month_days(tm.tm_mon + 1, tm.tm_year + TM_YEAR_BASE);
	{
		struct date nd;
		nd.yyyy = tm.tm_year + TM_YEAR_BASE;
		nd.mm = tm.tm_mon + 1;
		nd.dd = (int)d->dd > ndays ? ndays : d->dd;
		ui_calendar_set_slctd_day(nd);
	}
	ui_day_sel_reset();
	ui_day_load_items();
	wins_update(FLAG_CAL | FLAG_APP);
}

static void ui_move_year(int years)
{
	struct date *d = ui_calendar_get_slctd_day();
	struct date nd = *d;
	int ndays;
	nd.yyyy += years;
	ndays = month_days(nd.mm, nd.yyyy);
	if ((int)nd.dd > ndays)
		nd.dd = ndays;
	ui_calendar_set_slctd_day(nd);
	ui_day_sel_reset();
	ui_day_load_items();
	wins_update(FLAG_CAL | FLAG_APP);
}

/* Goto a date typed by the user. */
static void ui_goto(void)
{
	char buf[BUFSIZ_LINE] = "";
	char *msg;
	int y, m, d;
	struct date *slctd = ui_calendar_get_slctd_day();

	msg = strdup_printf(_("Enter the day to go to [ENTER for today] : %s"), DATEFMT_DESC(conf.input_datefmt));
	for (;;) {
		status_mesg(msg, "");
		{
			int ret = getstring(win[STA].p, buf, BUFSIZ_LINE, 0, 1);
			if (ret == GETSTRING_ESC) {
				break;
			} else if (ret == GETSTRING_RET) {
				ui_calendar_goto_today();
				ui_day_sel_reset();
				ui_day_load_items();
				break;
			} else if (parse_date(buf, conf.input_datefmt, &y, &m, &d, slctd)) {
				struct date nd;
				nd.yyyy = y;
				nd.mm = m;
				nd.dd = d;
				ui_calendar_set_slctd_day(nd);
				ui_day_sel_reset();
				ui_day_load_items();
				break;
			} else {
				status_mesg(_("The day you entered is not valid"), _("Press [ENTER] to continue"));
				ui_wgetch(win[STA].p);
			}
		}
	}
	mem_free(msg);
	wins_update(FLAG_ALL);
}

static void ui_generic_change_view(int next)
{
	if (next)
		wins_slctd_next();
	else
		wins_slctd_prev();
	wins_reset_status_page();
	wins_update(FLAG_ALL);
}

static void ui_import(void)
{
	io_import_data(IO_IMPORT_ICAL, NULL, NULL, NULL, NULL, NULL, NULL);
	ui_day_load_items();
	ui_todo_load_items();
	notify_check_next_app(1);
	wins_update(FLAG_ALL);
}

static void ui_export(void)
{
	extern void ui_export_dialog(void);
	ui_export_dialog();
	wins_update(FLAG_ALL);
}

int ui_main(void)
{
	int ch, count;
	int first_run;

	first_run = io_check_data_files();
	io_check_file(path_keys);
	config_load();
	wins_set_layout(conf.layout);
	wins_set_sbar_width(conf.sbar_width);
	ui_calendar_set_view(conf.cal_view);
	ui_calendar_set_first_day_of_week(conf.first_day_of_week);

	if (!io_set_lock_quiet()) {
		fprintf(stderr, "%s", _("\nWARNING: it seems that another calcurse instance is already running.\n"
					"If this is not the case, please remove the following lock file: \n\"%s\"\nand restart calcurse.\n"));
		/* the above format expects the path; print properly */
		exit(EXIT_FAILURE);
	}
	(void)first_run;

	keys_init();
	{
		int r = keys_load_bindings();
		if (r < 0)
			keys_fill_missing();
		else
			keys_fill_missing();
	}

	ui_init();
	wins_slctd_set(conf.default_panel);
	wins_init();
	ui_calendar_init_slctd_day();
	io_load_data(NULL, 0);
	ui_day_load_items();
	ui_todo_load_items();
	notify_init_bar();
	ui_first_run();
	wins_update(FLAG_ALL);
	wtimeout(win[STA].p, 1000);
	wtimeout(win[CAL].p, 1000);
	wtimeout(win[APP].p, 1000);
	wtimeout(win[TOD].p, 1000);

	count = 0;
	for (;;) {
		int key;
		if (ui_quit_request) {
			ui_quit(ui_quit_request == 2);
			ui_quit_request = 0;
		}
		if (conf.periodic_save > 0 && !read_only &&
		    now() - last_save_time >= (time_t)conf.periodic_save * 60 && last_save_time != 0) {
			ui_save(1);
		}
		ch = ui_wgetch(win[STA].p);
		if (ch >= '0' && ch <= '9' && !(ch == '0' && count == 0 && keys_get_action('0') != KEY_UNDEF)) {
			/* numeric prefix for repeat counts (not implemented for '0' binding) */
		}
		key = keys_get_action(ch);
		if (key == KEY_UNDEF && ch >= '1' && ch <= '9') {
			count = count * 10 + (ch - '0');
			continue;
		}
		if (count == 0)
			count = 1;

		switch (key) {
		case KEY_GENERIC_REDRAW:
			wins_reset_status_page();
			ui_handle_resize();
			break;
		case KEY_GENERIC_CHANGE_VIEW:
			ui_generic_change_view(1);
			break;
		case KEY_GENERIC_PREV_VIEW:
			ui_generic_change_view(0);
			break;
		case KEY_GENERIC_OTHER_CMD:
			wins_other_status_page();
			wins_update(FLAG_STA);
			break;
		case KEY_GENERIC_GOTO:
			ui_goto();
			break;
		case KEY_GENERIC_GOTO_TODAY:
			ui_calendar_goto_today();
			ui_day_sel_reset();
			ui_day_load_items();
			wins_update(FLAG_CAL | FLAG_APP);
			break;
		case KEY_GENERIC_SCROLL_DOWN:
			ui_scroll_down();
			break;
		case KEY_GENERIC_SCROLL_UP:
			ui_scroll_up();
			break;
		case KEY_GENERIC_CONFIG_MENU:
			wins_reset_status_page();
			custom_config_main();
			ui_day_load_items();
			wins_update(FLAG_ALL);
			break;
		case KEY_GENERIC_ADD_APPT:
			ui_day_item_add();
			wins_update(FLAG_CAL | FLAG_APP | FLAG_STA);
			break;
		case KEY_GENERIC_ADD_TODO:
			ui_todo_add();
			wins_update(FLAG_TOD | FLAG_STA);
			break;
		case KEY_GENERIC_PREV_DAY:
			ui_move_day(-count);
			break;
		case KEY_GENERIC_NEXT_DAY:
			ui_move_day(count);
			break;
		case KEY_GENERIC_PREV_WEEK:
			ui_move_day(-7 * count);
			break;
		case KEY_GENERIC_NEXT_WEEK:
			ui_move_day(7 * count);
			break;
		case KEY_GENERIC_PREV_MONTH:
			ui_move_month(-count);
			break;
		case KEY_GENERIC_NEXT_MONTH:
			ui_move_month(count);
			break;
		case KEY_GENERIC_PREV_YEAR:
			ui_move_year(-count);
			break;
		case KEY_GENERIC_NEXT_YEAR:
			ui_move_year(count);
			break;
		case KEY_GENERIC_IMPORT:
			ui_import();
			break;
		case KEY_GENERIC_EXPORT:
			ui_export();
			break;
		case KEY_GENERIC_SAVE:
			ui_save(0);
			wins_update(FLAG_STA);
			break;
		case KEY_GENERIC_RELOAD:
			ui_reload();
			break;
		case KEY_GENERIC_QUIT:
			ui_quit(0);
			break;
		case KEY_GENERIC_HELP:
			display_help(NULL);
			wins_update(FLAG_ALL);
			break;
		case KEY_GENERIC_CREDITS:
			display_help("credits");
			wins_update(FLAG_ALL);
			break;
		case KEY_GENERIC_CMD:
			ui_command();
			break;
		case KEY_GENERIC_COPY:
			if (wins_slctd() == APP) {
				ui_day_item_copy(0);
				wins_update(FLAG_APP | FLAG_STA);
			}
			break;
		case KEY_GENERIC_PASTE:
			if (wins_slctd() == APP) {
				ui_day_item_paste(0);
				wins_update(FLAG_CAL | FLAG_APP | FLAG_STA);
			}
			break;

		case KEY_MOVE_RIGHT:
			if (wins_slctd() == CAL) {
				ui_calendar_move(CAL_RIGHT, count);
				ui_day_sel_reset();
				ui_day_load_items();
				wins_update(FLAG_CAL | FLAG_APP);
			}
			break;
		case KEY_MOVE_LEFT:
			if (wins_slctd() == CAL) {
				ui_calendar_move(CAL_LEFT, count);
				ui_day_sel_reset();
				ui_day_load_items();
				wins_update(FLAG_CAL | FLAG_APP);
			}
			break;
		case KEY_MOVE_DOWN:
			if (wins_slctd() == CAL) {
				ui_calendar_move(CAL_DOWN, count);
				ui_day_sel_reset();
				ui_day_load_items();
				wins_update(FLAG_CAL | FLAG_APP);
			} else if (wins_slctd() == APP) {
				ui_day_sel_move(count);
				wins_update(FLAG_APP | FLAG_CAL);
			} else if (wins_slctd() == TOD) {
				ui_todo_sel_move(count);
				wins_update(FLAG_TOD);
			}
			break;
		case KEY_MOVE_UP:
			if (wins_slctd() == CAL) {
				ui_calendar_move(CAL_UP, count);
				ui_day_sel_reset();
				ui_day_load_items();
				wins_update(FLAG_CAL | FLAG_APP);
			} else if (wins_slctd() == APP) {
				ui_day_sel_move(-count);
				wins_update(FLAG_APP | FLAG_CAL);
			} else if (wins_slctd() == TOD) {
				ui_todo_sel_move(-count);
				wins_update(FLAG_TOD);
			}
			break;
		case KEY_START_OF_WEEK:
			if (wins_slctd() == CAL) {
				ui_calendar_move(CAL_WEEK_START, count);
				ui_day_sel_reset();
				ui_day_load_items();
				wins_update(FLAG_CAL | FLAG_APP);
			}
			break;
		case KEY_END_OF_WEEK:
			if (wins_slctd() == CAL) {
				ui_calendar_move(CAL_WEEK_END, count);
				ui_day_sel_reset();
				ui_day_load_items();
				wins_update(FLAG_CAL | FLAG_APP);
			}
			break;
		case KEY_ADD_ITEM:
			if (wins_slctd() == APP) {
				ui_day_item_add();
				wins_update(FLAG_CAL | FLAG_APP | FLAG_STA);
			} else if (wins_slctd() == TOD) {
				ui_todo_add();
				wins_update(FLAG_TOD | FLAG_STA);
			}
			break;
		case KEY_DEL_ITEM:
			if (wins_slctd() == APP) {
				ui_day_item_delete(0);
				wins_update(FLAG_CAL | FLAG_APP | FLAG_STA);
			} else if (wins_slctd() == TOD) {
				ui_todo_delete();
				wins_update(FLAG_TOD | FLAG_STA);
			}
			break;
		case KEY_EDIT_ITEM:
			if (wins_slctd() == APP) {
				ui_day_item_edit();
				wins_update(FLAG_CAL | FLAG_APP | FLAG_STA);
			} else if (wins_slctd() == TOD) {
				ui_todo_edit();
				wins_update(FLAG_TOD | FLAG_STA);
			}
			break;
		case KEY_VIEW_ITEM:
			if (wins_slctd() == APP) {
				ui_day_popup_item();
				wins_update(FLAG_ALL);
			} else if (wins_slctd() == TOD) {
				ui_todo_popup_item();
				wins_update(FLAG_ALL);
			}
			break;
		case KEY_PIPE_ITEM:
			if (wins_slctd() == APP)
				ui_day_item_pipe();
			else if (wins_slctd() == TOD)
				ui_todo_pipe();
			wins_update(FLAG_ALL);
			break;
		case KEY_FLAG_ITEM:
			if (wins_slctd() == APP) {
				ui_day_flag();
				wins_update(FLAG_APP);
			} else if (wins_slctd() == TOD) {
				ui_todo_flag();
				wins_update(FLAG_TOD);
			}
			break;
		case KEY_REPEAT_ITEM:
			if (wins_slctd() == APP) {
				ui_day_item_repeat();
				wins_update(FLAG_CAL | FLAG_APP | FLAG_STA);
			}
			break;
		case KEY_EDIT_NOTE:
			if (wins_slctd() == APP) {
				ui_day_edit_note();
				wins_update(FLAG_ALL);
			} else if (wins_slctd() == TOD) {
				ui_todo_edit_note();
				wins_update(FLAG_ALL);
			}
			break;
		case KEY_VIEW_NOTE:
			if (wins_slctd() == APP) {
				ui_day_view_note();
				wins_update(FLAG_ALL);
			} else if (wins_slctd() == TOD) {
				ui_todo_view_note();
				wins_update(FLAG_ALL);
			}
			break;
		case KEY_RAISE_PRIORITY:
			if (wins_slctd() == TOD) {
				ui_todo_chg_priority(1);
				wins_update(FLAG_TOD);
			}
			break;
		case KEY_LOWER_PRIORITY:
			if (wins_slctd() == TOD) {
				ui_todo_chg_priority(-1);
				wins_update(FLAG_TOD);
			}
			break;
		case KEY_GENERIC_CANCEL:
		case KEY_GENERIC_SELECT:
			break;
		default:
			break;
		}
		count = 0;
	}
	return 0;
}

int main(int argc, char **argv)
{
	int ret;

	setlocale(LC_ALL, "");
	vars_init();
	ret = parse_args(argc, argv);
	if (ret == 2)
		exit_calcurse(EXIT_FAILURE);
	if (ret)
		exit_calcurse(EXIT_SUCCESS);

	/* Interactive mode. */
	ui_mode = UI_CURSES;
	return ui_main();
}
