/* Pipe the selected item to an external command. */
void ui_day_item_pipe(void)
{
	char cmd[BUFSIZ_LINE] = "";
	char const *arg[] = { cmd, NULL };
	int pout, pid;
	FILE *fpout;
	struct day_item *d = ui_day_get_sel();

	if (!d)
		return;
	status_mesg(_("Pipe item to external command:"), "");
	if (getstring(win[STA].p, cmd, BUFSIZ_LINE, 0, 1) != GETSTRING_VALID)
		return;
	wins_prepare_external();
	if ((pid = shell_exec(NULL, &pout, NULL, *arg, arg))) {
		fpout = fdopen(pout, "w");
		if (fpout) {
			switch (d->type) {
			case RECUR_EVNT:
				recur_event_write(d->item.rev, fpout);
				break;
			case EVNT:
				event_write(d->item.ev, fpout);
				break;
			case RECUR_APPT:
				recur_apoint_write(d->item.rapt, fpout);
				break;
			case APPT:
				apoint_write(d->item.apt, fpout);
				break;
			}
			fclose(fpout);
		}
		child_wait(NULL, &pout, NULL, pid);
		press_any_key();
	}
	wins_unprepare_external();
}

void press_any_key(void)
{
	struct termios t_attr_old, t_attr;
	int c;
	tcgetattr(STDIN_FILENO, &t_attr_old);
	t_attr = t_attr_old;
	t_attr.c_lflag &= ~(ICANON | ECHO);
	tcsetattr(STDIN_FILENO, TCSANOW, &t_attr);
	fputs(_("Press any key to continue..."), stdout);
	fflush(stdout);
	c = getchar();
	(void)c;
	tcsetattr(STDIN_FILENO, TCSANOW, &t_attr_old);
	puts("");
}

/* ---- copy / paste ---- */

void ui_day_item_copy(unsigned reg)
{
	struct day_item *d = ui_day_get_sel();
	struct day_item copy;
	(void)reg;
	if (!d)
		return;
	day_item_fork(d, &copy);
	{
		struct day_item *old = ui_day_cut_item_get();
		if (old) {
			switch (old->type) {
			case APPT:
				apoint_free(old->item.apt);
				break;
			case EVNT:
				event_free(old->item.ev);
				break;
			case RECUR_APPT:
				recur_apoint_free(old->item.rapt);
				break;
			case RECUR_EVNT:
				recur_event_free(old->item.rev);
				break;
			}
		}
	}
	ui_day_cut_item_set(&copy);
}

void ui_day_item_cut(unsigned reg)
{
	ui_day_item_copy(reg);
	ui_day_item_delete(reg);
}

void ui_day_item_paste(unsigned reg)
{
	struct day_item *c = ui_day_cut_item_get();
	struct day_item copy;
	time_t date = ui_calendar_get_slctd_day_sec();
	void *newptr = NULL;
	(void)reg;
	if (!c)
		return;
	day_item_fork(c, &copy);
	switch (copy.type) {
	case APPT:
		apoint_paste_item(copy.item.apt, date);
		newptr = copy.item.apt;
		break;
	case EVNT:
		event_paste_item(copy.item.ev, date);
		newptr = copy.item.ev;
		break;
	case RECUR_APPT:
		recur_apoint_paste_item(copy.item.rapt, date);
		newptr = copy.item.rapt;
		break;
	case RECUR_EVNT:
		recur_event_paste_item(copy.item.rev, date);
		newptr = copy.item.rev;
		break;
	}
	io_set_modified();
	ui_day_load_items();
	ui_day_set_selitem_by_aptev_ptr(newptr);
	if (notify_bar())
		notify_check_next_app(1);
}

/* Go to the next occurrence of the selected recurrent item. */
void ui_day_nextocc(void)
{
	struct day_item *d = ui_day_get_sel();
	time_t day = ui_day_sel_date();
	time_t next;
	int found = 0;
	void *ptr;

	if (!d || !item_is_recur(d))
		return;
	ptr = d->item.ptr;
	if (d->type == RECUR_APPT) {
		struct recur_apoint *rapt = d->item.rapt;
		found = recur_next_occurrence(rapt->start, rapt->dur, &rapt->exc, rapt->rpt, day, &next);
	} else {
		struct recur_event *rev = d->item.rev;
		found = recur_next_occurrence(rev->day, DAYINSEC, &rev->exc, rev->rpt, day, &next);
	}
	if (!found)
		return;
	{
		struct tm tm;
		struct date nd;
		localtime_r_safe(next, &tm);
		nd.dd = tm.tm_mday;
		nd.mm = tm.tm_mon + 1;
		nd.yyyy = tm.tm_year + TM_YEAR_BASE;
		ui_calendar_set_slctd_day(nd);
	}
	ui_day_sel_reset();
	ui_day_load_items();
	ui_day_set_selitem_by_aptev_ptr(ptr);
}

void ui_day_prevocc(void)
{
	struct day_item *d = ui_day_get_sel();
	time_t day = ui_day_sel_date();
	time_t t, occ;
	int i;
	void *ptr;

	if (!d || !item_is_recur(d))
		return;
	ptr = d->item.ptr;
	/* search backwards day by day */
	for (i = 1; i < 366 * 20; i++) {
		int ok;
		t = date_sec_change(day, 0, -i);
		if (d->type == RECUR_APPT) {
			struct recur_apoint *rapt = d->item.rapt;
			if (t < DAY(rapt->start))
				return;
			ok = recur_apoint_find_occurrence(rapt, t, &occ) && DAY(occ) == t;
		} else {
			struct recur_event *rev = d->item.rev;
			if (t < rev->day)
				return;
			ok = recur_event_find_occurrence(rev, t, &occ) && occ == t;
		}
		if (ok) {
			struct tm tm;
			struct date nd;
			localtime_r_safe(t, &tm);
			nd.dd = tm.tm_mday;
			nd.mm = tm.tm_mon + 1;
			nd.yyyy = tm.tm_year + TM_YEAR_BASE;
			ui_calendar_set_slctd_day(nd);
			ui_day_sel_reset();
			ui_day_load_items();
			ui_day_set_selitem_by_aptev_ptr(ptr);
			return;
		}
	}
}
