#include "ui.h"

/*
 * Appointment panel actions: add, edit, delete, repeat, ...
 */

static void press_enter_msg(const char *msg)
{
	status_mesg(msg, _("Press [Enter] to continue"));
	ui_wgetch(win[STA].p);
}

static void press_any_key_msg(const char *msg)
{
	status_mesg(msg, _("Press any key to continue."));
	ui_wgetch(win[STA].p);
}

/*
 * Parse a date and/or time string relative to the selected day.
 * Accepts "date", "time", "date time".  Returns the resulting time or
 * -1 on error.  The date may omit the year or the month.
 */
static time_t parse_date_time_rel(const char *str, time_t base, int allow_time_only)
{
	char *buf = mem_strdup(str), *p, *sv = NULL;
	char *tok[3];
	int n = 0;
	int y, m, d;
	unsigned hour, min;
	struct date dt;
	struct tm tm;
	time_t res = -1;

	for (p = strtok_r(buf, " ", &sv); p && n < 3; p = strtok_r(NULL, " ", &sv))
		tok[n++] = p;
	if (n == 0 || n > 2)
		goto out;
	localtime_r_safe(base, &tm);
	dt.yyyy = tm.tm_year + TM_YEAR_BASE;
	dt.mm = tm.tm_mon + 1;
	dt.dd = tm.tm_mday;
	hour = tm.tm_hour;
	min = tm.tm_min;
	if (n == 1) {
		if (parse_time(tok[0], &hour, &min)) {
			if (!allow_time_only)
				goto out;
		} else if (parse_date(tok[0], conf.input_datefmt, &y, &m, &d, &dt)) {
			dt.yyyy = y;
			dt.mm = m;
			dt.dd = d;
		} else {
			goto out;
		}
	} else {
		if (!parse_date(tok[0], conf.input_datefmt, &y, &m, &d, &dt))
			goto out;
		if (!parse_time(tok[1], &hour, &min))
			goto out;
		dt.yyyy = y;
		dt.mm = m;
		dt.dd = d;
	}
	res = date2sec(dt, hour, min);
out:
	mem_free(buf);
	return res;
}

/* Parse a time of the forms hh:mm, hh:, :mm, hhmm. */
static int parse_time_ext(const char *s, unsigned *hour, unsigned *min, unsigned def_hour, unsigned def_min)
{
	const char *colon = strchr(s, ':');
	if (colon) {
		char *h = mem_strdup(s);
		char *mm = h + (colon - s);
		int ok = 1;
		*mm = '\0';
		mm++;
		if (*h) {
			if (!is_all_digit(h) || atoi(h) > 23)
				ok = 0;
			else
				*hour = atoi(h);
		} else {
			*hour = def_hour;
		}
		if (ok && *mm) {
			if (!is_all_digit(mm) || atoi(mm) > 59)
				ok = 0;
			else
				*min = atoi(mm);
		} else if (ok) {
			*min = def_min;
		}
		if (ok && !*h && !*mm)
			ok = 0;
		mem_free(h);
		return ok;
	}
	return parse_time(s, hour, min);
}

/*
 * Parse the end of an appointment: duration ("+..."), time, date and/or
 * time.  Returns the end time or -1.
 */
static time_t parse_end(const char *str, time_t start)
{
	unsigned dur;
	time_t end;

	if (str[0] == '+') {
		if (!parse_duration(str + 1, &dur, start))
			return -1;
		return start + (time_t)dur * MININSEC;
	}
	{
		/* time only: end on the same day, or next day if earlier */
		unsigned hour, min;
		char *buf = mem_strdup(str);
		int only_time = (strchr(buf, ' ') == NULL) && parse_time_ext(buf, &hour, &min, get_item_hour(start), get_item_min(start));
		mem_free(buf);
		if (only_time) {
			end = update_time_in_date(start, hour, min);
			if (end < start)
				end = date_sec_change(end, 0, 1);
			return end;
		}
	}
	end = parse_date_time_rel(str, start, 0);
	if (end == -1)
		return -1;
	if (end < start)
		return -1;
	return end;
}

static void show_end_help(void)
{
	status_mesg(_("Date: mm/dd/yyyy (and/or time), year or month may be omitted."),
		    _("Time: hh:mm (hh: or :mm) or hhmm. Duration: +mm, +hh:mm, +??d??h??m."));
	ui_wgetch(win[STA].p);
}

/* Ask for the end time; returns 1 with *end set, 0 if cancelled. */
static int ask_end(time_t start, time_t *end, const char *prompt, char *buf)
{
	for (;;) {
		int ret;
		status_mesg(prompt, "");
		ret = getstring(win[STA].p, buf, BUFSIZ_LINE, 0, 1);
		if (ret == GETSTRING_ESC)
			return 0;
		if (ret == GETSTRING_RET) {
			*end = start;
			return 1;
		}
		if (!strcmp(buf, "?")) {
			show_end_help();
			buf[0] = '\0';
			continue;
		}
		*end = parse_end(buf, start);
		if (*end == -1) {
			press_enter_msg(_("Invalid time or duration."));
			continue;
		}
		return 1;
	}
}

/* Add an appointment or an event on the selected day. */
void ui_day_item_add(void)
{
	char item_time[BUFSIZ_LINE] = "";
	char item_mesg[BUFSIZ_LINE] = "";
	char end_buf[BUFSIZ_LINE] = "";
	time_t day = ui_calendar_get_slctd_day_sec();
	time_t start = 0, end = 0;
	unsigned hour, min;
	int is_appointment = 1;
	int ret;
	void *newptr = NULL;

	for (;;) {
		status_mesg(_("Enter start time ([hh:mm] or [hhmm]), leave blank for an all-day event:"), "");
		ret = getstring(win[STA].p, item_time, BUFSIZ_LINE, 0, 1);
		if (ret == GETSTRING_ESC)
			return;
		if (ret == GETSTRING_RET) {
			is_appointment = 0;
			break;
		}
		if (parse_time(item_time, &hour, &min)) {
			start = update_time_in_date(day, hour, min);
			break;
		}
		press_enter_msg(_("Invalid start time."));
	}

	if (is_appointment) {
		if (!ask_end(start, &end, _("Enter end time as date (and/or time) or duration ('?' for input formats):"), end_buf))
			return;
	}

	status_mesg(_("Enter description:"), "");
	ret = getstring(win[STA].p, item_mesg, BUFSIZ_LINE, 0, 1);
	if (ret != GETSTRING_VALID)
		return;

	if (is_appointment) {
		struct apoint *apt = apoint_new(item_mesg, NULL, start, end - start, 0);
		newptr = apt;
		if (notify_bar())
			notify_check_added(item_mesg, start, 0);
	} else {
		struct event *ev = event_new(item_mesg, NULL, day, 1);
		newptr = ev;
	}
	io_set_modified();
	ui_day_load_items();
	ui_day_set_selitem_by_aptev_ptr(newptr);
}

static int item_is_recur(struct day_item *d)
{
	return d->type == RECUR_EVNT || d->type == RECUR_APPT;
}

/* Delete the selected item. */
void ui_day_item_delete(unsigned reg)
{
	struct day_item *d = ui_day_get_sel();
	time_t date = ui_day_sel_date();
	int ch;
	(void)reg;

	if (!d)
		return;
	if (item_is_recur(d)) {
		const char choices[] = { 's', 'a' };
		ch = status_ask_choice(_("This item is recurrent. Delete (s)elected occurrence or (a)ll occurrences?"), choices, 2);
		if (ch == -1)
			return;
		if (ch == 1) {
			/* add an exception */
			day_item_add_exc(d, date);
			io_set_modified();
			ui_day_load_items();
			ui_day_find_sel();
			return;
		}
	} else if (conf.confirm_delete) {
		const char choices[] = { 's' };
		ch = status_ask_choice(_("Confirm deletion. Delete (s)elected occurrence? Press (s) to confirm."), choices, 1);
		if (ch == -1)
			return;
	}
	switch (d->type) {
	case APPT:
		apoint_delete(d->item.apt);
		break;
	case EVNT:
		event_delete(d->item.ev);
		break;
	case RECUR_APPT:
		recur_apoint_erase(d->item.rapt);
		break;
	case RECUR_EVNT:
		recur_event_erase(d->item.rev);
		break;
	}
	io_set_modified();
	ui_day_load_items();
	ui_day_find_sel();
}

/* ---- repetition ---- */

static int ask_base_period(enum recur_type *type, int has_default)
{
	const char choices[] = { 'd', 'w', 'm', 'y' };
	char msg[BUFSIZ_LINE];
	int ch;
	const char *def = "";

	if (has_default) {
		switch (*type) {
		case RECUR_DAILY: def = " [day]"; break;
		case RECUR_WEEKLY: def = " [week]"; break;
		case RECUR_MONTHLY: def = " [month]"; break;
		case RECUR_YEARLY: def = " [year]"; break;
		default: break;
		}
	}
	snprintf(msg, sizeof(msg), _("Base period: day/week/month/year?%s"), def);
	ch = status_ask_choice(msg, choices, 4);
	if (ch == -1)
		return 0;
	*type = (enum recur_type)ch;	/* RECUR_DAILY == 1 */
	return 1;
}

static int ask_frequency(int *freq)
{
	char buf[BUFSIZ_LINE];
	for (;;) {
		int ret;
		snprintf(buf, sizeof(buf), "%d", *freq);
		status_mesg(_("Frequency:"), "");
		ret = getstring(win[STA].p, buf, BUFSIZ_LINE, 0, 1);
		if (ret == GETSTRING_ESC)
			return 0;
		if (ret == GETSTRING_RET)
			continue;
		if (is_all_digit(buf) && atoi(buf) > 0) {
			*freq = atoi(buf);
			return 1;
		}
		press_any_key_msg(_("Invalid frequency."));
	}
}

static void show_until_help(void)
{
	status_mesg(_("Date: mm/dd/yyyy (year, month may be omitted, endless: 0)."),
		    _("Increment: +?? (days) or: +??w??d (weeks). Repeat count: #?? (number)."));
	ui_wgetch(win[STA].p);
}

/*
 * Ask for the until date.  start is the item start; rpt has the type and
 * frequency set.  Returns 1 with rpt->until set (0 = endless), 0 if cancelled.
 */
static int ask_until(time_t start, long dur, struct rpt *rpt, llist_t *exc, int has_default)
{
	char buf[BUFSIZ_LINE] = "";
	int y, m, d;
	struct date dt;
	struct tm tm;

	localtime_r_safe(start, &tm);
	dt.yyyy = tm.tm_year + TM_YEAR_BASE;
	dt.mm = tm.tm_mon + 1;
	dt.dd = tm.tm_mday;

	if (has_default && rpt->until != 0) {
		struct tm tu;
		localtime_r_safe(rpt->until, &tu);
		strftime(buf, sizeof(buf), DATEFMT(conf.input_datefmt), &tu);
	} else if (has_default) {
		strcpy(buf, "0");
	}

	for (;;) {
		int ret;
		time_t until;
		status_mesg(_("Until date, increment or repeat count ('?' for input formats):"), "");
		ret = getstring(win[STA].p, buf, BUFSIZ_LINE, 0, 1);
		if (ret == GETSTRING_ESC)
			return 0;
		if (ret == GETSTRING_RET || !strcmp(buf, "0")) {
			rpt->until = 0;
			return 1;
		}
		if (!strcmp(buf, "?")) {
			show_until_help();
			buf[0] = '\0';
			continue;
		}
		if (buf[0] == '#') {
			long n;
			if (strtol_safe(buf + 1, &n) && n > 0) {
				time_t nth;
				time_t saved = rpt->until;
				rpt->until = 0;
				if (recur_nth_occurrence(start, dur, exc, rpt, (int)n, &nth)) {
					rpt->until = nth;
					return 1;
				}
				rpt->until = saved;
			}
			press_any_key_msg(_("Invalid date."));
			buf[0] = '\0';
			continue;
		}
		if (buf[0] == '+') {
			/* increment: +days or +Nw+Nd */
			const char *p = buf + 1;
			long days = 0, n = 0;
			int ok = 1, any = 0;
			while (*p && ok) {
				if (isdigit((unsigned char)*p)) {
					n = n * 10 + (*p - '0');
					any = 1;
					p++;
				} else if (*p == 'w') {
					days += n * 7;
					n = 0;
					any = 0;
					p++;
				} else if (*p == 'd') {
					days += n;
					n = 0;
					any = 0;
					p++;
				} else {
					ok = 0;
				}
			}
			if (any)
				days += n;
			if (!ok || days <= 0 || buf[1] == '\0') {
				press_any_key_msg(_("Invalid date."));
				buf[0] = '\0';
				continue;
			}
			until = date_sec_change(start, 0, (int)days);
			rpt->until = until;
			return 1;
		}
		if (parse_date(buf, conf.input_datefmt, &y, &m, &d, &dt)) {
			struct date du;
			du.yyyy = y;
			du.mm = m;
			du.dd = d;
			until = date2sec(du, get_item_hour(start), get_item_min(start));
			if (until < start) {
				press_any_key_msg(_("Until date must come after the start date."));
				buf[0] = '\0';
				continue;
			}
			rpt->until = until;
			return 1;
		}
		press_any_key_msg(_("Invalid date."));
		buf[0] = '\0';
	}
}

static const char *weekday_abbr[7] = { "Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun" };

static int parse_wday_token(const char *tok, enum recur_type type, int *val)
{
	const char *p = tok;
	int order = 0, sign = 1, i;
	int ndig = 0;
	if (*p == '-') {
		sign = -1;
		p++;
	}
	while (isdigit((unsigned char)*p)) {
		order = order * 10 + (*p - '0');
		p++;
		ndig++;
	}
	for (i = 0; i < 7; i++) {
		if (!strcasecmp(p, weekday_abbr[i]))
			break;
	}
	if (i == 7)
		return 0;
	{
		int wday = (i + 1) % 7;	/* Mon=1 .. Sun=0 */
		if (ndig == 0) {
			if (sign < 0)
				return 0;
			*val = wday;
			return 1;
		}
		if (type == RECUR_DAILY || type == RECUR_WEEKLY)
			return 0;
		if (order == 0)
			return 0;
		if (type == RECUR_MONTHLY && order > 5)
			return 0;
		if (type == RECUR_YEARLY && order > 53)
			return 0;
		*val = sign * (order * 7 + wday);
		return 1;
	}
}

static char *int_list_to_str(llist_t *l, int wday)
{
	llist_item_t *i;
	char *res = mem_strdup("");
	LLIST_FOREACH(l, i) {
		int v = *(int *)LLIST_GET_DATA(i);
		char *tmp, *s;
		if (wday)
			s = recur_wday_str(v);
		else
			s = strdup_printf("%d", v);
		tmp = strdup_printf("%s%s%s", res, *res ? " " : "", s);
		mem_free(s);
		mem_free(res);
		res = tmp;
	}
	return res;
}

/* Ask for the advanced lists. Returns 0 if cancelled. */
static int ask_lists(struct rpt *rpt, int has_default)
{
	char buf[BUFSIZ_LINE];
	int ret;

	/* weekdays */
	for (;;) {
		char *s;
		const char *prompt;
		if (rpt->type == RECUR_MONTHLY)
			prompt = _("Weekdays [n]Mon|..|[n]Sun, space-separated list, n=1,-1,..,5,-5, '?' for help:");
		else if (rpt->type == RECUR_YEARLY)
			prompt = _("Weekdays [n]Mon|..|[n]Sun, space-separated list, n=1,-1,..,53,-53, '?' for help:");
		else
			prompt = _("Weekdays Mon|..|Sun, space-separated list, '?' for help:");
		s = has_default ? int_list_to_str(&rpt->bywday, 1) : mem_strdup("");
		snprintf(buf, sizeof(buf), "%s", s);
		mem_free(s);
		status_mesg(prompt, "");
		ret = getstring(win[STA].p, buf, BUFSIZ_LINE, 0, 1);
		if (ret == GETSTRING_ESC)
			return 0;
		if (!strcmp(buf, "?")) {
			switch (rpt->type) {
			case RECUR_DAILY:
				status_mesg(_("Limit repetition to listed days."), "");
				break;
			case RECUR_WEEKLY:
				status_mesg(_("Expand repetition to listed days."), "");
				break;
			case RECUR_MONTHLY:
				status_mesg(_("Expand repetition to listed days, either all or 1st, 2nd, ... of month."),
					    _("Note: limit to monthdays, if any."));
				break;
			default:
				status_mesg(_("Expand repetition to listed days, either all or 1st, 2nd, ... of year."),
					    _("Note: expand to listed months, if any; limit to monthdays, if any."));
				break;
			}
			ui_wgetch(win[STA].p);
			has_default = 0;
			continue;
		}
		{
			char *cp = mem_strdup(buf), *p, *sv = NULL;
			llist_t l;
			int ok = 1;
			LLIST_INIT(&l);
			for (p = strtok_r(cp, " ", &sv); p; p = strtok_r(NULL, " ", &sv)) {
				int v;
				if (!parse_wday_token(p, rpt->type, &v)) {
					ok = 0;
					break;
				}
				{
					int *pv = mem_malloc(sizeof(int));
					*pv = v;
					LLIST_ADD(&l, pv);
				}
			}
			mem_free(cp);
			if (!ok) {
				recur_free_int_list(&l);
				press_any_key_msg(_("Invalid weekday list."));
				continue;
			}
			recur_free_int_list(&rpt->bywday);
			rpt->bywday = l;
			break;
		}
	}
	/* months */
	for (;;) {
		char *s = has_default ? int_list_to_str(&rpt->bymonth, 0) : mem_strdup("");
		snprintf(buf, sizeof(buf), "%s", s);
		mem_free(s);
		status_mesg(_("Months 1|..|12, space-separated list, '?' for help:"), "");
		ret = getstring(win[STA].p, buf, BUFSIZ_LINE, 0, 1);
		if (ret == GETSTRING_ESC)
			return 0;
		if (!strcmp(buf, "?")) {
			if (rpt->type == RECUR_YEARLY)
				status_mesg(_("Expand repetition to listed months."), "");
			else
				status_mesg(_("Limit repetition to listed months."), "");
			ui_wgetch(win[STA].p);
			has_default = 0;
			continue;
		}
		{
			char *cp = mem_strdup(buf), *p, *sv = NULL;
			llist_t l;
			int ok = 1;
			LLIST_INIT(&l);
			for (p = strtok_r(cp, " ", &sv); p; p = strtok_r(NULL, " ", &sv)) {
				long v;
				if (!strtol_safe(p, &v) || v < 1 || v > 12) {
					ok = 0;
					break;
				}
				{
					int *pv = mem_malloc(sizeof(int));
					*pv = (int)v;
					LLIST_ADD(&l, pv);
				}
			}
			mem_free(cp);
			if (!ok) {
				recur_free_int_list(&l);
				press_any_key_msg(_("Invalid month list."));
				continue;
			}
			recur_free_int_list(&rpt->bymonth);
			rpt->bymonth = l;
			break;
		}
	}
	/* monthdays */
	if (rpt->type == RECUR_WEEKLY)
		return 1;
	for (;;) {
		char *s = has_default ? int_list_to_str(&rpt->bymonthday, 0) : mem_strdup("");
		snprintf(buf, sizeof(buf), "%s", s);
		mem_free(s);
		status_mesg(_("Monthdays 1|..|31 or -1|..|-31, space-separated list, '?' for help:"), "");
		ret = getstring(win[STA].p, buf, BUFSIZ_LINE, 0, 1);
		if (ret == GETSTRING_ESC)
			return 0;
		if (!strcmp(buf, "?")) {
			if (rpt->type == RECUR_DAILY)
				status_mesg(_("Limit repetition to listed days of month."), "");
			else
				status_mesg(_("Expand repetition to listed days of month."), "");
			ui_wgetch(win[STA].p);
			has_default = 0;
			continue;
		}
		{
			char *cp = mem_strdup(buf), *p, *sv = NULL;
			llist_t l;
			int ok = 1;
			LLIST_INIT(&l);
			for (p = strtok_r(cp, " ", &sv); p; p = strtok_r(NULL, " ", &sv)) {
				long v;
				if (!strtol_safe(p, &v) || v == 0 || v > 31 || v < -31) {
					ok = 0;
					break;
				}
				{
					int *pv = mem_malloc(sizeof(int));
					*pv = (int)v;
					LLIST_ADD(&l, pv);
				}
			}
			mem_free(cp);
			if (!ok) {
				recur_free_int_list(&l);
				press_any_key_msg(_("Invalid monthday list."));
				continue;
			}
			recur_free_int_list(&rpt->bymonthday);
			rpt->bymonthday = l;
			break;
		}
	}
	return 1;
}

/*
 * Ask for a complete repetition specification.  rpt is updated in place.
 * Returns 1 on success, 0 if cancelled.
 */
static int ask_repetition(time_t start, long dur, struct rpt *rpt, llist_t *exc, int has_default)
{
	const char choices[] = { 's', 'a' };
	int ch, advanced;

	ch = status_ask_choice(_("A (s)imple or (a)dvanced repetition?"), choices, 2);
	if (ch == -1)
		return 0;
	advanced = (ch == 2);
	if (!ask_base_period(&rpt->type, has_default))
		return 0;
	if (!has_default)
		rpt->freq = 1;
	if (!ask_frequency(&rpt->freq))
		return 0;
	if (!ask_until(start, dur, rpt, exc, has_default))
		return 0;
	if (advanced) {
		if (!ask_lists(rpt, has_default))
			return 0;
	} else {
		recur_free_int_list(&rpt->bywday);
		recur_free_int_list(&rpt->bymonth);
		recur_free_int_list(&rpt->bymonthday);
		LLIST_INIT(&rpt->bywday);
		LLIST_INIT(&rpt->bymonth);
		LLIST_INIT(&rpt->bymonthday);
	}
	return 1;
}

static int check_rpt(time_t start, struct rpt *rpt)
{
	if (rpt->type == RECUR_WEEKLY && LLIST_FIRST(&rpt->bymonthday)) {
		press_any_key_msg(_("Monthdays are not allowed with a weekly repetition."));
		return 0;
	}
	if (!recur_check_rule(start, rpt)) {
		press_any_key_msg(_("The start date is not part of the repetition."));
		return 0;
	}
	return 1;
}

void ui_day_item_repeat(void)
{
	struct day_item *d = ui_day_get_sel();
	struct rpt *rpt;
	llist_t exc;
	time_t start;
	long dur;
	void *newptr = NULL;

	if (!d)
		return;
	if (item_is_recur(d)) {
		press_any_key_msg(_("Already repeated."));
		return;
	}
	rpt = recur_rpt_new();
	rpt->type = RECUR_DAILY;
	rpt->freq = 1;
	LLIST_INIT(&exc);
	if (d->type == APPT) {
		start = d->item.apt->start;
		dur = d->item.apt->dur;
	} else {
		start = d->item.ev->day;
		dur = DAYINSEC;
	}
	if (!ask_repetition(start, dur, rpt, &exc, 0) || !check_rpt(start, rpt)) {
		recur_rpt_free(rpt);
		return;
	}
	if (d->type == APPT) {
		struct apoint *apt = d->item.apt;
		struct recur_apoint *rapt = recur_apoint_new(apt->mesg, apt->note, apt->start, apt->dur,
							     apt->state, rpt, &exc);
		newptr = rapt;
		apoint_delete(apt);
		if (notify_bar())
			notify_check_repeated(rapt);
	} else {
		struct event *ev = d->item.ev;
		struct recur_event *rev = recur_event_new(ev->mesg, ev->note, ev->day, ev->id, rpt, &exc);
		newptr = rev;
		event_delete(ev);
	}
	io_set_modified();
	ui_day_load_items();
	ui_day_set_selitem_by_aptev_ptr(newptr);
}

/* ---- edit ---- */

static void edit_description(char **mesg)
{
	status_mesg(_("Enter the new item description:"), "");
	updatestring(win[STA].p, mesg, 0, 1);
}

static int edit_start(time_t *start, long *dur, int move)
{
	char buf[BUFSIZ_LINE];
	struct tm tm;
	char dbuf[BUFSIZ_LINE];
	time_t newstart;

	for (;;) {
		int ret;
		localtime_r_safe(*start, &tm);
		strftime(dbuf, sizeof(dbuf), DATEFMT(conf.input_datefmt), &tm);
		snprintf(buf, sizeof(buf), "%s %02d:%02d", dbuf, tm.tm_hour, tm.tm_min);
		{
			char *prompt = strdup_printf(_("Enter start date [%s] and/or time ([hh:mm] or [hhmm]):"),
						     DATEFMT_DESC(conf.input_datefmt));
			status_mesg(prompt, "");
			mem_free(prompt);
		}
		ret = getstring(win[STA].p, buf, BUFSIZ_LINE, 0, 1);
		if (ret == GETSTRING_ESC)
			return 0;
		if (ret == GETSTRING_RET)
			continue;
		newstart = parse_date_time_rel(buf, *start, 1);
		if (newstart == -1) {
			press_enter_msg(_("Invalid date or time."));
			continue;
		}
		if (!move) {
			time_t end = *start + *dur;
			if (newstart > end) {
				press_enter_msg(_("Invalid date or time."));
				continue;
			}
			*dur = end - newstart;
		}
		*start = newstart;
		return 1;
	}
}

static int edit_end(time_t start, long *dur)
{
	char buf[BUFSIZ_LINE];
	struct tm tm;
	char dbuf[BUFSIZ_LINE];
	time_t end;

	localtime_r_safe(start + *dur, &tm);
	strftime(dbuf, sizeof(dbuf), DATEFMT(conf.input_datefmt), &tm);
	snprintf(buf, sizeof(buf), "%s %02d:%02d", dbuf, tm.tm_hour, tm.tm_min);
	if (!ask_end(start, &end, _("Enter end date (and/or time) or duration ('?' for input formats):"), buf))
		return 0;
	*dur = end - start;
	return 1;
}

void ui_day_item_edit(void)
{
	struct day_item *d = ui_day_get_sel();
	int ch;

	if (!d)
		return;
	switch (d->type) {
	case EVNT:
		edit_description(&d->item.ev->mesg);
		io_set_modified();
		break;
	case RECUR_EVNT: {
		const char choices[] = { '1', '2' };
		ch = status_ask_choice(_("Edit: (1) Description, (2) Repetition?"), choices, 2);
		if (ch == 1) {
			edit_description(&d->item.rev->mesg);
			io_set_modified();
		} else if (ch == 2) {
			struct recur_event *rev = d->item.rev;
			struct rpt *rpt = recur_rpt_dup(rev->rpt);
			llist_t exc;
			recur_exc_dup(&exc, &rev->exc);
			if (ask_repetition(rev->day, DAYINSEC, rpt, &exc, 1) && check_rpt(rev->day, rpt)) {
				recur_rpt_free(rev->rpt);
				rev->rpt = rpt;
				recur_free_exc_list(&rev->exc);
				LLIST_INIT(&rev->exc);
				io_set_modified();
			} else {
				recur_rpt_free(rpt);
			}
			recur_free_exc_list(&exc);
		}
		break;
	}
	case APPT: {
		const char choices[] = { '1', '2', '3', '4' };
		struct apoint *apt = d->item.apt;
		ch = status_ask_choice(_("Edit: (1) Start time, (2) End time, (3) Description, (4) Move?"), choices, 4);
		switch (ch) {
		case 1: {
			time_t start = apt->start;
			long dur = apt->dur;
			if (edit_start(&start, &dur, 0)) {
				apoint_delete_quiet_resort(apt, start, dur);
				io_set_modified();
			}
			break;
		}
		case 2: {
			long dur = apt->dur;
			if (edit_end(apt->start, &dur)) {
				apt->dur = dur;
				io_set_modified();
			}
			break;
		}
		case 3:
			edit_description(&apt->mesg);
			io_set_modified();
			break;
		case 4: {
			time_t start = apt->start;
			long dur = apt->dur;
			if (edit_start(&start, &dur, 1)) {
				apoint_delete_quiet_resort(apt, start, dur);
				io_set_modified();
			}
			break;
		}
		default:
			break;
		}
		if (notify_bar())
			notify_check_next_app(1);
		break;
	}
	case RECUR_APPT: {
		const char choices[] = { '1', '2', '3', '4', '5' };
		struct recur_apoint *rapt = d->item.rapt;
		ch = status_ask_choice(_("Edit: (1) Start time, (2) End time, (3) Description, (4) Repetition, (5) Move?"), choices, 5);
		switch (ch) {
		case 1: {
			time_t start = rapt->start;
			long dur = rapt->dur;
			if (edit_start(&start, &dur, 0)) {
				recur_apoint_resort(rapt, start, dur);
				io_set_modified();
			}
			break;
		}
		case 2: {
			long dur = rapt->dur;
			if (edit_end(rapt->start, &dur)) {
				rapt->dur = dur;
				io_set_modified();
			}
			break;
		}
		case 3:
			edit_description(&rapt->mesg);
			io_set_modified();
			break;
		case 4: {
			struct rpt *rpt = recur_rpt_dup(rapt->rpt);
			llist_t exc;
			recur_exc_dup(&exc, &rapt->exc);
			if (ask_repetition(rapt->start, rapt->dur, rpt, &exc, 1) && check_rpt(rapt->start, rpt)) {
				recur_rpt_free(rapt->rpt);
				rapt->rpt = rpt;
				recur_free_exc_list(&rapt->exc);
				LLIST_INIT(&rapt->exc);
				io_set_modified();
			} else {
				recur_rpt_free(rpt);
			}
			recur_free_exc_list(&exc);
			break;
		}
		case 5: {
			time_t start = rapt->start;
			long dur = rapt->dur;
			if (edit_start(&start, &dur, 1)) {
				recur_apoint_resort(rapt, start, dur);
				io_set_modified();
			}
			break;
		}
		default:
			break;
		}
		if (notify_bar())
			notify_check_next_app(1);
		break;
	}
	}
	ui_day_load_items();
	ui_day_set_selitem_by_aptev_ptr(d->item.ptr);
}

/* ---- misc actions ---- */

void ui_day_flag(void)
{
	struct day_item *d = ui_day_get_sel();
	if (!d)
		return;
	if (d->type == APPT || d->type == RECUR_APPT) {
		day_item_switch_notify(d);
		io_set_modified();
	}
}

static const char *item_type_title(struct day_item *d)
{
	switch (d->type) {
	case APPT:
	case RECUR_APPT:
		return _("Appointment:");
	default:
		return _("Event:");
	}
}

/* Show the selected item in a popup window. */
void ui_day_popup_item(void)
{
	struct day_item *d = ui_day_get_sel();
	WINDOW *popup;
	int h = row - 5, w = col - 4, y = 1, x = 2;
	const char *title;
	char *mesg;
	int len;

	if (!d)
		return;
	if (h < 5 || w < 10)
		return;
	title = item_type_title(d);
	popup = newwin(h, w, y, x);
	keypad(popup, TRUE);
	box(popup, 0, 0);
	mvwaddch(popup, 2, 0, ACS_LTEE);
	mvwhline(popup, 2, 1, ACS_HLINE, w - 2);
	mvwaddch(popup, 2, w - 1, ACS_RTEE);
	len = string_width(title);
	custom_apply_attr(popup, ATTR_HIGHEST);
	mvwaddstr(popup, 1, (w - len) / 2, title);
	custom_remove_attr(popup, ATTR_HIGHEST);
	mesg = day_item_get_mesg(d);
	if (d->type == APPT || d->type == RECUR_APPT) {
		char s[32], e[32];
		time_t day = ui_day_sel_date();
		time_t start = d->start;
		long dur = day_item_get_duration(d);
		struct tm tm;
		if (start < day)
			strcpy(s, "..:..");
		else {
			localtime_r_safe(start, &tm);
			strftime(s, sizeof(s), conf.timefmt, &tm);
		}
		if (start + dur > NEXTDAY(day))
			strcpy(e, "..:..");
		else {
			localtime_r_safe(start + dur, &tm);
			strftime(e, sizeof(e), conf.timefmt, &tm);
		}
		mvwprintw(popup, 4, 3, "- %s -> %s", s, e);
		mvwaddstr(popup, 5, 5, mesg);
	} else {
		mvwaddstr(popup, 5, 5, mesg);
	}
	{
		const char *msg = _("Press any key to continue...");
		mvwaddstr(popup, h - 2, w - 2 - string_width(msg), msg);
	}
	wrefresh(popup);
	ui_wgetch(popup);
	delwin(popup);
}

void ui_day_view_note(void)
{
	struct day_item *d = ui_day_get_sel();
	char *note;
	if (!d)
		return;
	note = day_item_get_note(d);
	if (!note)
		return;
	wins_prepare_external();
	view_note(note, conf.pager);
	wins_unprepare_external();
}

void ui_day_edit_note(void)
{
	struct day_item *d = ui_day_get_sel();
	char **notep;
	if (!d)
		return;
	switch (d->type) {
	case APPT:
		notep = &d->item.apt->note;
		break;
	case EVNT:
		notep = &d->item.ev->note;
		break;
	case RECUR_APPT:
		notep = &d->item.rapt->note;
		break;
	case RECUR_EVNT:
		notep = &d->item.rev->note;
		break;
	default:
		return;
	}
