/* Change start and duration of an appointment, keeping the list sorted. */
void apoint_delete_quiet_resort(struct apoint *apt, time_t start, long dur)
{
	llist_item_t *i;
	LLIST_FOREACH(&alist_p, i) {
		if (LLIST_GET_DATA(i) == apt)
			break;
	}
	if (i)
		LLIST_REMOVE(&alist_p, i);
	apt->start = start;
	apt->dur = dur;
	LLIST_ADD_SORTED(&alist_p, apt, apoint_cmp);
}
