cat >> src/recur.c <<'EOF'

void recur_apoint_resort(struct recur_apoint *rapt, time_t start, long dur)
{
	llist_item_t *i;
	long shift = start - rapt->start;
	LLIST_FOREACH(&recur_alist_p, i) {
		if (LLIST_GET_DATA(i) == rapt)
			break;
	}
	if (i)
		LLIST_REMOVE(&recur_alist_p, i);
	rapt->start = start;
	rapt->dur = dur;
	if (rapt->rpt->until != 0)
		rapt->rpt->until += shift;
	LLIST_ADD_SORTED(&recur_alist_p, rapt, recur_apoint_cmp);
}
