		return;
	todo_flag(t);
	ui_todo_load_items();
	ui_todo_set_sel(t);
	io_set_modified();
}

void ui_todo_view_note(void)
{
	struct todo *t = ui_todo_selitem();
	if (!t || !t->note)
		return;
	wins_prepare_external();
	view_note(t->note, conf.pager);
	wins_unprepare_external();
}

void ui_todo_edit_note(void)
{
	struct todo *t = ui_todo_selitem();
	if (!t)
		return;
	wins_prepare_external();
	edit_note(&t->note, conf.editor);
	wins_unprepare_external();
	io_set_modified();
}
