#include <term.h>

static int corner_dirty = 0;

/*
 * Write a character with the highlight color into the bottom right corner
 * of the screen, bypassing curses (which refuses to draw a blank there).
 * (cy, cx) is the cursor position (window coordinates) to restore.
 */
void wins_corner_raw(WINDOW *w, int y, int x, int c, int cx)
{
	int by, bx;
	const char *cup;
	getbegyx(w, by, bx);
	if (by + y != LINES - 1 || bx + x != COLS - 1)
		return;
	cup = tigetstr("cup");
	if (!cup || cup == (char *)-1)
		return;
	putp(tparm(cup, LINES - 1, COLS - 1));
	if (colorize && conf.color_fg >= 0 && set_a_foreground)
		putp(tparm(set_a_foreground, conf.color_fg));
	if (colorize && conf.color_bg >= 0 && set_a_background)
		putp(tparm(set_a_background, conf.color_bg));
	putchar(c);
	if (exit_attribute_mode)
		putp(exit_attribute_mode);
	fflush(stdout);
	corner_dirty = 1;
	mvcur(-1, -1, by + y, bx + cx);
	fflush(stdout);
}

/* Clear a raw corner cell written by wins_corner_raw(). */
void wins_corner_clear(void)
{
	int y, x;
	const char *cup;
	if (!corner_dirty)
		return;
	corner_dirty = 0;
	cup = tigetstr("cup");
	if (!cup || cup == (char *)-1)
		return;
	getsyx(y, x);
	putp(tparm(cup, LINES - 1, COLS - 1));
	if (exit_attribute_mode)
		putp(exit_attribute_mode);
	putchar(' ');
	fflush(stdout);
	if (y >= 0 && x >= 0)
		mvcur(-1, -1, y, x);
	fflush(stdout);
}
