{"command":"cd /workspace; cat > src/ui-io.c <<'EOF'
#include "ui.h"

/* Ask for the file name to import; returns a malloc'ed string or NULL. */
char *ui_ask_import_file(void)
{
	static char buf[BUFSIZ_LINE];
	int ret;

	status_mesg(_("Enter the file name to import data from:"), "");
	ret = getstring(win[STA].p, buf, BUFSIZ_LINE, 0, 1);
	if (ret != GETSTRING_VALID)
		return NULL;
	return mem_strdup(buf);
}

/* Show the import report in the status bar and wait for a key. */
void ui_import_report(const char *proc_report, unsigned lines, char **stats_str)
{
	char *l1, *l2;
	if (!conf.system_dialogs && !quiet) {
		/* system dialogs disabled: no report */
	}
	if (quiet || !conf.system_dialogs)
		return;
	l1 = strdup_printf(proc_report, lines);
	l2 = strdup_printf("%s / %s / %s / %s (%s)", stats_str[1], stats_str[0], stats_str[2], stats_str[3],
			   _("Press [ENTER] to continue"));
	status_mesg(l1, l2);
	ui_wgetch(win[STA].p);
	mem_free(l1);
	mem_free(l2);
}

/* Ask whether to display the import log. */
void ui_import_log_ask(const char *logname)
{
	if (status_ask_bool(_("Some items could not be imported. Display log file?"))) {
		const char *arg[] = { conf.pager, logname, NULL };
		wins_prepare_external();
		{
			int pid = shell_exec(NULL, NULL, NULL, conf.pager, arg);
			if (pid > 0)
				child_wait(NULL, NULL, NULL, pid);
		}
		wins_unprepare_external();
	}
	wins_update(FLAG_STA);
}

/* Interactive export. */
void ui_export_dialog(void)
{
	const char choices[] = { 'i', 'p' };
	int ch;
	char buf[BUFSIZ_LINE];
	const char *home = getenv("HOME");
	FILE *stream;
	enum export_type type;

	ch = status_ask_choice(_("Export to (i)cal or (p)cal format?"), choices, 2);
	if (ch == -1)
		return;
	type = (ch == 1) ? IO_EXPORT_ICAL : IO_EXPORT_PCAL;
	if (!home)
		home = ".";
	snprintf(buf, sizeof(buf), "%s/calcurse.%s", home, type == IO_EXPORT_ICAL ? "ics" : "txt");
	for (;;) {
		int ret;
		status_mesg(_("Choose the file used to export calcurse data:"), "");
		ret = getstring(win[STA].p, buf, BUFSIZ_LINE, 0, 1);
		if (ret == GETSTRING_ESC)
			return;
		if (ret == GETSTRING_RET)
			continue;
		stream = fopen(buf, "w");
		if (!stream) {
			status_mesg(_("The file cannot be accessed, please enter another file name."),
				    _("Press [ENTER] to continue."));
			ui_wgetch(win[STA].p);
			continue;
		}
		break;
	}
	if (type == IO_EXPORT_ICAL)
		ical_export_data(stream, 0);
	else
		pcal_export_data(stream);
	fclose(stream);
	if (conf.system_dialogs && !quiet) {
		status_mesg(_("The data were successfully exported"), _("Press [ENTER] to continue"));
		ui_wgetch(win[STA].p);
	}
}
