	case 1: return conf.default_panel == APP ? _("Appointments") : conf.default_panel == TOD ? _("TODO") : _("Calendar");
	case 2: return conf.cal_view == CAL_WEEK_VIEW ? _("weekly") : _("monthly");
	case 3: return conf.todo_view == TODO_SHOW_COMPLETED_VIEW ? _("show completed") : _("hide completed");
	case 4: *is_bool = 1; *bval = conf.multiple_days; break;
	case 5: *is_bool = 1; *bval = conf.header_line; break;
	case 6: *is_bool = 1; *bval = conf.event_separator; break;
	case 7: *is_bool = 1; *bval = conf.day_separator; break;
	case 8: *is_bool = 1; *bval = conf.empty_appt_line; break;
	case 9: return conf.empty_day;
	case 10: *is_bool = 1; *bval = conf.auto_save; break;
	case 11: *is_bool = 1; *bval = conf.auto_gc; break;
	case 12: snprintf(buf, sz, "%u", conf.periodic_save); return buf;
	case 13: *is_bool = 1; *bval = conf.systemevents; break;
	case 14: *is_bool = 1; *bval = conf.confirm_quit; break;
	case 15: *is_bool = 1; *bval = conf.confirm_delete; break;
	case 16: return weekday_full[conf.first_day_of_week % 7];
	case 17: return conf.output_datefmt;
	case 18: snprintf(buf, sz, "%d", conf.input_datefmt); return buf;
	case 19: return conf.heading_pos == LEFT ? _("to the left") : conf.heading_pos == CENTER ? _("in the middle") : _("to the right");
	case 20: return conf.day_heading;
	case 21: return conf.timefmt;
	}
	return "";
}

static const char *notify_value(int i, int *is_bool, int *bval, char *buf, size_t sz)
{
	*is_bool = 0;
	*bval = 0;
	switch (i) {
	case 0: *is_bool = 1; *bval = conf.notify_bar; break;
	case 1: return conf.notify_date;
	case 2: return conf.notify_time;
	case 3: snprintf(buf, sz, "%d", conf.notify_warning); return buf;
	case 4: return conf.notify_cmd;
	case 5: return conf.notify_all == NOTIFY_ALL ? "all" : conf.notify_all == NOTIFY_UNFLAGGED_ONLY ? "unflagged-only" : "flagged-only";
	case 6: *is_bool = 1; *bval = conf.daemon_enable; break;
	case 7: *is_bool = 1; *bval = conf.daemon_log; break;
	}
	return "";
}

static void options_draw(struct scrollwin *sw, const struct conf_item *items, int n,
			 const char *(*value)(int, int *, int *, char *, size_t), int sel)
{
	int i, y = 0;
	char buf[BUFSIZ_LINE];
	int total = 0;

	for (i = 0; i < n; i++)
		total += items[i].lines;
	wins_scrollwin_set_linecount(sw, total);
	werase(sw->inner);
	for (i = 0; i < n; i++) {
		int is_bool, bval;
		const char *v = value(i, &is_bool, &bval, buf, sizeof(buf));
		if (i == sel)
			custom_apply_attr(sw->inner, ATTR_HIGHEST);
		mvwprintw(sw->inner, y, 0, "%s = ", items[i].name);
		if (i == sel)
			custom_remove_attr(sw->inner, ATTR_HIGHEST);
		if (is_bool) {
			custom_apply_attr(sw->inner, bval ? ATTR_TRUE : ATTR_FALSE);
			waddstr(sw->inner, bval ? _("yes") : _("no"));
			custom_remove_attr(sw->inner, bval ? ATTR_TRUE : ATTR_FALSE);
		} else {
			custom_apply_attr(sw->inner, ATTR_HIGHEST);
			waddstr(sw->inner, v);
			custom_remove_attr(sw->inner, ATTR_HIGHEST);
		}
		mvwaddstr(sw->inner, y + 1, 0, items[i].desc1);
		if (items[i].desc2)
			mvwaddstr(sw->inner, y + 2, 0, items[i].desc2);
		y += items[i].lines;
	}
}

static int options_line_of(const struct conf_item *items, int sel)
{
	int i, y = 0;
	for (i = 0; i < sel; i++)
		y += items[i].lines;
	return y;
}

static void options_ensure_visible(struct scrollwin *sw, const struct conf_item *items, int sel)
{
	int first = options_line_of(items, sel);
	int last = first + items[sel].lines - 1;
	int h = (int)sw->inner_h;
	if ((unsigned)first < sw->line_off)
		sw->line_off = first;
	else if ((unsigned)last >= sw->line_off + h)
		sw->line_off = last - h + 1;
}

static int ask_string_option(const char *prompt, char *dest, size_t size)
{
	char buf[BUFSIZ_LINE];
	int ret;
	snprintf(buf, sizeof(buf), "%s", dest);
	status_mesg(prompt, "");
	ret = getstring(win[STA].p, buf, BUFSIZ_LINE, 0, 1);
	if (ret == GETSTRING_VALID) {
		snprintf(dest, size, "%s", buf);
		return 1;
	}
	if (ret == GETSTRING_RET)
		return 2;
	return 0;
}

static void general_edit(int i)
{
	char buf[BUFSIZ_LINE];
	switch (i) {
	case 0: conf.compact_panels = !conf.compact_panels; wins_reinit(); break;
	case 1: conf.default_panel = (conf.default_panel + 1) % 3; break;
	case 2: conf.cal_view = (conf.cal_view + 1) % CAL_VIEWS; ui_calendar_set_view(conf.cal_view); break;
	case 3: conf.todo_view = (conf.todo_view + 1) % TODO_VIEWS; ui_todo_set_view(conf.todo_view); break;
	case 4: conf.multiple_days = !conf.multiple_days; break;
	case 5: conf.header_line = !conf.header_line; break;
	case 6: conf.event_separator = !conf.event_separator; break;
	case 7: conf.day_separator = !conf.day_separator; break;
	case 8: conf.empty_appt_line = !conf.empty_appt_line; break;
	case 9: {
		int r = ask_string_option(_("Enter a text string (an empty string for the default text)"), conf.empty_day, sizeof(conf.empty_day));
		if (r == 2)
			strcpy(conf.empty_day, "--");
		break;
	}
	case 10: conf.auto_save = !conf.auto_save; break;
	case 11: conf.auto_gc = !conf.auto_gc; break;
	case 12:
		snprintf(buf, sizeof(buf), "%u", conf.periodic_save);
		status_mesg(_("Enter the delay, in minutes, between automatic saves (0 to disable)"), "");
		if (getstring(win[STA].p, buf, BUFSIZ_LINE, 0, 1) == GETSTRING_VALID && is_all_digit(buf))
			conf.periodic_save = atoi(buf);
		break;
	case 13: conf.systemevents = !conf.systemevents; break;
	case 14: conf.confirm_quit = !conf.confirm_quit; break;
	case 15: conf.confirm_delete = !conf.confirm_delete; break;
	case 16:
		conf.first_day_of_week = (conf.first_day_of_week + 1) % 7;
		ui_calendar_set_first_day_of_week(conf.first_day_of_week);
		break;
	case 17:
		ask_string_option(_("Enter the date format (see 'man 3 strftime' for possible formats)"), conf.output_datefmt, sizeof(conf.output_datefmt));
		break;
	case 18: {
		const char choices[] = { '1', '2', '3', '4' };
		int c = status_ask_choice(_("Enter the date format: (1) mm/dd/yyyy, (2) dd/mm/yyyy, (3) yyyy/mm/dd, (4) yyyy-mm-dd"), choices, 4);
		if (c > 0)
			conf.input_datefmt = c;
		break;
	}
	case 19: conf.heading_pos = (conf.heading_pos + 1) % 3; break;
	case 20:
		ask_string_option(_("Enter the date format (see 'man 3 strftime' for possible formats)"), conf.day_heading, sizeof(conf.day_heading));
		break;
	case 21:
		ask_string_option(_("Enter the time format (see 'man 3 strftime' for possible formats)"), conf.timefmt, sizeof(conf.timefmt));
		break;
	}
}

static void notify_edit(int i)
{
	char buf[BUFSIZ_LINE];
	switch (i) {
	case 0:
		conf.notify_bar = !conf.notify_bar;
		wins_reinit();
		break;
	case 1:
		ask_string_option(_("Enter the date format (see 'man 3 strftime' for possible formats)"), conf.notify_date, sizeof(conf.notify_date));
		break;
	case 2:
		ask_string_option(_("Enter the time format (see 'man 3 strftime' for possible formats)"), conf.notify_time, sizeof(conf.notify_time));
		break;
	case 3:
		snprintf(buf, sizeof(buf), "%d", conf.notify_warning);
		status_mesg(_("Enter the number of seconds (0 not to be warned before an appointment)"), "");
		if (getstring(win[STA].p, buf, BUFSIZ_LINE, 0, 1) == GETSTRING_VALID && is_all_digit(buf))
			conf.notify_warning = atoi(buf);
		break;
	case 4:
		ask_string_option(_("Enter the notification command"), conf.notify_cmd, sizeof(conf.notify_cmd));
		break;
	case 5:
		conf.notify_all = (conf.notify_all + 1) % 3;
		break;
	case 6:
		conf.daemon_enable = !conf.daemon_enable;
		break;
	case 7:
		conf.daemon_log = !conf.daemon_log;
		break;
	}
}

static void options_menu(const char *title, const struct conf_item *items, int n,
			 const char *(*value)(int, int *, int *, char *, size_t), void (*edit)(int))
{
	struct scrollwin sw;
	int sel = 0;
	int ch, action;

	conf_win_init(&sw, title);
	for (;;) {
		options_draw(&sw, items, n, value, sel);
		options_ensure_visible(&sw, items, sel);
		conf_win_display(&sw);
		custom_status_bar(sbar_keys_options, 4);
		ch = ui_wgetch(win[STA].p);
		action = keys_get_action(ch);
		if (action == KEY_GENERIC_QUIT || action == KEY_GENERIC_CANCEL)
			break;
		switch (action) {
		case KEY_MOVE_DOWN:
			if (sel < n - 1)
				sel++;
			break;
		case KEY_MOVE_UP:
			if (sel > 0)
				sel--;
			break;
		case KEY_EDIT_ITEM:
			edit(sel);
			if (conf_win_resize_needed())
				conf_win_init_resized(&sw, title);
			break;
		default:
			break;
		}
	}
	wins_scrollwin_delete(&sw);
}

static int conf_win_resize_flag = 0;

int conf_win_resize_needed(void)
{
	int r = conf_win_resize_flag;
	conf_win_resize_flag = 0;
	return r;
}

void conf_win_init_resized(struct scrollwin *sw, const char *title)
{
	wins_scrollwin_delete(sw);
	conf_win_init(sw, title);
}

