static void options_draw(struct scrollwin *sw, const struct conf_item *items, int n,
			 const char *(*value)(int, int *, int *, char *, size_t), int sel)
{
	int i, y = 0;
	char buf[BUFSIZ_LINE];
	int total = 0;

	for (i = 0; i < n; i++)
		total += items[i].lines;
	wins_scrollwin_set_linecount(sw, total);
	werase(sw->inner);
	for (i = 0; i < n; i++) {
		int is_bool, bval;
		const char *v = value(i, &is_bool, &bval, buf, sizeof(buf));
		if (i == sel)
			custom_apply_attr(sw->inner, ATTR_HIGHEST);
		mvwprintw(sw->inner, y, 0, "%s = ", items[i].name);
		if (i == sel)
			custom_remove_attr(sw->inner, ATTR_HIGHEST);
		if (is_bool) {
			custom_apply_attr(sw->inner, bval ? ATTR_TRUE : ATTR_FALSE);
			waddstr(sw->inner, bval ? _("yes") : _("no"));
			custom_remove_attr(sw->inner, bval ? ATTR_TRUE : ATTR_FALSE);
		} else {
			custom_apply_attr(sw->inner, ATTR_HIGHEST);
			waddstr(sw->inner, v);
			custom_remove_attr(sw->inner, ATTR_HIGHEST);
		}
		mvwaddstr(sw->inner, y + 1, 0, items[i].desc1);
		if (items[i].desc2)
			mvwaddstr(sw->inner, y + 2, 0, items[i].desc2);
		y += items[i].lines;
	}
}

static int options_line_of(const struct conf_item *items, int sel)
{
	int i, y = 0;
	for (i = 0; i < sel; i++)
		y += items[i].lines;
	return y;
}

static void options_ensure_visible(struct scrollwin *sw, const struct conf_item *items, int sel)
{
	int first = options_line_of(items, sel);
	int last = first + items[sel].lines - 1;
	int h = (int)sw->inner_h;
	if ((unsigned)first < sw->line_off)
		sw->line_off = first;
	else if ((unsigned)last >= sw->line_off + h)
		sw->line_off = last - h + 1;
}

static int ask_string_option(const char *prompt, char *dest, size_t size)
{
	char buf[BUFSIZ_LINE];
	int ret;
	snprintf(buf, sizeof(buf), "%s", dest);
	status_mesg(prompt, "");
	ret = getstring(win[STA].p, buf, BUFSIZ_LINE, 0, 1);
	if (ret == GETSTRING_VALID) {
		snprintf(dest, size, "%s", buf);
		return 1;
	}
	if (ret == GETSTRING_RET)
		return 2;
	return 0;
}

