		status_mesg(_("Enter the delay, in minutes, between automatic saves (0 to disable)"), "");
		if (getstring(win[STA].p, buf, BUFSIZ_LINE, 0, 1) == GETSTRING_VALID && is_all_digit(buf))
			conf.periodic_save = atoi(buf);
		break;
	case 13: conf.systemevents = !conf.systemevents; break;
	case 14: conf.confirm_quit = !conf.confirm_quit; break;
	case 15: conf.confirm_delete = !conf.confirm_delete; break;
	case 16:
