		ask_string_option(_("Enter the date format (see 'man 3 strftime' for possible formats)"), conf.day_heading, sizeof(conf.day_heading));
		break;
	case 21:
		ask_string_option(_("Enter the time format (see 'man 3 strftime' for possible formats)"), conf.timefmt, sizeof(conf.timefmt));
		break;
	}
}

