static void options_menu(const char *title, const struct conf_item *items, int n,
			 const char *(*value)(int, int *, int *, char *, size_t), void (*edit)(int))
{
	struct scrollwin sw;
	int sel = 0;
	int ch, action;

	conf_win_init(&sw, title);
	for (;;) {
		options_draw(&sw, items, n, value, sel);
		options_ensure_visible(&sw, items, sel);
		conf_win_display(&sw);
		custom_status_bar(sbar_keys_options, 4);
		ch = ui_wgetch(win[STA].p);
		action = keys_get_action(ch);
		if (action == KEY_GENERIC_QUIT || action == KEY_GENERIC_CANCEL)
			break;
		switch (action) {
		case KEY_MOVE_DOWN:
			if (sel < n - 1)
				sel++;
			break;
		case KEY_MOVE_UP:
			if (sel > 0)
				sel--;
			break;
		case KEY_EDIT_ITEM:
			edit(sel);
			if (conf_win_resize_needed())
				conf_win_init_resized(&sw, title);
			break;
		default:
			break;
		}
	}
	wins_scrollwin_delete(&sw);
}

static int conf_win_resize_flag = 0;

int conf_win_resize_needed(void)
{
	int r = conf_win_resize_flag;
	conf_win_resize_flag = 0;
	return r;
}

void conf_win_init_resized(struct scrollwin *sw, const char *title)
{
	wins_scrollwin_delete(sw);
	conf_win_init(sw, title);
}

void custom_general_config(void)
{
	options_menu(_("general options"), general_items, NB_GENERAL, general_value, general_edit);
}

void custom_notify_config(void)
{
	options_menu(_("notification options"), notify_items, NB_NOTIFY, notify_value, notify_edit);
}

/* ---- layout ---- */

void custom_layout_config(void)
{
	struct scrollwin sw;
	int ch, action;
	int sel = wins_layout() - 1;
	const char *layouts[8][5] = {
		{ "+---+---+", "|   | c |", "| a +---+", "|   | t |", "+---+---+" },
		{ "+---+---+", "| c |   |", "+---+ a |", "| t |   |", "+---+---+" },
		{ "+---+---+", "|   | c |", "| t +---+", "|   | a |", "+---+---+" },
		{ "+---+---+", "| c |   |", "+---+ t |", "| a |   |", "+---+---+" },
		{ "+---+---+", "|   | t |", "| a +---+", "|   | c |", "+---+---+" },
		{ "+---+---+", "| t |   |", "|---+ a |", "| c |   |", "+---+---+" },
		{ "+---+---+", "|   | a |", "| t +---+", "|   | c |", "+---+---+" },
		{ "+---+---+", "| a |   |", "+---+ t |", "| c |   |", "+---+---+" },
	};
	int i, j;

	conf_win_init(&sw, _("layout configuration"));
	for (;;) {
		wins_scrollwin_set_linecount(&sw, sw.inner_h);
		werase(sw.inner);
		for (i = 0; i < 8; i++) {
			int bx = 8 + (i % 4) * 22;
			int by = 2 + (i / 4) * 8;
			for (j = 0; j < 5; j++) {
				if (i == sel)
					custom_apply_attr(sw.inner, ATTR_HIGHEST);
				mvwaddstr(sw.inner, by + j, bx, layouts[i][j]);
				if (i == sel)
					custom_remove_attr(sw.inner, ATTR_HIGHEST);
			}
			mvwprintw(sw.inner, by + 2, bx - 5, "[%c]", i == sel ? 'X' : ' ');
		}
		conf_win_display(&sw);
		custom_status_bar(sbar_keys_layout, 7);
		ch = ui_wgetch(win[STA].p);
		action = keys_get_action(ch);
		if (action == KEY_GENERIC_QUIT || action == KEY_GENERIC_CANCEL)
			break;
		switch (action) {
		case KEY_MOVE_DOWN:
			if (sel < 4)
				sel += 4;
			break;
		case KEY_MOVE_UP:
			if (sel >= 4)
				sel -= 4;
			break;
		case KEY_MOVE_LEFT:
			if (sel % 4 > 0)
				sel--;
			break;
		case KEY_MOVE_RIGHT:
			if (sel % 4 < 3)
				sel++;
			break;
		case KEY_GENERIC_SELECT:
			wins_set_layout(sel + 1);
			conf.layout = sel + 1;
			wins_reinit();
			break;
		case KEY_GENERIC_HELP:
			display_help("layout");
			break;
		default:
			break;
		}
	}
	wins_scrollwin_delete(&sw);
}

/* ---- sidebar ---- */

void custom_sidebar_config(void)
{
	int ch, action;
	for (;;) {
		wins_update(FLAG_ALL & ~FLAG_STA);
		custom_status_bar(sbar_keys_sidebar, 4);
		ch = ui_wgetch(win[STA].p);
		action = keys_get_action(ch);
		if (action == KEY_GENERIC_QUIT || action == KEY_GENERIC_CANCEL)
			break;
		switch (action) {
		case KEY_MOVE_UP:
			wins_sbar_winc();
			conf.sbar_width = wins_sbar_wperc();
			wins_reinit();
			ui_day_load_items();
			break;
		case KEY_MOVE_DOWN:
			wins_sbar_wdec();
			conf.sbar_width = wins_sbar_wperc();
			wins_reinit();
			ui_day_load_items();
			break;
		case KEY_GENERIC_HELP:
			display_help("sidebar");
			break;
		default:
			break;
		}
	}
}

/* ---- color ---- */

void custom_color_config(void)
{
	struct scrollwin sw;
	int ch, action;
	int cursor = 0;	/* 0..13: 0-6 fg, 7-13 bg; 6/13 = default */
	int colors[7] = { COLOR_RED, COLOR_GREEN, COLOR_YELLOW, COLOR_BLUE, COLOR_MAGENTA, COLOR_CYAN, -1 };
	int fg_sel, bg_sel, i;
	int mark_fg, mark_bg;

	fg_sel = 6;
	for (i = 0; i < 6; i++)
		if (colors[i] == conf.color_fg)
			fg_sel = i;
	bg_sel = 6;
	for (i = 0; i < 6; i++)
		if (colors[i] == conf.color_bg)
			bg_sel = i;
	mark_fg = fg_sel;
	mark_bg = bg_sel;

	conf_win_init(&sw, _("color theme"));
	for (;;) {
		int x_fg = 21, x_bg = 56;
		wins_scrollwin_set_linecount(&sw, sw.inner_h);
		werase(sw.inner);
		custom_apply_attr(sw.inner, ATTR_HIGHEST);
		mvwaddstr(sw.inner, 0, x_fg + 5, _("Foreground"));
		mvwaddstr(sw.inner, 0, x_bg + 5, _("Background"));
		custom_remove_attr(sw.inner, ATTR_HIGHEST);
		for (i = 0; i < 7; i++) {
			int y = 2 + 2 * i;
			/* foreground */
			mvwprintw(sw.inner, y, x_fg, "[ ]");
			if (mark_fg == i) {
				if (cursor == i) {
					custom_apply_attr(sw.inner, ATTR_HIGHEST);
					wattron(sw.inner, A_REVERSE);
				} else {
					custom_apply_attr(sw.inner, ATTR_HIGHEST);
				}
				mvwaddch(sw.inner, y, x_fg + 1, 'X');
				if (cursor == i)
					wattroff(sw.inner, A_REVERSE);
				custom_remove_attr(sw.inner, ATTR_HIGHEST);
			} else if (cursor == i) {
				wattron(sw.inner, A_REVERSE);
				mvwaddch(sw.inner, y, x_fg + 1, ' ');
				wattroff(sw.inner, A_REVERSE);
			}
			if (i < 6) {
				if (colorize)
					wattron(sw.inner, COLOR_PAIR(COLR_RED + i) | A_REVERSE);
				else
					wattron(sw.inner, A_REVERSE);
				mvwaddstr(sw.inner, y, x_fg + 5, "          ");
				if (colorize)
					wattroff(sw.inner, COLOR_PAIR(COLR_RED + i) | A_REVERSE);
				else
					wattroff(sw.inner, A_REVERSE);
			} else {
				wattron(sw.inner, A_REVERSE);
				mvwaddstr(sw.inner, y, x_fg + 5, "          ");
				wattroff(sw.inner, A_REVERSE);
				mvwaddstr(sw.inner, y + 1, x_fg + 5, _("(terminal's default)"));
			}
			/* background */
			mvwprintw(sw.inner, y, x_bg, "[ ]");
			if (mark_bg == i) {
				if (cursor == 7 + i) {
					custom_apply_attr(sw.inner, ATTR_HIGHEST);
					wattron(sw.inner, A_REVERSE);
				} else {
					custom_apply_attr(sw.inner, ATTR_HIGHEST);
				}
				mvwaddch(sw.inner, y, x_bg + 1, 'X');
				if (cursor == 7 + i)
					wattroff(sw.inner, A_REVERSE);
				custom_remove_attr(sw.inner, ATTR_HIGHEST);
			} else if (cursor == 7 + i) {
				wattron(sw.inner, A_REVERSE);
				mvwaddch(sw.inner, y, x_bg + 1, ' ');
				wattroff(sw.inner, A_REVERSE);
			}
			if (i < 6) {
				if (colorize)
					wattron(sw.inner, COLOR_PAIR(COLR_RED + i) | A_REVERSE);
				else
					wattron(sw.inner, A_REVERSE);
				mvwaddstr(sw.inner, y, x_bg + 5, "          ");
				if (colorize)
					wattroff(sw.inner, COLOR_PAIR(COLR_RED + i) | A_REVERSE);
				else
					wattroff(sw.inner, A_REVERSE);
			} else {
				mvwaddstr(sw.inner, y + 1, x_bg + 5, _("(terminal's default)"));
			}
		}
		conf_win_display(&sw);
		custom_status_bar(sbar_keys_color, 8);
		ch = ui_wgetch(win[STA].p);
		action = keys_get_action(ch);
		if (action == KEY_GENERIC_QUIT || action == KEY_GENERIC_CANCEL)
			break;
		switch (action) {
		case KEY_MOVE_DOWN:
			if (cursor % 7 < 6)
				cursor++;
			break;
		case KEY_MOVE_UP:
			if (cursor % 7 > 0)
				cursor--;
			break;
		case KEY_MOVE_LEFT:
			if (cursor >= 7)
				cursor -= 7;
			break;
		case KEY_MOVE_RIGHT:
			if (cursor < 7)
				cursor += 7;
			break;
		case KEY_GENERIC_SELECT:
			if (cursor < 7)
				mark_fg = cursor;
			else
				mark_bg = cursor - 7;
			custom_set_colors(colors[mark_fg], colors[mark_bg]);
			conf.color_theme_set = 1;
			break;
		default:
			if (ch == 'X' || ch == 'x') {
				if (cursor < 7)
					mark_fg = cursor;
				else
					mark_bg = cursor - 7;
				custom_set_colors(colors[mark_fg], colors[mark_bg]);
			}
			break;
		}
	}
	wins_scrollwin_delete(&sw);
}

/* ---- keys ---- */

void custom_keys_config(void)
{
	struct scrollwin sw;
	int ch, action;
	int sel = 0;
	int i;

	conf_win_init(&sw, _("keys configuration"));
	for (;;) {
		wins_scrollwin_set_linecount(&sw, NBVKEYS * 2);
		werase(sw.inner);
		for (i = 0; i < NBVKEYS; i++) {
			char *keystr = keys_action_allkeys(i);
			if (i == sel)
				custom_apply_attr(sw.inner, ATTR_HIGHEST);
			mvwprintw(sw.inner, i * 2, 0, "%-21s", keys_get_label(i));
			if (i == sel)
				custom_remove_attr(sw.inner, ATTR_HIGHEST);
			if (i == sel)
				custom_apply_attr(sw.inner, ATTR_HIGHEST);
			mvwaddstr(sw.inner, i * 2, 22, "=");
			custom_remove_attr(sw.inner, ATTR_HIGHEST);
			if (i == sel)
				custom_apply_attr(sw.inner, ATTR_HIGHEST);
			mvwprintw(sw.inner, i * 2, 24, "%s ", keystr);
			if (i == sel)
				custom_remove_attr(sw.inner, ATTR_HIGHEST);
			mem_free(keystr);
		}
		{
			int first = sel * 2, h = (int)sw.inner_h;
			if ((unsigned)first < sw.line_off)
				sw.line_off = first;
			else if ((unsigned)first + 1 >= sw.line_off + h)
				sw.line_off = first + 2 - h;
		}
		conf_win_display(&sw);
		custom_status_bar(sbar_keys_keys, 8);
		ch = ui_wgetch(win[STA].p);
		action = keys_get_action(ch);
		if (action == KEY_GENERIC_QUIT || action == KEY_GENERIC_CANCEL) {
			if (keys_check_missing_bindings()) {
				status_mesg(_("Some actions do not have any associated key bindings!"), "");
				ui_wgetch(win[STA].p);
				continue;
			}
			break;
		}
		switch (action) {
		case KEY_MOVE_DOWN:
			if (sel < NBVKEYS - 1)
				sel++;
			break;
		case KEY_MOVE_UP:
			if (sel > 0)
				sel--;
			break;
		case KEY_GENERIC_HELP:
			keys_popup_info(sel);
			break;
		case KEY_ADD_ITEM: {
			int k;
			status_mesg(_("Press the key you want to assign to:"), keys_get_label(sel));
			k = ui_wgetch(win[STA].p);
			if (k == 27 || k == ERR)
				break;
			{
				int r = keys_assign_binding(k, sel);
				if (r == 1) {
					char *m = strdup_printf(_("The key '%s' is already used for %s. Choose another one."),
								keys_int2str(k), keys_get_label(keys_get_action(k)));
					status_mesg(m, "");
					mem_free(m);
					ui_wgetch(win[STA].p);
				}
			}
			break;
		}
		case KEY_DEL_ITEM: {
			int n = keys_action_count_keys(sel);
			if (n == 0)
				break;
			if (n == 1) {
				const char *k = keys_action_firstkey(sel);
				keys_remove_binding(keys_str2int(k), sel);
			} else {
				char *m;
				int k;
				m = strdup_printf(_("Enter the key to remove from %s:"), keys_get_label(sel));
				status_mesg(m, "");
				mem_free(m);
				k = ui_wgetch(win[STA].p);
				if (k != 27 && keys_get_action(k) == sel)
					keys_remove_binding(k, sel);
			}
			break;
		}
		default:
			break;
		}
	}
	wins_scrollwin_delete(&sw);
}

void keys_popup_info(enum vkey key)
{
	char *msg = strdup_printf("%s", keys_get_label(key));
	wins_show_popup(_("Key binding"), msg);
	mem_free(msg);
}

/* ---- main configuration menu ---- */

void custom_config_main(void)
{
	int ch;
	for (;;) {
		custom_status_bar(sbar_keys_config, 7);
		ch = ui_wgetch(win[STA].p);
		if (keys_get_action(ch) == KEY_GENERIC_QUIT || keys_get_action(ch) == KEY_GENERIC_CANCEL)
			break;
		switch (ch) {
		case 'C':
		case 'c':
			custom_color_config();
			break;
		case 'L':
		case 'l':
			custom_layout_config();
			break;
		case 'S':
		case 's':
			custom_sidebar_config();
			break;
		case 'G':
		case 'g':
			custom_general_config();
			break;
		case 'N':
		case 'n':
			custom_notify_config();
			break;
		case 'K':
		case 'k':
			custom_keys_config();
			break;
		default:
			continue;
		}
		ui_day_load_items();
		wins_update(FLAG_ALL & ~FLAG_STA);
	}
	config_save();
	{
		FILE *fp = fopen(path_keys, "w");
		if (fp && !read_only) {
			keys_save_bindings(fp);
			fclose(fp);
		} else if (fp) {
			fclose(fp);
		}
	}
}
